let MAX_Z = 10
let PROXIMITY_RADIUS = 1
let GOOD_VOXEL_SIZE = 2
let RED = 1
let BLACK = 0
let NIL = -1

// Node array layout: [key, val, left, right, parent, color]
let NK = 0
let NV = 1
let NL = 2
let NR = 3
let NP = 4
let NC = 5

// =====================================================
// Helpers
// =====================================================
pn safe_div(a, b) {
    if (b == 0) { return 0.0 }
    var r = a / b
    return r
}

