    return b
}

pn check_overlap(low, high) {
    if (low <= 1) {
        if (1 <= high) { return 1 }
    }
    if (low <= 0) {
        if (0 <= high) { return 1 }
    }
    if (0 <= low) {
        if (high <= 1) { return 1 }
    }
    return 0
}

pn get_old_or_new(old, newp) {
    if (old == null) { return newp }
