                while (jj < mvsz) {
                    var mIdx2 = vec_at(motVec, jj)
                    var mot2 = vec_at(motions, mIdx2)
                    var coll = find_intersection(mot1, mot2)
                    if (coll != null) {
                        collisionCount = collisionCount + 1
                    }
                    jj = jj + 1
                }
                ii = ii + 1
            }
        }
        vmCur = rbt_successor(voxelMap, vmCur)
    }

    return collisionCount
}

