    this.taskList = t;
    this.taskTable[identity] = t;
  }

  createWorker(identity, priority, workPacket, state) {
    const dataRecord = new WorkerTaskDataRecord();

    this.createTask(
      identity,
      priority,
      workPacket,
      state,
      dataRecord,
      (work, word) => {
        const data = word;
        if (NO_WORK === work) {
