// Oracle at 36,000 canonical AWFY steps: the reference algorithm yields
// -0.16901424478751628, so floor(-energy * 10^7) is 1690142.
// 5-body gravitational simulation using flat arrays

let PI = 3.141592653589793
let SOLAR_MASS = 4.0 * PI * PI
let DAYS_PER_YEAR = 365.24

pn advance(var bx, var by, var bz, var bvx, var bvy, var bvz, var bmass, dt) {
    var i = 0
    while (i < 5) {
        var j = i + 1
        while (j < 5) {
            var dx = bx[i] - bx[j]
            var dy = by[i] - by[j]
            var dz = bz[i] - bz[j]

            var d_squared = dx * dx + dy * dy + dz * dz
            var distance = math.sqrt(d_squared)
            var mag = dt / (d_squared * distance)

            bvx[i] = bvx[i] - dx * bmass[j] * mag
            bvy[i] = bvy[i] - dy * bmass[j] * mag
            bvz[i] = bvz[i] - dz * bmass[j] * mag

            bvx[j] = bvx[j] + dx * bmass[i] * mag
            bvy[j] = bvy[j] + dy * bmass[i] * mag
            bvz[j] = bvz[j] + dz * bmass[i] * mag

            j = j + 1
        }
        i = i + 1
    }

    i = 0
    while (i < 5) {
        bx[i] = bx[i] + dt * bvx[i]
        by[i] = by[i] + dt * bvy[i]
        bz[i] = bz[i] + dt * bvz[i]
        i = i + 1
    }
}

pn energy(bx, by, bz, bvx, bvy, bvz, bmass) {
    var e = 0.0
    var i = 0
    while (i < 5) {
        var ke = bvx[i] * bvx[i] + bvy[i] * bvy[i] + bvz[i] * bvz[i]
        e = e + 0.5 * bmass[i] * ke

        var j = i + 1
        while (j < 5) {
            var dx = bx[i] - bx[j]
            var dy = by[i] - by[j]
            var dz = bz[i] - bz[j]
            var distance = math.sqrt(dx * dx + dy * dy + dz * dz)
            e = e - (bmass[i] * bmass[j]) / distance
            j = j + 1
        }
        i = i + 1
    }
    return e
}

pn offset_momentum(var bvx, var bvy, var bvz, var bmass) {
    var px = 0.0
    var py = 0.0
    var pz = 0.0
    var i = 0
    while (i < 5) {
        px = px + bvx[i] * bmass[i]
        py = py + bvy[i] * bmass[i]
        pz = pz + bvz[i] * bmass[i]
        i = i + 1
    }
    bvx[0] = 0.0 - (px / SOLAR_MASS)
    bvy[0] = 0.0 - (py / SOLAR_MASS)
    bvz[0] = 0.0 - (pz / SOLAR_MASS)
