// Kostya Benchmark: brainfuck (Node.js)
// Brainfuck interpreter — interprets a BF program 10000 times
'use strict';

function buildJumpTable(prog) {
    const len = prog.length;
    const jumps = new Int32Array(len);
    const stack = [];
    for (let i = 0; i < len; i++) {
        const c = prog.charCodeAt(i);
        if (c === 91) { // '['
            stack.push(i);
        } else if (c === 93) { // ']'
            const j = stack.pop();
            jumps[i] = j;
            jumps[j] = i;
        }
    }
    return jumps;
}

function runBf(prog, jumps) {
    const len = prog.length;
    const tape = new Uint8Array(30000);
    let dp = 0;
    let ip = 0;
    const output = [];

    while (ip < len) {
        const op = prog.charCodeAt(ip);
        if (op === 43) { // '+'
            tape[dp] = (tape[dp] + 1) & 0xFF;
        } else if (op === 45) { // '-'
            tape[dp] = (tape[dp] + 255) & 0xFF;
        } else if (op === 62) { // '>'
            dp++;
        } else if (op === 60) { // '<'
            dp--;
        } else if (op === 46) { // '.'
            output.push(String.fromCharCode(tape[dp]));
        } else if (op === 91) { // '['
            if (tape[dp] === 0) {
                ip = jumps[ip];
            }
        } else if (op === 93) { // ']'
            if (tape[dp] !== 0) {
                ip = jumps[ip];
            }
        }
        ip++;
    }
    return output.join('');
}

function benchmark_main() {
const prog = "++++++++[>++++[>++>+++>+++>+<<<<-]>+>+>->>+[<]<-]>>.>---.+++++++..+++.>>.<-.<.+++.------.--------.>>+.>++.";
const jumps = buildJumpTable(prog);
let output = "";
for (let iter = 0; iter < 10000; iter++) {
  output = runBf(prog, jumps);
}
return output === "Hello World!\n";
}
benchmark_main()

// Kostya Benchmark: levenshtein (Node.js)
// Levenshtein edit distance using dynamic programming
'use strict';

function levenshtein(s1, s2) {
    const n = s1.length;
    const m = s2.length;
    let prev = new Int32Array(m + 1);
    let curr = new Int32Array(m + 1);
    for (let j = 0; j <= m; j++) prev[j] = j;

    for (let i = 1; i <= n; i++) {
        curr[0] = i;
        const c1 = s1.charCodeAt(i - 1);
        for (let j = 1; j <= m; j++) {
            const cost = c1 === s2.charCodeAt(j - 1) ? 0 : 1;
            const del = prev[j] + 1;
            const ins = curr[j - 1] + 1;
            const sub = prev[j - 1] + cost;
            curr[j] = del < ins ? (del < sub ? del : sub) : (ins < sub ? ins : sub);
        }
        [prev, curr] = [curr, prev];
    }
    return prev[m];
}

function makeString(ch, n) {
    return ch.repeat(n);
}

function benchmark_main() {
const d1 = levenshtein("kitten", "sitting");
const d2 = levenshtein("saturday", "sunday");
const s1 = makeString("a", 500);
const s2 = makeString("b", 500);
const d3 = levenshtein(s1, s2);
const s3 = makeString("ab", 200);
const s4 = makeString("ba", 200);
const d4 = levenshtein(s3, s4);
return d1 === 3 && d2 === 3 && d3 === 500 && d4 === 2;
}
