    struct ArrayNum {
        // 8-byte Container header. `elem_type` IS the map_kind byte (@3).
        TypeId type_id;
        uint8_t flags;
        uint8_t array_flags;
        uint8_t elem_type;     // ArrayNumElemType, in the map_kind byte
        uint8_t cow_state;
        uint8_t ctor_reserved_mask_lo;
        uint8_t ctor_reserved_mask_hi;
        uint8_t reserved_state;
        //--------------------- Map face (D2.6.6v2)
