static inline size_t string_builder_copy_part(char* destination, const String* part) {
    // The stored byte length proves this copy needs one store, including NUL;
    // multi-byte UTF-8 fragments retain the general length-based copy.
    size_t length = part->len;
    if (length == 1) *destination = part->chars[0];
    else memcpy(destination, part->chars, length);
    return length;
}

static String* string_buffer_copy_join(String* const* parts, int count,
        size_t capacity, size_t required, bool ascii, bool owned) {
    size_t bytes = sizeof(String) + capacity + 1;
    if (bytes > (size_t)INT_MAX) return NULL;
    // Every source can move during allocation, including converted temporaries.
    RootSpan roots(count);
    uint64_t* homes = roots.words();
    for (int i = 0; i < count; i++) {
        if (homes) homes[i] = (uint64_t)(uintptr_t)parts[i];
    }
    String* result = (String*)heap_alloc((int)bytes, LMD_TYPE_STRING);
    if (!result) return NULL;
    result->len = (uint32_t)required;
    result->flags = 0;
    result->is_ascii = ascii;
    result->is_buffer = owned;
    size_t offset = 0;
    for (int i = 0; i < count; i++) {
        String* part = homes ? (String*)(uintptr_t)homes[i] : parts[i];
        offset += string_builder_copy_part(result->chars + offset, part);
    }
    result->chars[offset] = 0;
    string_profile_append(count, required, false);
    return result;
}

// Specialize the binary API's fixed count without duplicating reserve/copy code.
// Otherwise the release compiler keeps a variable-count loop and stack array
// wrapper even for every single-piece append.
template<int fixed_count>
static String* string_buffer_join(String* const* parts, int variable_count, bool owned) {
    const int count = fixed_count ? fixed_count : variable_count;
    size_t required = 0;
    bool ascii = true;
    bool overlaps = false;
    for (int i = 0; i < count; i++) {
        if (!parts[i] || parts[i]->len > UINT32_MAX - required) return &STR_ERROR;
        required += parts[i]->len;
        ascii = ascii && parts[i]->is_ascii;
        if (i && parts[i] == parts[0]) overlaps = true;
    }
    gc_header_t* header = NULL;
    size_t capacity = required;
    bool reuse = owned && !overlaps && string_is_owned_buffer(parts[0], &header);
    if (reuse) {
        capacity = (size_t)header->alloc_size - sizeof(String) - 1;
        if (capacity < required) {
            if (capacity < 64) capacity = 64;
            while (capacity < required) {
                capacity = capacity > UINT32_MAX / 2 ? required : capacity * 2;
            }
        } else {
            String* result = parts[0];
            size_t offset = result->len;
            for (int i = 1; i < count; i++) {
                offset += string_builder_copy_part(result->chars + offset, parts[i]);
            }
            result->chars[offset] = 0;
            string_profile_append(count, required - result->len, true);
            result->len = (uint32_t)offset;
            result->is_ascii = ascii;
            return result;
        }
    }
    return string_buffer_copy_join(parts, count, capacity, required, ascii, owned);
}

String *fn_strcat(String *left, String *right) {
    String* parts[] = {left, right};
    return string_buffer_join<2>(parts, 2, true);
}

// The MIR owner path knows its exact arity. These entries retain the shared
// builder implementation while avoiding the variadic ABI and dynamic-count
// join loop for common multi-piece appends.
#define LAMBDA_STRING_FIXED_APPEND(name, count, parameters, ...) \
    String *name parameters { \
        String* joined[] = {__VA_ARGS__}; \
        return string_buffer_join<count>(joined, count, true); \
    }

LAMBDA_STRING_FIXED_APPEND(fn_strcat3, 3,
    (String *part0, String *part1, String *part2), part0, part1, part2)
LAMBDA_STRING_FIXED_APPEND(fn_strcat4, 4,
    (String *part0, String *part1, String *part2, String *part3),
    part0, part1, part2, part3)
LAMBDA_STRING_FIXED_APPEND(fn_strcat5, 5,
    (String *part0, String *part1, String *part2, String *part3, String *part4),
    part0, part1, part2, part3, part4)
LAMBDA_STRING_FIXED_APPEND(fn_strcat6, 6,
    (String *part0, String *part1, String *part2, String *part3, String *part4,
        String *part5), part0, part1, part2, part3, part4, part5)

#undef LAMBDA_STRING_FIXED_APPEND

String *fn_strcat_many(int64_t owned, int64_t count, ...) {
    if (count < 2 || count > LAMBDA_STRING_CONCAT_MAX_PARTS) return &STR_ERROR;
    String* parts[LAMBDA_STRING_CONCAT_MAX_PARTS];
    va_list args;
    va_start(args, count);
    for (int i = 0; i < count; i++) parts[i] = va_arg(args, String*);
    va_end(args);
    return string_buffer_join<0>(parts, (int)count, owned != 0);
}

String *fn_string_freeze(String *str) {
    if (str && str->is_buffer) {
        // The MIR owner is about to publish this value through an ordinary
        // read, so later concatenation must allocate rather than alter an alias.
        str->is_buffer = 0;
        string_profile_note(STRING_FREEZES);
    }
    return str;
}

static String* fn_concat_string_items(Item left, Item right) {
    string_profile_note(STRING_GENERIC_JOINS);
    // The second conversion can collect the first conversion result before
    // fn_strcat receives it, so conversion temporaries need native homes too.
    RootFrame roots(2);
    Rooted<String*> left_str(roots, fn_string(left));
    Rooted<String*> right_str(roots, (String*)NULL);
    right_str.set(fn_string(right));
    String* result = fn_strcat(left_str.get(), right_str.get());
    // Generic fn_join has no MIR ownership proof. Its result may immediately
    // escape through a container, call, or alias, so it is immutable on return.
    if (result && result != &STR_ERROR) result->is_buffer = 0;
    return result;
}

bool lambda_value_rep_proves_contract(Item value, Type* contract);
static bool array_rebuild_native_lane(Item source, const LaneStorageDesc* desc,
    Item* rebuilt);
static bool array_native_lane_supported(const LaneStorageDesc* desc);

// `acc ++ [x]` under a typed accumulator: when one operand carries an exact
// representation certificate and every element of the other operand proves
// that certificate's element contract (or carries the same certificate), the
// concatenation is the same T[] -- publish the certificate on the result,
// laid out in the certificate's native lane when it has one (a record lane
// for `Node[]`). Without it every `acc: T[]` crossing re-admitted and rebuilt
// the whole accumulator, quadratic per list (prettier_ast2 join_docs_at /
// print_nodes_at). lambda_array_rep_proves_cert re-checks the final layout.
static Item array_concat_inherit_cert(Item result, Item left, Item right) {
    ArrayRepCert* left_cert = left.array ? left.array->rep_cert : NULL;
    ArrayRepCert* right_cert = right.array ? right.array->rep_cert : NULL;
    ArrayRepCert* cert = left_cert ? left_cert : right_cert;
    if (!cert || !cert->immediate_element || cert->rank != 1) return result;
    // item_at may box a wide element and the lane rebuild allocates: the
    // fresh result and the operand being proven stay rooted across both
    RootFrame roots(2);
    Rooted<Item> rooted_result(roots, result);
    Rooted<Item> rooted_other(roots, cert == left_cert ? right : left);
    ArrayRepCert* other_cert = cert == left_cert ? right_cert : left_cert;
    if (other_cert != cert) {
        int64_t count = rooted_other.get().array->length;
        for (int64_t i = 0; i < count; i++) {
            if (!lambda_value_rep_proves_contract(item_at(rooted_other.get(), i),
                    cert->immediate_element)) {
                return rooted_result.get();
            }
        }
    }
    LaneStorageDesc lane = {};
    if (get_type_id(rooted_result.get()) == LMD_TYPE_ARRAY &&
            lambda_type_array_lane_storage_desc(cert->immediate_element, &lane) &&
            array_native_lane_supported(&lane) &&
            !array_native_lane_matches_desc(rooted_result.get().array, &lane)) {
        Item rebuilt = ItemNull;
        if (!array_rebuild_native_lane(rooted_result.get(), &lane, &rebuilt)) {
            return rooted_result.get();
        }
        rooted_result.set(rebuilt);
    }
    lambda_array_install_rep_cert(rooted_result.get(), cert);
    if (!lambda_array_rep_proves_cert(rooted_result.get(), cert, true)) {
        lambda_array_clear_rep_cert(rooted_result.get());
    }
    return rooted_result.get();
}

// A certified native Array already stores its elements in the destination
// layout. Build the joined lane directly instead of boxing its prefix into a
// generic Array and re-admitting that whole prefix at the next typed boundary.
static bool array_concat_native_lane(Item left, Item right, Item* joined) {
    Array* la = left.array;
    Array* ra = right.array;
    ArrayRepCert* cert = la ? la->rep_cert : NULL;
    if (!joined || !la || !ra || !cert || !cert->immediate_element ||
            cert->rank != 1 || !array_has_native_lane(la) ||
            la->is_view || la->is_ndim || ra->is_view || ra->is_ndim ||
            la->length < 0 || ra->length < 0 ||
            la->length > INT64_MAX - ra->length ||
            !lambda_array_rep_proves_cert(left, cert, true)) return false;
    LaneStorageDesc lane = {};
    if (!lambda_type_array_lane_storage_desc(cert->immediate_element, &lane) ||
            !array_native_lane_supported(&lane) ||
            lane.kind != LANE_STORAGE_POINTER ||
            !array_native_lane_matches_desc(la, &lane)) return false;

    RootFrame roots(4);
    Rooted<Item> rooted_left(roots, left);
    Rooted<Item> rooted_right(roots, right);
    Rooted<Array*> rooted_result(roots, array_plain());
    Rooted<Item> rooted_element(roots, ItemNull);
    if (!rooted_result.get()) {
        *joined = ItemError;
        return true;
    }
    array_native_lane_configure(rooted_result.get(), &lane);
    la = rooted_left.get().array;
    ra = rooted_right.get().array;
    int64_t total = la->length + ra->length;
    if (!array_reserve_append_slots(rooted_result.get(), total)) {
        *joined = ItemError;
        return true;
    }
    la = rooted_left.get().array;
    ra = rooted_right.get().array;
    Array* result = rooted_result.get();
    size_t slot_size = array_native_lane_slot_size(result);
    if (la->length) {
        memcpy(result->items, la->items, (size_t)la->length * slot_size);
    }
    result->length = la->length;
    bool right_lane = ra->rep_cert == cert &&
        lambda_array_rep_proves_cert(rooted_right.get(), cert, true) &&
        array_native_lane_matches_desc(ra, &lane);
    if (right_lane) {
        if (ra->length) {
            memcpy(array_native_lane_slot(result, result->length), ra->items,
                (size_t)ra->length * slot_size);
        }
        result->length = total;
    } else {
        for (int64_t i = 0; i < rooted_right.get().array->length; i++) {
            rooted_element.set(item_at(rooted_right.get(), i));
            if (!lambda_value_rep_proves_contract(rooted_element.get(),
                    cert->immediate_element) ||
                    !array_native_lane_store(rooted_result.get(),
                        rooted_result.get()->length,
                        rooted_element.get())) {
                return false;
            }
            result = rooted_result.get();
            result->length++;
        }
    }
    result = rooted_result.get();
    lambda_array_install_rep_cert({.array = result}, cert);
    if (!lambda_array_rep_proves_cert({.array = result}, cert, true)) {
        lambda_array_clear_rep_cert({.array = result});
    }
    *joined = {.array = result};
    return true;
}

// The two-sequence arm of `++` (S10.6.1): concatenate the items, keeping a
// packed lane when both sides share it. The caller decides the result's kind.
static Item fn_join_sequences(Item left, Item right, TypeId left_type, TypeId right_type) {
    if (left_type == LMD_TYPE_ARRAY && right_type == LMD_TYPE_ARRAY &&
            !item_is_list(left) && !item_is_list(right)) {
        Item native_result = ItemNull;
        if (array_concat_native_lane(left, right, &native_result)) return native_result;
    }
    // An N-D array's items are its leading-axis rows (S11.1.1v3), so it joins
    // row by row; its flat leaves are storage, not items (S10.6.1).
    bool rows = (left_type == LMD_TYPE_ARRAY_NUM && array_num_rank(left.array_num) > 1) ||
        (right_type == LMD_TYPE_ARRAY_NUM && array_num_rank(right.array_num) > 1);
    // same-type optimization: direct memcpy of native items (not for Range)
    bool same_lane = !rows && (left_type != LMD_TYPE_ARRAY_NUM || right_type != LMD_TYPE_ARRAY_NUM ||
        left.array_num->get_elem_type() == right.array_num->get_elem_type());
    // A native-lane operand (an admitted `T?[]`) holds lane words, not Items,
    // so it takes the element-wise path below, which decodes every slot.
    bool native_lane = left_type == LMD_TYPE_ARRAY && right_type == LMD_TYPE_ARRAY &&
        (array_has_native_lane(left.array) || array_has_native_lane(right.array));
    if (left_type == right_type && left_type != LMD_TYPE_RANGE && same_lane && !native_lane) {
        if (left_type == LMD_TYPE_ARRAY_NUM) {
            ArrayNum *la = left.array_num, *ra = right.array_num;
            int64_t total = la->length + ra->length;
            ArrayNum *result = (ArrayNum *)heap_calloc(sizeof(ArrayNum), LMD_TYPE_ARRAY_NUM);
            result->type_id = LMD_TYPE_ARRAY_NUM;
            result->set_elem_type(la->get_elem_type());
            result->length = total;  result->capacity = total;
            RootFrame roots(1);
            Rooted<ArrayNum*> rooted_result(roots, result);
            size_t elem_size = ELEM_TYPE_SIZE[la->get_elem_type() >> 4];
            result->data = heap_data_alloc(total * elem_size);
            result = rooted_result.get();
            // copy positions, not bytes: a strided view (a row of a transposed
            // matrix) is not the next `length` elements of its base
            if (!array_num_copy_same_type_bytes(result, 0, la, 0, la->length) ||
                    !array_num_copy_same_type_bytes(result, la->length, ra, 0, ra->length)) {
                return ItemError;
            }
            return array_concat_inherit_cert({.array_num = result}, left, right);
        }
        // a view or N-D array stores a descriptor in extra, not a scalar tail
        // count. Reserve one tail word per item so copied wide scalars fit.
        Array *la = left.array, *ra = right.array;
        int64_t total_len = la->length + ra->length;
        int64_t total_extra = (la->is_view || la->is_ndim ? la->length : la->extra) +
                              (ra->is_view || ra->is_ndim ? ra->length : ra->extra);
        // destination allocation may collect, so retain both sources and result.
        RootFrame roots(3);
        Rooted<Item> rooted_left(roots, left);
        Rooted<Item> rooted_right(roots, right);
        Array *result = (Array *)heap_calloc(sizeof(Array) + sizeof(Item)*(total_len + total_extra), left_type);
        if (!result) return ItemError;
        Rooted<Array*> rooted_result(roots, result);
        la = rooted_left.get().array;
        ra = rooted_right.get().array;
        result->type_id = left_type;
        result->length = total_len;
        result->capacity = total_len + total_extra;
        result->extra = 0;
        result->items = (Item*)(result + 1);
        // Source tail pointers cannot survive after either operand dies.
        array_copy_owned_items(result, 0, la->items, la->length);
        array_copy_owned_items(result, la->length, ra->items, ra->length);
        return array_concat_inherit_cert({.array = rooted_result.get()},
                                         rooted_left.get(), rooted_right.get());
    }
    // different types: produce generic Array, convert typed elements to Items
    int64_t left_len = fn_seq_count(left), right_len = fn_seq_count(right);
    int64_t total_len = left_len + right_len;
    // item_at allocates (a boxed wide scalar, an N-D row view): keep the
    // operands and the destination rooted across every read
    RootFrame roots(3);
    Rooted<Item> rooted_left(roots, left);
    Rooted<Item> rooted_right(roots, right);
    // A typed source can expose one external scalar payload per element;
    // reserve the exact worst-case tail before copy-in discovers the mix.
    Array *result = (Array *)heap_calloc(sizeof(Array) + sizeof(Item)*(total_len * 2), LMD_TYPE_ARRAY);
    if (!result) return ItemError;
    Rooted<Array*> rooted_result(roots, result);
    result->type_id = LMD_TYPE_ARRAY;
    result->length = total_len;
    result->capacity = total_len * 2;
    result->extra = 0;
    result->items = (Item*)(result + 1);
    for (int64_t i = 0; i < left_len; i++)
        array_set(rooted_result.get(), i, item_at(rooted_left.get(), i));
    for (int64_t i = 0; i < right_len; i++)
        array_set(rooted_result.get(), left_len + i, item_at(rooted_right.get(), i));
    return {.array = rooted_result.get()};
}

// S10.6.1: `++` concatenates sequences and places every other value as one
// item. A sequence is a list, an array (packed or generic) or a range -- text
// is a scalar here, the one place where S2.5.8's "placed as one value" rule
// differs from the sequence walk.
static bool join_operand_is_sequence(TypeId type_id) {
    return type_id == LMD_TYPE_ARRAY || type_id == LMD_TYPE_ARRAY_NUM ||
        type_id == LMD_TYPE_RANGE;
}

// A map or an element is not a concatenation operand (S10.6.1): merge is
// `{*: m1, *: m2}`.
static bool join_operand_is_scalar(TypeId type_id) {
    return type_id <= LMD_TYPE_BINARY || type_id == LMD_TYPE_PATH;
}

// One operand's contribution: a sequence gives its items, anything else gives
// itself. The destination stays rooted across the reads, which may box a wide
// scalar out of a packed lane.
static void join_push_operand(Array* out, Item value, bool is_sequence) {
    if (!is_sequence) { array_push_verbatim(out, value); return; }
    RootFrame roots(2);
    Rooted<Array*> rooted_out(roots, out);
    Rooted<Item> rooted_value(roots, value);
    int64_t count = fn_seq_count(rooted_value.get());
    for (int64_t i = 0; i < count; i++) {
        array_push_verbatim(rooted_out.get(), item_at(rooted_value.get(), i));
    }
}

// A local `x = x ++ rhs` can consume its old open Array after the assignment
// has evaluated rhs. Detach shared snapshots first; a reserve failure falls
// back before changing the visible length (S9.1.2, S10.6.1).
Item fn_join_consume_open_array(Item left, Item right) {
    if (get_type_id(left) != LMD_TYPE_ARRAY ||
            get_type_id(right) != LMD_TYPE_ARRAY) return fn_join(left, right);
    Array* left_array = left.array;
    Array* right_array = right.array;
    if (!left_array || !right_array || item_is_list(left) ||
            left_array->type || left_array->data ||
            left_array->is_view || left_array->is_ndim ||
            right_array->is_view || right_array->is_ndim ||
            array_has_native_lane(left_array) || array_has_native_lane(right_array) ||
            left_array->rep_cert || right_array->rep_cert ||
            right_array->length < 0 || right_array->extra < 0 ||
            right_array->length > INT64_MAX - right_array->extra) {
        return fn_join(left, right);
    }
    RootFrame roots(2);
    Rooted<Item> rooted_left(roots, left);
    Rooted<Item> rooted_right(roots, right);
    // The RHS may be the old LHS itself or share its buffer through a view.
    // Force a snapshot before any append can overwrite its source positions.
    if (left_array == right_array || left_array->items == right_array->items) {
        cow_mark_shared(rooted_left.get());
    }
    rooted_left.set(cow_prepare_write(rooted_left.get()));
    if (get_type_id(rooted_left.get()) == LMD_TYPE_ERROR) return ItemError;
    left_array = rooted_left.get().array;
    right_array = rooted_right.get().array;
    int64_t right_length = right_array->length;
    if (!array_reserve_append_slots(left_array,
            right_length + right_array->extra)) {
        return fn_join(rooted_left.get(), rooted_right.get());
    }
    left_array = rooted_left.get().array;
    right_array = rooted_right.get().array;
    array_copy_owned_items(left_array, left_array->length,
        right_array->items, right_length);
    left_array->length += right_length;
    return rooted_left.get();
}

// A direct small-literal append constructs its literal only on a failed proof.
// Sequence append keeps the original RHS unchanged on that same fallback.
static Item join_consume_cert_array_fallback(Item left, Item right,
        Item second, int literal_count) {
    if (!literal_count) return fn_join(left, right);
    RootFrame roots(5);
    Rooted<Item> rooted_left(roots, left);
    Rooted<Item> rooted_right(roots, right);
    Rooted<Item> rooted_second(roots, second);
    Rooted<Array*> literal(roots, array_plain());
    if (!literal.get()) return ItemError;
    array_push(literal.get(), rooted_right.get());
    if (literal_count == 2) array_push(literal.get(), rooted_second.get());
    Rooted<Item> finished(roots, array_end(literal.get()));
    return fn_join(rooted_left.get(), finished.get());
}

// `left ++ [item]` still returns a fresh Array. Its literal is disposable
// when the left carrier is plain and one item cannot splice or promote an N-D
// numeric RHS; copy into the final owner directly (S9.1.2, S10.6.1).
Item fn_join_fresh_array_item(Item left, Item element) {
    TypeId element_type = get_type_id(element);
    if (get_type_id(left) != LMD_TYPE_ARRAY || item_is_list(left) ||
            element.item == ITEM_NULL_SPREADABLE || item_is_list(element) ||
            element_type == LMD_TYPE_ARRAY_NUM || element_type == LMD_TYPE_ERROR) {
        return join_consume_cert_array_fallback(left, element, ItemNull, 1);
    }
    Array* la = left.array;
    if (!la || la->type || la->data || la->is_view || la->is_ndim ||
            array_has_native_lane(la) || la->rep_cert ||
            la->length < 0 || la->extra < 0 ||
            la->length > INT64_MAX - la->extra - 3 ||
            (la->length && !la->items)) {
        return join_consume_cert_array_fallback(left, element, ItemNull, 1);
    }
    RootFrame roots(3);
    Rooted<Item> rooted_left(roots, left);
    Rooted<Item> rooted_element(roots, element);
    Rooted<Array*> result(roots, array_plain());
    if (!result.get()) return ItemError;
    la = rooted_left.get().array;
    // Reserve scalar tail homes before copying so array_set cannot relocate
    // the source buffer midway through its owned-item walk.
    if (!array_reserve_append_slots(result.get(), la->length + la->extra + 2)) {
        return join_consume_cert_array_fallback(rooted_left.get(),
            rooted_element.get(), ItemNull, 1);
    }
    la = rooted_left.get().array;
    array_copy_owned_items(result.get(), 0, la->items, la->length);
    result.get()->length = la->length;
    array_push(result.get(), rooted_element.get());
    return {.array = result.get()};
}

// A proved tail accumulator owns its post-entry versions. Both sequence and
// small-literal appends validate all source items before unsharing the left lane;
// the latter avoids allocating a temporary Array (S9.1.2,
// S10.6.1, D4.4.4v4).
static Item join_consume_cert_array(Item left, Item right, Item second,
        int literal_count) {
    if (get_type_id(left) != LMD_TYPE_ARRAY || item_is_list(left) ||
            (!literal_count && (get_type_id(right) != LMD_TYPE_ARRAY ||
                item_is_list(right)))) {
        return join_consume_cert_array_fallback(left, right, second, literal_count);
    }
    Array* la = left.array;
    Array* ra = literal_count ? NULL : right.array;
    ArrayRepCert* cert = la ? la->rep_cert : NULL;
    int64_t right_length = literal_count ? literal_count : ra ? ra->length : -1;
    if (!la || (!literal_count && !ra) || !cert || cert->rank != 1 ||
            !cert->immediate_element || la->type || la->data ||
            la->is_view || la->is_ndim ||
            (!literal_count && (ra->is_view || ra->is_ndim)) ||
            la->length < 0 || right_length < 0 ||
            la->length > INT64_MAX - right_length ||
            !lambda_array_rep_proves_cert(left, cert, true)) {
        return join_consume_cert_array_fallback(left, right, second, literal_count);
    }
    LaneStorageDesc lane = {};
    if (!lambda_type_array_lane_storage_desc(cert->immediate_element, &lane) ||
            lane.kind != LANE_STORAGE_POINTER ||
            !array_native_lane_matches_desc(la, &lane)) {
        return join_consume_cert_array_fallback(left, right, second, literal_count);
    }

    RootFrame roots(4);
    Rooted<Item> rooted_left(roots, left);
    Rooted<Item> rooted_right(roots, right);
    Rooted<Item> rooted_second(roots, second);
    Rooted<Item> rooted_element(roots, ItemNull);
    bool right_lane = !literal_count && ra->rep_cert == cert &&
        lambda_array_rep_proves_cert(right, cert, true) &&
        array_native_lane_matches_desc(ra, &lane);
    if (!right_lane) {
        // A bad RHS must fall back before the old accumulator is touched.
        for (int64_t i = 0; i < right_length; i++) {
            rooted_element.set(literal_count
                ? (i == 0 ? rooted_right.get() : rooted_second.get())
                : item_at(rooted_right.get(), i));
            if ((literal_count && item_is_list(rooted_element.get())) ||
                    !lambda_value_rep_proves_contract(rooted_element.get(),
                    cert->immediate_element)) {
                return join_consume_cert_array_fallback(rooted_left.get(),
                    rooted_right.get(), rooted_second.get(), literal_count);
            }
        }
    }
    la = rooted_left.get().array;
    ra = literal_count ? NULL : rooted_right.get().array;
    bool aliases_left = !literal_count &&
        (la == ra || la->items == ra->items);
    for (int i = 0; i < literal_count && !aliases_left; i++) {
        Item element = i == 0 ? rooted_right.get() : rooted_second.get();
        aliases_left = get_type_id(element) == LMD_TYPE_ARRAY &&
            (element.array == la || element.array->items == la->items);
    }
    if (aliases_left) cow_mark_shared(rooted_left.get());
    rooted_left.set(cow_prepare_write(rooted_left.get()));
    if (get_type_id(rooted_left.get()) == LMD_TYPE_ERROR) return ItemError;
    la = rooted_left.get().array;
    ra = literal_count ? NULL : rooted_right.get().array;
    if (!array_reserve_append_slots(la, right_length)) {
        return join_consume_cert_array_fallback(rooted_left.get(),
            rooted_right.get(), rooted_second.get(), literal_count);
    }
    la = rooted_left.get().array;
    ra = literal_count ? NULL : rooted_right.get().array;
    int64_t old_length = la->length;
    if (right_lane) {
        if (right_length) {
            memcpy(array_native_lane_slot(la, old_length), ra->items,
                (size_t)right_length * array_native_lane_slot_size(la));
        }
    } else {
        for (int64_t i = 0; i < right_length; i++) {
            rooted_element.set(literal_count
                ? (i == 0 ? rooted_right.get() : rooted_second.get())
                : item_at(rooted_right.get(), i));
            if (!array_native_lane_store(rooted_left.get().array,
                    old_length + i, rooted_element.get())) {
                return join_consume_cert_array_fallback(rooted_left.get(),
                    rooted_right.get(), rooted_second.get(), literal_count);
            }
        }
    }
    la = rooted_left.get().array;
    la->length = old_length + right_length;
    if (!lambda_array_rep_proves_cert(rooted_left.get(), cert, true)) {
        lambda_array_clear_rep_cert(rooted_left.get());
    }
    return rooted_left.get();
}

Item fn_join_consume_cert_array(Item left, Item right) {
    return join_consume_cert_array(left, right, ItemNull, 0);
}

Item fn_join_consume_cert_array_item(Item left, Item element) {
    return join_consume_cert_array(left, element, ItemNull, 1);
}

Item fn_join_consume_cert_array_pair(Item left, Item first, Item second) {
    return join_consume_cert_array(left, first, second, 2);
}

Item fn_join(Item left, Item right) {
    GUARD_ERROR2(left, right);
    // S10.6.1: sequence ++ sequence concatenates, a scalar beside a sequence is
    // one item, scalar ++ scalar is text, `null` is the identity, a map or an
    // element is an error; a path on the left keeps S2.4.2v4.
    TypeId left_type = get_type_id(left), right_type = get_type_id(right);

    // Handle path concatenation first (path must be on the left)
    if (left_type == LMD_TYPE_PATH) {
        Path* left_path = left.path;
        Pool* pool = eval_context_get_pool();

        if (right_type == LMD_TYPE_STRING) {
            // path ++ string: add string as new segment
            String* right_str = right.get_safe_string();
            Path* result = path_extend(pool, left_path, right_str->chars);
            return {.path = result};
        }
        else if (right_type == LMD_TYPE_SYMBOL) {
            // path ++ symbol: add symbol name as new segment
            Symbol* right_sym = right.get_safe_symbol();
            Path* result = path_extend(pool, left_path, right_sym->chars);
            return {.path = result};
        }
        else if (right_type == LMD_TYPE_PATH) {
            // path ++ path: concat if right is relative, error if absolute
            Path* right_path = right.path;
            if (path_is_absolute(right_path)) {
                set_runtime_error(ERR_TYPE_MISMATCH, "fn_join: cannot concatenate path with absolute path");
                return ItemError;
            }
            // Concatenate relative/parent path to base path
            Path* result = path_concat(pool, left_path, right_path);
            return {.path = result};
        }
        else {
            set_runtime_error(ERR_TYPE_MISMATCH, "fn_join: path can only be concatenated with string, symbol, or relative path, got %s",
                type_info[right_type].name);
            return ItemError;
        }
    }

    // S10.6.1: a sequence operand decides the shape of the result before any
    // text arm is consulted -- `[1] ++ "ab"` is `[1, "ab"]`, not `"[1]ab"`.
    bool left_seq = join_operand_is_sequence(left_type);
    bool right_seq = join_operand_is_sequence(right_type);
    if (left_seq || right_seq) {
        if (left_type == LMD_TYPE_NULL) return right;   // null is the identity
        if (right_type == LMD_TYPE_NULL) return left;
        if (!(left_seq || join_operand_is_scalar(left_type)) ||
                !(right_seq || join_operand_is_scalar(right_type))) {
            set_runtime_error(ERR_TYPE_MISMATCH, "fn_join: unsupported operand types: %s and %s",
                type_info[left_type].name, type_info[right_type].name);
            return ItemError;
        }
        // S2.5.7: a list only when no operand is of array kind; a scalar
        // leaves the kind to the sequence it is appended to.
        bool as_list = left_seq && right_seq ? seq_operands_are_lists(left, right)
            : item_is_list(left_seq ? left : right);
        if (left_seq && right_seq) return seq_finish_kind(
            fn_join_sequences(left, right, left_type, right_type), as_list);
        RootFrame roots(3);
        Rooted<Item> rooted_left(roots, left);
        Rooted<Item> rooted_right(roots, right);
        Rooted<Array*> rooted_out(roots, array());
        join_push_operand(rooted_out.get(), rooted_left.get(), left_seq);
        join_push_operand(rooted_out.get(), rooted_right.get(), right_seq);
        return seq_finish_kind({ .array = rooted_out.get() }, as_list);
    }

    if (left_type == LMD_TYPE_BINARY && right_type == LMD_TYPE_BINARY) {
        Binary* result = heap_binary_concat(left.get_safe_binary(), right.get_safe_binary());
        if (!result) {
            set_runtime_error(ERR_OUT_OF_MEMORY, "fn_join: failed to concatenate binary operands");
            return ItemError;
        }
        return {.item = x2it(result)};
    }

    if (left_type == LMD_TYPE_STRING || right_type == LMD_TYPE_STRING) {
        // null ++ string → string, string ++ null → string
        if (left_type == LMD_TYPE_NULL) return right;
        if (right_type == LMD_TYPE_NULL) return left;
        String *result = fn_concat_string_items(left, right);
        return {.item = s2it(result)};
    }
    else if (left_type == LMD_TYPE_SYMBOL || right_type == LMD_TYPE_SYMBOL) {
        // null ++ symbol → symbol, symbol ++ null → symbol
        if (left_type == LMD_TYPE_NULL) return right;
        if (right_type == LMD_TYPE_NULL) return left;
        String *result = fn_concat_string_items(left, right);
        // Symbol allocation is another safepoint before it copies the inline
        // characters from the intermediate String.
        RootFrame roots(1);
        Rooted<String*> rooted_result(roots, result);
        // Create a proper Symbol from the concatenated string
        result = rooted_result.get();
        Symbol* sym = heap_create_symbol(result->chars, result->len);
        return {.item = y2it(sym)};
    }
    if (left_type <= LMD_TYPE_BINARY && right_type <= LMD_TYPE_BINARY) {
        // scalar ++ scalar: convert both to string and concatenate
        if (left_type == LMD_TYPE_NULL) return right;
        if (right_type == LMD_TYPE_NULL) return left;
        String *result = fn_concat_string_items(left, right);
        return {.item = s2it(result)};
    }
    else {
        set_runtime_error(ERR_TYPE_MISMATCH, "fn_join: unsupported operand types: %s and %s",
            type_info[left_type].name, type_info[right_type].name);
        return ItemError;   // type mismatch
    }
}

// ---------------------------------------------------------------------------
// S10.1.1v2: `|`, `&` and `!` are the type operators, and only that. In a value
// expression they build a type from their operands -- a type operand is itself,
// a scalar reads as its literal type -- and never collapse: `1 | 2` is the type
// admitting 1 or 2, `1 | 1` is a type too, `int | null` is `int?`. The set
// algebra on containers these symbols once did is `unique`, `intersect` and
// `except` (lambda-vector.cpp). Type context never reaches here: the type
// parser builds those types.

// the payload behind a type value: a TypeType wrapper's type, else the type itself
static Type* type_op_payload(Type* type) {
    if (type && type->type_id == LMD_TYPE_TYPE && type->kind == TYPE_KIND_SIMPLE) {
        return ((TypeType*)type)->type;
    }
    return type;
}

// a String copied into the runtime pool, which a type value may hold
static String* type_op_pool_string(const char* chars, uint32_t len) {
    String* copy = (String*)pool_alloc(context->pool, sizeof(String) + len + 1);
    copy->len = len;
    copy->flags = 0;
    copy->is_ascii = str_is_ascii(chars, len);
    memcpy(copy->chars, chars, len);
    copy->chars[len] = 0;
    return copy;
}

// A scalar's literal type -- the type admitting exactly that value, as the
// builder makes for a literal in type position -- allocated in the runtime pool,
// since a type value is not GC-managed and must outlive the value it came from.
static Type* type_op_literal_type(Item value) {
    Pool* pool = context->pool;
    TypeId type_id = get_type_id(value);
    switch (type_id) {
    case LMD_TYPE_NULL:
        return &TYPE_NULL;
    case LMD_TYPE_BOOL:
        // the two bool literal types are static singletons (LR03-31)
        return value.bool_val ? (Type*)&LIT_BOOL_TRUE : (Type*)&LIT_BOOL_FALSE;
    case LMD_TYPE_DTIME: {
        // a DateTime is a value, so the literal type holds its own copy
        TypeDateTime* t = (TypeDateTime*)alloc_type(pool, LMD_TYPE_DTIME, sizeof(TypeDateTime));
        t->datetime = value.get_datetime();
        t->const_index = -1;
        t->is_literal = 1;
        return (Type*)t;
    }
    case LMD_TYPE_BINARY: {
        // the bytes are copied into the pool, as a binary literal's are
        Binary* source = value.get_binary();
        if (!source) return NULL;
        TypeBinaryConst* t = (TypeBinaryConst*)alloc_type(pool, LMD_TYPE_BINARY,
            sizeof(TypeBinaryConst));
        t->binary = pool_binary_from_bytes(pool, binary_data(source), binary_length(source));
        if (!t->binary) return NULL;
        t->const_index = -1;
        t->is_literal = 1;
        return (Type*)t;
    }
    case LMD_TYPE_INT: case LMD_TYPE_INT64: {
        int64_t v = 0;
        if (!lambda_item_to_int64_exact(value, &v)) return NULL;
        TypeInt64* t = (TypeInt64*)alloc_type(pool, type_id, sizeof(TypeInt64));
        t->int64_val = v;
        t->is_literal = 1;
        return (Type*)t;
    }
    case LMD_TYPE_FLOAT: {
        TypeFloat* t = (TypeFloat*)alloc_type(pool, LMD_TYPE_FLOAT, sizeof(TypeFloat));
        t->double_val = it2d(value);
        t->is_literal = 1;
        return (Type*)t;
    }
    case LMD_TYPE_STRING: case LMD_TYPE_SYMBOL: {
        const char* chars = value.get_chars();
        uint32_t len = value.get_len();
        if (!chars) return NULL;
        TypeString* t = (TypeString*)alloc_type(pool, type_id, sizeof(TypeString));
        if (type_id == LMD_TYPE_STRING) {
            t->string = type_op_pool_string(chars, len);
        } else {
            Symbol* copy = (Symbol*)pool_alloc(pool, sizeof(Symbol) + len + 1);
            memset(copy, 0, sizeof(Symbol));
            copy->len = len;
            copy->kind = SYMBOL_LAMBDA_NAME;
            memcpy(copy->chars, chars, len);
            copy->chars[len] = 0;
            t->string = (String*)copy;
        }
        t->is_literal = 1;
        return (Type*)t;
    }
    default:
        return NULL;
    }
}

// wraps a payload type as a type value, the way the builder does for type syntax
static Item type_op_value(Type* payload) {
    TypeType* wrapper = (TypeType*)alloc_type(context->pool, LMD_TYPE_TYPE, sizeof(TypeType));
    wrapper->type = payload;
    return (Item){.item = (uint64_t)(uintptr_t)wrapper};
}

// S10.1.1v2: a container operand reads as its literal type too -- the pattern
// its own literal spells in type position, so `let t = [1, 2] | 3` is the type
// `type T = [1, 2] | 3` names. It is built in the runtime pool: a scalar slot
// or field holds its literal value's pool copy, a nested container its own
// type, a type value itself, so the type keeps nothing of the GC heap.
static Type* type_op_operand_type(Item operand, int depth);

// one slot of a sequence pattern, filled as fill_sequence_pattern_slots does
// for type syntax: a scalar by value, anything else by type
static bool type_op_slot(Item element, int depth, Item* pattern, uint8_t* is_type) {
    TypeId type_id = get_type_id(element);
    if (type_id == LMD_TYPE_NULL) {
        *pattern = ItemNull;
        *is_type = 0;
        return true;
    }
    Type* slot = type_id == LMD_TYPE_TYPE ? element.type
        : type_op_operand_type(element, depth + 1);
    if (!slot) return false;
    Item literal;
    if (type_id != LMD_TYPE_TYPE && lambda_literal_contract_value(slot, &literal)) {
        *pattern = literal;
        *is_type = 0;
        return true;
    }
    pattern->type = type_id == LMD_TYPE_TYPE ? slot : type_op_value(slot).type;
    *is_type = 1;
    return true;
}

static TypeList* type_op_sequence_pattern(int64_t count) {
    Pool* pool = context->pool;
    TypeList* type = (TypeList*)alloc_type(pool, LMD_TYPE_ARRAY, sizeof(TypeList));
    type->type_index = -1;
    type->length = count;
    if (count > 0) {
        type->item_patterns = (Item*)pool_calloc(pool, sizeof(Item) * (size_t)count);
        type->item_is_type_pattern = (uint8_t*)pool_calloc(pool, (size_t)count);
    }
    return type;
}

// an array or list is the bracket pattern of its items, rows for an N-D array
static Type* type_op_sequence_type(Item value, int depth) {
    RootFrame roots(1);
    Rooted<Item> source(roots, vector_is_ndim(value) ? vector_unstack_rows(value) : value);
    int64_t count = vector_length(source.get());
    if (count < 0) return NULL;
    TypeList* type = type_op_sequence_pattern(count);
    for (int64_t i = 0; i < count; i++) {
        if (!type_op_slot(vector_get(source.get(), i), depth, &type->item_patterns[i],
                &type->item_is_type_pattern[i])) return NULL;
    }
    return (Type*)type;
}

// a map's fields, or an element's attributes, as a shape of per-field types;
// the names are copied, since a key list's symbols are GC values
static bool type_op_fill_fields(TypeMap* type, Item source, int depth) {
    SymbolKeyList* keys = item_keys(source);
    int64_t count = keys ? symbol_key_list_len(keys) : 0;
    bool ok = true;
    for (int64_t i = 0; i < count && ok; i++) {
        Symbol* key = symbol_key_list_at(keys, i);
        Item field = item_attr(source, key->chars);
        Type* field_type = get_type_id(field) == LMD_TYPE_NULL ? &TYPE_NULL
            : get_type_id(field) == LMD_TYPE_TYPE ? type_op_payload(field.type)
            : type_op_operand_type(field, depth + 1);
        if (!field_type) { ok = false; break; }
        String* name_chars = type_op_pool_string(key->chars, key->len);
        StrView* name = (StrView*)pool_calloc(context->pool, sizeof(StrView));
        ShapeEntry* entry = (ShapeEntry*)pool_calloc(context->pool, sizeof(ShapeEntry));
        name->str = name_chars->chars;
        name->length = key->len;
        entry->name = name;
        shape_entry_set_type(entry, field_type);
        if (type->last) type->last->chain_next = entry;
        else type->shape = entry;
        type->last = entry;
        type->length++;
    }
    if (keys) symbol_key_list_free(keys);
    return ok;
}

static Type* type_op_map_type(Item value, int depth) {
    RootFrame roots(1);
    Rooted<Item> source(roots, value);
    TypeMap* type = (TypeMap*)alloc_type(context->pool, LMD_TYPE_MAP, sizeof(TypeMap));
    type->type_index = -1;
    return type_op_fill_fields(type, source.get(), depth) ? (Type*)type : NULL;
}

// an element is its tag, its attributes and, as a content section, its
// children (S11.1.6v3); with no children the content stays open, as `<br>` in
// type position leaves it
static Type* type_op_element_type(Item value, int depth) {
    RootFrame roots(1);
    Rooted<Item> source(roots, value);
    Element* element = value.element;
    TypeElmt* source_type = (TypeElmt*)element->type;
    TypeElmt* type = (TypeElmt*)alloc_type(context->pool, LMD_TYPE_ELEMENT, sizeof(TypeElmt));
    type->type_index = -1;
    if (source_type && source_type->name.length) {
        String* tag = type_op_pool_string(source_type->name.str, (uint32_t)source_type->name.length);
        type->name.str = tag->chars;
        type->name.length = source_type->name.length;
        type->name_id = source_type->name_id;
        type->ns = source_type->ns;
    }
    if (!type_op_fill_fields(type, source.get(), depth)) return NULL;
    int64_t count = ((List*)source.get().element)->length;
    if (count > 0) {
        TypeList* content = type_op_sequence_pattern(count);
        for (int64_t i = 0; i < count; i++) {
            if (!type_op_slot(list_get((List*)source.get().element, i), depth,
                    &content->item_patterns[i], &content->item_is_type_pattern[i])) return NULL;
        }
        type->content_list = content;
    }
    return (Type*)type;
}

// a range value is the range type of its bounds, as `is` already reads one (S11.1.3)
static Type* type_op_range_type(Item value) {
    Range* range = value.range;
    TypeRange* type = (TypeRange*)alloc_type_kind(context->pool, TYPE_KIND_RANGE,
        sizeof(TypeRange));
    type->is_char = range->is_char;
    if (!range->is_char) {
        type->start = (Item){.item = i2it(range->start)};
        type->end = (Item){.item = i2it(range->end)};
        return (Type*)type;
    }
    char first[8], last[8];
    size_t first_len = str_utf8_encode((uint32_t)range->start, first, sizeof(first));
    size_t last_len = str_utf8_encode((uint32_t)range->end, last, sizeof(last));
    type->start = (Item){.item = s2it(type_op_pool_string(first, (uint32_t)first_len))};
    type->end = (Item){.item = s2it(type_op_pool_string(last, (uint32_t)last_len))};
    return (Type*)type;
}

static Type* type_op_operand_type(Item operand, int depth) {
    if (depth > 64) return NULL;
    TypeId type_id = get_type_id(operand);
    // a nominal object's identity is not a literal pattern: unruled, so refused
    if ((type_id == LMD_TYPE_MAP || type_id == LMD_TYPE_ELEMENT) &&
            lambda_value_nominal(type_id, (const void*)(uintptr_t)operand.item)) {
        return NULL;
    }
    switch (type_id) {
    case LMD_TYPE_ARRAY: case LMD_TYPE_ARRAY_NUM:
        return type_op_sequence_type(operand, depth);
    case LMD_TYPE_MAP:
        return type_op_map_type(operand, depth);
    case LMD_TYPE_ELEMENT:
        return type_op_element_type(operand, depth);
    case LMD_TYPE_RANGE:
        return type_op_range_type(operand);
    default:
        return type_op_literal_type(operand);
    }
}

// the type an operand stands for: a type's payload, any other value's literal type
static Type* type_op_arm(Item operand) {
    if (get_type_id(operand) == LMD_TYPE_TYPE) return type_op_payload(operand.type);
    Type* literal = type_op_operand_type(operand, 0);
    if (!literal) {
        log_error("type operation: no literal type for a %s operand",
            get_type_name(get_type_id(operand)));
    }
    return literal;
}

static Item type_op_binary_type(Item left_item, Item right_item, Operator op) {
    // reading a container operand's literal type can allocate (its keys and
    // values), so both operands stay rooted until the result is built
    RootFrame roots(2);
    Rooted<Item> left_root(roots, left_item);
    Rooted<Item> right_root(roots, right_item);
    Item left = left_root.get();
    Item right = right_root.get();
    Type* left_arm = type_op_arm(left);
    Type* right_arm = type_op_arm(right);
    if (!left_arm || !right_arm) return ItemError;
    // S11.1.7: an operation that reduces is `none`, or the operand that `none`
    // leaves -- a type operand is itself, a scalar reads as its literal type
    if (Type* reduced = lambda_type_operation_reduced(left_arm, right_arm, op)) {
        if (reduced == &TYPE_NONE) return (Item){.item = (uint64_t)(uintptr_t)&LIT_TYPE_NONE};
        Item operand = reduced == left_arm ? left : right;
        return get_type_id(operand) == LMD_TYPE_TYPE ? operand : type_op_value(reduced);
    }
    TypeBinary* binary = (TypeBinary*)alloc_type_kind(context->pool, TYPE_KIND_BINARY,
        sizeof(TypeBinary));
    binary->left = left_arm;
    binary->right = right_arm;
    binary->op = op;
    return type_op_value((Type*)binary);
}

Item fn_union(Item left, Item right) {
    GUARD_ERROR2(left, right);
    return type_op_binary_type(left, right, OPERATOR_UNION);
}

Item fn_intersect(Item left, Item right) {
    GUARD_ERROR2(left, right);
    return type_op_binary_type(left, right, OPERATOR_INTERSECT);
}

Item fn_exclude(Item left, Item right) {
    GUARD_ERROR2(left, right);
    return type_op_binary_type(left, right, OPERATOR_EXCLUDE);
}


String *str_repeat(String *str, int64_t times) {
    if (times <= 0 || !str->len) {
        // Return empty string
        String *result = (String *)heap_alloc(sizeof(String) + 1, LMD_TYPE_STRING);
        if (!result) return NULL;
        result->len = 0;
        result->flags = 0;
        result->is_ascii = 1;
        result->chars[0] = '\0';
        return result;
    }

    size_t str_len = str->len;
    size_t total_len;
    // guard str_len * times and the allocation size against overflow / heap_alloc's int param.
    if (!lam::checked_mul(str_len, (size_t)times, &total_len) ||
        total_len + sizeof(String) + 1 > (size_t)INT_MAX) {
        return NULL;
    }
    // the source must survive result allocation even for callers holding only a raw pointer.
    RootFrame roots(1);
    if (!roots.valid()) return NULL;
    Rooted<String*> source(roots, str);
    String *result = (String *)heap_alloc((int)(sizeof(String) + total_len + 1), LMD_TYPE_STRING);
    if (!result) return NULL;
    str = source.get();
    result->len = total_len;
    result->flags = 0;
    result->is_ascii = str->is_ascii;

    for (long i = 0; i < times; i++) {
        memcpy(result->chars + (i * str_len), str->chars, str_len);
    }
    result->chars[total_len] = '\0';

    return result;
}

// Unicode string normalization function
Item fn_normalize(Item str_item, Item type_item) {
    // an error mode must not be mistaken for an omitted mode and silently default to NFC
    GUARD_ERROR2(str_item, type_item);
    // normalize(string, 'nfc'|'nfd'|'nfkc'|'nfkd') - Unicode normalization
    if (str_item._type_id != LMD_TYPE_STRING) {
        log_debug("normalize: first argument must be a string, got type: %s", get_type_name(str_item._type_id));
        return ItemError;
    }

    String* str = str_item.get_safe_string();
    if (!str || str->len == 0) {
        return str_item;  // Return empty string as-is
    }

    // Default to NFC if no type specified or invalid type
    int options = UTF8PROC_STABLE | UTF8PROC_COMPOSE;

    if (type_item._type_id == LMD_TYPE_STRING) {
        String* type_str = type_item.get_safe_string();
        if (type_str && type_str->len > 0) {
            if (strncmp(type_str->chars, "nfd", 3) == 0) {
                options = UTF8PROC_STABLE | UTF8PROC_DECOMPOSE;
            } else if (strncmp(type_str->chars, "nfkc", 4) == 0) {
                options = UTF8PROC_STABLE | UTF8PROC_COMPOSE | UTF8PROC_COMPAT;
            } else if (strncmp(type_str->chars, "nfkd", 4) == 0) {
                options = UTF8PROC_STABLE | UTF8PROC_DECOMPOSE | UTF8PROC_COMPAT;
            }
            // Default case (nfc) already set above
        }
    }

    // Use utf8proc for Unicode normalization
    utf8proc_uint8_t* normalized = NULL;
    utf8proc_ssize_t normalized_len = utf8proc_map(
        (const utf8proc_uint8_t*)str->chars, str->len, &normalized, (utf8proc_option_t)options);

    if (normalized_len < 0) {
        log_debug("normalize: utf8proc_map failed with error: %zd", normalized_len);
        return ItemError;
    }

    // Create new string with normalized content
    String* result = heap_strcpy((const char*)normalized, normalized_len);

    // utf8proc_map allocates outside Lambda memtrack; keep the allocator pair matched.
    free_utf8proc_result((char*)normalized);
    return (Item){.item = s2it(result)};
}

static bool item_single_string_codepoint(Item item, uint32_t* codepoint) {
    if (!codepoint || get_type_id(item) != LMD_TYPE_STRING) return false;
    const char* chars = item.get_chars();
    uint32_t length = item.get_len();
    if (!chars || length == 0) return false;
    uint32_t value = 0;
    int decoded = str_utf8_decode(chars, length, &value);
    if (decoded <= 0 || (uint32_t)decoded != length) return false;
    *codepoint = value;
    return true;
}

static bool range_contains_item(Range* range, Item item) {
    if (!range) return false;
    if (range->is_char) {
        uint32_t codepoint = 0;
        return item_single_string_codepoint(item, &codepoint) &&
            range->start <= (int64_t)codepoint && (int64_t)codepoint <= range->end;
    }
    int64_t value = 0;
    return lambda_item_to_int64_exact(item, &value) &&
        range->start <= value && value <= range->end;
}

bool lambda_range_type_bounds(const Type* range_type, int64_t* start, int64_t* end) {
    if (!lambda_type_is_range(range_type) || !start || !end) return false;
    const TypeRange* range = (const TypeRange*)range_type;
    if (range->is_char) {
        uint32_t first = 0;
        uint32_t last = 0;
        if (!item_single_string_codepoint(range->start, &first) ||
                !item_single_string_codepoint(range->end, &last)) return false;
        *start = first;
        *end = last;
        return true;
    }
    return lambda_item_to_int64_exact(range->start, start) &&
        lambda_item_to_int64_exact(range->end, end);
}

bool lambda_range_type_position(const Type* range_type, Item item, int64_t* position) {
    if (!lambda_type_is_range(range_type) || !position) return false;
    if (((const TypeRange*)range_type)->is_char) {
        uint32_t codepoint = 0;
        if (!item_single_string_codepoint(item, &codepoint)) return false;
        *position = codepoint;
        return true;
    }
    return lambda_item_to_int64_exact(item, position);
}

// The one membership test for a range type: `is`, boundary admission and the
// schema validator all answer through it (S11.1.3).
bool lambda_range_type_contains(const Type* range_type, Item item) {
    int64_t start = 0;
    int64_t end = 0;
    int64_t value = 0;
    return lambda_range_type_bounds(range_type, &start, &end) &&
        lambda_range_type_position(range_type, item, &value) &&
        start <= value && value <= end;
}

// One owner for the bad-range-bound diagnosis. The JIT's counted-range lowering
// (T19-3) re-checks the int53 band itself, because its bounds arrive in the
// TOTAL int lane where a saturated or null value is an ordinary i64 sentinel;
// its cold arm reports through here so the message never forks from fn_to's.
Item fn_range_bound_error(Item item_a, Item item_b) {
    log_error("fn_to: range bounds must be exact integers or single-codepoint strings, got %s, %s",
        get_type_name(get_type_id(item_a)), get_type_name(get_type_id(item_b)));
    return ItemError;
}

Item fn_to(Item item_a, Item item_b) {
    GUARD_ERROR2(item_a, item_b);
    int64_t start = 0;
    int64_t end = 0;
    if (lambda_item_to_int64_exact(item_a, &start) &&
            lambda_item_to_int64_exact(item_b, &end)) {
        // Formal semantics 4.8: an `int` range requires its bounds within
        // +/-(2^53 - 1). A range is a sequence of CONSECUTIVE integers, so it
        // needs a well-defined successor -- x + 1 must differ from x -- which
        // in binary64 holds precisely to 2^53. Above it the spacing exceeds 1,
        // consecutive integers no longer all exist, and the request stops
        // denoting a sequence: at 2^70 the spacing is 2^18, so `big to big + 2`
        // silently yielded a one-element range. Refuse rather than guess; a
        // larger sequence is written `1n to N` over `integer`, which is exact
        // at every magnitude. This is also what keeps start/end/length proven
        // i64 (plan item G3), so `Range` needs no widening.
        if (start < INT53_MIN || start > INT53_MAX ||
                end < INT53_MIN || end > INT53_MAX) {
            set_runtime_error(ERR_INDEX_OUT_OF_BOUNDS,
                "int range bound outside +/-(2^53 - 1); use an `integer` range "
                "(`1n to N`) for larger sequences");
            return ItemError;
        }
        if (start > end) {
            // return empty range instead of NULL
            log_debug("Error: start of range is greater than end: %ld > %ld", start, end);
            Range *range = (Range *)heap_alloc(sizeof(Range), LMD_TYPE_RANGE);
            range->type_id = LMD_TYPE_RANGE;
            range->start = 0;  range->end = -1;  // Empty range
            range->length = 0;
            range->is_char = false;
            return {.range = range};
        }
        Range *range = (Range *)heap_alloc(sizeof(Range), LMD_TYPE_RANGE);
        range->type_id = LMD_TYPE_RANGE;
        range->start = start;  range->end = end;
        range->length = end - start + 1;
        range->is_char = false;
        return {.range = range};
    }

    uint32_t char_start = 0;
    uint32_t char_end = 0;
    if (item_single_string_codepoint(item_a, &char_start) &&
            item_single_string_codepoint(item_b, &char_end)) {
        Range* range = (Range*)heap_alloc(sizeof(Range), LMD_TYPE_RANGE);
        range->type_id = LMD_TYPE_RANGE;
        range->is_char = true;
        if (char_start > char_end) {
            range->start = 0;
            range->end = -1;
            range->length = 0;
        } else {
            range->start = (int64_t)char_start;
            range->end = (int64_t)char_end;
            range->length = (int64_t)char_end - (int64_t)char_start + 1;
        }
        return {.range = range};
    }
    else {
        return fn_range_bound_error(item_a, item_b);
    }
}

Function* to_fn(fn_ptr ptr) {
    Function *fn = (Function*)heap_calloc(sizeof(Function), LMD_TYPE_FUNC);
    function_init_abi(fn, LMD_TYPE_FUNC, FN_ENTRY_ABI_UNKNOWN);
    fn->ptr = ptr;
    fn->closure_env = NULL;
    return fn;
}

// Create function with arity info
Function* to_fn_n(fn_ptr ptr, int arity) {
    Function *fn = (Function*)heap_calloc(sizeof(Function), LMD_TYPE_FUNC);
    function_init_abi(fn, LMD_TYPE_FUNC, FN_ENTRY_ABI_UNKNOWN);
    fn->arity = (uint8_t)arity;
    fn->ptr = ptr;
    fn->closure_env = NULL;
    fn->name = NULL;
    return fn;
}

// Create function with arity and name for stack traces
Function* to_fn_named(fn_ptr ptr, int arity, const char* name) {
    Function *fn = (Function*)heap_calloc(sizeof(Function), LMD_TYPE_FUNC);
    function_init_abi(fn, LMD_TYPE_FUNC, FN_ENTRY_ABI_UNKNOWN);
    fn->arity = (uint8_t)arity;
    fn->ptr = ptr;
    fn->closure_env = NULL;
    fn->name = name;  // should be interned string, no need to copy
    return fn;
}

Function* to_sys_fn_named(fn_ptr ptr, int arity, const char* name) {
    Function *fn = to_fn_named(ptr, arity, name);
    // builtin C functions have heterogeneous ABIs; this value is for identity/name.
    fn->is_system_function_ref = 1;
    fn->entry_abi = FN_ENTRY_ABI_FOREIGN;
    return fn;
}

void lambda_function_mark_mir_context_abi(Function* fn) {
    if (!fn) return;
    Context* runtime = (Context*)context;
    if (!runtime) {
        log_error("mir-context-abi: missing TLS owner while publishing function");
        return;
    }
    // A generated Function may outlive its creating activation. Capture the
    // TLS owner here so later native dispatch can forward it only to MIR code.
    fn->requires_runtime_context = 1;
    fn->runtime_context = runtime;
}

void lambda_function_mark_lambda_boxed_function(Function* fn) {
    if (!fn) return;
    fn->entry_abi = FN_ENTRY_ABI_LAMBDA_BOXED_FUNCTION;
}

void lambda_function_mark_lambda_boxed_procedure(Function* fn) {
    if (!fn) return;
    fn->entry_abi = FN_ENTRY_ABI_LAMBDA_BOXED_PROCEDURE;
}

void lambda_function_mark_mir_public_return_shape(Function* fn, uint32_t shape) {
    if (!fn) return;
    // Unknown remains fail-closed: a missed publication site must resolve the
    // slot rather than let a pending Item cross a dynamic call boundary.
    if (shape > LAMBDA_MIR_PUBLIC_RETURN_ITEM_COMPANION) {
        shape = LAMBDA_MIR_PUBLIC_RETURN_UNKNOWN;
    }
    fn->mir_public_return_shape = shape;
}

void lambda_function_set_type(Function* fn, void* fn_type) {
    if (!fn) return;
    // First-class calls need the semantic signature for optional and variadic
    // arity checks. The source TypeFunc outlives the compiled module, so this
    // records metadata only; it never changes the function's physical ABI.
    fn->fn_type = fn_type;
}

// S12.1.1/S11.1.5: a function value's colour is its signature's effect bit.
// Hosted entries reuse this storage under their own layout, so only a Lambda
// signature is read; a value without one is not a Lambda `pn`.
static bool lambda_function_is_proc(const Function* fn) {
    if (!fn || fn->entry_abi >= FN_ENTRY_ABI_HOSTED_FIRST) return false;
    const TypeFunc* signature = (const TypeFunc*)fn->fn_type;
    return signature && signature->type_id == LMD_TYPE_FUNC && signature->is_proc;
}

// S11.1.5: `function` admits both colours; every other function type admits
// only its own, so a `pn` never crosses an `fn` contract (S12.1.1). Shared by
// `is` and boundary admission so the two cannot disagree.
static bool lambda_function_admitted(Item item, TypeId actual_id, Type* expected) {
    if (actual_id != LMD_TYPE_FUNC) return false;
    return expected == &TYPE_FUNC ||
        lambda_function_is_proc(item.function) == lambda_type_func_is_proc(expected);
}

static bool lambda_item_is_proc(Item item) {
    return get_type_id(item) == LMD_TYPE_FUNC && lambda_function_is_proc(item.function);
}

// one wording for both tiers: the JIT checks a direct call's argument without
// the callee in hand, so the argument case never names it
#define LAMBDA_COLOUR_ARG_DETAIL "a pn argument makes this call a pn call"

static Item lambda_fn_colour_error(const char* detail) {
    set_runtime_error(ERR_PROC_IN_FN,
        "cannot call a procedure (pn) from a function (fn): %s", detail);
    return ItemError;
}

// S12.1.4v2(3): an `fn`-context call whose colour was not resolved statically.
// A `pn` callee is refused when asked (a dynamic callee); a `function` callee
// is refused when a masked argument lands in one of its polymorphic slots as a
// `pn`, since that would make the call itself a `pn` call.
extern "C" Item lambda_fn_colour_guard(Function* fn, const Item* args, int argc,
        uint32_t guard) {
    if (!fn || !guard) return ItemNull;
    if ((guard & LAMBDA_COLOUR_GUARD_CALLEE) && lambda_function_is_proc(fn)) {
        return lambda_fn_colour_error(fn->name ? fn->name : "anonymous procedure");
    }
    if (fn->entry_abi >= FN_ENTRY_ABI_HOSTED_FIRST) return ItemNull;
    const TypeFunc* signature = (const TypeFunc*)fn->fn_type;
    if (!signature || signature->type_id != LMD_TYPE_FUNC ||
            !signature->is_colour_poly || !args) return ItemNull;
    int index = 0;
    for (const TypeParam* param = signature->param; param && index < argc &&
            index < 16; param = param->next, index++) {
        if ((guard & (1u << index)) && lambda_type_param_is_colour_poly(param) &&
                lambda_item_is_proc(args[index])) {
            return lambda_fn_colour_error(LAMBDA_COLOUR_ARG_DETAIL);
        }
    }
    return ItemNull;
}

// The JIT's dynamic-call form, emitted only at a colour-guarded call site so
// the general dispatch path carries no colour work at all.
extern "C" Item lambda_fn_colour_guard_list(Item callee, List* args, uint32_t guard) {
    if (get_type_id(callee) != LMD_TYPE_FUNC) return ItemNull;  // dispatch reports it
    return lambda_fn_colour_guard(callee.function, args ? args->items : NULL,
        args ? (int)args->length : 0, guard);
}

// The JIT's per-arity form (at most three arguments, no list is built).
extern "C" Item lambda_fn_colour_guard_args(Item callee, uint32_t guard, int argc,
        Item a, Item b, Item c) {
    if (get_type_id(callee) != LMD_TYPE_FUNC) return ItemNull;  // dispatch reports it
    Item args[3] = {a, b, c};
    return lambda_fn_colour_guard(callee.function, args, argc < 3 ? argc : 3, guard);
}

// The direct-call form: the caller already resolved the callee, so each
// guarded argument is known to fill a polymorphic slot (S12.1.4v2(3)).
extern "C" Item lambda_fn_colour_arg_check(Item argument) {
    return lambda_item_is_proc(argument)
        ? lambda_fn_colour_error(LAMBDA_COLOUR_ARG_DETAIL) : argument;
}

// Create a closure with captured environment
Function* to_closure(fn_ptr ptr, int arity, void* env) {
    Function* fn = (Function*)heap_calloc(sizeof(Function), LMD_TYPE_FUNC);
    function_init_abi(fn, LMD_TYPE_FUNC, FN_ENTRY_ABI_UNKNOWN);
    fn->fn_type = NULL;
    fn->arity = (uint8_t)arity;
    fn->closure_field_count = 0;  // caller sets after creation if env has Item fields
    fn->ptr = ptr;
    fn->closure_env = env;
    fn->name = NULL;
    return fn;
}

// Create a closure with captured environment and name for stack traces
Function* to_closure_named(fn_ptr ptr, int arity, void* env, const char* name) {
    Function* fn = (Function*)heap_calloc(sizeof(Function), LMD_TYPE_FUNC);
    function_init_abi(fn, LMD_TYPE_FUNC, FN_ENTRY_ABI_UNKNOWN);
    fn->fn_type = NULL;
    fn->arity = (uint8_t)arity;
    fn->closure_field_count = 0;  // caller sets after creation if env has Item fields
    fn->ptr = ptr;
    fn->closure_env = env;
    fn->name = name;  // should be interned string, no need to copy
    return fn;
}

// Helper to validate that an Item is actually a function
// When Items are passed to fn_call*, they get cast to Function*
// We need to check if this is a valid pointer to a Function struct
static inline bool is_valid_function(Function* fn) {
    if (!fn) return false;

    // Check if this looks like a tagged Item value rather than a real pointer
    // Tagged Items have the type_id in the high byte (bits 56-63)
    // Valid heap pointers have the high byte as 0 on most platforms
    uint64_t val = (uint64_t)fn;
    uint8_t high_byte = (val >> 56) & 0xFF;
    if (high_byte != 0) {
        // This is a tagged value (like ItemError), not a valid pointer
        return false;
    }

    // Reject small values that can't be valid heap pointers
    // Typical heap addresses are well above 4KB (first page is reserved)
    // On most systems, valid heap addresses are > 0x10000
    if (val < 0x10000) {
        return false;
    }

    // Now safe to dereference - check that type_id matches Function
    TypeId type_id = *(TypeId*)fn;
    return type_id == LMD_TYPE_FUNC;
}


typedef enum LambdaDynamicCallMode {
    LAMBDA_DYNAMIC_CALL_FUNCTION,
    LAMBDA_DYNAMIC_CALL_PROCEDURE,
    // T21-3b (CW33, D8.1.1v6): a function-mode call whose caller has already
    // published the borrowed `var` homes in Context::mir_var_homes, so a
    // signature with untyped `var` parameters is dispatchable -- the callee
    // (generated prologue or interp_call) consumes the cells and writes the
    // final parameter values back through them.
    LAMBDA_DYNAMIC_CALL_BORROWED,
} LambdaDynamicCallMode;

static Item lambda_dynamic_call_error(LambdaErrorCode code, const char* caller,
        const char* detail) {
    char message[256];
    snprintf(message, sizeof(message), "%s: %s", caller, detail);
    return runtime_error_item(code, message, NULL);
}

static Item lambda_dynamic_argument_limit_error(const char* caller, int64_t count,
        const char* kind) {
    char detail[192];
    snprintf(detail, sizeof(detail), "%s count %lld exceeds Core Lambda limit %d",
        kind, (long long)count, LAMBDA_MAX_FUNCTION_ARGS);
    return lambda_dynamic_call_error(ERR_FUNCTION_ARGUMENT_LIMIT, caller, detail);
}

static bool lambda_dynamic_abi_is_core(FunctionEntryAbi abi) {
    // The interpreted entry is a Core Lambda callable too: it carries the same
    // TypeFunc signature and needs the same optional/rest adaptation. Only its
    // final invocation differs (AI7).
    return abi == FN_ENTRY_ABI_LAMBDA_BOXED_FUNCTION ||
        abi == FN_ENTRY_ABI_LAMBDA_BOXED_PROCEDURE ||
        abi == FN_ENTRY_ABI_LAMBDA_INTERPRETED;
}

static bool lambda_dynamic_signature_has_var_parameter(const TypeFunc* signature) {
    if (!signature) return false;
    for (const TypeParam* param = signature->param; param; param = param->next) {
        if (param->is_var_param) return true;
    }
    return false;
}

static Item lambda_dynamic_check_signature(Function* fn, int actual,
        LambdaDynamicCallMode mode, const char* caller, int* physical_count,
        bool* needs_adapter) {
    if (actual > LAMBDA_MAX_FUNCTION_ARGS) {
        return lambda_dynamic_argument_limit_error(caller, actual, "argument");
    }
    if (fn->arity > LAMBDA_MAX_FUNCTION_ARGS) {
        return lambda_dynamic_argument_limit_error(caller, fn->arity, "function arity");
    }
    TypeFunc* signature = (TypeFunc*)fn->fn_type;
    if ((mode == LAMBDA_DYNAMIC_CALL_FUNCTION || mode == LAMBDA_DYNAMIC_CALL_BORROWED) &&
            !lambda_dynamic_abi_is_core(fn->entry_abi) &&
            fn->entry_abi != FN_ENTRY_ABI_HOST_ADAPTER) {
        // Procedure methods are boxed entries too; ordinary object.method()
        // reaches this function-mode dispatcher even when the method is `pn`.
        return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
            "dynamic expression call requires a boxed Lambda callable entry");
    }
    if (mode == LAMBDA_DYNAMIC_CALL_PROCEDURE &&
            fn->entry_abi != FN_ENTRY_ABI_LAMBDA_BOXED_PROCEDURE &&
            !(fn->entry_abi == FN_ENTRY_ABI_LAMBDA_INTERPRETED &&
              signature && signature->is_proc)) {
        // T0 procedures retain their source entry until the scheduler invokes
        // it; rejecting them here leaves `start` and `run pn main` tier-only.
        return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
            "task launch requires a Lambda procedure entry");
    }
    if (!fn->ptr && fn->entry_abi != FN_ENTRY_ABI_LAMBDA_INTERPRETED) {
        return lambda_dynamic_call_error(ERR_INVALID_CALL, caller,
            "function has no native entry");
    }
    if (fn->is_system_function_ref) {
        return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
            "builtin references do not expose the boxed dynamic-call ABI");
    }

    if (lambda_dynamic_abi_is_core(fn->entry_abi) &&
            (!signature || signature->type_id != LMD_TYPE_FUNC) &&
            mode != LAMBDA_DYNAMIC_CALL_PROCEDURE) {
        // A Core boxed pointer without its semantic signature cannot safely
        // materialize optional/rest slots or reject mutable parameters.
        return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
            "boxed Lambda entry is missing its function signature");
    }

    int required = fn->arity;
    int fixed = fn->arity;
    bool variadic = false;
    if (signature && signature->type_id == LMD_TYPE_FUNC) {
        if (lambda_dynamic_signature_has_var_parameter(signature) &&
                mode != LAMBDA_DYNAMIC_CALL_BORROWED) {
            return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
                "dynamic dispatch of a function with `var` parameters is deferred");
        }
        required = signature->required_param_count;
        fixed = signature->param_count;
        variadic = signature->is_variadic;
    } else if (lambda_dynamic_abi_is_core(fn->entry_abi)) {
        // Async task root lowering has a generated procedure wrapper but no
        // source TypeFunc in its scheduler frame. It has no optional/rest
        // adapter; retain the exact fixed arity supplied by the launcher.
        fixed = fn->arity;
    }
    int physical = fixed + (variadic ? 1 : 0);
    if (physical > LAMBDA_MAX_FUNCTION_ARGS) {
        return lambda_dynamic_argument_limit_error(caller, physical, "formal slot");
    }
    if (fn->entry_abi == FN_ENTRY_ABI_HOST_ADAPTER && fn->closure_env &&
            physical >= LAMBDA_MAX_FUNCTION_ARGS) {
        return lambda_dynamic_argument_limit_error(caller, physical + 1,
            "hosted native argument");
    }
    if (actual < required || (!variadic && actual > fixed)) {
        char detail[192];
        snprintf(detail, sizeof(detail), "function '%s' expects %d%s argument%s, got %d",
            fn->name ? fn->name : "<anonymous>", required,
            variadic ? " or more" : "", required == 1 && !variadic ? "" : "s", actual);
        return lambda_dynamic_call_error(ERR_ARGUMENT_COUNT_MISMATCH, caller, detail);
    }
    if (fn->entry_abi == FN_ENTRY_ABI_HOST_ADAPTER &&
            (variadic || actual != fixed)) {
        return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
            "host adapter does not expose optional or rest argument adaptation");
    }
    *physical_count = physical;
    *needs_adapter = variadic || actual < fixed;
    return ItemNull;
}

static Item lambda_dynamic_invoke_host_adapter(Function* fn, const Item* args,
        int count, const char* caller) {
    // hosted callbacks use the shared Item-only ABI.  A legacy closure
    // environment is normalized as the first explicit Item so Core and JS do
    // not cast the same callback through different hidden-prefix prototypes.
    int native_count = count + (fn->closure_env ? 1 : 0);
    if (native_count > LAMBDA_MAX_FUNCTION_ARGS) {
        return lambda_dynamic_argument_limit_error(caller, native_count,
            "hosted native argument");
    }
    Item env_item = (Item){.item = (uint64_t)(uintptr_t)fn->closure_env};
    return lambda_hosted_item_invoke_by_count((void*)fn->ptr,
        args, count, fn->closure_env != NULL, env_item);
}

template <typename IndexSequence>
struct LambdaDynamicNativeInvoker;

template <int... indices>
struct LambdaDynamicNativeInvoker<LambdaHostedItemIndexSequence<indices...>> {
    static Item resolve_public_result(Function* fn, Item value) {
        if (fn && fn->mir_public_return_shape ==
                LAMBDA_MIR_PUBLIC_RETURN_ITEM) {
            return value;
        }
        return lambda_item_resolve_pending_slot(value);
    }

    static Item invoke(Function* fn, const Item* args, uint64_t* result_home,
            const char* caller) {
        // A published Core entry must retain its hidden context operand. This
        // blocks raw/native bodies from being reinterpreted as boxed calls —
        // and return convention v3 (RVO3) leans on it, because the casts below
        // are single-result C prototypes and must never be applied to a
        // pair-returning body.
        //
        // The compiled wrapper hands lane 2 back through
        // `Context::mir_companion_slot` (RV12), so its result is resolved
        // after the call rather than receiving caller-owned storage first.
        if (!fn->requires_runtime_context) {
            return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
                "boxed Lambda entry is missing its context ABI metadata");
        }
        (void)result_home;
        Context* runtime = fn->runtime_context;
        if (!runtime) {
            return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
                "boxed Lambda entry has no owning runtime context");
        }
        if (eval_context_tls_runtime() != runtime) {
            return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
                "boxed Lambda entry belongs to a different runtime context");
        }
        // RV12: no trailing home operand; resolve lane 2 from the context slot
        // immediately, before anything else can clobber it (RV4.2).
        if (fn->closure_env) {
            return resolve_public_result(fn,
                ((Item (*)(Context*, void*, LambdaHostedItem<indices>...))fn->ptr)(
                    runtime, fn->closure_env, args[indices]...));
        }
        return resolve_public_result(fn,
            ((Item (*)(Context*, LambdaHostedItem<indices>...))fn->ptr)(
                runtime, args[indices]...));
    }
};

template <int count>
static Item lambda_dynamic_invoke_native(Function* fn, const Item* args,
        uint64_t* result_home, const char* caller) {
    typedef typename LambdaHostedMakeIndexSequence<count>::Type Indices;
    return LambdaDynamicNativeInvoker<Indices>::invoke(fn, args, result_home, caller);
}

static Item lambda_dynamic_invoke_by_count(Function* fn, const Item* args,
        int count, uint64_t* result_home, const char* caller,
        LambdaDynamicCallMode mode) {
    if (fn->entry_abi == FN_ENTRY_ABI_HOST_ADAPTER) {
        return lambda_dynamic_invoke_host_adapter(fn, args, count, caller);
    }
    if (fn->entry_abi == FN_ENTRY_ABI_LAMBDA_INTERPRETED) {
        // T0 values retain the source entry until this one dispatch boundary.
        // Upgrade before selecting a C prototype: a published satellite uses
        // the ordinary generated boxed ABI, while a cold/pinned definition
        // must keep the exact interpreter call path (D8.1.1v2 §5.3).
        if (!interp_promote_function_if_hot(fn)) {
            // the borrowed mode's homes are consumed by the interpreted
            // prologue the way the generated prologue consumes them
            return mode == LAMBDA_DYNAMIC_CALL_BORROWED
                ? interp_call_borrowed(fn, args, count)
                : interp_call(fn, args, count);
        }
    }
    // This is the Core boxed ABI dispatch; hosted native callbacks use the
    // shared Item-only switch in hosted-call-dispatch.hpp above.
    switch (count) {
    case 0: return lambda_dynamic_invoke_native<0>(fn, args, result_home, caller);
    case 1: return lambda_dynamic_invoke_native<1>(fn, args, result_home, caller);
    case 2: return lambda_dynamic_invoke_native<2>(fn, args, result_home, caller);
    case 3: return lambda_dynamic_invoke_native<3>(fn, args, result_home, caller);
    case 4: return lambda_dynamic_invoke_native<4>(fn, args, result_home, caller);
    case 5: return lambda_dynamic_invoke_native<5>(fn, args, result_home, caller);
    case 6: return lambda_dynamic_invoke_native<6>(fn, args, result_home, caller);
    case 7: return lambda_dynamic_invoke_native<7>(fn, args, result_home, caller);
    case 8: return lambda_dynamic_invoke_native<8>(fn, args, result_home, caller);
    case 9: return lambda_dynamic_invoke_native<9>(fn, args, result_home, caller);
    case 10: return lambda_dynamic_invoke_native<10>(fn, args, result_home, caller);
    case 11: return lambda_dynamic_invoke_native<11>(fn, args, result_home, caller);
    case 12: return lambda_dynamic_invoke_native<12>(fn, args, result_home, caller);
    case 13: return lambda_dynamic_invoke_native<13>(fn, args, result_home, caller);
    case 14: return lambda_dynamic_invoke_native<14>(fn, args, result_home, caller);
    case 15: return lambda_dynamic_invoke_native<15>(fn, args, result_home, caller);
    case 16: return lambda_dynamic_invoke_native<16>(fn, args, result_home, caller);
    default: return lambda_dynamic_argument_limit_error(caller, count, "physical argument");
    }
}

static Item lambda_dynamic_call(Function* fn, List* args, uint64_t* result_home,
        LambdaDynamicCallMode mode, const char* caller) {
    int64_t source_actual = args ? args->length : 0;
    if (source_actual < 0 || source_actual > LAMBDA_MAX_FUNCTION_ARGS) {
        return lambda_dynamic_argument_limit_error(caller, source_actual,
            "argument");
    }
    int actual = (int)source_actual;
    if (!is_valid_function(fn)) {
        return lambda_dynamic_call_error(ERR_INVALID_CALL, caller,
            "cannot call non-function value");
    }
    // A LambdaJS function begins with the common type id but has a distinct
    // layout. Validate this byte before reading Core Function metadata.
    if (fn->entry_abi != FN_ENTRY_ABI_LAMBDA_BOXED_FUNCTION &&
            fn->entry_abi != FN_ENTRY_ABI_LAMBDA_BOXED_PROCEDURE &&
            fn->entry_abi != FN_ENTRY_ABI_HOST_ADAPTER &&
            fn->entry_abi != FN_ENTRY_ABI_LAMBDA_INTERPRETED) {
        return lambda_dynamic_call_error(ERR_UNSUPPORTED_DYNAMIC_ABI, caller,
            "function does not publish a Core boxed dynamic-call entry");
    }

    int physical = 0;
    bool needs_adapter = false;
    // Keep the public *_into diagnostic stable while convenience wrappers
    // retain their historical names for non-function values.
    const char* signature_caller = strncmp(caller, "fn_call", 7) == 0
        ? "fn_call_into" : caller;
    Item checked = lambda_dynamic_check_signature(fn, actual, mode,
        signature_caller,
        &physical, &needs_adapter);
    if (checked.item != ITEM_NULL) return checked;

    // Root the function plus every source Item before `list()` can allocate.
    // This exact span is the native equivalent of LambdaJS's adapter span.
    RootSpan source_roots((size_t)actual + 1);
    if (!source_roots.valid()) {
        return lambda_dynamic_call_error(ERR_INVALID_CALL, caller,
            "dynamic boxed dispatch requires an active Lambda runtime");
    }
    uint64_t* source_words = source_roots.words();
    source_words[0] = (uint64_t)(uintptr_t)fn;
    for (int i = 0; i < actual; i++) source_words[i + 1] = args->items[i].item;
    Item* source_items = (Item*)(void*)(source_words + 1);

    if (!needs_adapter) {
        Function* rooted_fn = (Function*)(uintptr_t)source_words[0];
        return lambda_dynamic_invoke_by_count(rooted_fn, source_items, actual,
            result_home, caller, mode);
    }

    RootSpan adapter_roots((size_t)physical);
    if (!adapter_roots.valid()) {
        return lambda_dynamic_call_error(ERR_INVALID_CALL, caller,
            "could not reserve dynamic-call adapter roots");
    }
    uint64_t* adapter_words = adapter_roots.words();
    TypeFunc* signature = (TypeFunc*)fn->fn_type;
    int fixed = signature->param_count;
    for (int i = 0; i < fixed; i++) {
        adapter_words[i] = i < actual ? source_words[i + 1] : ITEM_MISSING_ARGUMENT;
    }
    if (signature->is_variadic) {
        adapter_words[fixed] = ITEM_NULL;
        if (actual > fixed) {
            List* rest = list();
            if (!rest) {
                return lambda_dynamic_call_error(ERR_OUT_OF_MEMORY, caller,
                    "could not allocate rest argument list");
            }
            adapter_words[fixed] = (uint64_t)(uintptr_t)rest;
            for (int i = fixed; i < actual; i++) {
                // Reload both rooted values after each append: growth may collect.
                rest = (List*)(uintptr_t)adapter_words[fixed];
                // Arguments are not content: append verbatim so `null` and
                // adjacent strings survive (see emit_variadic_args).
                array_push_verbatim((Array*)rest, (Item){.item = source_words[i + 1]});
            }
        }
    }
    Function* rooted_fn = (Function*)(uintptr_t)source_words[0];
    return lambda_dynamic_invoke_by_count(rooted_fn,
        (Item*)(void*)adapter_words, physical, result_home, caller, mode);
}

Item fn_call_into(Function* fn, List* args, uint64_t* result_home) {
    return lambda_dynamic_call(fn, args, result_home, LAMBDA_DYNAMIC_CALL_FUNCTION,
        "fn_call_into");
}

// S12.3.4 `call(f, args)` — dynamic application. Shared body for both colours;
// `caller_is_proc` is fixed by the ENCLOSING context at lowering time, which is
// what selects the error convention (S12.3.4: fn returns, pn raises). The
// TARGET's colour is read from its TypeFunc and checked here whenever the
// static side could not (S12.1.4).
static Item lambda_dynamic_apply(Item callee, Item args_item, bool caller_is_proc,
        const char* caller) {
    Function* fn = get_type_id(callee) == LMD_TYPE_FUNC
        ? (Function*)(uintptr_t)callee.item : NULL;
    if (!is_valid_function(fn)) {
        set_runtime_error(ERR_INVALID_OPERATION,
            "%s: first argument must be a function", caller);
        return ItemError;
    }
    // S12.1.4: a pn target reached from fn context. Static analysis catches
    // this when the callee is statically known; a dynamic callee can only be
    // caught here.
    if (!caller_is_proc && lambda_function_is_proc(fn)) {
        set_runtime_error(ERR_PROC_IN_FN,
            "%s: cannot call a procedure (pn) from a function (fn)", caller);
        return ItemError;
    }
    // S12.3.4: `args` is an array, never coerced from a bare value — a
    // one-element promotion would silently call a 1-arity function. Both the
    // generic and the packed-numeric array faces are accepted; an `array[num]`
    // is what an all-numeric literal like `[1, 2]` actually builds.
    TypeId args_type = get_type_id(args_item);
    if (args_type == LMD_TYPE_ARRAY) {  // lists are ARRAY at runtime
        return fn_call_into(fn, it2list(args_item), NULL);
    }
    if (args_type == LMD_TYPE_ARRAY_NUM) {
        // Packed numerics carry no Item[] to hand the dynamic ABI, so widen
        // through the boundary accessor that already boxes each element.
        ArrayNum* packed = (ArrayNum*)(uintptr_t)args_item.item;
        List* widened = list();
        for (int64_t i = 0; i < packed->length; i++) {
            // Widening must be length-preserving, and this is an argument
            // list: append verbatim (LR09-R3).
            array_push_verbatim((Array*)widened, array_num_get(packed, i));
        }
        return fn_call_into(fn, widened, NULL);
    }
    set_runtime_error(ERR_INVALID_OPERATION,
        "%s: second argument must be an array of arguments, got %s",
        caller, get_type_name(args_type));
    return ItemError;
}

