static bool literal_type_matches_item(Type* expected, Item item) {
    if (!expected || !expected->is_literal) return false;
    Item literal;
    if (!lambda_literal_contract_value(expected, &literal)) return false;
    if (IS_NUMERIC_ID(expected->type_id)) {
        // S11.2.1: a numeric literal type is the singleton of its value, matched
        // by `==` as a literal match arm is; the TypeId alone admitted 3 into
        // `1 | 2` on every tier (LR03-11)
        return IS_NUMERIC_ID(get_type_id(item)) && fn_eq(item, literal) == BOOL_TRUE;
    }
    if (expected->type_id != LMD_TYPE_STRING && expected->type_id != LMD_TYPE_SYMBOL) {
        // any other literal -- a bool (LR03-31) -- admits its own value
        return get_type_id(item) == get_type_id(literal) && fn_eq(item, literal) == BOOL_TRUE;
    }
    // a text literal admits its own domain and spelling. A symbol literal's
    // payload is a Symbol, whose chars sit at another offset than a String's
    // (parse_type_pattern.cpp), so it is read through the Item: cast to String,
    // `type Y = 'sym'` compared padding and admitted nothing
    if (get_type_id(item) != expected->type_id) return false;
    const char* literal_chars = literal.get_chars();
    const char* actual_chars = item.get_chars();
    uint32_t len = literal.get_len();
    return literal_chars && actual_chars && item.get_len() == len &&
        memcmp(literal_chars, actual_chars, len) == 0;
}

bool lambda_type_matches(Item item, Type* expected) {
    expected = runtime_boundary_unwrap_type(expected);
    if (!expected) return false;
    // S11.1.7: the empty type admits no value -- not null, not an error
    if (expected == &TYPE_NONE) return false;
    TypeId actual_id = get_type_id(item);
    if (actual_id == LMD_TYPE_ERROR) return lambda_type_accepts_error(expected);
    // These contract tops share the compact TYPE_TYPE tag with first-class
    // type values, but their pointer identity defines admission (D3.3.3v3).
    if (type_is_any_without_error(expected) && type_is_any_without_null(expected)) {
        return actual_id != LMD_TYPE_NULL;
    }
    if (type_is_any_without_error(expected)) return true;
    if (type_is_any_without_null(expected)) return actual_id != LMD_TYPE_NULL;
    if (expected->type_id == LMD_TYPE_ANY) return true;
    // Literal aliases used to enter the pattern builder; compare their content directly now that literal-only forms are ordinary type values.
    Item literal_value;
    if (expected->is_literal &&
            (expected->type_id == LMD_TYPE_STRING || expected->type_id == LMD_TYPE_SYMBOL ||
             lambda_literal_contract_value(expected, &literal_value))) {
        return literal_type_matches_item(expected, item);
    }
    // S11.3.1v2: a nominal expectation is answered by the record chain, ahead of
    // the structural switch — since the flip, a nominal type wears a map or
    // element tag and would otherwise be treated as a plain shape.
    if (TypeNominal* wanted = type_nominal_record(expected)) {
        const void* container = (const void*)(uintptr_t)item.item;
        TypeNominal* actual = lambda_value_nominal(actual_id, container);
        if (!actual || !lambda_nominal_derives_from(actual, wanted)) return false;
        return !wanted->constraint_fn || wanted->constraint_fn(item.item);
    }
    if (expected == &TYPE_OBJECT) {
        // `is object` asks only whether the value carries a nominal record.
        return lambda_value_nominal(actual_id,
            (const void*)(uintptr_t)item.item) != NULL;
    }
    if (expected == &TYPE_MAP && actual_id == LMD_TYPE_VMAP) {
        // Host-backed VMaps implement Lambda's map interface but retain a distinct
        // physical tag; the global map contract must not reject them at a native call.
        return true;
    }
    if ((expected == (Type*)&TYPE_ARRAY && actual_id == LMD_TYPE_VARRAY) ||
            (expected == &TYPE_ELMT && actual_id == LMD_TYPE_VELMT)) {
        return true;
    }

    if (expected->type_id == LMD_TYPE_TYPE && expected->kind == TYPE_KIND_PATTERN) {
        TypePattern* pattern = (TypePattern*)expected;
        if (pattern->is_symbol) {
            if (actual_id != LMD_TYPE_SYMBOL) return false;
        } else if (actual_id != LMD_TYPE_STRING) {
            return false;
        }
        return pattern_full_match_chars(pattern, item.get_chars(), item.get_len());
    }
    if (lambda_type_is_range(expected)) {
        return lambda_range_type_contains(expected, item);
    }
    if ((expected->type_id == LMD_TYPE_TYPE &&
            (expected->kind == TYPE_KIND_BINARY || expected->kind == TYPE_KIND_UNARY)) ||
            ((expected->type_id == LMD_TYPE_MAP || expected->type_id == LMD_TYPE_ELEMENT) &&
             expected != &TYPE_MAP && expected != &TYPE_ELMT)) {
        // TYPE_MAP and TYPE_ELMT are compact global Type prefixes, not shaped
        // TypeMap/TypeElmt payloads. Their tag match below is complete; casting
        // either singleton into the validator would read past its allocation.
        return runtime_validate_value_against_type(item, expected, NULL);
    }

    Type actual_scratch = {.type_id = LMD_TYPE_NULL};
    Type* actual_type = item_static_type_for_is(item, &actual_scratch);
    switch (expected->type_id) {
    case LMD_TYPE_TYPE:
        if (expected == &TYPE_NUMBER) return numeric_type_subsumes(actual_type, expected);
        if (expected == &TYPE_INTEGER) return item_type_is_integer_subtype(item, actual_id);
        return actual_id == LMD_TYPE_TYPE;
    case LMD_TYPE_INT:
    case LMD_TYPE_INT64:
    case LMD_TYPE_FLOAT:
    case LMD_TYPE_DECIMAL:
    case LMD_TYPE_NUM_SIZED:
    case LMD_TYPE_UINT64:
        return numeric_type_subsumes(actual_type, expected);
    case LMD_TYPE_DTIME:
        if (actual_id != LMD_TYPE_DTIME) return false;
        if (expected == &TYPE_DATE) {
            DateTime dt = item.get_datetime();
            return dt.precision == DATETIME_PRECISION_DATE_ONLY ||
                dt.precision == DATETIME_PRECISION_YEAR_ONLY;
        }
        if (expected == &TYPE_TIME) {
            return item.get_datetime().precision == DATETIME_PRECISION_TIME_ONLY;
        }
        return true;
    case LMD_TYPE_ARRAY:
        return actual_id == LMD_TYPE_RANGE || actual_id == LMD_TYPE_ARRAY ||
            actual_id == LMD_TYPE_ARRAY_NUM;
    case LMD_TYPE_FUNC:
        return lambda_function_admitted(item, actual_id, expected);
    default:
        return actual_id == expected->type_id;
    }
}

static void runtime_value_summary(Item item, char* buffer, size_t capacity) {
    TypeId type_id = get_type_id(item);
    if (type_id == LMD_TYPE_STRING || type_id == LMD_TYPE_SYMBOL) {
        const char* chars = item.get_chars();
        uint32_t len = item.get_len();
        int shown = len > 80 ? 80 : (int)len;
        snprintf(buffer, capacity, "%s '%.*s%s'", get_type_name(type_id), shown,
            chars ? chars : "", len > 80 ? "…" : "");
        return;
    }
    if (type_id == LMD_TYPE_INT) {
        snprintf(buffer, capacity, "int %lld", (long long)lambda_int_item_to_i64(item));
        return;
    }
    if (type_id == LMD_TYPE_FLOAT) {
        snprintf(buffer, capacity, "float %.17g", item.get_double());
        return;
    }
    if (type_id == LMD_TYPE_BOOL) {
        snprintf(buffer, capacity, "bool %s", item.bool_val ? "true" : "false");
        return;
    }
    if (type_id == LMD_TYPE_FUNC) {
        // name the colour: a function-contract mismatch is a colour mismatch
        const char* name = item.function ? item.function->name : NULL;
        snprintf(buffer, capacity, "%s%s%s",
            lambda_function_is_proc(item.function) ? "pn" : "fn",
            name && *name ? " " : "", name ? name : "");
        return;
    }
    snprintf(buffer, capacity, "%s", get_type_name(type_id));
}

static void runtime_validation_detail(ValidationResult* result, char* buffer,
        size_t capacity) {
    if (!result || !result->errors || !buffer || capacity == 0) return;
    ValidationError* error = result->errors;
    const char* message = error->message ? error->message->chars : "validation failed";
    if (error->path && context && context->pool) {
        String* path = format_validation_path(error->path, context->pool);
        snprintf(buffer, capacity, "; validator at %s: %s",
            path ? path->chars : "<value>", message);
        return;
    }
    snprintf(buffer, capacity, "; validator: %s", message);
}

static Item lambda_type_error_lazy(Item actual, Type* expected,
        const LambdaBoundary* boundary, ValidationResult* validation) {
    char label[192];
    char expected_name[128];
    char actual_summary[192];
    char message[512];
    char validation_detail[320] = {};
    const char* where = boundary ? boundary->text : NULL;
    if (boundary && boundary->format) {
        // the only point at which a deferred label is ever materialized
        label[0] = '\0';
        boundary->format(boundary, label, sizeof(label));
        where = label;
    }
    lambda_type_format_contract_name(expected, expected_name, sizeof(expected_name));
    runtime_value_summary(actual, actual_summary, sizeof(actual_summary));
    runtime_validation_detail(validation, validation_detail, sizeof(validation_detail));
    snprintf(message, sizeof(message),
        "type check at %s failed: expected %s, got %s%s",
        where ? where : "typed boundary", expected_name, actual_summary,
        validation_detail);
    return runtime_error_item(ERR_TYPE_MISMATCH, message, NULL);
}

static Item lambda_type_error_with_validation(Item actual, Type* expected,
        const char* boundary, ValidationResult* validation) {
    LambdaBoundary label = {boundary, NULL, NULL, NULL, 0};
    return lambda_type_error_lazy(actual, expected, &label, validation);
}

Item lambda_type_error(Item actual, Type* expected, const char* boundary) {
    return lambda_type_error_with_validation(actual, expected, boundary, NULL);
}

static Type* binder_narrowest_type(Item value) {
    Type scratch = {};
    Type* narrowest = item_static_type_for_is(value, &scratch);
    if (!narrowest) return &TYPE_ANY;
    LambdaNumericKind numeric = lambda_numeric_kind_from_type(narrowest);
    if (numeric != LAMBDA_NUM_INVALID) return lambda_numeric_type_from_kind(numeric);
    TypeId actual = get_type_id(value);
    if (actual == LMD_TYPE_MAP && value.map && value.map->type) {
        return (Type*)value.map->type;
    }
    if ((actual == LMD_TYPE_ARRAY || actual == LMD_TYPE_ARRAY_NUM) &&
            value.array && value.array->rep_cert) {
        return value.array->rep_cert->array_contract;
    }
    if (narrowest != &scratch) return narrowest;
    // item_static_type_for_is uses caller scratch for ordinary scalars. A
    // binder environment outlives this helper, so retain the canonical static
    // contract instead of publishing that transient address (S4.2.2).
    Type* canonical = type_info[narrowest->type_id].type;
    return canonical ? canonical : &TYPE_ANY;
}

static Type* binder_join(Type* left, Type* right) {
    if (!left || !right) return NULL;
    if (left == right) return left;
    LambdaNumericKind left_kind = lambda_numeric_kind_from_type(left);
    LambdaNumericKind right_kind = lambda_numeric_kind_from_type(right);
    if (left_kind != LAMBDA_NUM_INVALID && right_kind != LAMBDA_NUM_INVALID) {
        LambdaNumericKind joined = lambda_numeric_semantic_join(
            lambda_numeric_enter_semantic_domain(left_kind),
            lambda_numeric_enter_semantic_domain(right_kind));
        return joined == LAMBDA_NUM_INVALID ? NULL : lambda_numeric_type_from_kind(joined);
    }
    // A nominal subtype pair joins at the already-written wider contract. The
    // full nearest-base walk remains the record implementation's authority.
    if (lambda_type_contract_semantically_compatible(right, left)) return left;
    if (lambda_type_contract_semantically_compatible(left, right)) return right;
    return NULL;
}

static bool runtime_type_admit_binder(Item value, TypeBinder* binder,
        Type** env, Item* converted) {
    if (!binder || !converted || !runtime_type_admit_value_env(value,
            binder->bound, env, converted)) return false;
    if (!env) return true;
    Type* narrowest = binder_narrowest_type(*converted);
    Type* prior = env[binder->slot];
    // NULL is the per-invocation unbound marker. A reference resolves to its
    // declared bound until the first binder site writes the concrete type,
    // avoiding the bound==first-value ambiguity during numeric joins (S4.2.2).
    Type* joined = prior ? binder_join(prior, narrowest) : narrowest;
    if (!joined) return false;
    env[binder->slot] = joined;
    return true;
}

Item lambda_type_check_env(Item value, Type* expected, Type** env,
        const char* boundary) {
    LambdaBoundary label = {boundary, NULL, NULL, NULL, 0};
    return lambda_type_check_lazy(value, expected, env, &label);
}

Item lambda_type_check_lazy(Item value, Type* expected, Type** env,
        const LambdaBoundary* boundary) {
    // Error-transparent contracts (`any`, `error`, or an explicit union) keep
    // an incoming error value.  Plain T short-circuits it unchanged so callers
    // retain the original diagnostic instead of receiving a misleading second
    // type mismatch.
    if (get_type_id(value) == LMD_TYPE_ERROR) return value;

    Item converted = ItemError;
    if (runtime_type_admit_value_env(value, expected, env, &converted)) {
        return converted;
    }

    // Shape/union/occurrence matching is delegated to the validator. Reuse its
    // first concrete failure here so a rejected dynamic binding identifies the
    // offending member/index instead of merely saying "got map".
    Type* contract = runtime_boundary_unwrap_type(expected);
    ValidationResult* validation = NULL;
    if (contract && ((contract->type_id == LMD_TYPE_TYPE &&
            (contract->kind == TYPE_KIND_BINARY || contract->kind == TYPE_KIND_UNARY)) ||
            contract->type_id == LMD_TYPE_MAP ||
            contract->type_id == LMD_TYPE_ELEMENT)) {
        (void)runtime_validate_value_against_type(value, contract, &validation);
    }
    return lambda_type_error_lazy(value, expected, boundary, validation);
}

Item lambda_type_check(Item value, Type* expected, const char* boundary) {
    return lambda_type_check_env(value, expected, NULL, boundary);
}

Bool lambda_type_value_is_exact(Item value, Type* expected) {
    if (!expected || get_type_id(value) != LMD_TYPE_TYPE) return BOOL_FALSE;
    Type* actual = runtime_boundary_unwrap_type(value.type);
    return actual == expected ? BOOL_TRUE : BOOL_FALSE;
}

Bool lambda_value_type_is_exact(Item value, Type* expected) {
    expected = runtime_boundary_unwrap_type(expected);
    if (!expected) return BOOL_FALSE;

    TypeId actual_id = get_type_id(value);
    if (expected->type_id == LMD_TYPE_MAP && expected != &TYPE_MAP) {
        // Named and nominal map values preserve their descriptor through
        // type(value), so identity of the authoritative instance shape is the
        // exact semantic key (S2.1.1v3, D8.3.1v2).
        return actual_id == LMD_TYPE_MAP &&
            lambda_attr_shape(actual_id, value.map) == (TypeMap*)expected
            ? BOOL_TRUE : BOOL_FALSE;
    }
    if (expected->type_id == LMD_TYPE_ELEMENT && expected != &TYPE_ELMT) {
        // Every element type is shape-bearing; a generic element does not
        // denote one exact binder result and is therefore never specialized.
        return actual_id == LMD_TYPE_ELEMENT &&
            lambda_attr_shape(actual_id, value.element) == (TypeMap*)expected
            ? BOOL_TRUE : BOOL_FALSE;
    }

    actual_id = item_semantic_type_id(actual_id);
    if (expected == &TYPE_ARRAY) {
        return (actual_id == LMD_TYPE_ARRAY || actual_id == LMD_TYPE_ARRAY_NUM)
            ? BOOL_TRUE : BOOL_FALSE;
    }
    return actual_id == expected->type_id ? BOOL_TRUE : BOOL_FALSE;
}

// The operand `x is T` receives for a type the graph keeps unwrapped, such as a
// constrained base: an extended kind is its own value; a base-type word is its
// published singleton (`list`, `date` and the sized numerics are not their
// TypeId's type); a structural type the builder made rides in `scratch`.
static Type* is_operand_type_value(Type* type, TypeType* scratch) {
    if (!type) return NULL;
    if (type->type_id == LMD_TYPE_TYPE && !type_is_global_meta_type(type)) {
        return type;
    }
    *(Type*)scratch = LIT_TYPE;
    scratch->type = type;
    TypeId tid = LMD_TYPE_ANY;
    TypeType* singleton = lambda_type_node_singleton((Type*)scratch, &tid);
    if (singleton) return (Type*)singleton;
    if (tid > 0 && tid < LMD_TYPE_COUNT && type_info[tid].type == type) {
        return base_type(tid);
    }
    return (Type*)scratch;
}

Bool fn_is(Item a, Item b) {
    TypeId b_type_id = get_type_id(b);
    if (b_type_id == LMD_TYPE_RANGE) {
        // A runtime range in `is` is the value-space set denoted by its bounds;
        // comparing the container identity would discard the range predicate.
        return range_contains_item(b.range, a) ? BOOL_TRUE : BOOL_FALSE;
    }
    if (b_type_id != LMD_TYPE_TYPE) return fn_eq(a, b);
    {
        // D2.6.6v2 phase 2: `object` is a TYPE with no tag of its own — it wears
        // a container tag purely to route through the switches below, so it MUST
        // be matched by pointer identity here, ahead of anything that compares
        // tags. Otherwise `{x: 1} is object` would answer true simply because
        // both sides read as MAP.
        // `b.type` may arrive as the LIT_TYPE_OBJECT wrapper or already
        // unwrapped to the bare singleton, so normalise before comparing —
        // casting a bare Type to TypeType would read past its end.
        if (runtime_boundary_unwrap_type(b.type) == &TYPE_OBJECT) {
            return lambda_value_nominal(get_type_id(a),
                (const void*)(uintptr_t)a.item) ? BOOL_TRUE : BOOL_FALSE;
        }
    }

    Type* b_type = b.type;
    if (b_type->kind == TYPE_KIND_PATTERN) {
        TypeId a_type_id = get_type_id(a);
        TypePattern* pattern = (TypePattern*)b_type;
        // S11.1.2v2: matching checks the value domain before content, so a
        // value outside it -- another text kind, or no text at all -- is no
        // member. A non-text value had raised an error from `is`.
        if ((pattern->is_symbol && a_type_id != LMD_TYPE_SYMBOL) ||
                (!pattern->is_symbol && a_type_id != LMD_TYPE_STRING)) {
            return BOOL_FALSE;
        }
        return pattern_full_match_chars(pattern, a.get_chars(), a.get_len()) ? BOOL_TRUE : BOOL_FALSE;
    }

    // S11.4.6: a first-class constrained type value carries no predicate in
    // reach, so this generic path admits the base only; `is` and a match arm
    // that name the type run its predicates too (ast_constrained_type). The
    // base must admit exactly as `x is <base>` would: the tag test this
    // replaced skipped every union, occurrence and array base outright.
    if (b_type->kind == TYPE_KIND_CONSTRAINED) {
        TypeType scratch;
        Type* base = is_operand_type_value(lambda_constrained_type_base(b_type),
            &scratch);
        return base ? fn_is(a, (Item){.item = (uint64_t)(uintptr_t)base})
            : BOOL_FALSE;
    }

    if (b_type->kind == TYPE_KIND_UNARY || b_type->kind == TYPE_KIND_BINARY) {
        ValidationResult* result = schema_validator_validate_type(context->validator, a.to_const(), b_type);
        return result->valid ? BOOL_TRUE : BOOL_FALSE;
    }

    // a range type may arrive bare (type lists register it raw) or wrapped
    TypeType* type_b = (TypeType*)b_type;
    Type* range_type = lambda_type_is_range(b_type) ? b_type : type_b->type;
    if (lambda_type_is_range(range_type)) {
        return lambda_range_type_contains(range_type, a) ? BOOL_TRUE : BOOL_FALSE;
    }
    // a literal type is the singleton of its value, numeric ones included: the
    // tag switch below would admit every int into the literal `1`, which S11.1.7
    // exposes as `2 is (none | 1)` -- the same test lambda_type_matches makes
    Item literal_value;
    if (type_b->type->is_literal &&
            (type_b->type->type_id == LMD_TYPE_STRING || type_b->type->type_id == LMD_TYPE_SYMBOL ||
             lambda_literal_contract_value(type_b->type, &literal_value))) {
        return literal_type_matches_item(type_b->type, a) ? BOOL_TRUE : BOOL_FALSE;
    }
    TypeId a_type_id = get_type_id(a);
    Type actual_type_scratch = {.type_id = LMD_TYPE_NULL};
    Type* actual_type = item_static_type_for_is(a, &actual_type_scratch);
    if (type_b->type->type_id != LMD_TYPE_NUM_SIZED &&
            (type_b->type->kind == TYPE_KIND_UNARY || type_b->type->kind == TYPE_KIND_BINARY)) {
        ValidationResult* result = schema_validator_validate_type(context->validator, a.to_const(), type_b->type);
        return result->valid ? BOOL_TRUE : BOOL_FALSE;
    }

    switch (type_b->type->type_id) {
    case LMD_TYPE_ANY:
        // `is any` uses the validator form of top: errors remain inspectable
        // values, but are not ordinary validated data.
        return a_type_id == LMD_TYPE_ERROR ? BOOL_FALSE : BOOL_TRUE;
    case LMD_TYPE_TYPE:
        if (type_b->type == &TYPE_NONE) return BOOL_FALSE;  // S11.1.7: admits nothing
        if (type_b->type == &TYPE_NUMBER) {
            return numeric_type_subsumes(actual_type, type_b->type) ? BOOL_TRUE : BOOL_FALSE;
        }
        if (type_b->type == &TYPE_INTEGER) {
            if (a_type_id == LMD_TYPE_TYPE) {
                return numeric_type_subsumes(actual_type, type_b->type) ? BOOL_TRUE : BOOL_FALSE;
            }
            return item_type_is_integer_subtype(a, a_type_id) ? BOOL_TRUE : BOOL_FALSE;
        }
        return a_type_id == LMD_TYPE_TYPE ? BOOL_TRUE : BOOL_FALSE;
    case LMD_TYPE_INT:
    case LMD_TYPE_INT64:
    case LMD_TYPE_FLOAT:
    case LMD_TYPE_DECIMAL:
    case LMD_TYPE_NUM_SIZED:
    case LMD_TYPE_UINT64:
        return numeric_type_subsumes(actual_type, type_b->type) ? BOOL_TRUE : BOOL_FALSE;
    case LMD_TYPE_DTIME:
        if (a_type_id != LMD_TYPE_DTIME) return BOOL_FALSE;
        if (type_b->type == &TYPE_DATE) {
            DateTime dt = a.get_datetime();
            return (dt.precision == DATETIME_PRECISION_DATE_ONLY || dt.precision == DATETIME_PRECISION_YEAR_ONLY)
                ? BOOL_TRUE : BOOL_FALSE;
        }
        if (type_b->type == &TYPE_TIME) {
            DateTime dt = a.get_datetime();
            return dt.precision == DATETIME_PRECISION_TIME_ONLY ? BOOL_TRUE : BOOL_FALSE;
        }
        return BOOL_TRUE;
    case LMD_TYPE_ARRAY:
    case LMD_TYPE_MAP:
    case LMD_TYPE_ELEMENT:
        // the kinds are known by their payload, which `type(x)` wraps afresh:
        // by the static wrapper alone, `[1] is type((1, 2))` sent the bare
        // `list` Type to the validator, which read it as a TypeArray
        if (type_b->type == (Type*)&TYPE_ARRAY) {
            return a_type_id == LMD_TYPE_RANGE || a_type_id == LMD_TYPE_ARRAY ||
                a_type_id == LMD_TYPE_ARRAY_NUM || a_type_id == LMD_TYPE_VARRAY
                ? BOOL_TRUE : BOOL_FALSE;
        }
        // S2.5.1v2: `is list` tests the kind bit; `is array` holds for lists too
        if (type_b->type == &TYPE_LIST) {
            return item_is_list(a) ? BOOL_TRUE : BOOL_FALSE;
        }
        if (type_nominal_record(type_b->type)) {
            TypeNominal* actual = lambda_value_nominal(a_type_id,
                (const void*)(uintptr_t)a.item);
            TypeNominal* expected = type_nominal_record(type_b->type);
            if (!actual || !expected ||
                    !lambda_nominal_derives_from(actual, expected)) return BOOL_FALSE;
            return (!expected->constraint_fn || expected->constraint_fn(a.item)) ? BOOL_TRUE : BOOL_FALSE;
        }
        if (type_b->type == &TYPE_OBJECT) {
            // `is object` asks only whether the value carries a nominal record.
            return lambda_value_nominal(a_type_id,
                (const void*)(uintptr_t)a.item) ? BOOL_TRUE : BOOL_FALSE;
        }
        {
            ValidationResult* result = schema_validator_validate_type(context->validator, a.to_const(), type_b->type);
            return result->valid ? BOOL_TRUE : BOOL_FALSE;
        }
    case LMD_TYPE_FUNC:
        return lambda_function_admitted(a, a_type_id, type_b->type)
            ? BOOL_TRUE : BOOL_FALSE;
    default:
        return a_type_id == type_b->type->type_id ? BOOL_TRUE : BOOL_FALSE;
    }
}

Bool fn_subtype(Item a, Item b) {
    if (get_type_id(a) != LMD_TYPE_TYPE || get_type_id(b) != LMD_TYPE_TYPE) {
        return BOOL_ERROR;
    }
    Type* candidate = runtime_boundary_unwrap_type(a.type);
    Type* expected = runtime_boundary_unwrap_type(b.type);
    if (!candidate || !expected || candidate->type_id == LMD_TYPE_FUNC ||
            expected->type_id == LMD_TYPE_FUNC) {
        // TGO14(b): function-type variance is not yet ruled, so neither tier
        // may silently invent a variance relation for function values.
        return BOOL_ERROR;
    }
    return lambda_type_contract_is_subtype(candidate, expected)
        ? BOOL_TRUE : BOOL_FALSE;
}

// IEEE NaN check: expr is nan
Bool fn_is_nan(Item a) {
    TypeId tid = get_type_id(a);
    if (is_float_type_id(tid)) {
        double val = a.get_double();
        return __builtin_isnan(val) ? BOOL_TRUE : BOOL_FALSE;
    }
    // `int` and `float` share one nan (formal semantics 4), and a shared value
    // types as its narrowest -- so a nan reports `int` and would miss the float
    // arm above. Its native form is the same double either way.
    if (tid == LMD_TYPE_INT) {
        return __builtin_isnan(lambda_int_item_value(a)) ? BOOL_TRUE : BOOL_FALSE;
    }
    if (tid == LMD_TYPE_DECIMAL) return decimal_item_is_nan(a) ? BOOL_TRUE : BOOL_FALSE;
    return BOOL_FALSE;  // non-float values are never NaN
}

// maximum recursion depth for structural equality comparison
#define EQ_MAX_DEPTH 256

typedef enum EqualityMode {
    EQUALITY_VALUE = 0,
    EQUALITY_STRICT,
} EqualityMode;

// forward declaration for recursive structural equality
static Bool fn_eq_depth(Item a_item, Item b_item, int depth, EqualityMode mode);

static Bool numeric_items_equal_exact(Item a_item, Item b_item) {
    LambdaNumericComparison comparison = lambda_numeric_compare(a_item, b_item);
    return comparison.valid && !comparison.unordered && comparison.order == 0 ?
        BOOL_TRUE : BOOL_FALSE;
}

// forward declaration: get field value from a map's packed data by shape entry
static Item _map_field_value(TypeMap* map_type, void* data, ShapeEntry* field);

// helper: structural equality for list/array items (element-wise comparison)
static Bool list_eq(List* a, List* b, int depth, EqualityMode mode) {
    if (a == b) return BOOL_TRUE;  // pointer identity fast-path
    if (a->length != b->length) return BOOL_FALSE;
    for (int64_t i = 0; i < a->length; i++) {
        Bool r = fn_eq_depth(array_item_read(a, i), array_item_read(b, i),
            depth + 1, mode);
        if (r == BOOL_ERROR) return BOOL_ERROR;
        if (r == BOOL_FALSE) return BOOL_FALSE;
    }
    return BOOL_TRUE;
}

static bool array_num_shape_eq(ArrayNum* a, ArrayNum* b) {
    int a_ndim = 1, b_ndim = 1;
    int64_t a_dims_stack[LAMBDA_ARRAY_NUM_MAX_NDIM], b_dims_stack[LAMBDA_ARRAY_NUM_MAX_NDIM];
    a_dims_stack[0] = a ? a->length : 0;
    b_dims_stack[0] = b ? b->length : 0;

    if (a && a->is_ndim && a->extra) {
        ArrayNumShape* s = (ArrayNumShape*)(uintptr_t)a->extra;
        if (s && s->ndim >= 1 && s->ndim <= LAMBDA_ARRAY_NUM_MAX_NDIM) {
            a_ndim = s->ndim;
            int64_t* dims = array_num_shape_dims(s);
            for (int i = 0; i < a_ndim; i++) a_dims_stack[i] = dims[i];
        }
    }
    if (b && b->is_ndim && b->extra) {
        ArrayNumShape* s = (ArrayNumShape*)(uintptr_t)b->extra;
        if (s && s->ndim >= 1 && s->ndim <= LAMBDA_ARRAY_NUM_MAX_NDIM) {
            b_ndim = s->ndim;
            int64_t* dims = array_num_shape_dims(s);
            for (int i = 0; i < b_ndim; i++) b_dims_stack[i] = dims[i];
        }
    }

    if (a_ndim != b_ndim) return false;
    for (int i = 0; i < a_ndim; i++) {
        if (a_dims_stack[i] != b_dims_stack[i]) return false;
    }
    return true;
}

static inline bool array_num_elem_type_is_float(ArrayNumElemType et) {
    return et == ELEM_FLOAT16 || et == ELEM_FLOAT32 || et == ELEM_FLOAT64;
}

// helper: structural equality for typed numeric arrays
static Bool array_num_eq(ArrayNum* a, ArrayNum* b, int depth, EqualityMode mode) {
    if (a == b) return BOOL_TRUE;
    if (a->length != b->length) return BOOL_FALSE;
    if (!array_num_shape_eq(a, b)) {
        // n-D arrays expose their shape as structure; equal flat storage alone is insufficient.
        return BOOL_FALSE;
    }
    if (a->get_elem_type() != b->get_elem_type() && mode == EQUALITY_STRICT) {
        return BOOL_FALSE;
    }
    if (a->get_elem_type() != b->get_elem_type() ||
            !array_num_is_dense(a) || !array_num_is_dense(b)) {
        // different elem types compare as values; double promotion loses high
        // int64/u64 bits. A strided view (a transposed matrix or its row) is
        // compared position by position, never by its base's storage order.
        for (int64_t i = 0; i < a->length; i++) {
            Item val_a = array_num_read_item(a, array_num_element_offset(a, i));
            Item val_b = array_num_read_item(b, array_num_element_offset(b, i));
            Bool r = fn_eq_depth(val_a, val_b, depth + 1, mode);
            if (r != BOOL_TRUE) return r;
        }
        return BOOL_TRUE;
    }
    if (a->get_elem_type() == ELEM_FLOAT64) {
        // element-wise comparison to respect NaN != NaN
        for (int64_t i = 0; i < a->length; i++) {
            if (a->float_items[i] != b->float_items[i]) return BOOL_FALSE;
        }
        return BOOL_TRUE;
    }
    if (array_num_elem_type_is_float(a->get_elem_type())) {
        for (int64_t i = 0; i < a->length; i++) {
            Item val_a = array_num_read_item(a, i);
            Item val_b = array_num_read_item(b, i);
            Bool r = fn_eq_depth(val_a, val_b, depth + 1, mode);
            if (r != BOOL_TRUE) return r;
        }
        return BOOL_TRUE;
    }
    uint8_t elem_size = ELEM_TYPE_SIZE[a->get_elem_type() >> 4];
    return (elem_size && memcmp(a->data, b->data, (size_t)a->length * elem_size) == 0) ? BOOL_TRUE : BOOL_FALSE;
}

static ShapeEntry* map_find_matching_field(TypeMap* map_type, ShapeEntry* needle) {
    if (!map_type || !needle || !needle->name) return NULL;
    ShapeEntry* hit = typemap_hash_lookup(map_type, needle->name->str, (int)needle->name->length);
    if (hit && target_equal(needle->ns, hit->ns)) return hit;

    // hash lookup is name-only; namespace collisions must fall back to the full shape chain.
    FOR_EACH_MAP_FIELD(map_type, field) {
        if (strview_equal(needle->name, field->name->str) &&
            target_equal(needle->ns, field->ns)) {
            return field;
        }
    }
    return NULL;
}

// helper: structural equality for map-shaped data (order-independent key-value comparison)
static Bool map_data_eq(TypeMap* type_a, void* data_a, TypeMap* type_b, void* data_b,
        int depth, EqualityMode mode) {
    if (type_a == type_b && data_a == data_b) return BOOL_TRUE;  // pointer identity fast-path
    if (!type_a || !type_b) return BOOL_FALSE;
    if (type_a->length != type_b->length) return BOOL_FALSE;

    // same-shape fast path: keys are identical in same order, compare values by slot
    if (type_a == type_b) {
        FOR_EACH_MAP_FIELD(type_a, field) {
            Item val_a = _map_field_value(type_a, data_a, field);
            Item val_b = _map_field_value(type_b, data_b, field);
            Bool r = fn_eq_depth(val_a, val_b, depth + 1, mode);
            if (r == BOOL_ERROR) return BOOL_ERROR;
            if (r == BOOL_FALSE) return BOOL_FALSE;
        }
        return BOOL_TRUE;
    }

    // different shapes: for each key in A, look up in B by name+namespace
    FOR_EACH_MAP_FIELD(type_a, field_a) {
        ShapeEntry* field_b = map_find_matching_field(type_b, field_a);
        if (!field_b) return BOOL_FALSE;

        Item val_a = _map_field_value(type_a, data_a, field_a);
        Item val_b = _map_field_value(type_b, data_b, field_b);
        Bool r = fn_eq_depth(val_a, val_b, depth + 1, mode);
        if (r == BOOL_ERROR) return BOOL_ERROR;
        if (r == BOOL_FALSE) return BOOL_FALSE;
    }
    // key-count check already done above — no extra keys in B
    return BOOL_TRUE;
}

// helper: structural equality for maps (order-independent key-value comparison)
static Bool map_eq(Map* a, Map* b, int depth, EqualityMode mode) {
    if (a == b) return BOOL_TRUE;  // pointer identity fast-path
    return map_data_eq((TypeMap*)a->type, a->data, (TypeMap*)b->type, b->data, depth, mode);
}

// helper: structural equality for elements (tag + attrs + children)
static Bool element_eq(Element* a, Element* b, int depth, EqualityMode mode) {
    if (a == b) return BOOL_TRUE;  // pointer identity fast-path

    // compare tag names
    TypeElmt* type_a = (TypeElmt*)a->type;
    TypeElmt* type_b = (TypeElmt*)b->type;
    if (type_a->name.length != type_b->name.length) return BOOL_FALSE;
    if (type_a->name.length > 0 &&
        strncmp(type_a->name.str, type_b->name.str, type_a->name.length) != 0) return BOOL_FALSE;
    // compare namespaces
    if (!target_equal(type_a->ns, type_b->ns)) return BOOL_FALSE;

    // Element stores list fields before attr type/data, so attrs must compare by explicit attr storage.
    Bool attr_r = map_data_eq((TypeMap*)type_a, a->data, (TypeMap*)type_b, b->data,
        depth, mode);
    if (attr_r != BOOL_TRUE) return attr_r;

    // compare children (list part)
    if (a->length != b->length) return BOOL_FALSE;
    for (int64_t i = 0; i < a->length; i++) {
        Bool r = fn_eq_depth(a->items[i], b->items[i], depth + 1, mode);
        if (r == BOOL_ERROR) return BOOL_ERROR;
        if (r == BOOL_FALSE) return BOOL_FALSE;
    }
    return BOOL_TRUE;
}

static bool element_text_equal(Item a, Item b) {
    if (!is_text_type_id(get_type_id(a)) || !is_text_type_id(get_type_id(b))) {
        return false;
    }
    uint32_t a_len = a.get_len();
    uint32_t b_len = b.get_len();
    return a_len == b_len && (!a_len || memcmp(a.get_chars(), b.get_chars(), a_len) == 0);
}

static ShapeEntry* materialized_element_attr_at(Element* element, int64_t index) {
    if (!element || !element->type || index < 0) return NULL;
    int64_t current = 0;
    FOR_EACH_MAP_FIELD((TypeMap*)element->type, field) {
        if (!field->name) continue;
        if (current++ == index) return field;
    }
    return NULL;
}

static int64_t element_attr_count_for(Item item) {
    if (get_type_id(item) == LMD_TYPE_VELMT) return velmt_attr_count(item.velmt);
    Element* element = item.element;
    if (!element || !element->type) return 0;
    int64_t count = 0;
    FOR_EACH_MAP_FIELD((TypeMap*)element->type, field) {
        if (field->name) count++;
    }
    return count;
}

static VirtualOpStatus element_attr_key_at_for(Item item, int64_t index, Item* out) {
    if (out) *out = ItemNull;
    if (get_type_id(item) == LMD_TYPE_VELMT) {
        return velmt_attr_key_at(item.velmt, index, out);
    }
    ShapeEntry* field = materialized_element_attr_at(item.element, index);
    if (!field || !field->name || !out) return field ? VIRTUAL_OP_ERROR : VIRTUAL_OP_MISSING;
    Symbol* key = name_key_symbol(field->name->str, field->name->length);
    if (!key) return VIRTUAL_OP_ERROR;
    // symbol.empty is shared and immutable; only a heap key carries the namespace
    if (key != symbol_empty()) key->ns = field->ns;
    *out = {.item = y2it(key)};
    return VIRTUAL_OP_OK;
}

static VirtualOpStatus element_attr_value_at_for(Item item, int64_t index, Item* out) {
    if (out) *out = ItemNull;
    if (get_type_id(item) == LMD_TYPE_VELMT) {
        return velmt_attr_value_at(item.velmt, index, out);
    }
    ShapeEntry* field = materialized_element_attr_at(item.element, index);
    if (!field || !out) return field ? VIRTUAL_OP_ERROR : VIRTUAL_OP_MISSING;
    *out = _map_field_value((TypeMap*)item.element->type, item.element->data, field);
    return VIRTUAL_OP_OK;
}

static VirtualOpStatus materialized_map_field_get(Map* owner, Item key,
        Item* out) {
    if (out) *out = ItemNull;
    if (!owner || !owner->type || !out || !is_text_type_id(get_type_id(key))) {
        return VIRTUAL_OP_MISSING;
    }
    const char* chars = key.get_chars();
    uint32_t length = key.get_len();
    Symbol* symbol = get_type_id(key) == LMD_TYPE_SYMBOL ? key.get_safe_symbol() : NULL;
    if (symbol && !symbol_is_lambda_name(symbol)) return VIRTUAL_OP_MISSING;
    Target* ns = symbol_lambda_namespace(symbol);
    FOR_EACH_MAP_FIELD((TypeMap*)owner->type, field) {
        if (!field->name || field->name->length != length ||
                !target_equal(field->ns, ns)) continue;
        if (!length || memcmp(field->name->str, chars, length) == 0) {
            *out = _map_field_value((TypeMap*)owner->type, owner->data, field);
            return VIRTUAL_OP_OK;
        }
    }
    return VIRTUAL_OP_MISSING;
}

static VirtualOpStatus element_attr_get_for(Item item, Item key, Item* out) {
    if (get_type_id(item) == LMD_TYPE_VELMT) {
        if (out) *out = ItemNull;
        if (!item.velmt || !item.velmt->vtable ||
                !item.velmt->vtable->element.attrs.get) return VIRTUAL_OP_MISSING;
        return item.velmt->vtable->element.attrs.get(item.velmt->data, key, out);
    }
    return materialized_map_field_get(item.map, key, out);
}

static VirtualOpStatus element_tag_for(Item item, Item* out) {
    if (out) *out = ItemNull;
    if (get_type_id(item) == LMD_TYPE_VELMT) return velmt_tag(item.velmt, out);
    TypeElmt* type = item.element ? (TypeElmt*)item.element->type : NULL;
    if (!type || !out) return VIRTUAL_OP_MISSING;
    Symbol* tag = heap_create_symbol(type->name.str ? type->name.str : "", type->name.length);
    if (!tag) return VIRTUAL_OP_ERROR;
    *out = {.item = y2it(tag)};
    return VIRTUAL_OP_OK;
}

static int element_namespace_cmp(Item a_item, Item b_item, bool* failed) {
    RootFrame roots(4);
    Rooted<Item> a_root(roots, a_item);
    Rooted<Item> b_root(roots, b_item);
    Rooted<Item> a_ns(roots, ItemNull);
    Rooted<Item> b_ns(roots, ItemNull);
    StrBuf* a_buf = strbuf_new();
    StrBuf* b_buf = strbuf_new();
    const char* a_chars = "";
    const char* b_chars = "";
    size_t a_len = 0;
    size_t b_len = 0;

    if (get_type_id(a_root.get()) == LMD_TYPE_VELMT) {
        Item namespace_item = ItemNull;
        VirtualOpStatus status = velmt_namespace_uri(a_root.get().velmt, &namespace_item);
        a_ns.set(namespace_item);
        if (status == VIRTUAL_OP_ERROR ||
                (status == VIRTUAL_OP_OK && get_type_id(a_ns.get()) != LMD_TYPE_NULL &&
                    !is_text_type_id(get_type_id(a_ns.get())))) {
            *failed = true;
        } else if (status == VIRTUAL_OP_OK && is_text_type_id(get_type_id(a_ns.get()))) {
            a_chars = a_ns.get().get_chars();
            a_len = a_ns.get().get_len();
        }
    } else {
        TypeElmt* type = a_root.get().element ? (TypeElmt*)a_root.get().element->type : NULL;
        if (type && type->ns && target_to_url_string(type->ns, a_buf)) {
            a_chars = a_buf->str;
            a_len = a_buf->length;
        }
    }

    if (get_type_id(b_root.get()) == LMD_TYPE_VELMT) {
        Item namespace_item = ItemNull;
        VirtualOpStatus status = velmt_namespace_uri(b_root.get().velmt, &namespace_item);
        b_ns.set(namespace_item);
        if (status == VIRTUAL_OP_ERROR ||
                (status == VIRTUAL_OP_OK && get_type_id(b_ns.get()) != LMD_TYPE_NULL &&
                    !is_text_type_id(get_type_id(b_ns.get())))) {
            *failed = true;
        } else if (status == VIRTUAL_OP_OK && is_text_type_id(get_type_id(b_ns.get()))) {
            b_chars = b_ns.get().get_chars();
            b_len = b_ns.get().get_len();
        }
    } else {
        TypeElmt* type = b_root.get().element ? (TypeElmt*)b_root.get().element->type : NULL;
        if (type && type->ns && target_to_url_string(type->ns, b_buf)) {
            b_chars = b_buf->str;
            b_len = b_buf->length;
        }
    }

    size_t min_len = a_len < b_len ? a_len : b_len;
    int cmp = min_len ? memcmp(a_chars, b_chars, min_len) : 0;
    if (!cmp) cmp = (a_len > b_len) - (a_len < b_len);
    strbuf_free(a_buf);
    strbuf_free(b_buf);
    return cmp < 0 ? -1 : cmp > 0 ? 1 : 0;
}

// S5.4.3: virtual and materialized elements share one structural relation.
static Bool element_semantic_eq(Item a_item, Item b_item, int depth,
        EqualityMode mode) {
    RootFrame roots(5);
    Rooted<Item> a_root(roots, a_item);
    Rooted<Item> b_root(roots, b_item);
    Rooted<Item> key_root(roots, ItemNull);
    Rooted<Item> value_a_root(roots, ItemNull);
    Rooted<Item> value_b_root(roots, ItemNull);

    Item tag_a = ItemNull;
    VirtualOpStatus tag_a_status = element_tag_for(a_root.get(), &tag_a);
    key_root.set(tag_a);
    Item tag_b = ItemNull;
    VirtualOpStatus tag_b_status = element_tag_for(b_root.get(), &tag_b);
    value_a_root.set(tag_b);
    if (tag_a_status == VIRTUAL_OP_ERROR || tag_b_status == VIRTUAL_OP_ERROR) return BOOL_ERROR;
    if (tag_a_status != VIRTUAL_OP_OK || tag_b_status != VIRTUAL_OP_OK ||
            !element_text_equal(key_root.get(), value_a_root.get())) return BOOL_FALSE;

    bool namespace_failed = false;
    int namespace_cmp = element_namespace_cmp(a_root.get(), b_root.get(), &namespace_failed);
    if (namespace_failed) return BOOL_ERROR;
    if (namespace_cmp != 0) return BOOL_FALSE;

    int64_t attr_count_a = element_attr_count_for(a_root.get());
    int64_t attr_count_b = element_attr_count_for(b_root.get());
    if (attr_count_a != attr_count_b) return BOOL_FALSE;
    for (int64_t i = 0; i < attr_count_a; i++) {
        Item key = ItemNull;
        VirtualOpStatus key_status = element_attr_key_at_for(a_root.get(), i, &key);
        key_root.set(key);
        if (key_status == VIRTUAL_OP_ERROR) return BOOL_ERROR;
        if (key_status != VIRTUAL_OP_OK) return BOOL_FALSE;

        Item value_a = ItemNull;
        VirtualOpStatus value_a_status = element_attr_value_at_for(a_root.get(), i, &value_a);
        value_a_root.set(value_a);
        Item value_b = ItemNull;
        VirtualOpStatus value_b_status = element_attr_get_for(
            b_root.get(), key_root.get(), &value_b);
        value_b_root.set(value_b);
        if (value_a_status == VIRTUAL_OP_ERROR || value_b_status == VIRTUAL_OP_ERROR) {
            return BOOL_ERROR;
        }
        if (value_a_status != VIRTUAL_OP_OK || value_b_status != VIRTUAL_OP_OK) {
            return BOOL_FALSE;
        }
        Bool attr_equal = fn_eq_depth(value_a_root.get(), value_b_root.get(),
            depth + 1, mode);
        if (attr_equal != BOOL_TRUE) return attr_equal;
    }

    int64_t child_count_a = get_type_id(a_root.get()) == LMD_TYPE_VELMT
        ? velmt_child_count(a_root.get().velmt) : a_root.get().element->length;
    int64_t child_count_b = get_type_id(b_root.get()) == LMD_TYPE_VELMT
        ? velmt_child_count(b_root.get().velmt) : b_root.get().element->length;
    if (child_count_a != child_count_b) return BOOL_FALSE;
    for (int64_t i = 0; i < child_count_a; i++) {
        Item child_a = get_type_id(a_root.get()) == LMD_TYPE_VELMT
            ? velmt_child_get(a_root.get().velmt, i) : a_root.get().element->items[i];
        value_a_root.set(child_a);
        Item child_b = get_type_id(b_root.get()) == LMD_TYPE_VELMT
            ? velmt_child_get(b_root.get().velmt, i) : b_root.get().element->items[i];
        value_b_root.set(child_b);
        Bool child_equal = fn_eq_depth(value_a_root.get(), value_b_root.get(),
            depth + 1, mode);
        if (child_equal != BOOL_TRUE) return child_equal;
    }
    return BOOL_TRUE;
}

// Compare virtual maps with either map carrier through one presence-aware field walk.
static Bool virtual_map_eq(Item a_item, Item b_item, int depth, EqualityMode mode) {
    if (a_item.item == b_item.item) return BOOL_TRUE;
    RootFrame roots(5);
    Rooted<Item> a_root(roots, a_item);
    Rooted<Item> b_root(roots, b_item);
    Rooted<Item> key_root(roots, ItemNull);
    Rooted<Item> val_a(roots, ItemNull);
    Rooted<Item> val_b(roots, ItemNull);
    bool native_b = get_type_id(b_item) == LMD_TYPE_MAP;
    if (native_b && lambda_value_nominal(LMD_TYPE_MAP,
            (const void*)(uintptr_t)b_item.item)) return BOOL_FALSE;
    // Handle equality is capability identity; two empty handle carriers must
    // never collapse to structural VMap equality.
    if (lambda_task_handle_is(a_item) || lambda_task_handle_is(b_item)) return BOOL_FALSE;
    int64_t count_a = a_root.get().vmap->vtable->count(a_root.get().vmap->data);
    int64_t count_b = native_b ? ((TypeMap*)b_root.get().map->type)->length
        : b_root.get().vmap->vtable->count(b_root.get().vmap->data);
    if (count_a != count_b) return BOOL_FALSE;

    // iterate A's keys and look up each in B
    for (int64_t i = 0; i < count_a; i++) {
        key_root.set(a_root.get().vmap->vtable->key_at(a_root.get().vmap->data, i));
        // S5.4.1: a missing key is distinct from a present null-valued key.
        if (native_b) {
            Item value = ItemNull;
            VirtualOpStatus status = materialized_map_field_get(b_root.get().map, key_root.get(), &value);
            val_b.set(value);
            if (status == VIRTUAL_OP_ERROR) return BOOL_ERROR;
            if (status != VIRTUAL_OP_OK) return BOOL_FALSE;
        } else {
            if (!vmap_backing_has(b_root.get().vmap, key_root.get())) return BOOL_FALSE;
            val_b.set(b_root.get().vmap->vtable->get(b_root.get().vmap->data, key_root.get()));
        }
        val_a.set(a_root.get().vmap->vtable->value_at(a_root.get().vmap->data, i));
        Bool r = fn_eq_depth(val_a.get(), val_b.get(), depth + 1, mode);
        if (r == BOOL_ERROR) return BOOL_ERROR;
        if (r == BOOL_FALSE) return BOOL_FALSE;
    }
    return BOOL_TRUE;
}

// helper: get element at index from any sequence type (list, array, range)
static inline Item seq_get_element(Item item, TypeId tid, int64_t i) {
    switch (tid) {
    case LMD_TYPE_ARRAY:        return array_get(item.array, i);
    case LMD_TYPE_ARRAY_NUM:   return array_num_get(item.array_num, i);
    case LMD_TYPE_VARRAY:       return varray_get(item.varray, i);
    case LMD_TYPE_RANGE:
        return item.range->is_char
            ? fn_chr((Item){.item = i2it(item.range->start + i)})
            : (Item){.item = i2it(item.range->start + i)};
    default:                   return ItemNull;
    }
}

// helper: get length from any sequence type
// For N-D ArrayNum, returns shape[0] (leading-axis count, NumPy-compatible).
// 1-D ArrayNum returns total length.
static inline int64_t seq_get_length(Item item, TypeId tid) {
    switch (tid) {
    case LMD_TYPE_ARRAY:        return item.array->length;
    case LMD_TYPE_ARRAY_NUM:   return array_num_iter_count(item.array_num);
    case LMD_TYPE_VARRAY:       return varray_count(item.varray);
    case LMD_TYPE_RANGE:       return item.range->length;
    default:                   return -1;
    }
}

// helper: cross-type sequence equality (range vs list, list vs array, etc.)
// element-wise comparison with numeric promotion
static Bool cross_seq_eq(Item a_item, TypeId a_tid, Item b_item, TypeId b_tid,
        int depth, EqualityMode mode) {
    int64_t len_a = seq_get_length(a_item, a_tid);
    int64_t len_b = seq_get_length(b_item, b_tid);
    if (len_a != len_b) return BOOL_FALSE;

    for (int64_t i = 0; i < len_a; i++) {
        Item elem_a = seq_get_element(a_item, a_tid, i);
        Item elem_b = seq_get_element(b_item, b_tid, i);
        Bool r = fn_eq_depth(elem_a, elem_b, depth + 1, mode);
        if (r == BOOL_ERROR) return BOOL_ERROR;
        if (r == BOOL_FALSE) return BOOL_FALSE;
    }
    return BOOL_TRUE;
}

static Bool function_eq(Function* a, Function* b, int depth, EqualityMode mode) {
    if (a == b) return BOOL_TRUE;
    if (!a || !b) return BOOL_FALSE;
    if (a->ptr != b->ptr || a->arity != b->arity || a->entry_abi != b->entry_abi ||
            a->has_kwargs != b->has_kwargs ||
            a->is_generator != b->is_generator ||
            a->is_coroutine != b->is_coroutine ||
            a->is_system_function_ref != b->is_system_function_ref ||
            a->requires_scalar_result_home != b->requires_scalar_result_home ||
            a->requires_runtime_context != b->requires_runtime_context) return BOOL_FALSE;
    if (a->closure_field_count != b->closure_field_count) return BOOL_FALSE;
    if (a->closure_field_count > 0) {
        if (!a->closure_env || !b->closure_env) return BOOL_FALSE;
        Item* a_fields = (Item*)a->closure_env;
        Item* b_fields = (Item*)b->closure_env;
        for (uint8_t i = 0; i < a->closure_field_count; i++) {
            Bool r = fn_eq_depth(a_fields[i], b_fields[i], depth + 1, mode);
            if (r != BOOL_TRUE) return r;
        }
        return BOOL_TRUE;
    }
    if (a->closure_env || b->closure_env) {
        // bound methods store the receiver as closure_env without a field count.
        return (a->closure_env == b->closure_env) ? BOOL_TRUE : BOOL_FALSE;
    }
    return BOOL_TRUE;
}

// 3-states comparison with depth tracking for structural equality
static Bool fn_eq_depth(Item a_item, Item b_item, int depth, EqualityMode mode) {
    if (depth > EQ_MAX_DEPTH) {
        if (mode == EQUALITY_STRICT) return BOOL_FALSE;
        // Equality depth is a language-visible runtime failure, not a native
        // fault. Return the existing three-state error lane so every caller
        // unwinds through its own completion path (D1.4v3/DI15v2).
        set_runtime_error(ERR_RUNTIME_ERROR,
            "structural equality recursion too deep (> %d)", EQ_MAX_DEPTH);
        return BOOL_ERROR;
    }

    TypeId a_type_id = get_type_id(a_item);
    TypeId b_type_id = get_type_id(b_item);
    if (mode == EQUALITY_STRICT && a_type_id != b_type_id) return BOOL_FALSE;
    if (a_type_id == LMD_TYPE_COMPLEX || b_type_id == LMD_TYPE_COMPLEX) {
        if (a_type_id == LMD_TYPE_COMPLEX && b_type_id == LMD_TYPE_COMPLEX) {
            Complex* a = a_item.get_complex();
            Complex* b = b_item.get_complex();
            if (!a || !b || isnan(a->real) || isnan(a->imag) ||
                    isnan(b->real) || isnan(b->imag)) return BOOL_FALSE;
            return (a->real == b->real && a->imag == b->imag) ? BOOL_TRUE : BOOL_FALSE;
        }
        Item complex_item = a_type_id == LMD_TYPE_COMPLEX ? a_item : b_item;
        Item real_item = a_type_id == LMD_TYPE_COMPLEX ? b_item : a_item;
        Complex* value = complex_item.get_complex();
        if (!value || value->imag != 0.0 || isnan(value->real) ||
                isnan(value->imag) || !is_numeric_type_id(get_type_id(real_item))) {
            return BOOL_FALSE;
        }
        // Native evaluator helpers use the TLS-only RootFrame ABI.
        RootFrame roots(2);
        Rooted<Item> rooted_complex(roots, complex_item);
        Rooted<Item> rooted_real(roots, real_item);
        value = rooted_complex.get().get_complex();
        // push_d() may collect before comparing an exact decimal or wide-integer peer.
        return value ? numeric_items_equal_exact(push_d(value->real), rooted_real.get()) : BOOL_FALSE;
    }
    if (IS_NUMERIC_ID(a_type_id) && IS_NUMERIC_ID(b_type_id)) {
        if (mode == EQUALITY_STRICT &&
                (a_type_id != b_type_id ||
                 (a_type_id == LMD_TYPE_NUM_SIZED &&
                  a_item.get_num_type() != b_item.get_num_type()))) {
            return BOOL_FALSE;
        }
        return numeric_items_equal_exact(a_item, b_item);
    }
    if (a_type_id != b_type_id) {
        // S5.4.1 / D7.4.5v2: a virtual carrier does not change the map value family.
        if ((a_type_id == LMD_TYPE_MAP && b_type_id == LMD_TYPE_VMAP) ||
                (a_type_id == LMD_TYPE_VMAP && b_type_id == LMD_TYPE_MAP)) {
            return virtual_map_eq(a_type_id == LMD_TYPE_VMAP ? a_item : b_item,
                a_type_id == LMD_TYPE_MAP ? a_item : b_item, depth, mode);
        }
        // special case: type(null) == null, type(error) == error
        // when one side is a type value and the other is null/error,
        // compare the type's inner type_id against the value's type_id
        if (a_type_id == LMD_TYPE_NULL || b_type_id == LMD_TYPE_NULL ||
            a_type_id == LMD_TYPE_ERROR || b_type_id == LMD_TYPE_ERROR) {
            // check if either side is a type value (container pointer with type_id == LMD_TYPE_TYPE)
            Item type_item, value_item;
            if (a_type_id == LMD_TYPE_TYPE) {
                type_item = a_item; value_item = b_item;
            } else if (b_type_id == LMD_TYPE_TYPE) {
                type_item = b_item; value_item = a_item;
            } else {
                // neither side is a type value — use existing null/error semantics
                return BOOL_FALSE;
            }
            // compare type's inner type_id against the value's type_id
            TypeType* tt = (TypeType*)type_item.type;
            return (tt->type->type_id == get_type_id(value_item)) ? BOOL_TRUE : BOOL_FALSE;
        }
        if (is_element_family_type_id(a_type_id) &&
                is_element_family_type_id(b_type_id)) {
            TypeNominal* nominal_a = lambda_value_nominal(a_type_id,
                (const void*)(uintptr_t)a_item.item);
            TypeNominal* nominal_b = lambda_value_nominal(b_type_id,
                (const void*)(uintptr_t)b_item.item);
            if (nominal_a != nominal_b) return BOOL_FALSE;
            return element_semantic_eq(a_item, b_item, depth, mode);
        }
        // cross-type sequence comparison: range, list, and array types
        // all represent ordered sequences and can be compared element-wise
        TypeId a_tid = a_type_id;
        TypeId b_tid = b_type_id;
        bool a_is_seq = (a_tid == LMD_TYPE_ARRAY ||
                         a_tid == LMD_TYPE_ARRAY_NUM || a_tid == LMD_TYPE_VARRAY ||
                         a_tid == LMD_TYPE_RANGE);
        bool b_is_seq = (b_tid == LMD_TYPE_ARRAY ||
                         b_tid == LMD_TYPE_ARRAY_NUM || b_tid == LMD_TYPE_VARRAY ||
                         b_tid == LMD_TYPE_RANGE);
        if (a_is_seq && b_is_seq) {
            return cross_seq_eq(a_item, a_tid, b_item, b_tid, depth, mode);
        }

        // equality is total across families; incompatible concrete families are unequal.
        return BOOL_FALSE;
    }

    if (a_type_id == LMD_TYPE_NULL) {
        return BOOL_TRUE; // null == null
    }
    else if (a_type_id == LMD_TYPE_ERROR) {
        // error values are poison for equality: even two errors are not equal.
        return BOOL_FALSE;
    }
    else if (a_type_id == LMD_TYPE_BOOL) {
        return (a_item.bool_val == b_item.bool_val) ? BOOL_TRUE : BOOL_FALSE;
    }
    else if (a_item._type_id == LMD_TYPE_DTIME) {
        DateTime dt_a = a_item.get_datetime();  DateTime dt_b = b_item.get_datetime();
        return (datetime_compare(&dt_a, &dt_b) == 0) ? BOOL_TRUE : BOOL_FALSE;
    }
    else if (a_item._type_id == LMD_TYPE_STRING || a_item._type_id == LMD_TYPE_BINARY) {
        // pointer identity fast-path (interned strings, same allocation)
        if (a_item.string_ptr == b_item.string_ptr) return BOOL_TRUE;
        const char* chars_a = a_item.get_chars();  const char* chars_b = b_item.get_chars();
        uint32_t len_a = a_item.get_len();  uint32_t len_b = b_item.get_len();
        bool result = (len_a == len_b && memcmp(chars_a, chars_b, len_a) == 0);
        return result ? BOOL_TRUE : BOOL_FALSE;
    }
    else if (a_item._type_id == LMD_TYPE_SYMBOL) {
        Symbol* sym_a = (Symbol*)a_item.symbol_ptr;
        Symbol* sym_b = (Symbol*)b_item.symbol_ptr;
        if (sym_a == sym_b) return BOOL_TRUE;
        if (!sym_a || !sym_b || symbol_has_js_identity(sym_a) ||
                symbol_has_js_identity(sym_b)) return BOOL_FALSE;
        if (sym_a->len != sym_b->len) return BOOL_FALSE;
        if (strncmp(sym_a->chars, sym_b->chars, sym_a->len) != 0) return BOOL_FALSE;
        return target_equal(symbol_lambda_namespace(sym_a),
            symbol_lambda_namespace(sym_b)) ? BOOL_TRUE : BOOL_FALSE;
    }
    else if (a_item._type_id == LMD_TYPE_RAW_POINTER) {
        // both are container/pointer types - resolve actual type_id
        TypeId a_tid = get_type_id(a_item);
        TypeId b_tid = get_type_id(b_item);

        if (a_tid == LMD_TYPE_ERROR || b_tid == LMD_TYPE_ERROR) {
            // error containers must not become equal through pointer identity.
            return BOOL_FALSE;
        }

        // pointer identity fast-path for all container types
        if (a_item.item == b_item.item) return BOOL_TRUE;

        if (a_tid == LMD_TYPE_PATH && b_tid == LMD_TYPE_PATH) {
            return path_equal(a_item.path, b_item.path) ? BOOL_TRUE : BOOL_FALSE;
        }

        // type values
        if (a_tid == LMD_TYPE_TYPE && b_tid == LMD_TYPE_TYPE) {
            // S5.5.2: normalized forms compare. The payload's tag alone made
            // every union, intersection, exclusion, occurrence and literal
            // type equal to every other (LR03-29).
            return lambda_type_repr_equal(a_item.type, b_item.type) ? BOOL_TRUE : BOOL_FALSE;
        }

        // structural equality for container types requires same resolved type
        if (a_tid != b_tid) {
            // cross-type sequence comparison (array[int] vs array[float], list vs range, etc.)
            bool a_is_seq = (a_tid == LMD_TYPE_ARRAY ||
                             a_tid == LMD_TYPE_ARRAY_NUM || a_tid == LMD_TYPE_VARRAY ||
                             a_tid == LMD_TYPE_RANGE);
            bool b_is_seq = (b_tid == LMD_TYPE_ARRAY ||
                             b_tid == LMD_TYPE_ARRAY_NUM || b_tid == LMD_TYPE_VARRAY ||
                             b_tid == LMD_TYPE_RANGE);
            if (a_is_seq && b_is_seq) {
                return cross_seq_eq(a_item, a_tid, b_item, b_tid, depth, mode);
            }
            return BOOL_FALSE;
        }

        // S5.4.2v3: nominal sameness gates structural comparison. A value
        // equals another only if BOTH carry the same nominal record, so a plain
        // map never equals a nominal one with identical fields, and two
        // different nominal types never equal each other.
        {
            TypeNominal* na = lambda_value_nominal(a_tid,
                (const void*)(uintptr_t)a_item.item);
            TypeNominal* nb = lambda_value_nominal(b_tid,
                (const void*)(uintptr_t)b_item.item);
            if (na != nb) return BOOL_FALSE;
        }
        // list structural equality
        if (a_tid == LMD_TYPE_ARRAY) {
            return list_eq(a_item.array, b_item.array, depth, mode);
        }
        if (a_tid == LMD_TYPE_VARRAY) {
            return cross_seq_eq(a_item, a_tid, b_item, b_tid, depth, mode);
        }
        // generic array (array of Items) structural equality
        if (a_tid == LMD_TYPE_ARRAY) {
            return list_eq((List*)a_item.array, (List*)b_item.array, depth, mode);
        }
        // typed array equality
        if (a_tid == LMD_TYPE_ARRAY_NUM) {
            return array_num_eq(a_item.array_num, b_item.array_num, depth, mode);
        }
        // map structural equality (order-independent)
        if (a_tid == LMD_TYPE_MAP) {
            return map_eq(a_item.map, b_item.map, depth, mode);
        }
        // element structural equality (tag + attrs + children)
        if (a_tid == LMD_TYPE_ELEMENT) {
            return element_eq(a_item.element, b_item.element, depth, mode);
        }
        if (a_tid == LMD_TYPE_VELMT) {
            return element_semantic_eq(a_item, b_item, depth, mode);
        }
        // vmap structural equality
        if (a_tid == LMD_TYPE_VMAP) {
            return virtual_map_eq(a_item, b_item, depth, mode);
        }
        // range equality (start, end, length)
        if (a_tid == LMD_TYPE_RANGE) {
            Range* ra = a_item.range;
            Range* rb = b_item.range;
            return (ra->is_char == rb->is_char && ra->start == rb->start &&
                    ra->end == rb->end && ra->length == rb->length)
                ? BOOL_TRUE : BOOL_FALSE;
        }
        // function reference equality
        if (a_tid == LMD_TYPE_FUNC) {
            return function_eq(a_item.function, b_item.function, depth, mode);
        }
        log_error("eq unsupported container type: %s", get_type_name(a_tid));
        return BOOL_ERROR;
    }
    log_error("unknown comparing type: %s", get_type_name(a_item._type_id));
    return BOOL_ERROR;
}

// Raw-pointer string equality for MIR inline fast path.
// Called when pointer identity check fails — compare content directly.
// Avoids boxing overhead and type dispatch of fn_eq.
Bool fn_str_eq_ptr(String* a, String* b) {
    if (a == b) return BOOL_TRUE;
    if (!a || !b) return BOOL_FALSE;
    if (a->len != b->len) return BOOL_FALSE;
    if (a->len == 0) return BOOL_TRUE;
    return memcmp(a->chars, b->chars, a->len) == 0 ? BOOL_TRUE : BOOL_FALSE;
}

// Raw-pointer symbol equality for MIR inline fast path.
Bool fn_sym_eq_ptr(Symbol* a, Symbol* b) {
    if (a == b) return BOOL_TRUE;
    if (!a || !b) return BOOL_FALSE;
    if (symbol_has_js_identity(a) || symbol_has_js_identity(b)) return BOOL_FALSE;
    if (a->len != b->len) return BOOL_FALSE;
    if (a->len > 0 && strncmp(a->chars, b->chars, a->len) != 0) return BOOL_FALSE;
    return target_equal(symbol_lambda_namespace(a),
        symbol_lambda_namespace(b)) ? BOOL_TRUE : BOOL_FALSE;
}

// 3-states comparison (public entry point)
Bool fn_eq(Item a_item, Item b_item) {
    return fn_eq_depth(a_item, b_item, 0, EQUALITY_VALUE);
}

Bool fn_eq_strict(Item a_item, Item b_item) {
    Bool result = fn_eq_depth(a_item, b_item, 0, EQUALITY_STRICT);
    return result == BOOL_TRUE ? BOOL_TRUE : BOOL_FALSE;
}

bool item_deep_equal(Item a_item, Item b_item) {
    return fn_eq_strict(a_item, b_item) == BOOL_TRUE;
}

Bool fn_ne(Item a_item, Item b_item) {
    Bool result = fn_eq(a_item, b_item);
    if (result == BOOL_ERROR) { return BOOL_ERROR; }
    return !result;
}

// S6.2.1v2 order bands, in ascending order. They were open-coded as integer
// literals at the `rank_a == N` sites below, which made inserting a band (PTH30
// put `path` between `symbol` and `string`) a renumbering exercise across two
// functions. Naming them makes an insertion local.
enum TotalOrderBand {
    ORDER_BAND_NULL = 0,
    ORDER_BAND_FALSE,
    ORDER_BAND_TRUE,
    ORDER_BAND_NUMBER,
    ORDER_BAND_DTIME,
    ORDER_BAND_SYMBOL,
    // PTH30: `path` is its own band between `symbol` and `string`, ordered
    // bytewise within the band by canonical spelling (S2.4.2v4).
    ORDER_BAND_PATH,
    ORDER_BAND_STRING,
    ORDER_BAND_BINARY,
    ORDER_BAND_SEQUENCE,
    ORDER_BAND_MAP,
    ORDER_BAND_OBJECT,
    ORDER_BAND_ELEMENT,
    ORDER_BAND_TYPE,
    ORDER_BAND_FUNC,
    ORDER_BAND_NAN,
    ORDER_BAND_ERROR,
    ORDER_BAND_OTHER,
};

static int total_type_rank(Item item) {
    TypeId tid = get_type_id(item);
    if (is_float_type_id(tid) && isnan(item.get_double())) return ORDER_BAND_NAN;
    if (tid == LMD_TYPE_DECIMAL && decimal_item_is_nan(item)) return ORDER_BAND_NAN;
    switch (tid) {
    case LMD_TYPE_NULL: return ORDER_BAND_NULL;
    case LMD_TYPE_BOOL: return item.bool_val ? ORDER_BAND_TRUE : ORDER_BAND_FALSE;
    case LMD_TYPE_INT: case LMD_TYPE_INT64: case LMD_TYPE_FLOAT:
    case LMD_TYPE_DECIMAL: case LMD_TYPE_NUM_SIZED: case LMD_TYPE_UINT64:
    case LMD_TYPE_COMPLEX:
        return ORDER_BAND_NUMBER;
    case LMD_TYPE_DTIME: return ORDER_BAND_DTIME;
    case LMD_TYPE_SYMBOL: return ORDER_BAND_SYMBOL;
    case LMD_TYPE_PATH: return ORDER_BAND_PATH;
    case LMD_TYPE_STRING: return ORDER_BAND_STRING;
    case LMD_TYPE_BINARY: return ORDER_BAND_BINARY;
    case LMD_TYPE_RANGE: case LMD_TYPE_ARRAY: case LMD_TYPE_ARRAY_NUM:
    case LMD_TYPE_VARRAY:
        return ORDER_BAND_SEQUENCE;
    case LMD_TYPE_MAP: case LMD_TYPE_VMAP:
        // S6.2.1: `object` is its own ORDER BAND between map and element. Since
        // the flip a nominal value wears a map or element tag, so the band is
        // selected by the record rather than by the tag.
        return lambda_value_nominal(tid, (const void*)(uintptr_t)item.item)
            ? ORDER_BAND_OBJECT : ORDER_BAND_MAP;
    case LMD_TYPE_ELEMENT: case LMD_TYPE_VELMT:
        return lambda_value_nominal(tid, (const void*)(uintptr_t)item.item)
            ? ORDER_BAND_OBJECT : ORDER_BAND_ELEMENT;
    case LMD_TYPE_TYPE:
        return ORDER_BAND_TYPE;
    case LMD_TYPE_FUNC:
        return ORDER_BAND_FUNC;
    case LMD_TYPE_ERROR:
        return ORDER_BAND_ERROR;
    default:
        return ORDER_BAND_OTHER;
    }
}

static int total_complex_component_cmp(double left, double right) {
    if (isnan(left) || isnan(right)) {
        if (isnan(left) && isnan(right)) {
            uint64_t left_bits, right_bits;
            __builtin_memcpy(&left_bits, &left, sizeof(left_bits));
            __builtin_memcpy(&right_bits, &right, sizeof(right_bits));
            return (left_bits > right_bits) - (left_bits < right_bits);
        }
        return isnan(left) ? 1 : -1;
    }
    return left < right ? -1 : left > right ? 1 : 0;
}

static int total_complex_cmp(Item a_item, Item b_item) {
    TypeId a_tid = get_type_id(a_item);
    TypeId b_tid = get_type_id(b_item);
    bool a_complex = a_tid == LMD_TYPE_COMPLEX;
    bool b_complex = b_tid == LMD_TYPE_COMPLEX;
    Complex* a = a_complex ? a_item.get_complex() : NULL;
    Complex* b = b_complex ? b_item.get_complex() : NULL;
    bool a_real = !a_complex || (a && a->imag == 0.0);
    bool b_real = !b_complex || (b && b->imag == 0.0);
    if (a_real && b_real) {
        RootFrame roots(2);
        Rooted<Item> rooted_a(roots, a_item);
        Rooted<Item> rooted_b(roots, b_item);
        a = a_complex ? rooted_a.get().get_complex() : NULL;
        b = b_complex ? rooted_b.get().get_complex() : NULL;
        Item ar = a_complex ? push_d(a->real) : rooted_a.get();
        Item br = b_complex ? push_d(b->real) : rooted_b.get();
        LambdaNumericComparison comparison = lambda_numeric_compare(ar, br);
        return comparison.valid && !comparison.unordered ? comparison.order : 0;
    }
    if (a_real != b_real) return a_real ? -1 : 1;
    int real_cmp = total_complex_component_cmp(a->real, b->real);
    return real_cmp ? real_cmp : total_complex_component_cmp(a->imag, b->imag);
}

static int total_byte_cmp(Item a_item, Item b_item) {
    const char* chars_a = a_item.get_chars();
    const char* chars_b = b_item.get_chars();
    uint32_t len_a = a_item.get_len();
    uint32_t len_b = b_item.get_len();
    uint32_t min_len = len_a < len_b ? len_a : len_b;
    int cmp = min_len ? memcmp(chars_a, chars_b, min_len) : 0;
    if (cmp != 0) return cmp < 0 ? -1 : 1;
    return (len_a > len_b) - (len_a < len_b);
}

static int shape_entry_name_cmp(ShapeEntry* a, ShapeEntry* b) {
    if (!a && !b) return 0;
    if (!a) return -1;
    if (!b) return 1;
    int ns_cmp = (a->ns > b->ns) - (a->ns < b->ns);
    if (ns_cmp != 0) return ns_cmp;
    const char* a_chars = a->name ? a->name->str : "";
    const char* b_chars = b->name ? b->name->str : "";
    int a_len = a->name ? (int)a->name->length : 0;
    int b_len = b->name ? (int)b->name->length : 0;
    int min_len = a_len < b_len ? a_len : b_len;
    int cmp = min_len ? memcmp(a_chars, b_chars, (size_t)min_len) : 0;
    if (cmp != 0) return cmp < 0 ? -1 : 1;
    return (a_len > b_len) - (a_len < b_len);
}

static int strview_total_cmp(StrView a, StrView b) {
    size_t min_len = a.length < b.length ? a.length : b.length;
    int cmp = min_len ? memcmp(a.str, b.str, min_len) : 0;
    if (cmp != 0) return cmp < 0 ? -1 : 1;
    return (a.length > b.length) - (a.length < b.length);
}

static ShapeEntry* map_next_sorted_field(TypeMap* type, ShapeEntry* previous) {
    ShapeEntry* best = NULL;
    FOR_EACH_MAP_FIELD(type, field) {
        if (previous && shape_entry_name_cmp(field, previous) <= 0) continue;
        if (!best || shape_entry_name_cmp(field, best) < 0) best = field;
    }
    return best;
}

static int map_data_total_cmp(TypeMap* type_a, void* data_a, TypeMap* type_b, void* data_b) {
    int64_t len_a = type_a ? type_a->length : 0;
    int64_t len_b = type_b ? type_b->length : 0;
    int len_cmp = (len_a > len_b) - (len_a < len_b);
    if (len_cmp != 0) return len_cmp;

    ShapeEntry* prev_a = NULL;
    ShapeEntry* prev_b = NULL;
    for (int64_t i = 0; i < len_a; i++) {
        ShapeEntry* field_a = map_next_sorted_field(type_a, prev_a);
        ShapeEntry* field_b = map_next_sorted_field(type_b, prev_b);
        int key_cmp = shape_entry_name_cmp(field_a, field_b);
        if (key_cmp != 0) return key_cmp;
        int val_cmp = total_cmp(_map_field_value(type_a, data_a, field_a),
                                _map_field_value(type_b, data_b, field_b));
        if (val_cmp != 0) return val_cmp;
        prev_a = field_a;
        prev_b = field_b;
    }
    return 0;
}

static int target_total_cmp(Target* a, Target* b) {
    if (target_equal(a, b)) return 0;
    if (!a) return -1;
    if (!b) return 1;
    StrBuf* a_buf = strbuf_new();
    StrBuf* b_buf = strbuf_new();
    target_to_url_string(a, a_buf);
    target_to_url_string(b, b_buf);
    size_t min_len = a_buf->length < b_buf->length ? a_buf->length : b_buf->length;
    int cmp = min_len ? memcmp(a_buf->str, b_buf->str, min_len) : 0;
    if (!cmp) cmp = (a_buf->length > b_buf->length) -
        (a_buf->length < b_buf->length);
    strbuf_free(a_buf);
    strbuf_free(b_buf);
    return cmp < 0 ? -1 : cmp > 0 ? 1 : 0;
}

static int element_attr_key_cmp(Item a, Item b) {
    Symbol* a_symbol = get_type_id(a) == LMD_TYPE_SYMBOL ? a.get_safe_symbol() : NULL;
    Symbol* b_symbol = get_type_id(b) == LMD_TYPE_SYMBOL ? b.get_safe_symbol() : NULL;
    if (symbol_has_js_identity(a_symbol) || symbol_has_js_identity(b_symbol)) {
        return a_symbol == b_symbol ? 0 : (a_symbol > b_symbol ? 1 : -1);
    }
    Target* a_ns = symbol_lambda_namespace(a_symbol);
    Target* b_ns = symbol_lambda_namespace(b_symbol);
    int ns_cmp = target_total_cmp(a_ns, b_ns);
    if (ns_cmp) return ns_cmp;
    if (!is_text_type_id(get_type_id(a)) || !is_text_type_id(get_type_id(b))) {
        return total_cmp(a, b);
    }
    uint32_t a_len = a.get_len();
    uint32_t b_len = b.get_len();
    uint32_t min_len = a_len < b_len ? a_len : b_len;
    int cmp = min_len ? memcmp(a.get_chars(), b.get_chars(), min_len) : 0;
    if (cmp) return cmp < 0 ? -1 : 1;
    return (a_len > b_len) - (a_len < b_len);
}

static bool element_attr_key_cmp_at(Item element_a, int64_t index_a,
        Item element_b, int64_t index_b, int* out_cmp) {
    RootFrame roots(4);
    Rooted<Item> a_root(roots, element_a);
    Rooted<Item> b_root(roots, element_b);
    Rooted<Item> key_a_root(roots, ItemNull);
    Rooted<Item> key_b_root(roots, ItemNull);
    Item key_a = ItemNull;
    VirtualOpStatus status_a = element_attr_key_at_for(a_root.get(), index_a, &key_a);
    key_a_root.set(key_a);
    Item key_b = ItemNull;
    VirtualOpStatus status_b = element_attr_key_at_for(b_root.get(), index_b, &key_b);
    key_b_root.set(key_b);
    if (status_a != VIRTUAL_OP_OK || status_b != VIRTUAL_OP_OK) return false;
    *out_cmp = element_attr_key_cmp(key_a_root.get(), key_b_root.get());
    return true;
}

static int64_t element_next_sorted_attr(Item element, int64_t previous) {
    int64_t count = element_attr_count_for(element);
    int64_t best = -1;
    for (int64_t candidate = 0; candidate < count; candidate++) {
        int cmp = 0;
        if (previous >= 0 &&
                (!element_attr_key_cmp_at(element, candidate, element, previous, &cmp) ||
                 cmp <= 0)) continue;
        if (best < 0 ||
                (element_attr_key_cmp_at(element, candidate, element, best, &cmp) && cmp < 0)) {
            best = candidate;
        }
    }
    return best;
}

static int element_attr_total_cmp(Item a_item, Item b_item) {
    RootFrame roots(4);
    Rooted<Item> a_root(roots, a_item);
    Rooted<Item> b_root(roots, b_item);
    Rooted<Item> value_a_root(roots, ItemNull);
    Rooted<Item> value_b_root(roots, ItemNull);
    int64_t count_a = element_attr_count_for(a_root.get());
    int64_t count_b = element_attr_count_for(b_root.get());
    if (count_a != count_b) return (count_a > count_b) - (count_a < count_b);
    int64_t previous_a = -1;
    int64_t previous_b = -1;
    for (int64_t i = 0; i < count_a; i++) {
        int64_t index_a = element_next_sorted_attr(a_root.get(), previous_a);
        int64_t index_b = element_next_sorted_attr(b_root.get(), previous_b);
        if (index_a < 0 || index_b < 0) return (index_a > index_b) - (index_a < index_b);
        int key_cmp = 0;
        if (!element_attr_key_cmp_at(a_root.get(), index_a,
                b_root.get(), index_b, &key_cmp)) {
            return (index_a > index_b) - (index_a < index_b);
        }
        if (key_cmp) return key_cmp;
        Item value_a = ItemNull;
        Item value_b = ItemNull;
        VirtualOpStatus status_a = element_attr_value_at_for(a_root.get(), index_a, &value_a);
        value_a_root.set(value_a);
        VirtualOpStatus status_b = element_attr_value_at_for(b_root.get(), index_b, &value_b);
        value_b_root.set(value_b);
        if (status_a != VIRTUAL_OP_OK || status_b != VIRTUAL_OP_OK) {
            return (status_a > status_b) - (status_a < status_b);
        }
        int value_cmp = total_cmp(value_a_root.get(), value_b_root.get());
        if (value_cmp) return value_cmp;
        previous_a = index_a;
        previous_b = index_b;
    }
    return 0;
}

static int element_semantic_total_cmp(Item a_item, Item b_item) {
    RootFrame roots(4);
    Rooted<Item> a_root(roots, a_item);
    Rooted<Item> b_root(roots, b_item);
    Rooted<Item> value_a_root(roots, ItemNull);
    Rooted<Item> value_b_root(roots, ItemNull);
    Item tag_a = ItemNull;
    VirtualOpStatus tag_status_a = element_tag_for(a_root.get(), &tag_a);
    value_a_root.set(tag_a);
    Item tag_b = ItemNull;
    VirtualOpStatus tag_status_b = element_tag_for(b_root.get(), &tag_b);
    value_b_root.set(tag_b);
    if (tag_status_a != tag_status_b) return (tag_status_a > tag_status_b) -
        (tag_status_a < tag_status_b);
    int tag_cmp = element_attr_key_cmp(value_a_root.get(), value_b_root.get());
    if (tag_cmp) return tag_cmp;
    bool namespace_failed = false;
    int namespace_cmp = element_namespace_cmp(a_root.get(), b_root.get(), &namespace_failed);
    if (namespace_cmp) return namespace_cmp;
    int attr_cmp = element_attr_total_cmp(a_root.get(), b_root.get());
    if (attr_cmp) return attr_cmp;
    int64_t count_a = get_type_id(a_root.get()) == LMD_TYPE_VELMT
        ? velmt_child_count(a_root.get().velmt) : a_root.get().element->length;
    int64_t count_b = get_type_id(b_root.get()) == LMD_TYPE_VELMT
        ? velmt_child_count(b_root.get().velmt) : b_root.get().element->length;
    int64_t min_count = count_a < count_b ? count_a : count_b;
    for (int64_t i = 0; i < min_count; i++) {
        Item child_a = get_type_id(a_root.get()) == LMD_TYPE_VELMT
            ? velmt_child_get(a_root.get().velmt, i) : a_root.get().element->items[i];
        value_a_root.set(child_a);
        Item child_b = get_type_id(b_root.get()) == LMD_TYPE_VELMT
            ? velmt_child_get(b_root.get().velmt, i) : b_root.get().element->items[i];
        value_b_root.set(child_b);
        int child_cmp = total_cmp(value_a_root.get(), value_b_root.get());
        if (child_cmp) return child_cmp;
    }
    return (count_a > count_b) - (count_a < count_b);
}

int total_cmp(Item a_item, Item b_item) {
    TypeId total_a_tid = get_type_id(a_item);
    TypeId total_b_tid = get_type_id(b_item);
    if ((total_a_tid == LMD_TYPE_COMPLEX || total_b_tid == LMD_TYPE_COMPLEX) &&
            is_numeric_type_id(total_a_tid) && is_numeric_type_id(total_b_tid)) {
        return total_complex_cmp(a_item, b_item);
    }
    int rank_a = total_type_rank(a_item);
    int rank_b = total_type_rank(b_item);
    if (rank_a != rank_b) return (rank_a > rank_b) - (rank_a < rank_b);

    TypeId a_tid = get_type_id(a_item);
    TypeId b_tid = get_type_id(b_item);
    if (rank_a == ORDER_BAND_NUMBER) {
        LambdaNumericComparison comparison = lambda_numeric_compare(a_item, b_item);
        if (comparison.valid && !comparison.unordered) return comparison.order;
        // A nan is unordered against every number, so the ORDER has to place it
        // by fiat or it is not an order at all: answering 0 made the relation
        // intransitive (1 == nan and nan == 3, yet 1 != 3), and a sort over an
        // array containing one then returned whatever its traversal happened to
        // produce. Nans sort after all numbers, as IEEE's own totalOrder does,
        // and are equivalent among themselves. Section 6's order is total; this
        // is where that is made true for poison.
        bool a_nan = fn_is_nan(a_item) == BOOL_TRUE;
        bool b_nan = fn_is_nan(b_item) == BOOL_TRUE;
        if (a_nan != b_nan) return a_nan ? 1 : -1;
        return 0;
    }
    if (a_tid == LMD_TYPE_DTIME) {
        DateTime dt_a = a_item.get_datetime();
        DateTime dt_b = b_item.get_datetime();
        return datetime_compare(&dt_a, &dt_b);
    }
    if (a_tid == LMD_TYPE_SYMBOL) {
        Symbol* sym_a = a_item.get_symbol();
        Symbol* sym_b = b_item.get_symbol();
        bool a_js_identity = symbol_has_js_identity(sym_a);
        bool b_js_identity = symbol_has_js_identity(sym_b);
        if (a_js_identity || b_js_identity) {
            if (a_js_identity != b_js_identity) return a_js_identity ? 1 : -1;
            return (sym_a > sym_b) - (sym_a < sym_b);
        }
        Target* a_ns = symbol_lambda_namespace(sym_a);
        Target* b_ns = symbol_lambda_namespace(sym_b);
        int ns_cmp = (a_ns > b_ns) - (a_ns < b_ns);
        if (ns_cmp != 0) return ns_cmp;
        return total_byte_cmp(a_item, b_item);
    }
    if (a_tid == LMD_TYPE_STRING || a_tid == LMD_TYPE_BINARY) {
        return total_byte_cmp(a_item, b_item);
    }
    if (a_tid == LMD_TYPE_PATH) {
        // PTH30: within the `path` band the order is bytewise over the
        // CANONICAL spelling (S2.4.2v4), not over the segment list, so two
        // paths that print alike order alike whatever their segment structure.
        StrBuf* sb_a = strbuf_new();
        StrBuf* sb_b = strbuf_new();
        if (a_item.path) path_to_string(a_item.path, sb_a);
        if (b_item.path) path_to_string(b_item.path, sb_b);
        uint32_t len_a = sb_a->length, len_b = sb_b->length;
        uint32_t min_len = len_a < len_b ? len_a : len_b;
        int cmp = min_len ? memcmp(sb_a->str, sb_b->str, min_len) : 0;
        strbuf_free(sb_a);  strbuf_free(sb_b);
        if (cmp != 0) return cmp < 0 ? -1 : 1;
        return (len_a > len_b) - (len_a < len_b);
    }
    if (rank_a == ORDER_BAND_SEQUENCE) {
        int64_t len_a = seq_get_length(a_item, a_tid);
        int64_t len_b = seq_get_length(b_item, b_tid);
        int64_t min_len = len_a < len_b ? len_a : len_b;
        for (int64_t i = 0; i < min_len; i++) {
            int cmp = total_cmp(seq_get_element(a_item, a_tid, i), seq_get_element(b_item, b_tid, i));
            if (cmp != 0) return cmp;
        }
        return (len_a > len_b) - (len_a < len_b);
    }
    if (rank_a == ORDER_BAND_MAP) {
        bool a_handle = a_tid == LMD_TYPE_VMAP && lambda_task_handle_is(a_item);
        bool b_handle = b_tid == LMD_TYPE_VMAP && lambda_task_handle_is(b_item);
        if (a_handle || b_handle) {
            if (a_handle != b_handle) return a_handle ? 1 : -1;
            uintptr_t a_ptr = (uintptr_t)a_item.vmap;
            uintptr_t b_ptr = (uintptr_t)b_item.vmap;
            return (a_ptr > b_ptr) - (a_ptr < b_ptr);
        }
        if (a_tid == LMD_TYPE_VMAP || b_tid == LMD_TYPE_VMAP) {
            // D2.6.6: the operand may be a map OR an element-shaped value, so
            // the attribute shape must be reached by kind, never through `.map`.
            int64_t len_a = a_tid == LMD_TYPE_VMAP ? a_item.vmap->vtable->count(a_item.vmap->data)
                                                   : lambda_attr_shape(a_tid, a_item.map)->length;
            int64_t len_b = b_tid == LMD_TYPE_VMAP ? b_item.vmap->vtable->count(b_item.vmap->data)
                                                   : lambda_attr_shape(b_tid, b_item.map)->length;
            return (len_a > len_b) - (len_a < len_b);
        }
        return map_data_total_cmp(lambda_attr_shape(a_tid, a_item.map),
                                  lambda_attr_data(a_tid, a_item.map),
                                  lambda_attr_shape(b_tid, b_item.map),
                                  lambda_attr_data(b_tid, b_item.map));
    }
    // S6.2.2v3: a nominal value is compared by its RECORD, whatever structural
    // tag it wears, so this must be keyed on the record and must come before
    // the structural arms that would otherwise claim it.
    if (lambda_value_nominal(a_tid, (const void*)(uintptr_t)a_item.item)) {
        // S6.2.2v3: nominal values order by type name, then attributes, then
        // content — the name is read from the record, which is the one place it
        // lives once nominal-ness is a descriptor property.
        TypeMap* type_a = (TypeMap*)a_item.object->type;
        TypeMap* type_b = (TypeMap*)b_item.object->type;
        StrView name_a = type_a && type_a->nominal ? type_a->nominal->type_name : StrView{};
        StrView name_b = type_b && type_b->nominal ? type_b->nominal->type_name : StrView{};
        int name_cmp = strview_total_cmp(name_a, name_b);
        if (name_cmp != 0) return name_cmp;
        int attr_cmp = map_data_total_cmp(type_a, a_item.object->data,
                                          type_b, b_item.object->data);
        if (attr_cmp != 0) return attr_cmp;
        int64_t len_a = a_item.object->length;
        int64_t len_b = b_item.object->length;
        int64_t min_len = len_a < len_b ? len_a : len_b;
        for (int64_t i = 0; i < min_len; i++) {
            int child_cmp = total_cmp(a_item.object->items[i], b_item.object->items[i]);
            if (child_cmp != 0) return child_cmp;
        }
        return (len_a > len_b) - (len_a < len_b);
    }
    if (is_element_family_type_id(a_tid) && is_element_family_type_id(b_tid)) {
        return element_semantic_total_cmp(a_item, b_item);
    }
    if (a_tid == LMD_TYPE_TYPE) {
        TypeType* at = (TypeType*)a_item.type;
        TypeType* bt = (TypeType*)b_item.type;
        TypeId aid = at && at->type ? at->type->type_id : LMD_TYPE_NULL;
        TypeId bid = bt && bt->type ? bt->type->type_id : LMD_TYPE_NULL;
        return (aid > bid) - (aid < bid);
    }
    return (a_item.item > b_item.item) - (a_item.item < b_item.item);
}

// 3-state value/ordered comparison
// Scalar 3-state ordered comparison (BOOL_TRUE/BOOL_FALSE/BOOL_ERROR).  The
// public fn_lt/fn_gt/fn_le/fn_ge wrappers keep symbolic comparisons scalar-only;
// explicit keyword operators route vector masks through vec_cmp.
static bool datetime_magnitude_comparable(DateTime* a, DateTime* b) {
    bool a_time = a->precision == DATETIME_PRECISION_TIME_ONLY;
    bool b_time = b->precision == DATETIME_PRECISION_TIME_ONLY;
    return a_time == b_time;
}

// Ordering outcome for a scalar pair. `UNORDERED` is kept distinct from `LT`
// so that `<=`/`>=` cannot be derived by negating `>`/`<`: with a NaN operand
// no ordered relation holds, and `!(a > b)` would wrongly report `a <= b`
// (Lambda_Formal_Semantics.md 6.1 — poison stays incomparable, IEEE).
typedef enum ScalarOrder {
    SCALAR_ORDER_LT,
    SCALAR_ORDER_EQ,
    SCALAR_ORDER_GT,
    SCALAR_ORDER_UNORDERED,
    SCALAR_ORDER_INVALID,
} ScalarOrder;

static ScalarOrder scalar_order(Item a_item, Item b_item) {
    TypeId a_type_id = get_type_id(a_item);
    TypeId b_type_id = get_type_id(b_item);
    if (IS_NUMERIC_ID(a_type_id) && IS_NUMERIC_ID(b_type_id)) {
        LambdaNumericComparison comparison = lambda_numeric_compare(a_item, b_item);
        if (!comparison.valid) return SCALAR_ORDER_INVALID;
        if (comparison.unordered) return SCALAR_ORDER_UNORDERED;
        return comparison.order < 0 ? SCALAR_ORDER_LT :
            comparison.order > 0 ? SCALAR_ORDER_GT : SCALAR_ORDER_EQ;
    }
    if (a_type_id != b_type_id) {
        // Type mismatch error for ordered comparisons
        return SCALAR_ORDER_INVALID;
    }

    if (a_type_id == LMD_TYPE_NULL) {
        return SCALAR_ORDER_INVALID;  // public wrappers absorb null before scalar comparison
    }
    else if (a_type_id == LMD_TYPE_BOOL) {
        return SCALAR_ORDER_INVALID;  // bool does not support <, >, <=, >=
    }
    else if (a_type_id == LMD_TYPE_DTIME) {
        DateTime dt_a = a_item.get_datetime();  DateTime dt_b = b_item.get_datetime();
        if (!datetime_magnitude_comparable(&dt_a, &dt_b)) return SCALAR_ORDER_INVALID;
        int cmp = datetime_compare(&dt_a, &dt_b);
        return cmp < 0 ? SCALAR_ORDER_LT : cmp > 0 ? SCALAR_ORDER_GT : SCALAR_ORDER_EQ;
    }
    else if (a_type_id == LMD_TYPE_STRING) {
        const char* chars_a = a_item.get_chars();  const char* chars_b = b_item.get_chars();
        uint32_t len_a = a_item.get_len();  uint32_t len_b = b_item.get_len();
        uint32_t min_len = len_a < len_b ? len_a : len_b;
        int cmp = min_len ? memcmp(chars_a, chars_b, min_len) : 0;
        // strings/binaries are length-prefixed; embedded NUL bytes participate in ordering.
        if (cmp != 0) return cmp < 0 ? SCALAR_ORDER_LT : SCALAR_ORDER_GT;
        return len_a < len_b ? SCALAR_ORDER_LT :
            len_a > len_b ? SCALAR_ORDER_GT : SCALAR_ORDER_EQ;
    }
    log_error("unknown comparing type: %s", get_type_name(a_type_id));
    return SCALAR_ORDER_INVALID;
}

// The four ordered relations all read the same ordering; an unordered pair
// satisfies none of them, and an invalid pair errors.
static inline Bool scalar_order_holds(ScalarOrder order, bool lt, bool eq, bool gt) {
    switch (order) {
    case SCALAR_ORDER_LT: return lt ? BOOL_TRUE : BOOL_FALSE;
    case SCALAR_ORDER_EQ: return eq ? BOOL_TRUE : BOOL_FALSE;
    case SCALAR_ORDER_GT: return gt ? BOOL_TRUE : BOOL_FALSE;
    case SCALAR_ORDER_UNORDERED: return BOOL_FALSE;
    default: return BOOL_ERROR;
    }
}

Bool fn_lt_scalar(Item a_item, Item b_item) {
    return scalar_order_holds(scalar_order(a_item, b_item), true, false, false);
}

Bool fn_gt_scalar(Item a_item, Item b_item) {
    return scalar_order_holds(scalar_order(a_item, b_item), false, false, true);
}

Bool fn_le_scalar(Item a_item, Item b_item) {
    return scalar_order_holds(scalar_order(a_item, b_item), true, true, false);
}

Bool fn_ge_scalar(Item a_item, Item b_item) {
    return scalar_order_holds(scalar_order(a_item, b_item), false, true, true);
}

Item fn_lt(Item a_item, Item b_item) {
    if (get_type_id(a_item) == LMD_TYPE_NULL || get_type_id(b_item) == LMD_TYPE_NULL)
        return ItemNull;
    Bool r = fn_lt_scalar(a_item, b_item);
    return (r == BOOL_ERROR) ? ItemError : (Item){ .item = b2it(r) };
}

Item fn_gt(Item a_item, Item b_item) {
    if (get_type_id(a_item) == LMD_TYPE_NULL || get_type_id(b_item) == LMD_TYPE_NULL)
        return ItemNull;
    Bool r = fn_gt_scalar(a_item, b_item);
    return (r == BOOL_ERROR) ? ItemError : (Item){ .item = b2it(r) };
}

Item fn_le(Item a_item, Item b_item) {
    if (get_type_id(a_item) == LMD_TYPE_NULL || get_type_id(b_item) == LMD_TYPE_NULL)
        return ItemNull;
    Bool r = fn_le_scalar(a_item, b_item);
    return (r == BOOL_ERROR) ? ItemError : (Item){ .item = b2it(r) };
}

Item fn_ge(Item a_item, Item b_item) {
    if (get_type_id(a_item) == LMD_TYPE_NULL || get_type_id(b_item) == LMD_TYPE_NULL)
        return ItemNull;
    Bool r = fn_ge_scalar(a_item, b_item);
    return (r == BOOL_ERROR) ? ItemError : (Item){ .item = b2it(r) };
}

Bool fn_not(Item item) {
    // invert the truthiness of the item, not just logic NOT
    Bool result = is_truthy(item);
    if (result == BOOL_ERROR) return BOOL_ERROR;
    return !result;
}

// 3-state AND with short-circuiting truthy idiom
Item fn_and(Item a_item, Item b_item) {
    // fast path for boolean types
    if (a_item._type_id == LMD_TYPE_BOOL && b_item._type_id == LMD_TYPE_BOOL) {
        return {.item = b2it(a_item.bool_val && b_item.bool_val)};
    }
    // fallback to generic truthy idiom
    Bool a_truth = is_truthy(a_item);
    if (a_truth == BOOL_ERROR) return ItemError;
    if (a_truth == BOOL_FALSE) return a_item; // short-circuit return
    if (b_item._type_id == LMD_TYPE_ERROR) return ItemError;
    return b_item;  // always return b_item, no matter truthy or falsy
}

// 3-state OR with short-circuiting truthy idiom
Item fn_or(Item a_item, Item b_item) {
    // fast path for boolean types
    if (a_item._type_id == LMD_TYPE_BOOL && b_item._type_id == LMD_TYPE_BOOL) {
        return {.item = b2it(a_item.bool_val || b_item.bool_val)};
    }
    // fallback to generic truthy idiom
    Bool a_truth = is_truthy(a_item);
    if (a_truth == BOOL_ERROR) return ItemError;
    if (a_truth == BOOL_TRUE) return a_item; // short-circuit return
    if (b_item._type_id == LMD_TYPE_ERROR) return ItemError;
    return b_item;  // always return b_item, no matter truthy or falsy
}

// helper: get field value from a map/element's packed data by shape entry
static Item _map_field_value(TypeMap* map_type, void* data, ShapeEntry* field) {
    (void)map_type;
    if (!data || !field || !field->type) return ItemNull;
    if (!field->name) {
        // Spread attributes occupy unnamed slots containing a raw Map pointer;
        // reading that slot as its inferred ANY type corrupts equality and ordering.
        Map* nested_map = map_shape_field_to_map(data, field);
        return nested_map ? (Item){.map = nested_map} : ItemNull;
    }
    // packed map slots must use the canonical reader so query/equality handle
    // every scalar field type the same way as MapReader and serializers.
    return map_shape_field_to_item(data, field);
}

// S8.2.4v3: a null value never matches, even under `T | null`, so a query's
// absence is always the run of none rather than a run holding null.
static void query_push_match(Array* result, Item val, Item type_val) {
    if (val.item && get_type_id(val) != LMD_TYPE_NULL &&
            fn_is(val, type_val) == BOOL_TRUE) {
        array_push_verbatim(result, val);
    }
}

static void query_collect(Item data, Item type_val, bool self_inclusive, Array* result, int depth);

// D7.4.5v2: a host-backed carrier (VArray, Velmt, VMap) keeps its content behind
// a vtable, out of reach of the layout arms below. `for (x in e)` walks it
// through the iteration helpers -- attribute values then children, a map's
// values, an array's items -- and a type query walks what `for` walks
// (S8.2.4v3): one level for `e[T]`, every level for `e?T`.
static bool query_walks_virtual(TypeId type_id) {
    return type_id == LMD_TYPE_VARRAY || type_id == LMD_TYPE_VELMT ||
        type_id == LMD_TYPE_VMAP;
}

static void query_walk_virtual(Item data, Item type_val, bool recursive,
        Array* result, int depth) {
    // a host value read through the vtable may be materialized fresh, so it is
    // rooted while the walk below it allocates
    RootFrame roots(2);
    Rooted<Item> source(roots, data);
    Rooted<Item> current(roots, ItemNull);
    SymbolKeyList* keys = get_type_id(data) == LMD_TYPE_VARRAY ? NULL : item_keys(data);
    int64_t count = iter_len(source.get(), keys, 0);
    for (int64_t i = 0; i < count; i++) {
        current.set(iter_val_at(source.get(), keys, i, 0));
        if (recursive) query_collect(current.get(), type_val, true, result, depth + 1);
        else query_push_match(result, current.get(), type_val);
    }
    if (keys) symbol_key_list_free(keys);
}

// recursive helper: collect all items matching type_val into result array
static void query_collect(Item data, Item type_val, bool self_inclusive, Array* result, int depth) {
    if (depth > 1000) return;  // prevent infinite recursion
    if (!data.item) return;

    TypeId type_id = get_type_id(data);
    // S8.2.4v3: a list is a sequence, not a node. The query steps through it
    // set-at-a-time, applying itself to each item as it would to the list, so
    // `(d1, d2)?T` searches each item's descendants and `.?T` also tests the
    // items -- XPath's `$seq//T`. Items nested in one another are not
    // deduplicated: values have no identity to deduplicate by (SI13).
    if (type_id == LMD_TYPE_ARRAY && data.array->is_spreadable) {
        Array* list = data.array;
        for (int64_t i = 0; i < list->length; i++) {
            query_collect(array_item_read(list, i), type_val, self_inclusive, result, depth + 1);
        }
        return;
    }

    // check if this item matches the type (only at root level when self-inclusive)
    if (self_inclusive) query_push_match(result, data, type_val);

    // recurse into attributes and children (both ? and .? do this)
    if (type_id == LMD_TYPE_ELEMENT) {
        Element* elmt = data.element;
        // recurse into attributes
        TypeElmt* elmt_type = (TypeElmt*)elmt->type;
        FOR_EACH_MAP_FIELD(elmt_type, field) {
            if (field->name) {
                Item val = _map_field_value((TypeMap*)elmt_type, elmt->data, field);
                // always recurse with self_inclusive=true so descendants are fully searched
                if (val.item) query_collect(val, type_val, true, result, depth + 1);
            }
        }
        // recurse into content items
        for (int64_t i = 0; i < elmt->length; i++) {
            query_collect(elmt->items[i], type_val, true, result, depth + 1);
        }
    } else if (type_id == LMD_TYPE_MAP) {
        Map* map = data.map;
        TypeMap* map_type = (TypeMap*)map->type;
        FOR_EACH_MAP_FIELD(map_type, field) {
            if (field->name) {
                Item val = _map_field_value(map_type, map->data, field);
                if (val.item) query_collect(val, type_val, true, result, depth + 1);
            }
        }
    } else if (type_id == LMD_TYPE_ARRAY) {
        // a list was stepped through above; an array is a container of its items
        Array* arr = (Array*)data.array;
        for (int64_t i = 0; i < arr->length; i++) {
            query_collect(array_item_read(arr, i), type_val, true, result, depth + 1);
        }
    } else if (type_id == LMD_TYPE_ARRAY_NUM) {
        ArrayNum* arr = data.array_num;
        for (int64_t i = 0; i < arr->length; i++) {
            Item val = array_num_get(arr, i);
            query_collect(val, type_val, true, result, depth + 1);
        }
    } else if (type_id == LMD_TYPE_RANGE) {
        // S8.2.4v3: `e?T` is `e[T]` applied recursively, and `e[T]` walks a
        // range's values, so `(1 to 3)?int` finds them too (it found none)
        for (int64_t i = 0; i < data.range->length; i++) {
            query_push_match(result, item_at(data, i), type_val);
        }
    } else if (query_walks_virtual(type_id)) {
        query_walk_virtual(data, type_val, true, result, depth);
    }
}

// S8.2.4v3: a type key answers as XPath does -- `e?T` extends `e[1]` the way
// a name extends a position -- so its result is the run `T*` a subscript
// yields: `null` for no match, the match itself for one, and a list for more
// (S2.5.5v2). It is a value, never an item-position producer, so `[e?T, 9]`
// with no match is `[null, 9]`, exactly like `[e[-1], 9]`.
Item fn_query(Item data, Item type_val, int direct) {
    TypeId type_tid = get_type_id(type_val);
    if (type_tid != LMD_TYPE_TYPE) {
        log_error("query: 2nd argument must be a type, got: %s", get_type_name(type_tid));
        return ItemNull;
    }
    // use array (not list) to avoid automatic string merging. The walk can
    // allocate -- a virtual carrier's keys and values, a boxed field -- so the
    // accumulator and both operands are rooted (rule 15: precise roots only)
    RootFrame roots(3);
    Rooted<Item> source(roots, data);
    Rooted<Item> type_root(roots, type_val);
    Rooted<Array*> result(roots, array_plain());
    // direct=1 means .? (self-inclusive), direct=0 means ? (not self-inclusive)
    uint64_t failure_version = virtual_failure_version;
    query_collect(source.get(), type_root.get(), direct != 0, result.get(), 0);
    if (virtual_failure_version != failure_version) return err2it_or_error(context ? context->last_error : nullptr);
    return list_collapse_value({.array = result.get()});
}

// child-level query: collect direct attributes + children matching type_val (one level only)
static void child_query_collect(Item data, Item type_val, Array* result) {
    if (!data.item) return;

    TypeId type_id = get_type_id(data);
    if (type_id == LMD_TYPE_ELEMENT) {
        Element* elmt = data.element;
        // check attribute values
        TypeElmt* elmt_type = (TypeElmt*)elmt->type;
        FOR_EACH_MAP_FIELD(elmt_type, field) {
            if (field->name) {
                query_push_match(result,
                    _map_field_value((TypeMap*)elmt_type, elmt->data, field), type_val);
            }
        }
        // check direct children
        for (int64_t i = 0; i < elmt->length; i++) {
            query_push_match(result, elmt->items[i], type_val);
        }
    } else if (type_id == LMD_TYPE_MAP) {
        Map* map = data.map;
        TypeMap* map_type = (TypeMap*)map->type;
        FOR_EACH_MAP_FIELD(map_type, field) {
            if (field->name) {
                query_push_match(result, _map_field_value(map_type, map->data, field), type_val);
            }
        }
    } else if (type_id == LMD_TYPE_ARRAY) {
        // runtime lists and arrays share LMD_TYPE_ARRAY. S8.2.4v3: a list is
        // stepped set-at-a-time, as an XPath sequence is -- each item takes the
        // child step, so `(b1, b2)[div]` is the divs of both bodies and a scalar
        // item, which has no content, contributes nothing: `(1, "a", 2)[int]`
        // is null while the array `[1, "a", 2][int]` is (1, 2).
        Array* arr = (Array*)data.array;
        for (int64_t i = 0; i < arr->length; i++) {
            Item child = array_item_read(arr, i);
            if (arr->is_spreadable) child_query_collect(child, type_val, result);
            else query_push_match(result, child, type_val);
        }
    } else if (type_id == LMD_TYPE_ARRAY_NUM) {
        ArrayNum* arr = data.array_num;
        for (int64_t i = 0; i < arr->length; i++) {
            query_push_match(result, array_num_get(arr, i), type_val);
        }
    } else if (type_id == LMD_TYPE_RANGE) {
        // a range is the sequence of its values, so `(1 to 3)[int]` filters them
        for (int64_t i = 0; i < data.range->length; i++) {
            query_push_match(result, item_at(data, i), type_val);
        }
    } else if (query_walks_virtual(type_id)) {
        query_walk_virtual(data, type_val, false, result, 0);
    }
}

// child-level query: expr[T] where T is a type
Item fn_child_query(Item data, Item type_val) {
    // rooted as in fn_query: the walk can allocate before the last push
    RootFrame roots(3);
    Rooted<Item> source(roots, data);
    Rooted<Item> type_root(roots, type_val);
    Rooted<Array*> result(roots, array_plain());
    uint64_t failure_version = virtual_failure_version;
    child_query_collect(source.get(), type_root.get(), result.get());
    if (virtual_failure_version != failure_version) return err2it_or_error(context ? context->last_error : nullptr);
    return list_collapse_value({.array = result.get()});   // the run a subscript yields (S8.2.4v3)
}

static int64_t array_num_find_equal(ArrayNum* array, Item needle, bool reverse) {
    if (!array) return -1;
    RootFrame roots(2);
    Rooted<ArrayNum*> rooted_array(roots, array);
    Rooted<Item> rooted_needle(roots, needle);
    int64_t index = reverse ? array->length - 1 : 0;
    int64_t limit = reverse ? -1 : array->length;
    int64_t step = reverse ? -1 : 1;
    for (; index != limit; index += step) {
        // Compact arrays can contain sized and ordinary numeric lanes. Compare
        // boxed lane values through the language equality relation so an
        // arithmetic-derived `integer` is never truncated through binary64.
        Item value = array_num_get(rooted_array.get(), index);
        if (fn_eq(value, rooted_needle.get()) == BOOL_TRUE) return index;
    }
    return -1;
}

Bool fn_in(Item a_item, Item b_item) {
    // Formal semantics 7.6: the membership operators are value computations, so
    // an error operand propagates. `in` searches ONE level, so an error nested
    // deeper is invisible to it -- answering `false` would read as "this data is
    // error-free" when it may not be, which is worse than no answer. (An error
    // cannot be found by search anyway: `in` matches by equality and
    // `error == error` is false by 5.1, so the participating reading would have
    // answered a confident false in every case.) Asking whether data contains an
    // error anywhere needs a deep check, not this operator.
    if (get_type_id(a_item) == LMD_TYPE_ERROR ||
            get_type_id(b_item) == LMD_TYPE_ERROR) {
        return BOOL_ERROR;
    }
    if (get_type_id(b_item) == LMD_TYPE_MAP && get_type_id(a_item) == LMD_TYPE_STRING) {
        String* name = a_item.get_string();
        if (!utf8_key_is_canonical(name->chars, name->len)) {
            name = heap_create_name(name->chars, name->len);
            if (!name) return BOOL_ERROR;
            a_item.item = s2it(name);
        }
    }
    if (b_item._type_id) { // b is scalar
        if (is_text_type_id((TypeId)b_item._type_id)) {
            // S2.5.8/S8.1.1: `in` tests what `for … in` walks, so a string or
            // symbol is tested by code point -- `"a" in "cat"` is true and
            // `"at" in "cat"` is false. The substring test is `contains`.
            // Only a one-code-point text can equal one of those items.
            if (!is_text_type_id(get_type_id(a_item)) || fn_len(a_item) != 1) return BOOL_FALSE;
            RootFrame roots(2);
            Rooted<Item> rooted_needle(roots, a_item);
            Rooted<Item> rooted_text(roots, b_item);
            int64_t count = fn_len(rooted_text.get());
            for (int64_t i = 0; i < count; i++) {
                if (fn_eq(rooted_needle.get(), item_at(rooted_text.get(), i)) == BOOL_TRUE) {
                    return BOOL_TRUE;
                }
            }
            return BOOL_FALSE;
        }
        if (b_item._type_id == LMD_TYPE_BINARY) {
            Binary* bin = b_item.get_safe_binary();
            if (!bin) return BOOL_FALSE;
            const uint8_t* bytes = binary_data(bin);
            // Membership follows Lambda numeric equality so 173, 173u8, and
            // 173.0 all match the same byte without silently narrowing 256.
            for (uint32_t i = 0; i < binary_length(bin); i++) {
                Item byte = {.item = u8_to_item(bytes[i])};
                if (fn_eq(a_item, byte) == BOOL_TRUE) return BOOL_TRUE;
            }
            return BOOL_FALSE;
        }
    }
    else { // b is container
        TypeId b_type = b_item.container->type_id;
        if (b_type == LMD_TYPE_ARRAY) {
            List *list = b_item.array;
            for (int i = 0; i < list->length; i++) {
                if (fn_eq(array_item_read(list, i), a_item) == BOOL_TRUE) {
                    return true;
                }
            }
            return false;
        }
        else if (b_type == LMD_TYPE_RANGE) {
            return range_contains_item(b_item.range, a_item);
        }
        else if (b_type == LMD_TYPE_ARRAY) {
            Array *arr = b_item.array;
            for (int i = 0; i < arr->length; i++) {
                if (fn_eq(arr->items[i], a_item) == BOOL_TRUE) {
                    return true;
                }
            }
            return false;
        }
        else if (b_type == LMD_TYPE_ARRAY_NUM) {
            return array_num_find_equal(b_item.array_num, a_item, false) >= 0;
        }
        else if (b_type == LMD_TYPE_MAP) {
            // value membership: check if a matches any field value.
            // D2.6.6: an object keeps its shape and buffer at Element's
            // offsets, so both must be reached by kind, never through `.map`.
            TypeMap* map_type = lambda_attr_shape(b_type, b_item.map);
            void* map_data = lambda_attr_data(b_type, b_item.map);
            if (map_type) {
                FOR_EACH_MAP_FIELD(map_type, field) {
                    Item val = _map_field_value(map_type, map_data, field);
                    if (fn_eq(val, a_item) == BOOL_TRUE) {
                        return true;
                    }
                }
            }
            // S8.1.1/S8.1.2v2: whatever `for…in` walks, `in` tests. An object
            // walks attribute values THEN content, so membership must reach the
            // content too — checking fields alone made `"click" in btn` false
            // for a child the loop plainly yields.
            List* content = lambda_content_list(b_type, b_item.object);
            if (content) {
                for (int64_t i = 0; i < content->length; i++) {
                    if (fn_eq(content->items[i], a_item) == BOOL_TRUE) return true;
                }
            }
            return false;
        }
        else if (b_type == LMD_TYPE_VMAP) {
            // value membership: iterate all values and compare
            VMap* vm = b_item.vmap;
            int64_t count = vm->vtable->count(vm->data);
            for (int64_t i = 0; i < count; i++) {
                Item val = vm->vtable->value_at(vm->data, i);
                if (fn_eq(val, a_item) == BOOL_TRUE) {
                    return true;
                }
            }
            return false;
        }
        else if (b_type == LMD_TYPE_ELEMENT) {
            Element* elmt = b_item.element;
            TypeElmt* elmt_type = (TypeElmt*)elmt->type;
            // check attribute values
            if (elmt_type) {
                FOR_EACH_MAP_FIELD(elmt_type, field) {
                    Item val = _map_field_value((TypeMap*)elmt_type, elmt->data, field);
                    if (fn_eq(val, a_item) == BOOL_TRUE) {
                        return true;
                    }
                }
            }
            // check children (value membership)
            for (int64_t i = 0; i < elmt->length; i++) {
                if (fn_eq(elmt->items[i], a_item) == BOOL_TRUE) {
                    return true;
                }
            }
            return false;
        }
        else {
            log_debug("invalid type %d", b_type);
        }
    }
    return false;
}

static bool shape_has_named_key(TypeMap* map_type, Item key_item) {
    TypeId key_type = get_type_id(key_item);
    if (!is_text_type_id(key_type)) return false;
    const char* key = key_item.get_chars();
    uint32_t key_len = key_item.get_len();
    if (!key) return false;

    ShapeEntry* hit = typemap_hash_lookup(map_type, key, (int)key_len);
    if (hit && hit->name && hit->name->length == key_len &&
        memcmp(hit->name->str, key, key_len) == 0) {
        return true;
    }

    FOR_EACH_MAP_FIELD(map_type, field) {
        if (field->name && field->name->length == key_len &&
            memcmp(field->name->str, key, key_len) == 0) {
            return true;
        }
    }
    return false;
}

Bool fn_at(Item a_item, Item b_item) {
    // Formal semantics 7.6: the membership operators are value computations, so
    // an error operand propagates. `in` searches ONE level, so an error nested
    // deeper is invisible to it -- answering `false` would read as "this data is
    // error-free" when it may not be, which is worse than no answer. (An error
    // cannot be found by search anyway: `in` matches by equality and
    // `error == error` is false by 5.1, so the participating reading would have
    // answered a confident false in every case.) Asking whether data contains an
    // error anywhere needs a deep check, not this operator.
    if (get_type_id(a_item) == LMD_TYPE_ERROR ||
            get_type_id(b_item) == LMD_TYPE_ERROR) {
        return BOOL_ERROR;
    }
    TypeId b_type = get_type_id(b_item);
    if (b_type == LMD_TYPE_ARRAY || b_type == LMD_TYPE_ARRAY_NUM ||
        b_type == LMD_TYPE_RANGE) {
        // Formal semantics 8.0.1: `at` tests NAME presence, and a name is a
        // symbol key only -- an integer key is a key but not a name. Arrays key
        // their items by index, so they have no names and `1 at xs` is false.
        // This is what makes `at` worth having: it is the only way to range
        // over just the *named* members, which is meaningful on an element,
        // where `for (k at e)` gives the attributes without the children.
        // Admitting indices here would delete that capability. Iteration always
        // agreed (`for (k at xs)` yields nothing); membership was the outlier.
        // An index bound is written explicitly: `i < len(xs)`.
        return BOOL_FALSE;
    }
    if (b_type == LMD_TYPE_MAP) {
        // D2.6.6: an object keeps its shape at Element's offset, not Map's.
        return shape_has_named_key(lambda_attr_shape(b_type, b_item.map), a_item)
            ? BOOL_TRUE : BOOL_FALSE;
    }
    if (b_type == LMD_TYPE_ELEMENT) {
        return shape_has_named_key((TypeMap*)b_item.element->type, a_item) ? BOOL_TRUE : BOOL_FALSE;
    }
    if (b_type == LMD_TYPE_VMAP) {
        VMap* vm = b_item.vmap;
        if (!vm || !vm->vtable) return BOOL_FALSE;
        int64_t count = vm->vtable->count(vm->data);
        for (int64_t i = 0; i < count; i++) {
            if (fn_eq(vm->vtable->key_at(vm->data, i), a_item) == BOOL_TRUE) {
                return BOOL_TRUE;
            }
        }
    }
    return BOOL_FALSE;
}

// use struct overlays for static String with flexible array member
static struct { uint32_t len; uint8_t is_ascii; char chars[5]; } _str_null  = {4, 1, "null"};
static struct { uint32_t len; uint8_t is_ascii; char chars[5]; } _str_true  = {4, 1, "true"};
static struct { uint32_t len; uint8_t is_ascii; char chars[6]; } _str_false = {5, 1, "false"};
static struct { uint32_t len; uint8_t is_ascii; char chars[8]; } _str_error = {7, 1, "<error>"};
String& STR_NULL  = reinterpret_cast<String&>(_str_null);
String& STR_TRUE  = reinterpret_cast<String&>(_str_true);
String& STR_FALSE = reinterpret_cast<String&>(_str_false);
String& STR_ERROR = reinterpret_cast<String&>(_str_error);

static int fn_datetime_append_suffix(DateTime* dt, char* buf, size_t buf_size,
        int len) {
    if (dt->millisecond > 0) {
        len += snprintf(buf + len, buf_size - (size_t)len, ".%03d", dt->millisecond);
    }
    if (DATETIME_HAS_TIMEZONE(dt)) {
        int tz_offset = DATETIME_GET_TZ_OFFSET(dt);
        if (tz_offset == 0) {
            len += snprintf(buf + len, buf_size - (size_t)len, "z");
        } else {
            int hours = abs(tz_offset) / 60;
            int minutes = abs(tz_offset) % 60;
            len += snprintf(buf + len, buf_size - (size_t)len, "%+03d:%02d",
                tz_offset >= 0 ? hours : -hours, minutes);
        }
    }
    return len + snprintf(buf + len, buf_size - (size_t)len, "'");
}

// string() keeps its concise finite spelling, but NaN's sign is not semantic (S4.8.2).
static void format_string_float(char* buf, size_t capacity, double value) {
    if (isnan(value)) snprintf(buf, capacity, "nan");
    else snprintf(buf, capacity, "%g", value);
}

String* fn_string(Item itm) {
    TypeId type_id = get_type_id(itm);
    switch (type_id) {
    case LMD_TYPE_NULL:
        return &STR_NULL;
    case LMD_TYPE_BOOL:
        return itm.bool_val ? &STR_TRUE : &STR_FALSE;
    case LMD_TYPE_STRING:
        return itm.get_safe_string();
    case LMD_TYPE_BINARY: {
        Binary* bin = itm.get_safe_binary();
        StrBuf* sb = strbuf_new_cap(bin ? (size_t)binary_length(bin) * 2 + 6 : 6);
        if (!sb) return &STR_ERROR;
        // String conversion is deliberately lossless and readable; raw UTF-8
        // decoding requires an explicit codec rather than implicit text.
        format_binary_literal(sb, bin);
        String* result = heap_strcpy(sb->str, (int64_t)sb->length);
        strbuf_free(sb);
        return result ? result : &STR_ERROR;
    }
    case LMD_TYPE_SYMBOL: {
        // Symbol has different layout than String; create a String from symbol chars
        // heap_strcpy may collect before copying its source. Keep the Symbol's
        // owning Item exact-rooted so its inline character buffer stays live.
        RootFrame roots(1);
        Rooted<Item> rooted(roots, itm);
        Symbol* sym = rooted.get().get_safe_symbol();
        if (!sym) return &STR_NULL;
        return heap_strcpy(sym->chars, sym->len);
    }
    case LMD_TYPE_DTIME: {
        DateTime *dt = (DateTime*)itm.datetime_ptr;
        if (dt) {
            // Debug: Print the datetime precision and basic info
            log_debug("fn_string debug: DateTime precision=%d, hour=%d, minute=%d, second=%d, ms=%d",
                   dt->precision, dt->hour, dt->minute, dt->second, dt->millisecond);

            // Format datetime in Lambda format based on precision
            char buf[64];
            int len = 0;

            switch (dt->precision) {
                case DATETIME_PRECISION_YEAR_ONLY:
                    len = snprintf(buf, sizeof(buf), "t'%04d'", DATETIME_GET_YEAR(dt));
                    break;

                case DATETIME_PRECISION_DATE_ONLY:
                    len = snprintf(buf, sizeof(buf), "t'%04d-%02d-%02d'",
                        DATETIME_GET_YEAR(dt), DATETIME_GET_MONTH(dt), dt->day);
                    break;

                case DATETIME_PRECISION_TIME_ONLY: {
                    // Debug: Print the datetime values we're formatting
                    log_debug("fn_string debug: formatting time-only: %02d:%02d:%02d.%03d, tz_offset=%d",
                           dt->hour, dt->minute, dt->second, dt->millisecond,
                           DATETIME_HAS_TIMEZONE(dt) ? DATETIME_GET_TZ_OFFSET(dt) : -999);

                    // Format time-only without 'T' prefix
                    len = snprintf(buf, sizeof(buf), "t'%02d:%02d:%02d",
                        dt->hour, dt->minute, dt->second);

                    len = fn_datetime_append_suffix(dt, buf, sizeof(buf), len);
                    break;
                }

                case DATETIME_PRECISION_DATE_TIME:
                default: {
                    // Format full datetime with 'T' separator
                    len = snprintf(buf, sizeof(buf), "t'%04d-%02d-%02dT%02d:%02d:%02d",
                        DATETIME_GET_YEAR(dt), DATETIME_GET_MONTH(dt), dt->day,
                        dt->hour, dt->minute, dt->second);

                    len = fn_datetime_append_suffix(dt, buf, sizeof(buf), len);
                    break;
                }
            }

            return heap_strcpy(buf, len);
        } else {
            return &STR_NULL;
        }
    }
    case LMD_TYPE_INT: {
        // THE int renderer -- covers the whole C16 domain and the poison. The
        // i64 conversion this replaced clamped every value above 2^63, so
        // `string(2^70)` returned INT64_MAX while printing it was correct.
        StrBuf* sb = strbuf_new_cap(40);
        print_int_value(sb, lambda_int_item_value(itm));
        String* result = heap_strcpy(sb->str, (int64_t)sb->length);
        strbuf_free(sb);
        return result;
    }
    case LMD_TYPE_COMPLEX: {
        RootFrame roots(1);
        Rooted<Item> rooted(roots, itm);
        StrBuf* sb = strbuf_new_cap(64);
        if (!sb) return &STR_ERROR;
        print_item(sb, rooted.get(), 1, null);
        String* result = heap_strcpy(sb->str, sb->length);
        strbuf_free(sb);
        return result ? result : &STR_ERROR;
    }
    case LMD_TYPE_INT64: {
        char buf[32];
        int64_t long_val = itm.get_int64();
        snprintf(buf, sizeof(buf), "%lld", (long long)long_val);
        int len = strlen(buf);
        return heap_strcpy(buf, len);
    }
    case LMD_TYPE_FLOAT: {
        char buf[32];
        format_string_float(buf, sizeof(buf), itm.get_double());
        int len = strlen(buf);
        return heap_strcpy(buf, len);
    }
    case LMD_TYPE_NUM_SIZED: {
        char buf[32];
        NumSizedType st = itm.get_num_type();
        if (st == NUM_FLOAT16 || st == NUM_FLOAT32) {
            format_string_float(buf, sizeof(buf), itm.get_num_sized_as_double());
        } else {
            snprintf(buf, sizeof(buf), "%" PRId64, itm.get_num_sized_as_int64());
        }
        int len = strlen(buf);
        return heap_strcpy(buf, len);
    }
    case LMD_TYPE_UINT64: {
        char buf[32];
        snprintf(buf, sizeof(buf), "%" PRIu64, itm.get_uint64());
        int len = strlen(buf);
        return heap_strcpy(buf, len);
    }
    case LMD_TYPE_DECIMAL:  case LMD_TYPE_RANGE:  case LMD_TYPE_ARRAY:
    case LMD_TYPE_ARRAY_NUM:
    case LMD_TYPE_MAP:  case LMD_TYPE_ELEMENT:   {
        StrBuf* sb = strbuf_new();
        print_item(sb, itm, 1, null);  // make list print as list, instead of beaking onto multiple lines
        String* result = heap_strcpy(sb->str, sb->length);
        strbuf_free(sb);
        return result;
    }
    case LMD_TYPE_PATH: {
        Path* path = (Path*)itm.item;
        if (!path) return &STR_NULL;
        StrBuf* sb = strbuf_new();
        path_to_string(path, sb);
        String* result = heap_strcpy(sb->str, sb->length);
        strbuf_free(sb);
        return result;
    }
    case LMD_TYPE_TYPE: {
        // convert Type value to its name string, e.g. type(123) → "int"
        TypeType* type_type = (TypeType*)itm.type;
        if (!type_type || !type_type->type) return &STR_NULL;
        const char* name = type_alias_name(type_type->type);
        if (!name && type_type->type->type_id == LMD_TYPE_NUM_SIZED) {
            name = get_num_sized_type_name((NumSizedType)type_type->type->kind);
        } else if (!name) {
            name = get_type_name(type_type->type->type_id);
        }
        if (name) return heap_strcpy((char*)name, strlen(name));
        return &STR_NULL;
    }
    case LMD_TYPE_ERROR:
        // pointer-returning ABI cannot carry ItemError; never render an error as ordinary text.
        return nullptr;
    default:
        // for other types
        log_error("fn_string unhandled type: %s", get_type_name(itm._type_id));
        return &STR_NULL;
    }
}

Type* base_type(TypeId type_id) {
    return (type_id <= 0 || type_id >= LMD_TYPE_COUNT) ?
        &LIT_TYPE_ERROR : ((TypeInfo*)context->type_info)[type_id].lit_type;
}

Type* const_type(int64_t type_index) {
    ArrayList* type_list = (ArrayList*)context->type_list;
    if (type_index < 0 || type_index >= type_list->length) {
        return &LIT_TYPE_ERROR;
    }
    Type* type = (Type*)(type_list->data[type_index]);
    return type;
}

TypePattern* const_pattern(int64_t pattern_index) {
    ArrayList* type_list = (ArrayList*)context->type_list;
    if (pattern_index < 0 || pattern_index >= type_list->length) {
        log_error("const_pattern: invalid index %d", pattern_index);
        return nullptr;
    }
    Type* type = (Type*)(type_list->data[pattern_index]);
    if (type->kind != TYPE_KIND_PATTERN) {
        log_error("const_pattern: index %d is not a pattern, got type: %s (kind=%d)", pattern_index, get_type_name(type->type_id), type->kind);
        return nullptr;
    }
    return (TypePattern*)type;
}

// MIR Direct module-type-list-aware wrappers: save/restore context->type_list so that
// cross-module calls use this module's own type_list.
Type* const_type_with_tl(int64_t type_index, void* type_list_ptr) {
    void* saved = context->type_list;
    context->type_list = type_list_ptr;
    Type* r = const_type(type_index);
    context->type_list = saved;
    return r;
}
TypePattern* const_pattern_with_tl(int64_t pattern_index, void* type_list_ptr) {
    void* saved = context->type_list;
    context->type_list = type_list_ptr;
    TypePattern* r = const_pattern(pattern_index);
    context->type_list = saved;
    return r;
}

Type* fn_type(Item item) {
    TypeType *type = (TypeType *)heap_calloc(sizeof(TypeType) + sizeof(Type), LMD_TYPE_TYPE);
    Type *item_type = (Type *)((uint8_t *)type + sizeof(TypeType));
    type->type = item_type;  type->type_id = LMD_TYPE_TYPE;
    TypeId storage_type = get_type_id(item);
    TypeId resolved_type = storage_type;
    // C16 surface rule: the poison values `int` and `float` share report as the
    // narrower domain, the same convention that makes `type(1)` be `int`. Only
    // the surface answer moves -- the decoder still sees them as doubles.
    if (lambda_item_is_merged_poison(item.item)) resolved_type = LMD_TYPE_INT;
    // D2.6.6v2 phase 2: a nominal value reports its DECLARED type, whatever its
    // structural kind, so `name(type(p))` is still "Point". Checked before the
    // structural arms below, which would otherwise collapse it to map/element.
    if (lambda_value_nominal(storage_type, (const void*)(uintptr_t)item.item)) {
        type->type = (Type*)item.element->type;
        return (Type*)type;
    }
    if (resolved_type == LMD_TYPE_ELEMENT && item.element && item.element->type) {
        // preserve tag metadata for element type values instead of collapsing to generic element.
        type->type = (Type*)item.element->type;
        return (Type*)type;
    }
    if (resolved_type == LMD_TYPE_MAP && item.map && item.map->type) {
        TypeMap* map_type = (TypeMap*)item.map->type;
        if (map_type->struct_name) {
            // keep named map aliases visible while anonymous maps still collapse to generic map.
            type->type = (Type*)map_type;
            return (Type*)type;
        }
    }
    if (item_is_list(item)) {
        // S2.5.1v2: a list is a specialized array and type() names its kind
        type->type = &TYPE_LIST;
        return (Type*)type;
    }
    if (resolved_type == LMD_TYPE_DECIMAL) {
        Decimal* dec = item.get_decimal();
        if (dec && dec->storage_kind == DECIMAL_BIGINT) {
            // integer is a language type carried by Decimal storage; hide the carrier from type().
            type->type = &TYPE_INTEGER;
            return (Type*)type;
        }
    }
    resolved_type = item_semantic_type_id(resolved_type);
    if (resolved_type == LMD_TYPE_TYPE) {
        // the type of a type value is `type` itself: the compact TYPE_TYPE,
        // whose identity S5.5.2 equality compares. A fresh prefix with that tag
        // is neither -- `type(int) == type` was false -- and every unwrapper
        // would read it as a TypeType and step past its end
        type->type = &TYPE_TYPE;
        return (Type*)type;
    }
    if (resolved_type != LMD_TYPE_RAW_POINTER) {
        // self-tagged floats do not carry LMD_TYPE_FLOAT in the raw high byte.
        item_type->type_id = resolved_type;
    }
    else if (item.item == 0) {
        // handle raw 0 value (from y2it(nullptr) etc.) as null
        item_type->type_id = LMD_TYPE_NULL;
    }
    else if (item.container) {
        item_type->type_id = item.container->type_id;
    }
    else {
        // fallback to null for any other case
        item_type->type_id = LMD_TYPE_NULL;
    }
    // normalize specialized types to their base type for consistent comparison
    // e.g., array[int], array[int64], array[float] all map to 'array'
    //        vmap maps to 'map'
    TypeId tid = item_type->type_id;
    if (tid == LMD_TYPE_ARRAY_NUM) {
        item_type->type_id = LMD_TYPE_ARRAY;
    } else if (tid == LMD_TYPE_VMAP) {
        item_type->type_id = LMD_TYPE_MAP;
    } else if (tid == LMD_TYPE_NUM_SIZED) {
        // preserve the sub-type in the kind field for sized numerics
        item_type->kind = item.get_num_type();
    }
    // a container or function kind is its singleton: every reader of an
    // array, map, element or function type may take a bare prefix with that
    // tag for the extended struct and read past its end
    switch (item_type->type_id) {
    case LMD_TYPE_ARRAY: type->type = (Type*)&TYPE_ARRAY; break;
    case LMD_TYPE_MAP: type->type = &TYPE_MAP; break;
    case LMD_TYPE_ELEMENT: type->type = &TYPE_ELMT; break;
    case LMD_TYPE_FUNC: type->type = &TYPE_FUNC; break;
    default: break;
    }
    return (Type*)type;
}

Item lambda_type_value_from_contract(Type* contract) {
    if (!contract) return ItemError;
    TypeType* value = (TypeType*)heap_calloc(sizeof(TypeType), LMD_TYPE_TYPE);
    if (!value) return ItemError;
    value->type_id = LMD_TYPE_TYPE;
    value->kind = TYPE_KIND_SIMPLE;
    value->type = contract;
    return {.type = value};
}

static Symbol* fn_name_symbol_from_chars(const char* name, size_t len) {
    if (!name || len == 0) return nullptr;
    return heap_create_symbol(name, len);
}

static Symbol* fn_name_symbol_from_strview(StrView name) {
    return fn_name_symbol_from_chars(name.str, name.length);
}

static Symbol* fn_name_from_type(Type* type) {
    if (!type) return nullptr;
    if (const char* alias = type_alias_name(type)) {
        return fn_name_symbol_from_chars(alias, strlen(alias));
    }
    // D2.6.6v2 phase 2: a nominal type answers with its declared name whatever
    // its structural kind, so `name(type(p))` stays "Point" after the flip.
    if (TypeNominal* record = type_nominal_record(type)) {
        Symbol* nominal_name = fn_name_symbol_from_strview(record->type_name);
        if (nominal_name) return nominal_name;
    }
    // the generic `map`, `element` and `object` are bare Types with no shape
    // fields to read: `name(map)` read a TypeMap's name past their end
    switch (lambda_type_is_concrete_attr_shape(type) ? type->type_id : LMD_TYPE_NULL) {
    case LMD_TYPE_ELEMENT: {
        TypeElmt* elmt_type = (TypeElmt*)type;
        Symbol* elmt_name = fn_name_symbol_from_strview(elmt_type->name);
        if (elmt_name) return elmt_name;
        const char* fallback = get_type_name(type->type_id);
        return fn_name_symbol_from_chars(fallback, fallback ? strlen(fallback) : 0);
    }
    case LMD_TYPE_MAP: {
        TypeMap* map_type = (TypeMap*)type;
        if (map_type->struct_name) {
            return fn_name_symbol_from_chars(map_type->struct_name, strlen(map_type->struct_name));
        }
        break;
    }
    default:
        break;
    }
    const char* name = get_type_name(type->type_id);
    return fn_name_symbol_from_chars(name, name ? strlen(name) : 0);
}

/**
 * fn_name(item) - return the (local) name of an element, function, or type
 * Returns the name as a symbol, or nullptr if the item doesn't have a name.
 */
Symbol* fn_name(Item item) {
    TypeId type_id = get_type_id(item);

    switch (type_id) {
    case LMD_TYPE_NULL:
    case LMD_TYPE_ERROR:
        return nullptr;
    case LMD_TYPE_MAP: {
        // D2.6.6v2 phase 2: a nominal MAP answers with its declared name; a
        // structural map still has none.
        if (lambda_value_nominal(type_id, item.map)) {
            return fn_name_from_type((Type*)item.map->type);
        }
        return nullptr;
    }
    case LMD_TYPE_ELEMENT: {
        // name() reads intrinsic tag metadata; user attrs like name: must only affect .name.
        Element* elmt = item.element;
        if (!elmt || !elmt->type) return nullptr;
        return fn_name_from_type((Type*)elmt->type);
    }
    case LMD_TYPE_FUNC: {
        // return the function's name as a symbol
        Function* fn = item.function;
        if (!fn) return nullptr;
        // function name is stored in the name field
        if (fn->name && strlen(fn->name) > 0) return fn_name_symbol_from_chars(fn->name, strlen(fn->name));
        // We return null for anonymous functions
        return nullptr;
    }
    case LMD_TYPE_TYPE: {
        TypeType* type_type = (TypeType*)item.type;
        if (!type_type || !type_type->type) return nullptr;
        return fn_name_from_type(type_type->type);
    }
    case LMD_TYPE_SYMBOL: {
        // for symbols, just return the symbol itself (it's already a name)
        return item.get_safe_symbol();
    }
    default:
        return nullptr;
    }
}

// returns the TypeId of an item for use in MIR-compiled code
// declared extern "C" to allow calling from C code (path.c)
extern "C" TypeId item_type_id(Item item) {
    return item.type_id();
}

extern "C" Input* input_from_target(Target* target, String* type, String* flavor);
extern "C" Input* input_from_target_with_name_parent(Target* target, String* type,
    String* flavor, NamePool* name_parent);

static bool input_schema_collect_type(Type* type, NamePool* name_pool,
        ArrayList* visited) {
    if (!type || !name_pool || !visited) return true;
    for (int i = 0; i < visited->length; i++) {
        if (arraylist_get(visited, i) == type) return true;
    }
    if (!arraylist_append(visited, type)) return false;

    // Declarations wrap their semantic type.  Follow that edge before
    // examining fields so schema names are admitted exactly once regardless
    // of whether the caller supplied a named declaration or its body.
    Type* semantic_type = type_field_unwrap_simple_decl(type);
    if (semantic_type != type) {
        return input_schema_collect_type(semantic_type, name_pool, visited);
    }

    if (type->type_id == LMD_TYPE_MAP || type->type_id == LMD_TYPE_ELEMENT) {
        TypeMap* map_type = (TypeMap*)type;
        if (type->type_id == LMD_TYPE_ELEMENT) {
            TypeElmt* element_type = (TypeElmt*)type;
            if (element_type->name.str && element_type->name.length > 0 &&
                    !name_pool_create_len(name_pool, element_type->name.str,
                        element_type->name.length)) {
                return false;
            }
        }
        FOR_EACH_MAP_FIELD(map_type, field) {
            if (field->name && !name_pool_create_len(name_pool,
                    field->name->str, field->name->length)) return false;
            if (!input_schema_collect_type(field->type, name_pool, visited)) return false;
        }
        if (TypeNominal* record = type_nominal_record(type)) {
            // walk the nominal base chain, which is where inheritance lives now
            for (TypeNominal* base = record->base; base; base = base->base) {
                (void)base;  // records carry no shape of their own to collect
            }
        }
        return true;
    }
    if (type->type_id == LMD_TYPE_ARRAY) {
        return input_schema_collect_type(((TypeArray*)type)->nested,
            name_pool, visited);
    }
    if (type->type_id == LMD_TYPE_TYPE) {
        switch (type->kind) {
        case TYPE_KIND_SIMPLE:
            return input_schema_collect_type(((TypeType*)type)->type,
                name_pool, visited);
        case TYPE_KIND_UNARY:
            return input_schema_collect_type(((TypeUnary*)type)->operand,
                name_pool, visited);
        case TYPE_KIND_BINARY:
            return input_schema_collect_type(((TypeBinary*)type)->left,
                    name_pool, visited) &&
                input_schema_collect_type(((TypeBinary*)type)->right,
                    name_pool, visited);
        case TYPE_KIND_CONSTRAINED:
            return input_schema_collect_type(((TypeConstrained*)type)->base,
                name_pool, visited);
        case TYPE_KIND_BINDER:
            return input_schema_collect_type(((TypeBinder*)type)->bound,
                name_pool, visited);
        case TYPE_KIND_BOUND_REF:
            return input_schema_collect_type(((TypeBoundRef*)type)->bound,
                name_pool, visited);
        case TYPE_KIND_PARAM: {
            TypeParam* param = (TypeParam*)type;
            return input_schema_collect_type(param->full_type, name_pool, visited) &&
                input_schema_collect_type(param->contract_type, name_pool, visited);
        }
        default:
            return true;
        }
    }
    if (TypeFunc* fn = lambda_type_func_signature(type)) {
        if (!input_schema_collect_type(fn->returned, name_pool, visited) ||
                !input_schema_collect_type(fn->inferred_return, name_pool, visited) ||
                !input_schema_collect_type(fn->return_contract, name_pool, visited) ||
                !input_schema_collect_type(fn->error_type, name_pool, visited)) return false;
        for (TypeParam* param = fn->param; param; param = param->next) {
            if (!input_schema_collect_type(param->full_type, name_pool, visited) ||
                    !input_schema_collect_type(param->contract_type, name_pool, visited)) return false;
        }
        for (uint16_t slot = 0; slot < fn->binder_count; slot++) {
            TypeBinder* binder = fn->binders ? fn->binders[slot] : NULL;
            if (binder && !input_schema_collect_type(binder->bound, name_pool, visited)) {
                return false;
            }
        }
    }
    return true;
}

static bool input_schema_prepare_name_parent(Type* schema_type, NamePool* name_pool) {
    if (!schema_type || !name_pool) return true;
    ArrayList* visited = arraylist_new(16);
    if (!visited) return false;
    bool ok = input_schema_collect_type(schema_type, name_pool, visited);
    arraylist_free(visited);
    return ok;
}

Item fn_input2(Item target_item, Item type) {
    GUARD_ERROR2(target_item, type);
    RootFrame input_roots(4);
    Rooted<Item> input_target_root(input_roots, target_item);
    Rooted<Item> input_options_root(input_roots, type);
    Rooted<Item> input_type_root(input_roots, ItemNull);
    Rooted<Item> input_flavor_root(input_roots, ItemNull);
    virtual_error_reporter = [](Item error) {
        if (context) eval_context_set_last_error(context, it2err(error));
    };
    ZipLimits limits = zip_default_limits();
    ZipError zip_error = {};
    if (get_type_id(type) == LMD_TYPE_MAP) {
        IoFsOptionMap option_map = {};
        Item error = ItemNull;
        if (!io_fs_options_open(type, "input", SYSFUNC_INPUT2, &option_map, &error)) return error;
    }
    if (!fs_zip_options(type, &limits, nullptr, &zip_error)) {
        return runtime_error_item(ERR_TYPE_MISMATCH, zip_error.message, nullptr);
    }
    InputZipLimitsScope zip_scope(&limits);
    bool fs_target = fs_node_is(target_item);

    // Dry-run mode: return fabricated input data
    if (g_dry_run) {
        log_debug("dry-run: fabricated input() call");
        const char* content = "{\"name\": \"dry-run\", \"version\": \"1.0\", \"items\": [1, 2, 3], \"active\": true}";
        // check type hint for more realistic fabrication
        TypeId tid = get_type_id(type);
        if (is_text_type_id(tid)) {
            String* ts = fn_string(type);
            if (ts) {
                if (strcmp(ts->chars, "html") == 0) content = "<html><head><title>Mock</title></head><body><p>Dry-run</p></body></html>";
                else if (strcmp(ts->chars, "text") == 0 || strcmp(ts->chars, "txt") == 0) content = "Dry-run fabricated content.\nLine 2.\nLine 3: 42, 3.14\n";
                else if (strcmp(ts->chars, "csv") == 0) content = "name,age,city\nAlice,30,NYC\nBob,25,LA\n";
                else if (strcmp(ts->chars, "yaml") == 0 || strcmp(ts->chars, "yml") == 0) content = "name: dry-run\nversion: 1\n";
                else if (strcmp(ts->chars, "xml") == 0) content = "<root><item id=\"1\">mock</item></root>";
                else if (strcmp(ts->chars, "markdown") == 0 || strcmp(ts->chars, "md") == 0) content = "# Mock\n\nDry-run content.\n";
            }
        }
        String* result_str = heap_strcpy((char*)content, strlen(content));
        return {.item = s2it(result_str)};
    }
    String *type_str = NULL, *flavor_str = NULL;
    Type* schema_type = NULL;

    // Validate target type: must be string, symbol, or path
    TypeId target_type_id = get_type_id(target_item);
    if (!fs_target && !is_text_type_id(target_type_id) && target_type_id != LMD_TYPE_PATH) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "input target must be a string, symbol, or path, got type: %s",
            get_type_name(target_type_id));
        return ItemError;
    }

    // Convert target Item to Target struct
    Url* cwd = context ? (Url*)context->cwd : NULL;
    Target* target = fs_target ? nullptr : item_to_target(target_item.item, cwd);
    if (!fs_target && !target) {
        set_runtime_error(ERR_INVALID_URL, "input: failed to resolve target");
        return ItemError;
    }

    if (target) log_debug("fn_input2: target scheme=%d, type=%d", target->scheme, target->type);

    TypeId type_id = get_type_id(type);
    if (type_id == LMD_TYPE_NULL) {
        // No type specified
        type_str = NULL;
    }
    else if (is_text_type_id(type_id)) {
        // Legacy behavior: type is a simple string/symbol
        type_str = fn_string(type);
        input_type_root.set((Item){.item = s2it(type_str)});
    }
    else if (type_id == LMD_TYPE_MAP) {
        log_debug("input type is a map");
        // New behavior: type is a map with options
        Map* options_map = type.map;

        // Extract 'type' from map
        bool is_found;
        Item input_type = _map_get((TypeMap*)options_map->type, options_map->data, "type", &is_found);
        if (!is_found || !input_type.item || input_type._type_id == LMD_TYPE_NULL) { // missing 'type' key
            type_str = NULL;
        } else {
            TypeId type_value_type = get_type_id(input_type);
            if (is_text_type_id(type_value_type)) {
                type_str = fn_string(input_type);
                input_type_root.set((Item){.item = s2it(type_str)});
            }
            else {
                set_runtime_error(ERR_TYPE_MISMATCH,
                    "input type option must be a string or symbol, got type: %s",
                    get_type_name(type_value_type));
                target_free(target);
                return ItemError;
            }
        }

        // Extract 'flavor' from map
        Item input_flavor = _map_get((TypeMap*)options_map->type, options_map->data, "flavor", &is_found);
        if (!is_found || !input_flavor.item || input_flavor._type_id == LMD_TYPE_NULL) { // missing 'flavor' key
            flavor_str = NULL;
        } else {
            TypeId flavor_value_type = get_type_id(input_flavor);
            if (is_text_type_id(flavor_value_type)) {
                flavor_str = fn_string(input_flavor);
                input_flavor_root.set((Item){.item = s2it(flavor_str)});
            }
            else {
                set_runtime_error(ERR_TYPE_MISMATCH,
                    "input flavor option must be a string or symbol, got type: %s",
                    get_type_name(flavor_value_type));
                target_free(target);
                return ItemError;
            }
        }

        Item input_schema = _map_get((TypeMap*)options_map->type, options_map->data,
            "schema", &is_found);
        if (is_found && input_schema.item && input_schema._type_id != LMD_TYPE_NULL) {
            if (get_type_id(input_schema) != LMD_TYPE_TYPE) {
                return lambda_type_error(input_schema, &TYPE_TYPE,
                    "input schema option");
            }
            schema_type = input_schema.type;
        }
    }
    else {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "input format must be a string, symbol, map, or null, got type: %s",
            get_type_name(type_id));
        target_free(target);
        return ItemError;
    }

    // Check if context is properly initialized
    if (!context) {
        set_runtime_error(ERR_INVALID_STATE, "input: runtime context is not initialized");
        target_free(target);
        return ItemError;
    }

    if (fs_target) {
        Item result = fs_node_input(input_target_root.get(), type_str, flavor_str);
        if (get_type_id(result) == LMD_TYPE_ERROR) {
            if (context) eval_context_set_last_error(context, it2err(result));
            return result;
        }
        return schema_type ? lambda_type_check(result, schema_type, "input schema") : result;
    }

    // Pre-register exact schema fields before parsing so known Input names hit
    // the retained static/dynamic parent; parser-only misses stay id-less per
    // D3.4.4v2 and D4.6.2v2.
    if (schema_type && !input_schema_prepare_name_parent(schema_type,
            context->name_pool)) {
        set_runtime_error(ERR_OUT_OF_MEMORY, "input: failed to prepare schema names");
        target_free(target);
        return ItemError;
    }

    log_debug("input type: %s, flavor: %s", type_str ? type_str->chars : "null", flavor_str ? flavor_str->chars : "null");

    // A schema-backed input inherits the schema/runtime pool; a schemaless
    // input keeps the existing id-less Input seam required by D4.6.2v2.
    Input *input = schema_type
        ? input_from_target_with_name_parent(target, type_str, flavor_str,
            context->name_pool)
        : input_from_target(target, type_str, flavor_str);
    if (!input) {
        // input() is a can-raise effect: a loader failure must not become a
        // successful null, or callers cannot distinguish failed execution from
        // a valid input whose root happens to be null.
        set_runtime_error(ERR_IO_ERROR, "input: failed to load target '%s'",
            target->original ? target->original : "<path target>");
    } else if (input->parse_failed) {
        set_input_parse_error("input", input, type_str);
        target_free(target);
        return ItemError;
    }
    target_free(target);

    // todo: input should be cached in context
    Item result = (input && input->root.item) ? input->root : ItemNull;
    if (schema_type && result.item) {
        // Keep input schema admission on the shared TE-10 boundary so its
        // conversion and validator-path diagnostics cannot diverge from bindings.
        return lambda_type_check(result, schema_type, "input schema");
    }
    return input ? result : ItemError;
}

// declared extern "C" to allow calling from C code (path.c)
extern "C" Item fn_input1(Item url) {
    return fn_input2(url, ItemNull);
}

// ============================================================================
// The force step `#` (PTH31-PTH39)
// ============================================================================
// Everything left of `#` is address resolution and performs no I/O (PTH38);
// only `#` crosses from the reference to its target. `p#` on a provider path is
// sugar for `input(p)` plus navigation (PTH53v2), so no new I/O path enters the
// runtime.

// A path may run from a provider to the deepest node of a document with no `#`
// at the boundary, so the walk that finds the boundary needs somewhere to stash
// the steps it passed. A document deeper than this is navigated by forcing the
// prefix explicitly.
enum { FORCE_MAX_TRAILING_STEPS = 64 };

// The canonical spelling (S2.4.2v4) is the document context's key, so two
// spellings of one location share a head and `===` holds across them.
static String* force_location_key(Path* path) {
    StrBuf* sb = strbuf_new();
    path_to_string(path, sb);
    String* key = heap_strcpy(sb->str, sb->length);
    strbuf_free(sb);
    return key;
}

// One trailing step, applied to the forced value. `fn_member`/`fn_index` are
// the ordinary in-memory navigation (S7.1) — PTH34 requires the result to be
// identical to navigating the value by hand, so this must not be a second
// lookup path.
static Item force_apply_step(Item value, Path* step) {
    switch (PATH_GET_SEG_TYPE(step)) {
    case LPATH_SEG_INT:
        return fn_index(value, (Item){.item = i2it((int32_t)step->int_value)});
    case LPATH_SEG_NORMAL: {
        if (!step->name) return ItemNull;
        String* name = heap_strcpy(step->name, strlen(step->name));
        return fn_member(value, (Item){.item = s2it(name)});
    }
    default:
        // A parent/root/wildcard step is a path operation, not an in-document
        // navigation; it belongs to the prefix, which the walk below guarantees.
        return ItemNull;
    }
}

// Force one document location and publish it in the per-evaluation document
// context, so a second force of the same location yields the SAME node
// (PTH50v3) and `p#body.0 === p#body.0` holds (PTH45v2).
static Item force_document(Path* doc_path, bool* raised) {
    *raised = false;
    String* key = force_location_key(doc_path);
    if (!key) return ItemNull;
    Document* existing = doc_context_lookup(key->chars, key->len);
    if (existing) return existing->head;

    Item head;
    if (path_get_scheme(doc_path) == PATH_SCHEME_SYS) {
        // PTH37: an in-memory reference is a TOTAL read — absence is null
        // (S7.1.1v3), never a raise.
        head = path_resolve_for_iteration(doc_path);
        if (head.item == ItemError.item) return ItemNull;
    } else {
        // PTH36: `input`/`fetch` are pn-family effectful readers, so an
        // unreadable document RAISES (S7.4.5) rather than answering null.
#ifdef LAMBDA_NO_FILE_IO
        set_runtime_error(ERR_IO_ERROR, "external document providers are excluded from this profile");
        *raised = true;
        return ItemError;
#else
        head = fn_input1((Item){.item = (uint64_t)(uintptr_t)doc_path});
#endif
        if (head.item == ItemError.item) { *raised = true; return ItemError; }
    }
    if (head.item == ItemNull.item) return ItemNull;
    doc_context_install(doc_path, key->chars, key->len, head, 0);
    return head;
}

// ============================================================================
// `temp.` documents (PTH44v2, PTH76)
// ============================================================================
// Runtime data gains identity by being PLACED IN A DOCUMENT: `temp.` is the
// in-memory provider root, and its documents live for the evaluation (SO20).
// `temp(...)` and `temp.'name'` are the same pairing `input(p)` and `p#`
// already have — the function acts, the dotted form addresses.

static Path* temp_path_for(String* name) {
    Pool* pool = context ? context->pool : NULL;
    Path* root = path_get_root(PATH_SCHEME_TEMP);
    if (!pool || !root || !name) return NULL;
    return path_extend(pool, root, name->chars);
}

static Item temp_document(Item name_item, Item content, bool has_content) {
    TypeId name_tid = get_type_id(name_item);
    if (!is_text_type_id(name_tid)) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "temp: document name must be a string or symbol, got type: %s",
            get_type_name(name_tid));
        return ItemError;
    }
    String* name = fn_string(name_item);
    Path* path = temp_path_for(name);
    if (!path) {
        set_runtime_error(ERR_IO_ERROR, "temp: no document context");
        return ItemError;
    }
    String* key = force_location_key(path);
    if (!key) return ItemError;
    Document* existing = doc_context_lookup(key->chars, key->len);
    if (has_content) {
        // PTH76: creation RAISES when the name is taken. Silently replacing
        // would make `temp` a Tier-3 write in disguise, and the whole point of
        // the immediate form is that it is document management, not an edit.
        if (existing) {
            set_runtime_error(ERR_IO_ERROR,
                "temp: document '%s' already exists", name->chars);
            return ItemError;
        }
        Document* doc = doc_context_install(path, key->chars, key->len, content, 0);
        return doc ? doc->head : ItemError;
    }
    if (existing) return existing->head;
    // `temp(name)` on an unknown name creates an EMPTY document (root `{}`) so
    // the address is live and `open t = temp('x') { … }` has something to open.
    Pool* pool = context ? context->pool : NULL;
    TypeMap* empty_shape = pool
        ? (TypeMap*)alloc_type(pool, LMD_TYPE_MAP, sizeof(TypeMap)) : NULL;
    Map* empty_map = empty_shape ? map_alloc_for_type(empty_shape, NULL, 0) : NULL;
    if (!empty_map) {
        set_runtime_error(ERR_OUT_OF_MEMORY, "temp: failed to create document");
        return ItemError;
    }
    Item empty = {.item = (uint64_t)(uintptr_t)empty_map};
    Document* doc = doc_context_install(path, key->chars, key->len, empty, 0);
    return doc ? doc->head : ItemError;
}

Item fn_temp1(Item name) { return temp_document(name, ItemNull, false); }
Item fn_temp2(Item name, Item content) { return temp_document(name, content, true); }

// ============================================================================
// Address-of `&` and reference equality `===` (PTH40-PTH45v2)
// ============================================================================

// PTH42: identity is the container's PATH WITHIN ITS DOCUMENT, and lineage
// lives in the document's node table rather than in the node — no parent
// pointers are added to Lambda values (S10.4.3v2, S10.5.3v2). So `&` walks the
// table to the root and spells the path on the way back down.
enum { ADDRESS_OF_MAX_DEPTH = 256 };

Item fn_address_of(Item value) {
    TypeId tid = get_type_id(value);
    if (tid == LMD_TYPE_ERROR) return value;
    // PTH41: scalars never carry identity — a scalar read yields an Item, and an
    // identity on it would have to be manufactured per read. PTH52v3: a local
    // COW copy carries nothing either, so it is simply absent from the table.
    const void* container = (const void*)(uintptr_t)value.item;
    const DocNodeEntry* entry = doc_context_find_node(container);
    if (!entry || !entry->doc || !entry->doc->path) return ItemNull;

    // Collect the chain root-ward, then extend the document's own path back
    // down. The two loops are the `&` cost: O(depth), no per-node storage.
    const DocNodeEntry* chain[ADDRESS_OF_MAX_DEPTH];
    int depth = 0;
    for (const DocNodeEntry* walk = entry; walk && walk->parent;
            walk = doc_context_find_node(walk->parent)) {
        if (depth >= ADDRESS_OF_MAX_DEPTH) return ItemNull;
        chain[depth++] = walk;
    }
    Pool* pool = context ? context->pool : NULL;
    Path* path = entry->doc->path;
    for (int i = depth - 1; i >= 0; i--) {
        const DocNodeEntry* step = chain[i];
        path = step->key_name
            ? path_extend_len(pool, path, step->key_name, step->key_name_length)
            : path_extend_int(pool, path, step->key_index);
        if (!path) return ItemNull;
    }
    return (Item){.item = (uint64_t)(uintptr_t)path};
}

// PTH45v2: `a === b` is `&a != null and &a == &b`. In practice it is pointer
// equality, which is sound because document nodes never move (D4.3.1), a
// `commit` always creates new nodes, and local copies carry no identity. The
// generation is part of the comparison because two nodes at one location across
// a commit are different nodes — and the table entry is per node, so comparing
// the registered entries compares both halves at once.
Bool fn_ref_eq(Item a, Item b) {
    // S1.9: equality is total. Identity-less operands compare FALSE, never a
    // compile error — this is the SO39 sub-question, settled.
    const DocNodeEntry* ea = doc_context_find_node((const void*)(uintptr_t)a.item);
    if (!ea) return BOOL_FALSE;
    return a.item == b.item ? BOOL_TRUE : BOOL_FALSE;
}

// PTH48: a symbol is a URN and needs a resolver mapping the name to a location.
// Lambda's resolver has no identity/namespace table yet, so the read is total
// and empty — it must never fall back to a lexical binding, a module export, or
// the sys-func registry (S1.8, S2.4.3v3).
static Item force_symbol(Item ref) {
    (void)ref;
    return ItemNull;
}

Item fn_force(Item ref) {
    TypeId tid = get_type_id(ref);
    if (tid == LMD_TYPE_ERROR) return ref;
    if (tid == LMD_TYPE_SYMBOL) return force_symbol(ref);
    if (tid != LMD_TYPE_PATH) {
        // PTH37: forcing a non-reference is a static type error where the type
        // is known and an error() value otherwise (S7.10).
        set_runtime_error(ERR_TYPE_MISMATCH,
            "'#' forces a reference (symbol or path), got type: %s",
            get_type_name(tid));
        return ItemError;
    }
    Path* path = ref.path;
    if (!path) return ItemNull;

    // PTH34: force the longest prefix that names a document, then apply the
    // remaining steps in memory. `a.b#c.d`, `a.b.c.d#` and `a.b#.c.d` are one
    // value because all three arrive here with the same full path.
    Path* trailing[FORCE_MAX_TRAILING_STEPS];
    int trailing_count = 0;
    Path* doc_path = path_longest_existing_prefix(path);
    if (!doc_path) {
        // No cheap existence probe (http) or nothing exists: the whole path is
        // the document, and forcing it reports the real failure.
        doc_path = path;
    } else {
        for (Path* probe = path; probe && probe != doc_path; probe = probe->parent) {
            if (trailing_count >= FORCE_MAX_TRAILING_STEPS) {
                set_runtime_error(ERR_IO_ERROR,
                    "'#' reference has more than %d steps past its document",
                    FORCE_MAX_TRAILING_STEPS);
                return ItemError;
            }
            trailing[trailing_count++] = probe;
        }
    }

    bool raised = false;
    Item value = force_document(doc_path, &raised);
    if (raised) return ItemError;

    // The walk above collected leaf-first; navigation runs root-first.
    for (int i = trailing_count - 1; i >= 0; i--) {
        if (value.item == ItemNull.item) return ItemNull;
        value = force_apply_step(value, trailing[i]);
        if (value.item == ItemError.item) return ItemError;
    }
    return value;
}

// parse(str, format) - parse a string into Lambda data structures
// Unlike input() which reads from files/URLs, parse() works on in-memory strings.
// 2nd arg can be a format symbol ('json, 'yaml, etc.) or an options map like input().
extern "C" Input* input_from_source(const char* source, Url* url, String* type, String* flavor);
extern "C" Input* input_from_source_with_positions(const char* source, Url* url, String* type, String* flavor);

// ---------------------------------------------------------------------------
// parse(src, {type: 'markdown' | 'html', sourcepos: 'spans', window: [first, last],
// prescan: {states, valid, labels}}) — the source editor's highlight parse
// (vibe/radiant/Radiant_Design_Source_Editor.md CED16v3, CED18v2). `src` is a string,
// an array of lines, or the editor buffer's array of line chunks, read in
// place. The result is [kinds, spans, states, restart, labels]: span kinds as
// symbols, spans as flat ints (kind index, block flag, line, col, end line, end
// col; 0-based lines, code-point columns), the state per chunk boundary as flat
// ints (BOUNDARY_STATE_FIELDS per boundary), and for Markdown each chunk's link
// reference labels (an array of strings per chunk); the last three go back in
// the next call's `prescan`.
// ---------------------------------------------------------------------------

struct HighlightLineSource {
    Array* chunks = nullptr;          // array of arrays of strings
    Array* flat = nullptr;            // array of strings
    char* owned = nullptr;            // a string source, split in place
    lam::ArrayList<char*> owned_lines;
    lam::ArrayList<int64_t> starts;   // first line of each chunk
    int64_t count = 0;
};

// Lines of a flat source are grouped as the editor buffer groups them, so the
// restart cache has the same grain either way.
static const int64_t HIGHLIGHT_FLAT_CHUNK = 256;

static const char* highlight_string_chars(Item item, size_t* len) {
    if (get_type_id(item) != LMD_TYPE_STRING) { *len = 0; return ""; }
    String* str = item.get_safe_string();
    if (!str) { *len = 0; return ""; }
    *len = str->len;
    return str->chars;
}

static const char* highlight_line_at(void* ctx, int64_t index, size_t* len) {
    HighlightLineSource* src = (HighlightLineSource*)ctx;
    *len = 0;
    if (index < 0 || index >= src->count) return "";
    if (src->owned) {
        char* line = src->owned_lines[(size_t)index];
        *len = strlen(line);
        return line;
    }
    if (src->flat) return highlight_string_chars(array_get(src->flat, index), len);
    int64_t lo = 0, hi = (int64_t)src->starts.length();
    while (lo < hi) {
        int64_t mid = (lo + hi) / 2;
        if (src->starts[(size_t)mid] <= index) lo = mid + 1; else hi = mid;
    }
    int64_t k = lo - 1;
    Item chunk = array_get(src->chunks, k);
    if (get_type_id(chunk) != LMD_TYPE_ARRAY) return "";
    return highlight_string_chars(array_get(chunk.array, index - src->starts[(size_t)k]), len);
}

static bool highlight_source_init(HighlightLineSource* src, Item item) {
    TypeId type = get_type_id(item);
    if (type == LMD_TYPE_STRING) {
        size_t len = 0;
        const char* chars = highlight_string_chars(item, &len);
        src->owned = mem_dup_n(chars, len, MEM_CAT_INPUT_MARKUP);
        if (!src->owned) return false;
        char* line = src->owned;
        for (char* p = src->owned; ; p++) {
            if (*p == '\n' || *p == '\0') {
                bool at_end = *p == '\0';
                if (p > line && p[-1] == '\r') p[-1] = '\0';
                *p = '\0';
                src->owned_lines.push_back(line);
                if (at_end) break;
                line = p + 1;
            }
        }
        src->count = (int64_t)src->owned_lines.length();
    } else if (type == LMD_TYPE_ARRAY) {
        Array* arr = item.array;
        bool chunked = arr->length > 0 && get_type_id(array_get(arr, 0)) == LMD_TYPE_ARRAY;
        if (chunked) {
            src->chunks = arr;
            for (int64_t k = 0; k < arr->length; k++) {
                Item chunk = array_get(arr, k);
                if (get_type_id(chunk) != LMD_TYPE_ARRAY) return false;
                src->starts.push_back(src->count);
                src->count += chunk.array->length;
            }
            return src->count > 0;
        }
        src->flat = arr;
        src->count = arr->length;
    } else {
        return false;
    }
    for (int64_t start = 0; start < src->count; start += HIGHLIGHT_FLAT_CHUNK) src->starts.push_back(start);
    return src->count > 0;
}

static int64_t highlight_int(Item item, int64_t fallback) {
    TypeId type = get_type_id(item);
    if (type == LMD_TYPE_INT || type == LMD_TYPE_INT64) return it2l(item);
    return fallback;
}

// An int list may be a plain array or a numeric one (`[lo, hi]` literals and
// arithmetic results are ARRAY_NUM); read both through the generic accessors.
static bool highlight_is_list(Item item) {
    TypeId type = get_type_id(item);
    return type == LMD_TYPE_ARRAY || type == LMD_TYPE_ARRAY_NUM;
}

static int64_t highlight_list_int(Item list, int64_t index) {
    return highlight_int(fn_index(list, {.item = i2it(index)}), 0);
}

static Item highlight_map_field(Item map_item, const char* key) {
    if (get_type_id(map_item) != LMD_TYPE_MAP) return ItemNull;
    bool found = false;
    Item value = _map_get((TypeMap*)map_item.map->type, map_item.map->data, key, &found);
    return found ? value : ItemNull;
}

static Item fn_parse_highlight_spans(bool html, Item src_item, Item window_item, Item prescan_item) {
    using namespace lambda::markup;
    HighlightLineSource source;
    if (!highlight_source_init(&source, src_item)) {
        if (source.owned) mem_free(source.owned);
        set_runtime_error(ERR_TYPE_MISMATCH,
            "parse: sourcepos 'spans' needs a non-empty string, line array or chunk array");
        return ItemError;
    }
    int64_t first = 0, last = source.count - 1;
    if (highlight_is_list(window_item) && fn_len(window_item) == 2) {
        first = highlight_list_int(window_item, 0);
        last = highlight_list_int(window_item, 1);
    }
    lam::ArrayList<BoundaryState> cache;
    HighlightLabels cached_labels;
    cached_labels.reset();
    int64_t valid = 0;
    Item states_item = highlight_map_field(prescan_item, "states");
    if (highlight_is_list(states_item)) {
        int64_t n = fn_len(states_item);
        int64_t f = BOUNDARY_STATE_FIELDS;
        for (int64_t i = 0; i + f - 1 < n; i += f) {
            BoundaryState st;
            st.restart = RestartState{(int32_t)highlight_list_int(states_item, i),      // INT_CAST_OK: state codes
                                      (int32_t)highlight_list_int(states_item, i + 1),  // INT_CAST_OK: fence char
                                      (int32_t)highlight_list_int(states_item, i + 2)}; // INT_CAST_OK: fence length
            st.link = (int32_t)highlight_list_int(states_item, i + 3);  // INT_CAST_OK: packed pre-scan state
            st.skip = (int32_t)highlight_list_int(states_item, i + 4);  // INT_CAST_OK: line count
            cache.push_back(st);
        }
        valid = highlight_int(highlight_map_field(prescan_item, "valid"), (int64_t)cache.length());
    }
    Item labels_item = highlight_map_field(prescan_item, "labels");
    if (get_type_id(labels_item) == LMD_TYPE_ARRAY) {
        for (int64_t k = 0; k < labels_item.array->length; k++) {
            Item chunk = array_get(labels_item.array, k);
            if (get_type_id(chunk) != LMD_TYPE_ARRAY) break;
            for (int64_t i = 0; i < chunk.array->length; i++) {
                size_t len = 0;
                const char* label = highlight_string_chars(array_get(chunk.array, i), &len);
                cached_labels.add(label, len);
            }
            cached_labels.close_chunk();
        }
    }

    HighlightLines lines = {&source, highlight_line_at, source.count,
                            source.starts.data(), (int64_t)source.starts.length()};
    HighlightCache given = {cache.data(), (int64_t)cache.length(), valid, &cached_labels};
    HighlightResult hl;
    bool ok = html
        ? html_highlight_window(&lines, first, last, &given, &hl)
        : markdown_highlight_window(&lines, first, last, &given, &hl);
    if (source.owned) mem_free(source.owned);
    if (!ok) {
        set_runtime_error(ERR_OUT_OF_MEMORY, "parse: the highlight parse could not allocate");
        return ItemError;
    }

    // Every allocation below may collect: each array is rooted, and slots are
    // reserved before a fresh symbol is pushed so the push cannot allocate.
    RootFrame roots(7);
    Rooted<Array*> result(roots, array_plain());
    Rooted<Array*> kinds(roots, array_plain());
    Rooted<Array*> spans(roots, array_plain());
    Rooted<Array*> states(roots, array_plain());
    Rooted<Array*> labels(roots, array_plain());
    Rooted<Array*> chunk_labels(roots, nullptr);
    Rooted<Item> label_item(roots, ItemNull);
    for (size_t i = 0; i < hl.kinds.length(); i++) {
        if (!array_reserve_append_slots(kinds.get(), 1)) return ItemError;
        Symbol* sym = heap_create_symbol(hl.kinds[i].name, strlen(hl.kinds[i].name));
        array_push(kinds.get(), {.item = y2it(sym)});
    }
    for (size_t i = 0; i < hl.spans.length(); i++) {
        const MarkupSpan& span = hl.spans[i];
        array_push(spans.get(), {.item = i2it(span.kind)});
        array_push(spans.get(), {.item = i2it(span.block)});
        array_push(spans.get(), {.item = i2it(span.line)});
        array_push(spans.get(), {.item = i2it(span.col)});
        array_push(spans.get(), {.item = i2it(span.end_line)});
        array_push(spans.get(), {.item = i2it(span.end_col)});
    }
    for (size_t i = 0; i < hl.states.length(); i++) {
        array_push(states.get(), {.item = i2it(hl.states[i].restart.kind)});
        array_push(states.get(), {.item = i2it(hl.states[i].restart.a)});
        array_push(states.get(), {.item = i2it(hl.states[i].restart.b)});
        array_push(states.get(), {.item = i2it(hl.states[i].link)});
        array_push(states.get(), {.item = i2it(hl.states[i].skip)});
    }
    for (int64_t k = 0; k < hl.labels.chunks(); k++) {
        chunk_labels.set(array_plain());
        for (int64_t i = hl.labels.first[(size_t)k]; i < hl.labels.first[(size_t)k + 1]; i++) {
            const char* label = hl.labels.label(i);
            label_item.set({.item = s2it(heap_strcpy(label, (int64_t)strlen(label)))});
            array_push(chunk_labels.get(), label_item.get());
        }
        array_push(labels.get(), {.array = chunk_labels.get()});
    }
    array_push(result.get(), {.array = kinds.get()});
    array_push(result.get(), {.array = spans.get()});
    array_push(result.get(), {.array = states.get()});
    array_push(result.get(), {.item = i2it(hl.restart_line)});
    array_push(result.get(), {.array = labels.get()});
    return {.array = result.get()};
}

// latex/tex options for the TeX expansion engine (Lambda_Pkg_Latex3 §9): the
// names stay owned by the caller's map for the duration of the parse
static void collect_names(Map* options_map, const char* key, ArrayList* names) {
    bool is_found = false;
    Item list = _map_get((TypeMap*)options_map->type, options_map->data, key, &is_found);
    if (!is_found || get_type_id(list) != LMD_TYPE_ARRAY) return;
    Array* arr = list.array;
    for (int64_t i = 0; i < arr->length; i++) {
        Item name = array_get(arr, i);
        if (is_text_type_id(get_type_id(name))) arraylist_append(names, (void*)fn_string(name)->chars);
    }
}

static bool parse_tex_options(Map* options_map, InputParseOptions* options,
                              ArrayList* adapter_names, ArrayList* raw_names) {
    bool is_found = false;
    Item expand = _map_get((TypeMap*)options_map->type, options_map->data, "expand", &is_found);
    if (is_found && get_type_id(expand) == LMD_TYPE_BOOL) options->tex_expand = it2b(expand);
    Item ini = _map_get((TypeMap*)options_map->type, options_map->data, "ini", &is_found);
    if (is_found && get_type_id(ini) == LMD_TYPE_BOOL) options->tex_ini = it2b(ini);
    Item base = _map_get((TypeMap*)options_map->type, options_map->data, "base", &is_found);
    if (is_found && is_text_type_id(get_type_id(base))) options->tex_base = fn_string(base)->chars;
    collect_names(options_map, "packages", adapter_names);
    options->tex_adapters = (const char* const*)adapter_names->data;
    options->tex_adapter_count = adapter_names->length;
    collect_names(options_map, "raw", raw_names);
    options->tex_raw_commands = (const char* const*)raw_names->data;
    options->tex_raw_command_count = raw_names->length;
    return options->tex_expand || options->tex_ini || options->tex_base || options->tex_adapter_count;
}

Item fn_parse2(Item str_item, Item type) {
    GUARD_ERROR2(str_item, type);

    // parse the 2nd argument (format symbol or options map) - same logic as fn_input2
    String* type_str = NULL;
    String* flavor_str = NULL;
    bool source_positions = false;
    InputParseOptions parse_options = {};
    ArrayList* adapter_names = arraylist_new(8);
    ArrayList* raw_names = arraylist_new(8);
    bool has_tex_options = false;
    bool highlight_spans = false;   // sourcepos: 'spans'
    Item window_item = ItemNull;
    Item prescan_item = ItemNull;

    TypeId type_id = get_type_id(type);
    if (type_id == LMD_TYPE_NULL) {
        type_str = NULL;  // auto-detect
    }
    else if (is_text_type_id(type_id)) {
        type_str = fn_string(type);
    }
    else if (type_id == LMD_TYPE_MAP) {
        Map* options_map = type.map;
        bool is_found;

        // extract 'type' from map
        Item input_type = _map_get((TypeMap*)options_map->type, options_map->data, "type", &is_found);
        if (is_found && input_type.item && input_type._type_id != LMD_TYPE_NULL) {
            TypeId type_value_type = get_type_id(input_type);
            if (is_text_type_id(type_value_type)) {
                type_str = fn_string(input_type);
            } else {
                set_runtime_error(ERR_TYPE_MISMATCH,
                    "parse: type option must be a string or symbol, got type: %s",
                    get_type_name(type_value_type));
                return ItemError;
            }
        }

        // extract 'flavor' from map
        Item input_flavor = _map_get((TypeMap*)options_map->type, options_map->data, "flavor", &is_found);
        if (is_found && input_flavor.item && input_flavor._type_id != LMD_TYPE_NULL) {
            TypeId flavor_value_type = get_type_id(input_flavor);
            if (is_text_type_id(flavor_value_type)) {
                flavor_str = fn_string(input_flavor);
            } else {
                set_runtime_error(ERR_TYPE_MISMATCH,
                    "parse: flavor option must be a string or symbol, got type: %s",
                    get_type_name(flavor_value_type));
                return ItemError;
            }
        }

        // extract 'sourcepos' from map: markup blocks record their source lines
        Item input_sourcepos = _map_get((TypeMap*)options_map->type, options_map->data, "sourcepos", &is_found);
        if (is_found && input_sourcepos.item && input_sourcepos._type_id != LMD_TYPE_NULL) {
            TypeId sourcepos_type = get_type_id(input_sourcepos);
            if (is_text_type_id(sourcepos_type) && strcmp(fn_string(input_sourcepos)->chars, "spans") == 0) {
                highlight_spans = true;
                window_item = _map_get((TypeMap*)options_map->type, options_map->data, "window", &is_found);
                if (!is_found) window_item = ItemNull;
                prescan_item = _map_get((TypeMap*)options_map->type, options_map->data, "prescan", &is_found);
                if (!is_found) prescan_item = ItemNull;
            } else if (sourcepos_type != LMD_TYPE_BOOL) {
                set_runtime_error(ERR_TYPE_MISMATCH,
                    "parse: sourcepos option must be a bool or 'spans', got type: %s",
                    get_type_name(sourcepos_type));
                return ItemError;
            } else {
                source_positions = it2b(input_sourcepos);
            }
        }
        has_tex_options = parse_tex_options(options_map, &parse_options, adapter_names, raw_names);
    }
    else {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "parse: 2nd argument must be a format symbol or options map, got type: %s",
            get_type_name(type_id));
        return ItemError;
    }

    if (highlight_spans) {
        bool html = type_str && strcmp(type_str->chars, "html") == 0;
        if (!html && (!type_str || strcmp(type_str->chars, "markdown") != 0)) {
            set_runtime_error(ERR_TYPE_MISMATCH, "parse: sourcepos 'spans' supports types 'markdown' and 'html'");
            return ItemError;
        }
        return fn_parse_highlight_spans(html, str_item, window_item, prescan_item);
    }

    // first arg must be a string
    TypeId str_type = get_type_id(str_item);
    if (str_type != LMD_TYPE_STRING) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "parse: 1st argument must be a string, got type: %s",
            get_type_name(str_type));
        return ItemError;
    }
    String* str = str_item.get_safe_string();
    if (!str) {
        set_runtime_error(ERR_INVALID_STATE, "parse: string value is unavailable");
        return ItemError;
    }

    // create a dummy URL for the parser infrastructure (no actual file)
    Url* dummy_url = url_parse("parse://inline");
    if (!dummy_url) {
        set_runtime_error(ERR_INVALID_STATE,
            "parse: failed to initialize the in-memory parser URL");
        return ItemError;
    }

    log_debug("fn_parse2: type=%s, flavor=%s", type_str ? type_str->chars : "auto", flavor_str ? flavor_str->chars : "null");

    parse_options.source_positions = source_positions;
    Input* input = (source_positions || has_tex_options)
        ? input_from_source_with_options(str->chars, dummy_url, type_str, flavor_str, &parse_options)
        : input_from_source(str->chars, dummy_url, type_str, flavor_str);
    arraylist_free(adapter_names);
    arraylist_free(raw_names);
    if (!input) {
        set_runtime_error(ERR_OUT_OF_MEMORY,
            "parse: failed to initialize parser for format '%s'",
            type_str ? type_str->chars : "auto");
        return ItemError;
    }
    // ItemNull is a valid parsed value, so only the explicit parser status or
    // an error root may convert this result into the non-admissive error path.
    if (input->parse_failed || get_type_id(input->root) == LMD_TYPE_ERROR) {
        set_input_parse_error("parse", input, type_str);
        return ItemError;
    }
    return input->root;
}

Item fn_parse1(Item str_item) {
    return fn_parse2(str_item, ItemNull);
}

Item fn_parse_html_fragment1(Item str_item) {
    GUARD_ERROR1(str_item);

    // HTML fragment parsing is non-admissive: null is reserved for a valid
    // absence, not for a rejected argument or failed parser allocation.
    TypeId str_type = get_type_id(str_item);
    if (str_type != LMD_TYPE_STRING) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "parse_html_fragment: argument must be a string, got type: %s",
            get_type_name(str_type));
        return ItemError;
    }

    String* str = str_item.get_safe_string();
    if (!str) {
        set_runtime_error(ERR_INVALID_STATE,
            "parse_html_fragment: string value is unavailable");
        return ItemError;
    }

    Url* dummy_url = url_parse("parse://html-fragment");
    if (!dummy_url) {
        set_runtime_error(ERR_INVALID_STATE,
            "parse_html_fragment: failed to initialize parser URL");
        return ItemError;
    }
    Input* input = InputManager::create_input(dummy_url);
    if (!input) {
        set_runtime_error(ERR_OUT_OF_MEMORY,
            "parse_html_fragment: failed to allocate parser input");
        return ItemError;
    }

    Html5Parser* parser = html5_fragment_parser_create(input->pool, input->arena, input);
    Html5ParserScope parser_scope(parser);
    if (!parser) {
        set_runtime_error(ERR_OUT_OF_MEMORY,
            "parse_html_fragment: failed to allocate HTML fragment parser");
        return ItemError;
    }
    if (!html5_fragment_parse(parser, str->chars)) {
        set_runtime_error(ERR_PARSE_ERROR,
            "parse_html_fragment: failed to parse the HTML fragment");
        return ItemError;
    }

    Element* fragment = html5_fragment_get_body(parser);
    input->root = fragment ? Item{.element = fragment} : ItemNull;
    if (!fragment) {
        set_runtime_error(ERR_PARSE_ERROR,
            "parse_html_fragment: parser produced no fragment body");
        return ItemError;
    }
    return input->root;
}

extern "C" String* format_data(Item item, String* type, String* flavor, Pool *pool);

// D6.4.1: format returns an Item, so a failure is an error value, never text.
// It returned String*: an error operand became the text "<error>" on both
// tiers, and a bad format argument's NULL read as error on T0 but null on the
// JIT (LR07-18).
Item fn_format2(Item item, Item type) {
    // an error operand is the result (S7.10.4)
    if (get_type_id(item) == LMD_TYPE_ERROR) return item;
    if (get_type_id(type) == LMD_TYPE_ERROR) return type;
    // datetime formatting: format(dt) or format(dt, pattern)
    TypeId item_type_id = get_type_id(item);
    if (item_type_id == LMD_TYPE_DTIME) {
        DateTime dt = item.get_datetime();
        StrBuf* buf = strbuf_new();
        TypeId type_id = get_type_id(type);

        if (type_id == LMD_TYPE_NULL) {
            // default: ISO 8601 format
            datetime_format_lambda(buf, &dt);
        }
        else if (is_text_type_id(type_id)) {
            const char* pattern_chars = type.get_chars();
            // check for named format presets
            if (strcmp(pattern_chars, "iso") == 0 || strcmp(pattern_chars, "iso8601") == 0) {
                datetime_format_iso8601(buf, &dt);
            }
            else if (strcmp(pattern_chars, "date") == 0) {
                // format date portion only: YYYY-MM-DD
                datetime_format_pattern(buf, &dt, "YYYY-MM-DD");
            }
            else if (strcmp(pattern_chars, "time") == 0) {
                // format time portion only: HH:mm:ss
                datetime_format_pattern(buf, &dt, "HH:mm:ss");
            }
            else {
                // custom pattern format
                datetime_format_pattern(buf, &dt, pattern_chars);
            }
        }
        else {
            log_error("format: datetime format must be a string pattern, got type: %s", get_type_name(type_id));
            datetime_format_lambda(buf, &dt);
        }

        size_t len = buf->length;
        String* result = heap_strcpy(buf->str, len);
        strbuf_free(buf);
        return (Item){.item = s2it(result)};
    }

    TypeId type_id = get_type_id(type);
    String* type_str = NULL;
    String* flavor_str = NULL;

    if (type_id == LMD_TYPE_NULL) {
        type_str = NULL;  // use default
    }
    else if (is_text_type_id(type_id)) {
        // Legacy behavior: type is a simple string or symbol
        type_str = fn_string(type);
    }
    else if (type_id == LMD_TYPE_MAP) {
        log_debug("format type is a map");
        // New behavior: type is a map with options
        Map* options_map = type.map;

        // Extract 'type' from map
        bool is_found;
        Item format_type = _map_get((TypeMap*)options_map->type, options_map->data, "type", &is_found);
        if (!is_found || !format_type.item || format_type._type_id == LMD_TYPE_NULL) { // missing 'type' key
            type_str = NULL;
        } else {
            TypeId type_value_type = get_type_id(format_type);
            if (is_text_type_id(type_value_type)) {
                type_str = fn_string(format_type);
            }
            else {
                log_debug("format type must be a string or symbol, got type: %s", get_type_name(type_value_type));
                // todo: push error
                type_str = NULL;  // format type ignored
            }
        }

        // Extract 'flavor' from map
        Item format_flavor = _map_get((TypeMap*)options_map->type, options_map->data, "flavor", &is_found);
        if (!is_found || !format_flavor.item || format_flavor._type_id == LMD_TYPE_NULL) { // missing 'flavor' key
            flavor_str = NULL;
        } else {
            TypeId flavor_value_type = get_type_id(format_flavor);
            if (is_text_type_id(flavor_value_type)) {
                flavor_str = fn_string(format_flavor);
            }
            else {
                log_debug("format flavor must be a string or symbol, got type: %s", get_type_name(flavor_value_type));
                // todo: push error
                flavor_str = NULL;  // format flavor ignored
            }
        }
    }
    else {
        set_runtime_error(ERR_FORMAT_ERROR,
            "format: the format must be a string, symbol, or map, got %s", get_type_name(type_id));
        return ItemError;
    }

    log_debug("format item type: %s, flavor: %s", type_str ? type_str->chars : "null", flavor_str ? flavor_str->chars : "null");
    String* result = format_data(item, type_str, flavor_str, context->heap->pool);
    if (!result) {
        set_runtime_error(ERR_FORMAT_ERROR, "format: could not format a %s value",
            get_type_name(get_type_id(item)));
        return ItemError;
    }
    // re-allocate as GC-tracked string (format_data uses pool directly, no GCHeader)
    return (Item){.item = s2it(heap_strcpy(result->chars, result->len))};
}

Item fn_format1(Item item) {
    return fn_format2(item, ItemNull);
}

// A positional selection by array needs a sequence face. Text is left out: a
// positional selection keeps its kind (S7.1.2) and a gather over it is unruled.
static bool index_source_has_sequence_face(TypeId type_id) {
    return type_id == LMD_TYPE_ARRAY || type_id == LMD_TYPE_ARRAY_NUM ||
        type_id == LMD_TYPE_VARRAY || type_id == LMD_TYPE_RANGE ||
        type_id == LMD_TYPE_ELEMENT || type_id == LMD_TYPE_VELMT;
}

// A bool array is a mask; any other array key is an index array.
static bool index_array_is_mask(Item index_array) {
    if (get_type_id(index_array) == LMD_TYPE_ARRAY_NUM)
        return index_array.array_num->get_elem_type() == ELEM_BOOL;
    Array* arr = index_array.array;
    if (!arr || arr->length == 0) return false;
    for (int64_t i = 0; i < arr->length; i++) {
        if (get_type_id(array_item_read(arr, i)) != LMD_TYPE_BOOL) return false;
    }
    return true;
}

// S8.2.4v3: a positional selection by array is NumPy's and always yields an
// array. An index array is a batch of scalar reads that keeps its own length
// -- `a[[1, 3, 9]]` is `[a[1], a[3], null]` -- each position reading as `a[i]`
// does, so one out of range, negative, fractional or not a number is null
// (S7.1.1v3, S7.2.1, S8.2.1v4); a nested index array selects again, so the
// result keeps the index array's shape. A mask selects the positions it marks.
static Item fn_index_select(Item source, Item index_array) {
    bool mask = index_array_is_mask(index_array);
    int64_t count = fn_seq_count(index_array);
    RootFrame roots(3);
    Rooted<Item> rooted_source(roots, source);
    Rooted<Item> rooted_index(roots, index_array);
    Rooted<Array*> rooted_out(roots, array_plain());
    for (int64_t i = 0; i < count; i++) {
        Item key = item_at(rooted_index.get(), i);
        TypeId key_type = get_type_id(key);
        Item value = ItemNull;
        if (mask) {
            if (key_type != LMD_TYPE_BOOL || !key.bool_val) continue;
            value = fn_index(rooted_source.get(), (Item){.item = i2it(i)});
        } else if (is_numeric_type_id(key_type) || key_type == LMD_TYPE_ARRAY ||
                key_type == LMD_TYPE_ARRAY_NUM) {
            value = fn_index(rooted_source.get(), key);
        }
        array_push_verbatim(rooted_out.get(), value);
    }
    return seq_finish_array({.array = rooted_out.get()});
}

// generic field access function for any type
Item fn_index(Item item, Item index_item) {
    // Quick null/error guard: indexing null returns null to propagate
    // null safely through algorithms. Operations like null[field]
    // should not crash or return a wrong result.
    TypeId item_type = get_type_id(item);
    if (item_type == LMD_TYPE_NULL || item_type == LMD_TYPE_ERROR) {
        return ItemNull;
    }
    if (item_type == LMD_TYPE_VMAP) {
        // S8.2.4v3: a type key is a query on every container, a VMap included;
        // taken as a map key it read `null` for `m[int]`
        if (get_type_id(index_item) == LMD_TYPE_TYPE) return fn_child_query(item, index_item);
        // VMap integer-looking keys are still map keys, not sequence offsets.
        VMap* vm = item.vmap;
        // Host-backed VMaps resolve through their host hook without a storage
        // vtable; rejecting them here made callback metadata appear absent.
        if (vm && (vm->host_type || vm->vtable)) return vmap_get_by_item(vm, index_item);
        return ItemNull;
    }
    if (item_type == LMD_TYPE_PATH) {
        // S2.4.2v5: a subscript on a path is the dotted step, `(/)[1]` is `/.1`.
        // It used to force the target and index its content instead, so
        // `p[1]` and `p.1` named different things.
        return fn_member(item, index_item);
    }

    // Arithmetic-derived semantic integers are decimal-backed Items. Sequence
    // access must consume their exact value instead of rejecting the storage tag.
    int64_t index = -1;
    if (lambda_item_to_int64_exact(index_item, &index)) {
        // Numeric keys are positional only for indexable faces. Sending a
        // numeric key to item_at for a map/object used to log an unsupported
        // type even though S7.1.1v2 requires a quiet null read.
        switch (item_type) {
        case LMD_TYPE_ARRAY:
        case LMD_TYPE_ARRAY_NUM:
        case LMD_TYPE_VARRAY:
        case LMD_TYPE_RANGE:
        // S8.2.1v3: a nominal value exposes the same two faces as its
        // structural kind, so an IntKey selects a content child here rather
        // than reading as null.
        case LMD_TYPE_ELEMENT:
        case LMD_TYPE_VELMT:
        case LMD_TYPE_STRING:
        case LMD_TYPE_SYMBOL:
        case LMD_TYPE_BINARY:
        case LMD_TYPE_VMAP:
            return item_at(item, index);
        default:
            return ItemNull;
        }
    }

    TypeId index_type = get_type_id(index_item);
    switch (index_type) {
    case LMD_TYPE_STRING:  case LMD_TYPE_SYMBOL:
        return fn_member(item, index_item);
    default: {
        // check for type value (pointer-based, so _type_id is 0)
        if (index_type == LMD_TYPE_TYPE) {
            return fn_child_query(item, index_item);
        }
        // range index: s[i to j] → slice(item, start, end+1)
        if (index_type == LMD_TYPE_RANGE) {
            Range* rng = index_item.range;
            if (rng) {
                if (rng->is_char) {
                    log_error("fn_index: character ranges cannot be used as slice bounds");
                    return ItemError;
                }
                Item start_it = {.item = i2it(rng->start)};
                Item end_it = {.item = i2it(rng->end + 1)}; // range end is inclusive, slice end is exclusive
                return fn_slice(item, start_it, end_it);
            }
            return ItemNull;
        }
        // boolean mask index: arr[mask] — select elements where mask is true
        if (index_type == LMD_TYPE_ARRAY_NUM && item_type == LMD_TYPE_ARRAY_NUM &&
                index_array_is_mask(index_item)) {
            return fn_mask_index(item, index_item);
        }
        // S8.2.4v3: any other array key is a positional selection
        if ((index_type == LMD_TYPE_ARRAY || index_type == LMD_TYPE_ARRAY_NUM) &&
                index_source_has_sequence_face(item_type)) {
            return fn_index_select(item, index_item);
        }
        log_debug("invalid index type %d", index_item._type_id);
        return ItemNull;
    }
    }

    return ItemNull;
}

// All dynamic member stores enter through this boundary so a key-domain
// mismatch cannot be truncated into index zero (or silently dropped by a map
// setter). Reads remain total in fn_index; writes are hard language errors.
static Item virtual_member_write_result(VirtualOpStatus status, Item result,
        const char* face, bool indexed, int64_t index) {
    if (status == VIRTUAL_OP_OK) return ItemNull;
    if (status == VIRTUAL_OP_ERROR) {
        return item_is_error(result) ? result : ItemError;
    }
    if (status == VIRTUAL_OP_MISSING) {
        if (indexed) {
            set_runtime_error(ERR_INDEX_OUT_OF_BOUNDS,
                "%s write index %lld is out of bounds", face, (long long)index);
        } else {
            set_runtime_error(ERR_TYPE_MISMATCH, "%s does not accept this key", face);
        }
    } else {
        set_runtime_error(ERR_TYPE_MISMATCH, "%s is read-only", face);
    }
    return ItemError;
}

Item fn_index_set(Item item, Item key, Item value) {
    TypeId item_type = get_type_id(item);
    if (item_type == LMD_TYPE_ERROR) return item;

    if (item_type == LMD_TYPE_VMAP) {
        // VMap's established hash backend accepts arbitrary Item keys. Keep
        // that ABI while the new VArray/Velmt carriers enforce face-specific
        // key domains (D7.4.5v2).
        return vmap_set(item, key, value);
    }

    int64_t index = 0;
    bool has_index_key = lambda_item_to_int64_exact(key, &index);
    bool has_name_key = is_text_type_id(get_type_id(key));

    if (item_type == LMD_TYPE_ARRAY || item_type == LMD_TYPE_ARRAY_NUM) {
        if (!has_index_key) {
            set_runtime_error(ERR_TYPE_MISMATCH,
                "invalid sequence member write: key must be an exact non-negative integer");
            return ItemError;
        }
        return fn_array_set(item.array, index, value);
    }
    if (item_type == LMD_TYPE_VARRAY) {
        if (!has_index_key || index < 0) {
            set_runtime_error(ERR_TYPE_MISMATCH,
                "invalid virtual array member write: key must be an exact non-negative integer");
            return ItemError;
        }
        Item result = ItemNull;
        VirtualOpStatus status = varray_set(item.varray, index, value, &result);
        return virtual_member_write_result(status, result, "virtual array", true, index);
    }
    if (item_type == LMD_TYPE_ELEMENT) {
        if (has_index_key) return fn_array_set(item.array, index, value);
        if (has_name_key) return fn_map_set(item, key, value);
        set_runtime_error(ERR_TYPE_MISMATCH,
            "invalid element member write: key must be an exact integer or string/symbol");
        return ItemError;
    }
    if (item_type == LMD_TYPE_VELMT) {
        Item result = ItemNull;
        if (has_index_key && index >= 0) {
            VirtualOpStatus status = velmt_child_set(item.velmt, index, value, &result);
            return virtual_member_write_result(status, result,
                "virtual element child face", true, index);
        }
        if (has_name_key) {
            if (virtual_host_member_set(item, key, value, &result)) {
                return item_is_error(result) ? result : ItemNull;
            }
            VirtualOpStatus status = velmt_attr_set(item.velmt, key, value, &result);
            return virtual_member_write_result(status, result,
                "virtual element attribute face", false, 0);
        }
        set_runtime_error(ERR_TYPE_MISMATCH,
            "invalid virtual element member write: key must be an exact non-negative integer or string/symbol");
        return ItemError;
    }
    if (item_type == LMD_TYPE_MAP) {
        if (has_name_key) return fn_map_set(item, key, value);
        set_runtime_error(ERR_TYPE_MISMATCH,
            "invalid named member write: key must be string or symbol");
        return ItemError;
    }
    set_runtime_error(ERR_TYPE_MISMATCH,
        "invalid member write: base has no writable member face");
    return ItemError;
}

int64_t fn_int64_index(Item item) {
    int64_t value = INT64_MIN;
    return lambda_item_to_int64_exact(item, &value) ? value : INT64_MIN;
}

// A multi-key read of anything but a typed array is an invalid member read,
// which is null (S7.1.1v3). Both tiers check here: array_num_at_nd reads the
// N-D flag from the Container header, which a String or other non-container
// payload does not have.
Item fn_index_nd(Item item, int ndim, int64_t* indices) {
    if (get_type_id(item) != LMD_TYPE_ARRAY_NUM) return ItemNull;
    return array_num_at_nd(item.array_num, ndim, indices);
}

// S12.3.3v2: the one method walk — own methods, then the base chain. Shared by
// the ANY lane (fn_member) and the static lane (item_attr) so a bare `obj.m`
// cannot resolve differently depending on which lane compiled the access.
extern "C" const TypeMethod* lambda_object_find_method(const TypeObject* type,
        const char* key) {
    // D2.6.6v2 phase 2: methods hang off the nominal RECORD, so the walk is the
    // record's base chain — the shape's own kind no longer participates.
    const TypeNominal* record = type_nominal_record((const Type*)type);
    for (const TypeNominal* t = record; t; t = t->base) {
        for (const TypeMethod* m = t->methods; m; m = m->next) {
            if (m->name && m->name->str && key && strcmp(m->name->str, key) == 0) return m;
        }
    }
    return NULL;
}

static Item lambda_bind_object_method(const TypeMethod* method, Item self) {
    // A method carries a compiled entry only once it has been JIT-compiled;
    // under T0 it has an AST definition instead. Binding used to require
    // compiled_fn, so a bare `obj.m` read null on the interpreter tier while
    // `obj.m()` worked — the call path builds the interpreted closure itself.
    if (!method->compiled_fn) {
        Function* interpreted = interp_bind_object_method(method, self);
        if (!interpreted) return ItemNull;
        return {.item = (uint64_t)(uintptr_t)interpreted};
    }
    Function* bound = to_closure_named(method->compiled_fn, method->arity,
        (void*)(uintptr_t)self.item, method->compiled_name);
    // A method table keeps raw code, so reattach its TypeFunc when rebuilding
    // the bound closure; dynamic dispatch needs it to validate and marshal calls.
    lambda_function_set_type(bound, method->fn_type);
    lambda_function_mark_mir_context_abi(bound);
    if (method->is_proc) {
        lambda_function_mark_lambda_boxed_procedure(bound);
    } else {
        lambda_function_mark_lambda_boxed_function(bound);
    }
    return {.item = (uint64_t)(uintptr_t)bound};
}

// S12.3.3v2 / S8.2.1v3: object member access — key domain first, then the
// type's methods. `obj.m` and its dynamic form `obj["m"]` are one operation,
// so both lanes route here. The method-eligible builtin tier is deliberately
// absent: it is a call-site rule (S12.3.3v2), applied in build_ast, so a bare
// miss stays null and `m[key]` probing on plain maps keeps working (LR02-17).
extern "C" Item lambda_object_member(Item self, const char* key) {
    Object* obj = self.object;
    if (!obj || !key) return ItemNull;
    bool is_found = false;
    Item field_val = _map_get((TypeMap*)obj->type, obj->data, (char*)key, &is_found);
    if (is_found) return field_val;
    const TypeNominal* nominal = ((TypeMap*)obj->type)->nominal;
    if (nominal && nominal->extension && nominal->extension->member)
        return nominal->extension->member(self, key, strlen(key), &is_found);
    const TypeMethod* method = lambda_object_find_method((TypeObject*)obj->type, key);
    if (!method) return ItemNull;
    // OB6 rules a bare `pn` method reference a compile error, but the rejection
    // cannot live here: MIR lowers a `pn` method CALL by lowering its callee
    // member expression as a value through this very lane, so refusing to bind
    // a proc method here silently turns `c.bump()` into a no-op on the JIT tier
    // (measured). Only build_ast can tell a bare reference from a sanctioned
    // callee — it holds `call->function` — and that needs an AST flag plus a
    // validation point, since the member node is built before the call node
    // that consumes it. Tracked as LR02-18.
    return lambda_bind_object_method(method, self);
}

// The single authority for a Path's built-in properties, shared by fn_member
// (the ANY-typed member lane) and item_attr (the statically-typed lane, which
// the T0 interpreter and the C transpiler also use). The two used to carry
// diverging copies — item_attr lacked path/extension/scheme/depth/mode and
// fn_member lacked is_file and metadata auto-load — so the value of `p.extension`
// depended on which lane compiled the access (tier mismatch, SI3v2/D3.3.1v2).
extern "C" bool path_is_property_name(const char* k) {
    if (!k) return false;
    static const char* const names[] = {
        "name", "is_dir", "is_file", "is_link", "size", "modified",
        "path", "extension", "scheme", "depth", "parent", "mode"};
    for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
        if (strcmp(k, names[i]) == 0) return true;
    }
    return false;
}

extern "C" Item path_property_get(Path* path, const char* k) {
    if (!path || !k) return ItemNull;

    // structural properties (always available)
    if (strcmp(k, "name") == 0) {
        // return the leaf segment name (e.g. "file.txt")
        if (path->name) return {.item = s2it(heap_create_name(path->name))};
        return ItemNull;
    }
    if (strcmp(k, "path") == 0) {
        // return the full OS path string (e.g. "./lib/file.txt")
        StrBuf* sb = strbuf_new();
        path_to_os_path(path_qualify_default(eval_context_get_pool(), path), sb);
        String* result = heap_strcpy(sb->str, sb->length);
        strbuf_free(sb);
        return {.item = s2it(result)};
    }
    if (strcmp(k, "extension") == 0) {
        // return file extension (e.g. "txt" from "file.txt")
        if (path->name) {
            const char* ext = str_file_ext(path->name, strlen(path->name), NULL);
            if (ext) {
                return {.item = s2it(heap_create_name(ext + 1))};
            }
        }
        return ItemNull;
    }
    if (strcmp(k, "scheme") == 0) {
        const char* scheme_name = path_get_scheme_name(path);
        if (scheme_name) return {.item = s2it(heap_create_name(scheme_name))};
        return ItemNull;
    }
    if (strcmp(k, "depth") == 0) {
        return {.item = i2it(path_depth(path))};
    }
    if (strcmp(k, "parent") == 0) {
        // return the parent path (go up one directory level);
        // path->parent is the next segment up in the linked list
        if (path->parent && path->parent->parent) return {.path = path->parent};
        return ItemNull;
    }

    // metadata properties (require stat'd metadata; loaded on first access)
    if (strcmp(k, "size") == 0 || strcmp(k, "modified") == 0 ||
        strcmp(k, "is_dir") == 0 || strcmp(k, "is_file") == 0 ||
        strcmp(k, "is_link") == 0 || strcmp(k, "mode") == 0) {
#ifdef LAMBDA_NO_FILE_IO
        set_runtime_error(ERR_IO_ERROR, "filesystem metadata provider is excluded");
        return ItemError;
#else
        if (!(path->flags & PATH_FLAG_META_LOADED)) {
            path_load_metadata(path);
        }
        PathMeta* meta = path->meta;
        if (!meta) {
            // path doesn't exist or couldn't be stat'd
            if (strcmp(k, "size") == 0) return {.item = i2it(-1)};  // -1 for unknown/error
            if (strcmp(k, "modified") == 0 || strcmp(k, "mode") == 0) return ItemNull;
            return {.item = b2it(false)};  // false for boolean flags
        }
        // v5: a byte count is an `int` (the int53 band reaches 9 PB), so it
        // boxes inline. `box_int64_value` here was a pre-v5 leftover from
        // 32-bit `int`, and it was the only reason this path could touch the
        // number stack.
        if (strcmp(k, "size") == 0) return {.item = i2it(meta->size)};
        if (strcmp(k, "modified") == 0) return push_k(meta->modified);
        if (strcmp(k, "is_dir") == 0) return {.item = b2it((meta->flags & PATH_META_IS_DIR) != 0)};
        if (strcmp(k, "is_file") == 0) return {.item = b2it((meta->flags & PATH_META_IS_DIR) == 0)};
        if (strcmp(k, "is_link") == 0) return {.item = b2it((meta->flags & PATH_META_IS_LINK) != 0)};
        if (strcmp(k, "mode") == 0) return {.item = i2it(meta->mode)};
#endif
    }

    log_debug("path_property_get: unknown path property '%s'", k);
    return ItemNull;
}

// A Path is a container pointer and so its own Item carrier.
static inline Item path_step_item(Path* path) {
    return path ? (Item){.item = (uint64_t)(uintptr_t)path} : ItemNull;
}

Item fn_path_key(Item path_item, Item key) {
    if (get_type_id(path_item) != LMD_TYPE_PATH || !path_item.path) return ItemNull;
    Pool* pool = context ? context->pool : NULL;
    // S2.4.2v5 through S8.2.1v4: an exact non-negative integral key is one
    // IntKey step, so `p.1`, `p[1]` and `p[1.0]` agree; a negative or
    // fractional number names no key and reads as null.
    int64_t int_key = -1;
    if (lambda_item_to_int64_exact(key, &int_key)) {
        if (int_key < 0) return ItemNull;
        return path_step_item(path_extend_int(pool, path_item.path, int_key));
    }
    if (is_text_type_id(key._type_id) && key.get_chars()) {
        return path_step_item(path_extend(pool, path_item.path, key.get_chars()));
    }
    return ItemNull;
}

Item fn_path_step(Item path_item, int64_t step_type, const char* name,
        int64_t int_value) {
    if (get_type_id(path_item) != LMD_TYPE_PATH || !path_item.path) return ItemNull;
    Pool* pool = context ? context->pool : NULL;
    Path* path = path_item.path;
    Path* next;
    switch ((LPathSegmentType)step_type) {
    case LPATH_SEG_WILDCARD: next = path_wildcard(pool, path); break;
    case LPATH_SEG_WILDCARD_REC: next = path_wildcard_recursive(pool, path); break;
    case LPATH_SEG_PARENT: next = path_select_parent(pool, path); break;
    case LPATH_SEG_ROOT: next = path_select_root(pool, path); break;
    case LPATH_SEG_INT: next = path_extend_int(pool, path, int_value); break;
    default: next = path_extend(pool, path, name ? name : ""); break;
    }
    return path_step_item(next);
}

Item fn_member(Item item, Item key) {
    TypeId type_id = get_type_id(item);

    // For paths (like sys.os), resolve the path content first
    if (type_id == LMD_TYPE_PATH) {
        Path* path = item.path;
        if (path) {
            // Check if it's a sys path - these should be resolved to their content
            if (path_get_scheme(path) == PATH_SCHEME_SYS) {
                if (path->result == 0) {
                    Item resolved = path_resolve_for_iteration(path);
                    if (resolved.item == ItemError.item) return ItemNull;
                }
                if (path->result != 0) {
                    // Recurse with resolved content
                    return fn_member({.item = path->result}, key);
                }
            }

            // path metadata and structural property access
            if (is_text_type_id(key._type_id)) {
                const char* k = key.get_chars();
                if (k && path_is_property_name(k)) return path_property_get(path, k);
            }
            return fn_path_key(item, key);
        }
        return ItemNull;
    }

    switch (type_id) {
    case LMD_TYPE_NULL:
        return ItemNull;  // null-safe: null.field returns null
    case LMD_TYPE_ERROR: {
        // error member properties: .code and .message
        // Error propagation accepts only named properties. A numeric computed
        // member must preserve the error instead of treating its payload bits
        // as a Symbol pointer (S7.1.1).
        if (!is_text_type_id(get_type_id(key))) return item;
        const char* k = key.get_chars();
        if (!k) return item;  // error propagation

        // S7.4.4: an error value carries its own code and message. Only the
        // payload-less ItemError sentinel falls back to context->last_error,
        // its diagnostic copy; reading that for every error made each one
        // report whichever error was built last (LR10-7).
        LambdaError* err = it2err(item);
        if (!err && context) err = context->last_error;
        if (strcmp(k, "code") == 0) {
            return {.item = i2it(err ? err->code : ERR_USER_ERROR)};
        }
        if (strcmp(k, "message") == 0) {
            if (err && err->message) {
                String* msg = heap_strcpy(err->message, strlen(err->message));
                return {.item = s2it(msg)};
            }
            String* msg = heap_create_name("Error");
            return {.item = s2it(msg)};  // default message
        }
        // S7.4.4's other members: the wrapped cause and the source location.
        // Each had fallen through to the error itself (LR10-10); an absent one
        // reads null (S7.1.1v3).
        if (strcmp(k, "source") == 0) {
            return err && err->cause ? err2it(err->cause) : ItemNull;
        }
        if (strcmp(k, "file") == 0) {
            const char* file = err ? err->location.file : NULL;
            return file ? (Item){.item = s2it(heap_strcpy(file, strlen(file)))} : ItemNull;
        }
        if (strcmp(k, "line") == 0 || strcmp(k, "column") == 0) {
            uint32_t value = !err ? 0 : k[0] == 'l' ? err->location.line
                : err->location.column;
            return value ? (Item){.item = i2it(value)} : ItemNull;
        }

        return item;  // error propagation for other properties
    }
    case LMD_TYPE_DTIME: {
        // datetime member properties
        DateTime dt = item.get_datetime();
        // Datetime properties are named; protect the text accessor from a
        // numeric member key on malformed/adversarial source (S4, S7.1.1).
        if (!is_text_type_id(get_type_id(key))) return ItemNull;
        const char* k = key.get_chars();
        if (!k) return ItemNull;

        // date properties
        if (strcmp(k, "year") == 0)         return {.item = i2it(DATETIME_GET_YEAR(&dt))};
        if (strcmp(k, "month") == 0)        return {.item = i2it(DATETIME_GET_MONTH(&dt))};
        if (strcmp(k, "day") == 0)          return {.item = i2it(dt.day)};
        if (strcmp(k, "weekday") == 0)      return {.item = i2it(datetime_weekday(&dt))};
        if (strcmp(k, "yearday") == 0)      return {.item = i2it(datetime_yearday(&dt))};
        if (strcmp(k, "week") == 0)         return {.item = i2it(datetime_week_number(&dt))};
        if (strcmp(k, "quarter") == 0)      return {.item = i2it(datetime_quarter(&dt))};

        // time properties
        if (strcmp(k, "hour") == 0)         return {.item = i2it(dt.hour)};
        if (strcmp(k, "minute") == 0)       return {.item = i2it(dt.minute)};
        if (strcmp(k, "second") == 0)       return {.item = i2it(dt.second)};
        if (strcmp(k, "millisecond") == 0)  return {.item = i2it(dt.millisecond)};

        // timezone properties
        if (strcmp(k, "timezone") == 0) {
            if (!DATETIME_HAS_TIMEZONE(&dt)) return ItemNull;
            return {.item = i2it(DATETIME_GET_TZ_OFFSET(&dt))};
        }
        if (strcmp(k, "utc_offset") == 0) {
            if (!DATETIME_HAS_TIMEZONE(&dt)) return ItemNull;
            int tz = DATETIME_GET_TZ_OFFSET(&dt);
            char buf[8];
            int h = abs(tz) / 60, m = abs(tz) % 60;
            int len = snprintf(buf, sizeof(buf), "%c%02d:%02d", tz >= 0 ? '+' : '-', h, m);
            Symbol* sym = heap_create_symbol(buf, len);
            return {.item = y2it(sym)};
        }
        if (strcmp(k, "is_utc") == 0) {
            if (!DATETIME_HAS_TIMEZONE(&dt)) return {.item = b2it(false)};
            return {.item = b2it(DATETIME_GET_TZ_OFFSET(&dt) == 0)};
        }

        // meta properties
        // v5: unix-ms is an `int` (the int53 band reaches year 285,000), so it
        // boxes inline rather than taking a number home — same pre-v5 leftover.
        if (strcmp(k, "unix") == 0)           return {.item = i2it(datetime_to_unix_ms(&dt))};
        if (strcmp(k, "is_date") == 0)        return {.item = b2it(dt.precision == DATETIME_PRECISION_DATE_ONLY || dt.precision == DATETIME_PRECISION_YEAR_ONLY)};
        if (strcmp(k, "is_time") == 0)        return {.item = b2it(dt.precision == DATETIME_PRECISION_TIME_ONLY)};
        if (strcmp(k, "is_leap_year") == 0)   return {.item = b2it(datetime_is_leap_year_dt(&dt))};
        if (strcmp(k, "days_in_month") == 0)  return {.item = i2it(datetime_days_in_month_dt(&dt))};

        // extraction properties (return transformed datetime)
        if (strcmp(k, "date") == 0) {
            DateTime result = dt;
            result.hour = 0;
            result.minute = 0;
            result.second = 0;
            result.millisecond = 0;
            result.precision = DATETIME_PRECISION_DATE_ONLY;
            return push_k(result);
        }
        if (strcmp(k, "time") == 0) {
            DateTime result;
            memset(&result, 0, sizeof(DateTime));
            DATETIME_SET_YEAR_MONTH(&result, 1970, 1);
            result.day = 1;
            result.hour = dt.hour;
            result.minute = dt.minute;
            result.second = dt.second;
            result.millisecond = dt.millisecond;
            result.tz_offset_biased = dt.tz_offset_biased;
            result.precision = DATETIME_PRECISION_TIME_ONLY;
            result.format_hint = dt.format_hint;
            return push_k(result);
        }
        if (strcmp(k, "utc") == 0) {
            DateTime* result = datetime_to_utc(context->pool, &dt);
            if (result) return push_k(*result);
            return ItemNull;
        }
        if (strcmp(k, "local") == 0) {
            DateTime* result = datetime_to_local(context->pool, &dt);
            if (result) return push_k(*result);
            return ItemNull;
        }

        log_debug("fn_member: unknown datetime property '%s'", k);
        return ItemNull;
    }
    case LMD_TYPE_MAP:
    case LMD_TYPE_ELEMENT: {
        // D2.6.6v2 phase 2: a nominal container resolves its methods after its
        // fields (S12.3.3v2); a structural one has no method tier. The kinds
        // share this prologue because they share the attribute face; they part
        // only at the fallback, where an element also answers `name` with its
        // tag.
        if (is_text_type_id(key._type_id) &&
                lambda_value_nominal(type_id, item.container)) {
            return lambda_object_member(item, (const char*)key.get_chars());
        }
        return type_id == LMD_TYPE_MAP ? map_get(item.map, key)
                                       : elmt_get(item.element, key);
    }
    case LMD_TYPE_VMAP: {
        VMap *vm = item.vmap;
        // A host projection is a map even when it has no local vtable; its
        // properties are supplied by vmap_get_by_item's host dispatch.
        if (!vm || (!vm->host_type && !vm->vtable)) return ItemNull;
        return vmap_get_by_item(vm, key);
    }
    case LMD_TYPE_VELMT: {
        Item projected = ItemNull;
        if (jube_member_projected_get(item, key, &projected)) return projected;
        if (is_text_type_id(get_type_id(key))) return velmt_attr_get(item.velmt, key);
        return ItemNull;
    }
    case LMD_TYPE_ARRAY:
    case LMD_TYPE_ARRAY_NUM:
    case LMD_TYPE_VARRAY: {
        // Handle built-in properties for List type
        if (is_text_type_id(key._type_id)) {
            const char* k = key.get_chars();
            if (k && strcmp(k, "length") == 0) {
                return {.item = i2it(fn_len(item))};
            }
        }
        int64_t index = -1;
        // Numeric dotted members are IntKey access (`a.1`), not NameKey
        // lookup; route them through the existing indexed-array helper.
        if (lambda_item_to_int64_exact(key, &index)) {
            return item_at(item, index);
        }
        return ItemNull;
    }
    case LMD_TYPE_TYPE: {
        // S2.2.2v2: `symbol.empty` names the one zero-length symbol
        TypeType* type_value = (TypeType*)item.type;
        if (type_value && type_value->type && type_value->type->type_id == LMD_TYPE_SYMBOL &&
                is_text_type_id(key._type_id) && key.get_len() == 5 &&
                strncmp(key.get_chars(), "empty", 5) == 0) {
            return {.item = y2it(symbol_empty())};
        }
        return ItemNull;
    }
    // todo: built-in properties for other types
    default:
        return ItemNull;
    }
}

extern "C" Item fn_member_by_id(Item item, NameId name_id) {
    // A generated static member name is already resolved in the active module
    // state. Maps and objects can consume that identity directly; only the
    // id-less/input and non-map property paths need the legacy boxed fallback.
    if (name_id == NAME_ID_NONE) return ItemNull;
    TypeId type_id = get_type_id(item);
    bool is_found = false;
    switch (type_id) {
    case LMD_TYPE_MAP: {
        Map* map = item.map;
        if (map) {
            Item result = map_get_by_name_id((Container*)map,
                (TypeMap*)map->type, map->data, name_id, &is_found);
            if (is_found) return result;
        }
        break;
    }
    default:
        break;
    }

    // Id-less input shapes and built-in properties still require spelling
    // semantics. This is cold relative to generated map field hops and
    // preserves fn_member's path, datetime, vmap, array, and element rules.
    Item key = lambda_name_id_to_item(name_id);
    return fn_member(item, key);
}

// The attribute half of a container's length, read through the shared Map face
// (D2.6.6v2). `length` is the entry count only while every entry is a named
// field: a spread is one nameless link slot covering many, so those shapes
// count through the same flattening walk iteration uses (S8.3.1).
static inline int64_t map_attr_count(const Map* owner) {
    TypeMap* shape = owner ? (TypeMap*)owner->type : NULL;
    if (!shape) return 0;
    return shape->has_spread ? map_flat_field_count(shape, owner->data) : shape->length;
}

// length of an item's content, relates to indexed access, i.e. item[index]
// S8.3.3v3: count(x) is the size of the run x is (S2.5.5v2, S11.1.6v2): 0 for
// null, len(x) for a list, and 1 for any other value -- an array or text is
// one item. It is what `len` cannot say about a query or any `T*`: a lone
// match is the value itself, and a lone array match is one item, not its
// contents. An error never reaches here: the call boundary rejects it first,
// so count(error) is error, as len(error) is (S8.3.1v3).
int64_t fn_count(Item item) {
    if (get_type_id(item) == LMD_TYPE_NULL) return 0;
    if (item_is_list(item)) return fn_len(item);
    return 1;
}

extern "C" Item fn_virtual_content_check(Item item) { return virtual_content_error(item); }

extern "C" Item fn_len_checked(Item item) {
    GUARD_ERROR1(item);
    Item error = virtual_content_error(item);
    // ItemNull carries a nonzero tag; only an error tag indicates a failed host read (S7.4.1).
    return get_type_id(error) == LMD_TYPE_ERROR ? error : (Item){.item = i2it(fn_len(item))};
}

int64_t fn_len(Item item) {
    TypeId type_id = get_type_id(item);
    int64_t size = 0;
    switch (type_id) {
    case LMD_TYPE_ARRAY:
        size = item.array->length;
        break;
    case LMD_TYPE_VARRAY:
        size = varray_count(item.varray);
        break;
    case LMD_TYPE_RANGE:
        size = item.range->length;
        break;
    case LMD_TYPE_ARRAY_NUM:
        size = array_num_iter_count(item.array_num);
        break;
    case LMD_TYPE_MAP: {
        // A map is iterable exactly like an array -- `for (v in m)` walks its
        // entries -- so its length is that entry count.
        size = map_attr_count(item.map);
        break;
    }
    case LMD_TYPE_VMAP: {
        VMap* vm = item.vmap;
        if (vm && vm->vtable) size = vm->vtable->count(vm->data);
        break;
    }
    case LMD_TYPE_ELEMENT: {
        // S8.3.1v2: length IS the for-iterable length, and `for (x in e)` walks
        // the attribute values and then the content items, so an element's
        // length is attributes plus content — `len(<e a:1, b:2, "t">)` is 3.
        // Nominal and structural elements answer alike (LR09-8 closed).
        size = map_attr_count((Map*)item.element) + item.element->length;
        break;
    }
    case LMD_TYPE_VELMT:
        size = velmt_attr_count(item.velmt) + velmt_child_count(item.velmt);
        break;
    case LMD_TYPE_BINARY:
        // Binary length is a byte count, including embedded NUL bytes.
        size = item.get_len();
        break;
    case LMD_TYPE_STRING:  case LMD_TYPE_SYMBOL: {
        // returns the character length of text values
        const char* chars = item.get_chars();
        if (!chars) { size = 0; break; }
        bool is_ascii = false;
        uint32_t len = item.get_len();
        if (type_id == LMD_TYPE_STRING) {
            String* str = item.get_safe_string();
            is_ascii = str->is_ascii != 0;
        }
        size = is_ascii ? (int64_t)len : (int64_t)str_utf8_count(chars, len);
        break;
    }
    case LMD_TYPE_PATH: {
        // Lazy evaluation: resolve path content if not cached, then get length
        Path* path_val = item.path;
        if (!path_val) { size = 0; break; }
        // Check if content is already resolved (cached in path->result)
        if (path_val->result == 0) {
            // Use path_resolve_for_iteration which handles:
            // - Directories: returns list of child paths
            // - Files: returns parsed content
            // - Wildcards: expands to list of matching paths
            // - Non-existent: returns null (len = 0)
            // - Access errors: returns error
            Item resolved = path_resolve_for_iteration(path_val);
            // result is now cached in path_val->result
            if (resolved.item == ItemError.item) {
                // 7.6: `len` is total -- an unresolvable path iterates zero
                // times. Returning an error here would violate the one function
                // the spec guarantees never fails.
                size = 0;
                break;
            }
        }
        // Get length from cached result
        Item cached = {.item = path_val->result};
        if (cached.item == 0) {
            size = 0;  // null path -> length 0
        } else {
            size = fn_len(cached);
        }
        break;
    }
    case LMD_TYPE_ERROR:
        // Formal semantics 7.6: `len` is a value function, so an error
        // propagates -- iterating an error yields an error, not nothing, which
        // is what distinguishes it from `len(null)` = 0. The parameter is
        // `any \ error` (7.7), so an error is rejected at the call boundary and
        // never reaches this body; the arm is a defensive floor. It answers 0
        // rather than a numeric error marker, which a double lane cannot reject
        // and which once reached callers as a real length -- `err |> ~` took it as an
        // iteration bound and attempted repeated 2 GB allocations.
        size = 0;
        break;
    default: // NULL and scalar types
        size = 0;
        break;
    }
    return size;
}

// Native len variants — type-specialized, avoid Item type switch overhead
// Used when compile-time type is known. The transpiler must unbox Items to raw
// pointers before calling these (emit_unbox_container strips tag bits).
// Physical VArray/Velmt carriers use fn_len_checked before these NO_GC leaves.

extern "C" int64_t fn_len_l(List* list) {
    if (!list) return 0;
    // Runtime check: nested numeric literals may have been auto-promoted from
    // List/Array to N-D ArrayNum (the JIT dispatched based on static type).
    if (list->type_id == LMD_TYPE_ARRAY_NUM) {
        return array_num_iter_count((ArrayNum*)list);
    }
    return list->length;
}

extern "C" int64_t fn_len_a(Array* arr) {
    if (!arr) return 0;
    // Runtime check: static type may say Array but actual could be ArrayNum
    // (e.g. nested literals auto-promoted to N-D). For N-D ArrayNum, return
    // shape[0] (leading axis) to match NumPy semantics.
    if (arr->type_id == LMD_TYPE_ARRAY_NUM) {
        return array_num_iter_count((ArrayNum*)arr);
    }
    return arr->length;
}

extern "C" int64_t fn_len_s(String* str) {
    if (!str) return 0;
    return str->is_ascii ? (int64_t)str->len : (int64_t)str_utf8_count(str->chars, str->len);
}

// content(e) — the element's content items as a read-only ARRAY VIEW.
//
// The view shadow-copies the element's content meta fields (items pointer and
// length) and does NOT copy the item slots, so `content(e)[i]` costs nothing
// over `e[i]` and the graph package's per-node walks stay allocation-free.
// Borrowing is expressed with the container view contract that ArrayNum
// already uses (LR09-9): `is_view` set, and `extra` holding an ArrayNumShape
// whose `base` is the owning element. That descriptor is what keeps the base
// alive through a collection and what lets the GC re-point `items` after the
// base's buffer is compacted — a plain aliased pointer would dangle, because
// element content buffers do move (`gc_compact_data`).
//
// Read-only for now: `is_mutable_view` stays 0 and every write path refuses a
// view, so aliasing can never be observed as a second writable handle. Whether
// writes should pass through to the element is deliberately left open.
Item fn_content(Item item) {
    GUARD_ERROR1(item);
    if (fs_node_is(item)) return fs_node_content(item);
    if (get_type_id(item) == LMD_TYPE_VELMT) {
        Item error = virtual_content_error(item);
        if (get_type_id(error) == LMD_TYPE_ERROR) return error;
        // Other virtual hosts expose the same immutable child-view contract.
        RootFrame roots(1);
        Rooted<Item> owner(roots, item);
        struct ChildView { Item owner; };
        static const VArrayVtable vtable = {
            {LAMBDA_VIRTUAL_ABI_VERSION, LMD_TYPE_VARRAY, {},
                [](void* p) { mem_free(p); },
                [](void* p, gc_heap* gc) { gc_mark_item(gc, ((ChildView*)p)->owner.item); }, nullptr},
            {[](void* p) -> int64_t { return velmt_child_count(((ChildView*)p)->owner.velmt); },
                [](void* p, int64_t i, Item* out) -> VirtualOpStatus {
                    Velmt* e = ((ChildView*)p)->owner.velmt;
                    return e->vtable->element.children.get_at(e->data, i, out);
                }, nullptr, nullptr, nullptr}
        };
        ChildView* view = (ChildView*)mem_calloc(1, sizeof(ChildView), MEM_CAT_INPUT_OTHER);
        if (!view) return ItemError;
        view->owner = owner.get();
        Item result = varray_new(&vtable, view, nullptr, nullptr);
        if (!result.item) { mem_free(view); return ItemError; }
        return result;
    }
    TypeId type_id = get_type_id(item);
    if (type_id != LMD_TYPE_ELEMENT) {
        return lambda_type_error(item, &TYPE_ELMT, "content");
    }
    Element* elmt = item.element;
    if (!elmt) return ItemNull;

    // The view must be ROOTED across the descriptor allocation: that allocation
    // can collect, and with conservative stack scanning retired (D-rule) a view
    // held only in this frame is invisible to the collector. Without this the
    // view was reclaimed mid-construction and its slot handed to the next
    // array, so `content(e)` silently returned a later, unrelated array.
    RootFrame roots(2);
    Rooted<Element*> rooted_base(roots, elmt);
    Rooted<Array*> rooted_view(roots,
        (Array*)heap_calloc(sizeof(Array), LMD_TYPE_ARRAY));
    Array* view = rooted_view.get();
    if (!view) return ItemError;
    view->type_id = LMD_TYPE_ARRAY;

    ArrayNumShape* shape = (ArrayNumShape*)heap_data_alloc(sizeof(ArrayNumShape));
    if (!shape) return ItemError;
    memset(shape, 0, sizeof(ArrayNumShape));
    view = rooted_view.get();     // reload: the allocation above may have moved nothing,
    elmt = rooted_base.get();     // but the rooted handles are the authoritative pointers
    shape->ndim = 1;
    shape->is_c_contig = 1;
    shape->is_f_contig = 1;
    shape->backing_kind = ARRAY_NUM_BACKING_GC_VIEW;
    shape->offset = 0;
    shape->base = (void*)elmt;

    view->is_view = 1;
    view->is_mutable_view = 0;
    view->items = elmt->items;
    view->length = elmt->length;
    // A view never owns storage, so it must not look growable: capacity 0 keeps
    // every push/realloc path away from the borrowed buffer.
    view->capacity = 0;
    view->extra = (int64_t)(uintptr_t)shape;
    return {.array = view};
}

// The number of positions a POSITIONAL traversal visits — the shared notion
// behind the mapping pipe, `last`, and the set operators, all of which pair a
// count with an IntKey read. It is NOT fn_len for an element: an IntKey reaches
// content only (S8.2.1v3) while len also counts attributes (S8.3.1v2), and an
// element's attributes describe the value rather than being members of it (a
// group element's attributes are its key, its children are the rows). Before
// S8.3.1v2 the two happened to agree, which is why every one of these callers
// was written against fn_len and silently gained a trailing null per attribute
// once they diverged (LR09-9).
extern "C" int64_t fn_seq_count(Item item) {
    TypeId type_id = get_type_id(item);
    if (type_id == LMD_TYPE_ELEMENT) return item.element ? item.element->length : 0;
    return fn_len(item);
}

extern "C" int64_t fn_len_e(Element* elmt) {
    if (!elmt) return 0;
    if (elmt->type_id == LMD_TYPE_VELMT) return velmt_attr_count((Velmt*)elmt) + velmt_child_count((Velmt*)elmt);
    // The JIT specializes `len` on a statically-element argument to this
    // helper, so it must apply the same S8.3.1v2 rule as fn_len's element arm
    // or the two tiers disagree — which is exactly how the nominal half of
    // LR09-8 was originally found.
    return map_attr_count((Map*)elmt) + elmt->length;
}

// substring system function - extracts a substring from start to end (exclusive)
Item fn_substring(Item str_item, Item start_item, Item end_item) {
    GUARD_ERROR3(str_item, start_item, end_item);
    TypeId str_tid = get_type_id(str_item);
    if (!is_text_type_id(str_tid)) {
        log_debug("fn_substring: first argument must be a string or symbol");
        return ItemError;
    }

    int64_t start = 0;
    int64_t end = 0;
    LambdaSliceStatus status = lambda_slice_offsets(start_item, end_item, &start, &end);
    if (status == LAMBDA_SLICE_ABSENT) return ItemNull;
    if (status == LAMBDA_SLICE_INVALID) {
        log_debug("fn_substring: start and end must be integer-valued numbers");
        return ItemError;
    }

    // use type-aware accessors: String and Symbol have different struct layouts
    // String: {len, is_ascii, chars[]}, Symbol: {len, ns*, chars[]}
    const char* chars = str_item.get_chars();
    uint32_t str_len = str_item.get_len();
    if (!chars || str_len == 0) {
        return str_item; // return empty string/symbol
    }

    // helper: return result as string or symbol depending on input type
    bool is_symbol = (str_tid == LMD_TYPE_SYMBOL);

    // is_ascii only exists on String, not Symbol; symbols use UTF-8 path
    bool is_ascii = false;
    if (!is_symbol) {
        String* str = str_item.get_safe_string();
        if (!str) return ItemNull;
        is_ascii = str->is_ascii != 0;
    }

    // ASCII fast path: char index == byte index
    if (is_ascii) {
        int64_t char_len = (int64_t)str_len;
        // negative offsets clamp, they do not wrap from the end
        lambda_clamp_slice_range(char_len, &start, &end);
        if (start >= end) {
            if (is_symbol) return {.item = y2it(heap_create_symbol("", 0))};
            String* empty = (String *)heap_alloc(sizeof(String) + 1, LMD_TYPE_STRING);
            empty->len = 0;
            empty->flags = 0;
            empty->is_ascii = 1;
            empty->chars[0] = '\0';
            return {.item = s2it(empty)};
        }
        long result_len = (long)(end - start);
        if (is_symbol) return {.item = y2it(heap_create_symbol(chars + start, result_len))};
        String* result = (String *)heap_alloc(sizeof(String) + result_len + 1, LMD_TYPE_STRING);
        result->len = result_len;
        result->flags = 0;
        result->is_ascii = 1;
        str_copy(result->chars, result_len + 1, chars + start, result_len);
        return {.item = s2it(result)};
    }

    // negative offsets clamp, they do not wrap from the end
    int64_t char_len = (int64_t)str_utf8_count(chars, str_len);
    lambda_clamp_slice_range(char_len, &start, &end);
    if (start >= end) {
        if (is_symbol) return {.item = y2it(heap_create_symbol("", 0))};
        String* empty = (String *)heap_alloc(sizeof(String) + 1, LMD_TYPE_STRING);
        empty->len = 0;
        empty->flags = 0;
        empty->is_ascii = 1;
        empty->chars[0] = '\0';
        return {.item = s2it(empty)};
    }

    // convert char indices to byte indices
    long byte_start = (long)str_utf8_char_to_byte(chars, str_len, (size_t)start);
    long byte_end = (long)str_utf8_char_to_byte(chars, str_len, (size_t)end);

    if (byte_start >= str_len || byte_end < 0) {
        if (is_symbol) return {.item = y2it(heap_create_symbol("", 0))};
        String* empty = (String *)heap_alloc(sizeof(String) + 1, LMD_TYPE_STRING);
        empty->len = 0;
        empty->flags = 0;
        empty->is_ascii = 1;
        empty->chars[0] = '\0';
        return {.item = s2it(empty)};
    }

    long result_len = byte_end - byte_start;
    if (is_symbol) return {.item = y2it(heap_create_symbol(chars + byte_start, result_len))};
    String* result = (String *)heap_alloc(sizeof(String) + result_len + 1, LMD_TYPE_STRING);
    result->len = result_len;
    result->flags = 0;
    result->is_ascii = 0;  // UTF-8 path — not necessarily ASCII
    str_copy(result->chars, result_len + 1, chars + byte_start, result_len);

    return {.item = s2it(result)};
}

// contains system function - checks if a string contains a substring
Bool fn_contains(Item str_item, Item substr_item) {
    GUARD_BOOL_ERROR2(str_item, substr_item);
    TypeId coll_type = get_type_id(str_item);
    // null doesn't contain anything, and nothing contains null
    if (coll_type == LMD_TYPE_NULL || get_type_id(substr_item) == LMD_TYPE_NULL) {
        return BOOL_FALSE;
    }

    // --- List/Array: check if any element equals the item ---
    if (coll_type == LMD_TYPE_ARRAY) {
        List* list = str_item.array;
        if (!list) return BOOL_FALSE;
        for (int64_t i = 0; i < list->length; i++) {
            if (fn_eq(array_item_read(list, i), substr_item) == BOOL_TRUE) {
                return BOOL_TRUE;
            }
        }
        return BOOL_FALSE;
    }
    if (coll_type == LMD_TYPE_ARRAY_NUM) {
        ArrayNum* arr = str_item.array_num;
        return array_num_find_equal(arr, substr_item, false) >= 0 ? BOOL_TRUE : BOOL_FALSE;
    }

    // --- Map: check if any key matches ---
    if (coll_type == LMD_TYPE_MAP) {
        Map* map = str_item.map;
        if (!map) return BOOL_FALSE;
        Item val = map_get(map, substr_item);
        return (get_type_id(val) != LMD_TYPE_NULL) ? BOOL_TRUE : BOOL_FALSE;
    }

    // --- Element: check attribute keys and children ---
    if (coll_type == LMD_TYPE_ELEMENT) {
        Element* el = str_item.element;
        if (!el) return BOOL_FALSE;
        // check children
        for (int64_t i = 0; i < el->length; i++) {
            if (fn_eq(el->items[i], substr_item) == BOOL_TRUE) {
                return BOOL_TRUE;
            }
        }
        return BOOL_FALSE;
    }

    // --- String: substring check ---
    if (coll_type != LMD_TYPE_STRING) {
        log_debug("fn_contains: first argument must be a string, list, map, or element");
        return BOOL_ERROR;
    }

    if (get_type_id(substr_item) != LMD_TYPE_STRING) {
        log_debug("fn_contains: second argument must be a string for string contains");
        return BOOL_ERROR;
    }

    String* str = str_item.get_safe_string();
    String* substr = substr_item.get_safe_string();

    if (!str || !substr) {
        return BOOL_FALSE;
    }

    // shared bounded byte search preserves embedded NUL and UTF-8 substrings.
    return str_find(str->chars, str->len, substr->chars, substr->len) != STR_NPOS
        ? BOOL_TRUE : BOOL_FALSE;
}

// starts_with native: String* in, Bool out (no Item boxing)
Bool fn_starts_with_str(String* str, String* prefix) {
    if (!str) return BOOL_FALSE;
    if (!prefix || prefix->len == 0) return BOOL_TRUE;
    if (str->len < prefix->len) return BOOL_FALSE;
    return (memcmp(str->chars, prefix->chars, prefix->len) == 0) ? BOOL_TRUE : BOOL_FALSE;
}

// starts_with(str, prefix) - check if string starts with prefix
Bool fn_starts_with(Item str_item, Item prefix_item) {
    GUARD_BOOL_ERROR2(str_item, prefix_item);
    TypeId str_type = get_type_id(str_item);
    TypeId prefix_type = get_type_id(prefix_item);

    if (str_type == LMD_TYPE_NULL) return BOOL_FALSE;
    if (prefix_type == LMD_TYPE_NULL) return BOOL_TRUE;

    if ((!is_text_type_id(str_type)) ||
        (!is_text_type_id(prefix_type))) {
        log_debug("fn_starts_with: arguments must be strings or symbols");
        return BOOL_ERROR;
    }

    const char* str_chars = str_item.get_chars();
    uint32_t str_len = str_item.get_len();
    const char* prefix_chars = prefix_item.get_chars();
    uint32_t prefix_len = prefix_item.get_len();

    if (!str_chars || !prefix_chars) return BOOL_FALSE;
    if (prefix_len == 0) return BOOL_TRUE;
    if (str_len < prefix_len) return BOOL_FALSE;

    return (memcmp(str_chars, prefix_chars, prefix_len) == 0) ? BOOL_TRUE : BOOL_FALSE;
}

// ends_with native: String* in, Bool out (no Item boxing)
Bool fn_ends_with_str(String* str, String* suffix) {
    if (!str) return BOOL_FALSE;
    if (!suffix || suffix->len == 0) return BOOL_TRUE;
    if (str->len < suffix->len) return BOOL_FALSE;
    size_t offset = str->len - suffix->len;
    return (memcmp(str->chars + offset, suffix->chars, suffix->len) == 0) ? BOOL_TRUE : BOOL_FALSE;
}

// ends_with(str, suffix) - check if string ends with suffix
Bool fn_ends_with(Item str_item, Item suffix_item) {
    GUARD_BOOL_ERROR2(str_item, suffix_item);
    TypeId str_type = get_type_id(str_item);
    TypeId suffix_type = get_type_id(suffix_item);

    if (str_type == LMD_TYPE_NULL) return BOOL_FALSE;
    if (suffix_type == LMD_TYPE_NULL) return BOOL_TRUE;

    if ((!is_text_type_id(str_type)) ||
        (!is_text_type_id(suffix_type))) {
        log_debug("fn_ends_with: arguments must be strings or symbols");
        return BOOL_ERROR;
    }

    const char* str_chars = str_item.get_chars();
    uint32_t str_len = str_item.get_len();
    const char* suffix_chars = suffix_item.get_chars();
    uint32_t suffix_len = suffix_item.get_len();

    if (!str_chars || !suffix_chars) return BOOL_FALSE;
    if (suffix_len == 0) return BOOL_TRUE;
    if (str_len < suffix_len) return BOOL_FALSE;

    size_t offset = str_len - suffix_len;
    return (memcmp(str_chars + offset, suffix_chars, suffix_len) == 0) ? BOOL_TRUE : BOOL_FALSE;
}

// index_of raw search helper — -1 is retained only for C/JS adapters.
// The public Lambda wrapper below converts absence to null.
static int64_t fn_index_of_raw_impl(Item str_item, Item sub_item, bool reverse) {
    // This raw helper keeps the C-family -1 ABI for foreign adapters. Lambda's
    // public wrapper maps its broad-input no-answer result to null.
    if (get_type_id(str_item) == LMD_TYPE_ERROR || get_type_id(sub_item) == LMD_TYPE_ERROR) {
        return -1;
    }
    TypeId coll_type = get_type_id(str_item);
    if (coll_type == LMD_TYPE_ARRAY) {
        List* list = str_item.array;
        if (!list) return -1;
        if (!reverse) {
            for (int64_t i = 0; i < list->length; i++) {
                if (fn_eq(array_item_read(list, i), sub_item) == BOOL_TRUE) return i;
            }
        } else {
            for (int64_t i = list->length - 1; i >= 0; i--) {
                if (fn_eq(array_item_read(list, i), sub_item) == BOOL_TRUE) return i;
            }
        }
        return -1;
    }
    if (coll_type == LMD_TYPE_ARRAY_NUM) {
        return array_num_find_equal(str_item.array_num, sub_item, reverse);
    }

    TypeId sub_type = get_type_id(sub_item);
    if (!is_text_type_id(coll_type) || !is_text_type_id(sub_type)) {
        log_debug("fn_%sindex_of: arguments must be strings/symbols or first arg must be a list",
            reverse ? "last_" : "");
        return -1;
    }
    const char* str_chars = str_item.get_chars();
    uint32_t str_len = str_item.get_len();
    const char* sub_chars = sub_item.get_chars();
    uint32_t sub_len = sub_item.get_len();
    if (!str_chars || !sub_chars) return -1;

    bool is_ascii = false;
    if (coll_type == LMD_TYPE_STRING) {
        String* str = str_item.get_safe_string();
        if (!str) return -1;
        is_ascii = str->is_ascii != 0;
    } else {
        is_ascii = str_is_ascii(str_chars, str_len);
    }
    if (sub_len == 0) {
        if (!reverse) return 0;
        return is_ascii ? (int64_t)str_len : (int64_t)str_utf8_count(str_chars, str_len);
    }
    if (str_len < sub_len) return -1;

    // byte matching is shared; Lambda's result remains a code-point index.
    size_t found = reverse ? str_rfind(str_chars, str_len, sub_chars, sub_len)
        : str_find(str_chars, str_len, sub_chars, sub_len);
    return found == STR_NPOS ? -1 : is_ascii ? (int64_t)found
        : (int64_t)str_utf8_count(str_chars, found);
}

int64_t fn_index_of_raw(Item str_item, Item sub_item) {
    return fn_index_of_raw_impl(str_item, sub_item, false);
}

// Lambda's public search result uses null for absence. Keep the raw -1 helper
// separate because JavaScript's String#indexOf family requires that sentinel.
static Item fn_nullable_int_result(int64_t result) {
    return result < 0 ? ItemNull : (Item){.item = i2it(result)};
}

Item fn_index_of(Item str_item, Item sub_item) {
    // preserve the original error payload; only a successful no-match becomes null.
    GUARD_ERROR2(str_item, sub_item);
    return fn_nullable_int_result(fn_index_of_raw(str_item, sub_item));
}

// last_index_of raw search helper — -1 is retained only for C/JS adapters.
// The public Lambda wrapper below converts absence to null.
int64_t fn_last_index_of_raw(Item str_item, Item sub_item) {
    return fn_index_of_raw_impl(str_item, sub_item, true);
}

Item fn_last_index_of(Item str_item, Item sub_item) {
    GUARD_ERROR2(str_item, sub_item);
    return fn_nullable_int_result(fn_last_index_of_raw(str_item, sub_item));
}

// Helper: check if character is ASCII whitespace
static inline bool is_ascii_whitespace(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

// trim(str) - remove leading and trailing whitespace
Item fn_trim(Item str_item) {
    GUARD_ERROR1(str_item);
    TypeId str_type = get_type_id(str_item);

    // null trims to empty string
    if (str_type == LMD_TYPE_NULL) return ItemNull;

    if (!is_text_type_id(str_type)) {
        log_debug("fn_trim: argument must be a string or symbol");
        return ItemError;
    }

    const char* chars = str_item.get_chars();
    uint32_t len = str_item.get_len();
    if (!chars || len == 0) {
        return str_item;
    }

    // find start (skip leading whitespace)
    size_t start = 0;
    while (start < len && is_ascii_whitespace((unsigned char)chars[start])) {
        start++;
    }

    // find end (skip trailing whitespace)
    size_t end = len;
    while (end > start && is_ascii_whitespace((unsigned char)chars[end - 1])) {
        end--;
    }

    if (start >= end) {
        // Trimming can legitimately produce an empty string; only solid symbols collapse to null.
        if (str_type == LMD_TYPE_SYMBOL) return ItemNull;
        String* empty = heap_strcpy("", 0);
        return {.item = s2it(empty)};
    }

    size_t result_len = end - start;
    if (str_type == LMD_TYPE_SYMBOL) {
        return {.item = y2it(heap_create_symbol(chars + start, result_len))};
    }

    String* result = (String *)heap_alloc(sizeof(String) + result_len + 1, LMD_TYPE_STRING);
    result->len = result_len;
    result->flags = 0;
    result->is_ascii = str_is_ascii(chars + start, result_len) ? 1 : 0;
    str_copy(result->chars, result_len + 1, chars + start, result_len);
    return {.item = s2it(result)};
}

// trim_start(str) - remove leading whitespace
Item fn_trim_start(Item str_item) {
    GUARD_ERROR1(str_item);
    TypeId str_type = get_type_id(str_item);

    // null trims to null
    if (str_type == LMD_TYPE_NULL) return ItemNull;

    if (!is_text_type_id(str_type)) {
        log_debug("fn_trim_start: argument must be a string or symbol");
        return ItemError;
    }

    const char* chars = str_item.get_chars();
    uint32_t len = str_item.get_len();
    if (!chars || len == 0) {
        return str_item;
    }

    // find start (skip leading whitespace)
    size_t start = 0;
    while (start < len && is_ascii_whitespace((unsigned char)chars[start])) {
        start++;
    }

    if (start == 0) {
        return str_item;  // no leading whitespace
    }

    size_t result_len = len - start;
    if (result_len == 0) {
        // Trimming can legitimately produce an empty string; only solid symbols collapse to null.
        if (str_type == LMD_TYPE_SYMBOL) return ItemNull;
        String* empty = heap_strcpy("", 0);
        return {.item = s2it(empty)};
    }
    if (str_type == LMD_TYPE_SYMBOL) {
        return {.item = y2it(heap_create_symbol(chars + start, result_len))};
    }

    String* result = (String *)heap_alloc(sizeof(String) + result_len + 1, LMD_TYPE_STRING);
    result->len = result_len;
    result->flags = 0;
    result->is_ascii = str_is_ascii(chars + start, result_len) ? 1 : 0;
    str_copy(result->chars, result_len + 1, chars + start, result_len);
    return {.item = s2it(result)};
}

// trim_end(str) - remove trailing whitespace
Item fn_trim_end(Item str_item) {
    GUARD_ERROR1(str_item);
    TypeId str_type = get_type_id(str_item);

    // null trims to null
    if (str_type == LMD_TYPE_NULL) return ItemNull;

    if (!is_text_type_id(str_type)) {
        log_debug("fn_trim_end: argument must be a string or symbol");
        return ItemError;
    }

    const char* chars = str_item.get_chars();
    uint32_t slen = str_item.get_len();
    if (!chars || slen == 0) {
        return str_item;
    }

    // find end (skip trailing whitespace)
    size_t end = slen;
    while (end > 0 && is_ascii_whitespace((unsigned char)chars[end - 1])) {
        end--;
    }

    if (end == slen) {
        return str_item;  // no trailing whitespace
    }

    if (end == 0) {
        // Trimming can legitimately produce an empty string; only solid symbols collapse to null.
        if (str_type == LMD_TYPE_SYMBOL) return ItemNull;
        String* empty = heap_strcpy("", 0);
        return {.item = s2it(empty)};
    }

    if (str_type == LMD_TYPE_SYMBOL) {
        return {.item = y2it(heap_create_symbol(chars, end))};
    }

    String* result = (String *)heap_alloc(sizeof(String) + end + 1, LMD_TYPE_STRING);
    result->len = end;
    result->flags = 0;
    result->is_ascii = str_is_ascii(chars, end) ? 1 : 0;
    str_copy(result->chars, end + 1, chars, end);
    return {.item = s2it(result)};
}

// lower/upper (S17.7.2): Unicode full case mapping, locale-independent, as
// ECMAScript's toLowerCase/toUpperCase, shared with LambdaJS; they had mapped
// ASCII letters only. The text is mapped into a malloc'd buffer before the
// result is allocated, so a collection there cannot move the source mid-copy.
static Item text_case_map(Item str_item, bool to_upper) {
    GUARD_ERROR1(str_item);
    TypeId str_type = get_type_id(str_item);

    // null maps to null
    if (str_type == LMD_TYPE_NULL) return ItemNull;

    if (!is_text_type_id(str_type)) {
        log_debug("fn_%s: argument must be a string or symbol", to_upper ? "upper" : "lower");
        return ItemError;
    }

    const char* chars = str_item.get_chars();
    uint32_t len = str_item.get_len();
    if (!chars || len == 0) return str_item;

    // no special case reaches ASCII, so ASCII text maps byte by byte
    bool ascii = str_is_ascii(chars, len);
    if (ascii) {
        char first = to_upper ? 'a' : 'A';
        uint32_t i = 0;
        while (i < len && (chars[i] < first || chars[i] > first + 25)) i++;
        if (i == len) return str_item;  // nothing to map
    }

    StrBuf* mapped = strbuf_new_cap(len + 1);
    bool changed = true;
    if (ascii) {
        strbuf_append_str_n(mapped, chars, len);
        if (to_upper) str_to_upper(mapped->str, chars, len);
        else str_to_lower(mapped->str, chars, len);
    } else {
        changed = utf8_case_map(chars, len, to_upper, mapped);
    }
    if (!changed) {
        strbuf_free(mapped);
        return str_item;
    }
    Item result = str_type == LMD_TYPE_SYMBOL
        ? (Item){.item = y2it(heap_create_symbol(mapped->str, mapped->length))}
        : (Item){.item = s2it(heap_strcpy(mapped->str, (int64_t)mapped->length))};
    strbuf_free(mapped);
    return result;
}

// lower(str) - convert string to lowercase
Item fn_lower(Item str_item) {
    return text_case_map(str_item, false);
}

// upper(str) - convert string to uppercase
Item fn_upper(Item str_item) {
    return text_case_map(str_item, true);
}

// url_resolve(base, relative) - resolve a relative URL against a base URL
Item fn_url_resolve(Item base_item, Item relative_item) {
    GUARD_ERROR2(base_item, relative_item);
    TypeId base_type = get_type_id(base_item);
    TypeId rel_type = get_type_id(relative_item);

    if ((!is_text_type_id(base_type)) ||
        (!is_text_type_id(rel_type))) {
        log_debug("fn_url_resolve: arguments must be strings");
        return ItemError;
    }

    const char* base_chars = base_item.get_chars();
    const char* rel_chars = relative_item.get_chars();
    if (!base_chars || !rel_chars) {
        return ItemNull;
    }

    // parse the base URL
    Url* base_url = url_parse(base_chars);
    if (!base_url || !base_url->is_valid) {
        log_debug("fn_url_resolve: invalid base URL '%s'", base_chars);
        if (base_url) url_destroy(base_url);
        return ItemNull;
    }

    // resolve the relative URL against the base
    Url* resolved = url_resolve_relative(rel_chars, base_url);
    if (!resolved || !resolved->is_valid) {
        log_debug("fn_url_resolve: failed to resolve '%s' against '%s'", rel_chars, base_chars);
        if (resolved) url_destroy(resolved);
        url_destroy(base_url);
        return ItemNull;
    }

    // get the href string from the resolved URL
    const char* href = url_get_href(resolved);
    if (!href) {
        url_destroy(resolved);
        url_destroy(base_url);
        return ItemNull;
    }

    uint32_t len = (uint32_t)strlen(href);
    String* result = heap_strcpy(href, len);

    url_destroy(resolved);
    url_destroy(base_url);
    return {.item = s2it(result)};
}

bool text_item_is_ascii(Item item) {
    TypeId type = get_type_id(item);
    if (type == LMD_TYPE_STRING) {
        String* string = item.get_safe_string();
        return string && string->is_ascii;
    }
    if (type == LMD_TYPE_SYMBOL) {
        const char* chars = item.get_chars();
        uint32_t len = item.get_len();
        return len == 0 || (chars && str_is_ascii(chars, len));
    }
    return false;
}

static String* split_heap_string_slice(Rooted<Item>& rooted_source, size_t offset,
        size_t len, bool source_is_ascii) {
    String* part = (String*)heap_alloc(sizeof(String) + len + 1, LMD_TYPE_STRING);
    // The allocation can compact the source string, so reload its interior
    // character address from the exact root before examining or copying it.
    const char* chars = rooted_source.get().get_chars() + offset;
    part->len = (uint32_t)len;
    part->flags = 0;
    // A source's false bit is conservative, but its true bit proves every
    // substring ASCII. This avoids re-scanning each copied split segment.
    part->is_ascii = source_is_ascii ? 1 : 0;
    str_copy(part->chars, len + 1, chars, len);
    return part;
}

// T28-5 (N5): the literal scan shared by split(), replace() and find().
// Returns the index of the leftmost occurrence of `needle` starting at or
// after `from`, or SIZE_MAX. The case-sensitive scan is lib's `str_find`, the
// one candidate-scan kernel (memchr to the next first byte, a second-byte
// filter, memcmp only at candidates). The byte-at-a-time loops this replaced
// called `memcmp` at EVERY position, and paid it twice (the count pass, then
// the split/replace pass): a quarter of three_way_merge, and four fifths of
// revcomp, whose complement is a chain of replace() calls.
// A case-insensitive search goes to RE2 instead (S17.7.1), whose folding the
// pattern path shares. Leftmost-first like the loops it replaces; callers step
// past a match by `needle_len`, which keeps matches non-overlapping.
static size_t literal_find(const char* chars, size_t chars_len, size_t from,
        const char* needle, size_t needle_len) {
    if (!chars || !needle || needle_len == 0 || needle_len > chars_len) {
        return SIZE_MAX;
    }
    size_t last = chars_len - needle_len;   // last index a match may start at
    if (from > last) return SIZE_MAX;
    size_t at = str_find(chars + from, chars_len - from, needle, needle_len);
    return at == STR_NPOS ? SIZE_MAX : from + at;
}

// Non-overlapping match count: split()'s part count, replace()'s output size
// and find()'s window total. A one-byte needle goes to the SWAR byte counter,
// because a dense one ("A" in DNA) would pay a memchr call per match.
static int64_t count_literal_matches(const char* chars, size_t chars_len,
        const char* needle, size_t needle_len) {
    if (!chars || !needle || needle_len == 0 || needle_len > chars_len) return 0;
    if (needle_len == 1) {
        return (int64_t)str_count_byte(chars, chars_len, needle[0]);
    }
    int64_t count = 0;
    size_t pos = 0;
    for (;;) {
        size_t at = literal_find(chars, chars_len, pos, needle, needle_len);
        if (at == SIZE_MAX) return count;
        count++;
        pos = at + needle_len;
    }
}

static int64_t split_whitespace_part_count(const char* chars, size_t chars_len) {
    int64_t count = 0;
    size_t pos = 0;
    while (pos < chars_len) {
        while (pos < chars_len && (chars[pos] == ' ' || chars[pos] == '\t' ||
                chars[pos] == '\n' || chars[pos] == '\r' || chars[pos] == '\f' ||
                chars[pos] == '\v')) {
            pos++;
        }
        if (pos == chars_len) break;
        count++;
        while (pos < chars_len && chars[pos] != ' ' && chars[pos] != '\t' &&
                chars[pos] != '\n' && chars[pos] != '\r' && chars[pos] != '\f' &&
                chars[pos] != '\v') {
            pos++;
        }
    }
    return count;
}

static int64_t split_utf8_part_count(const char* chars, size_t chars_len) {
    int64_t count = 0;
    for (size_t pos = 0; pos < chars_len; count++) {
        int char_len = (int)str_utf8_char_len((unsigned char)chars[pos]);
        pos += char_len > 0 ? (size_t)char_len : 1;
    }
    return count;
}

static bool literal_type_pattern_item(Item type_item, Item* literal_item);
// runtime_pattern_from_type is declared in re2_wrapper.hpp (shared with io.grep)

// split(str, sep) - split string by separator; a constructor, so its result
// is an array of strings (S2.5.7)
static List* split_string_list(void) {
    List* result = list();
    if (!result) return NULL;
    LaneStorageDesc lane = {};
    if (lambda_type_lane_storage_desc(&TYPE_STRING, &lane)) {
        // Text split has a full inferred string[] result. Construct that
        // pointer carrier directly; an open incompatible mutation widens it,
        // while an explicit boundary may certify it (D3.3.3v3, D3.3.4).
        array_native_lane_configure((Array*)result, &lane);
    }
    return result;
}

static void split_adopt_string_lane(List* result) {
    if (!result || array_has_native_lane((Array*)result)) return;
    for (int64_t index = 0; index < result->length; index++) {
        if (get_type_id(result->items[index]) != LMD_TYPE_STRING) return;
    }
    LaneStorageDesc lane = {};
    if (!lambda_type_lane_storage_desc(&TYPE_STRING, &lane)) return;
    array_native_lane_configure((Array*)result, &lane);
    for (int64_t index = 0; index < result->length; index++) {
        Item value = result->items[index];
        if (!array_native_lane_store((Array*)result, index, value)) return;
    }
}

static void split_literal_string_into(Rooted<Item>& rooted_str,
        Rooted<Item>& rooted_sep, Rooted<List*>& rooted_result,
        uint32_t str_len, uint32_t sep_len, bool source_is_ascii) {
    const char* source_chars = rooted_str.get().get_chars();
    const char* separator_chars = rooted_sep.get().get_chars();
    int64_t part_count = count_literal_matches(source_chars, str_len,
        separator_chars, sep_len) + 1;
    (void)array_reserve_append_slots((Array*)rooted_result.get(), part_count);
    size_t start = 0;
    size_t p = 0;

    for (;;) {
        // Slice and append may collect, so retain indices and reload bytes.
        const char* str_chars = rooted_str.get().get_chars();
        const char* sep_chars = rooted_sep.get().get_chars();
        size_t at = literal_find(str_chars, str_len, p, sep_chars, sep_len);
        if (at == SIZE_MAX) break;
        String* part = split_heap_string_slice(rooted_str, start, at - start,
            source_is_ascii);
        array_push((Array*)rooted_result.get(), {.item = s2it(part)});
        p = at + sep_len;
        start = p;
    }

    String* part = split_heap_string_slice(rooted_str, start, str_len - start,
        source_is_ascii);
    array_push((Array*)rooted_result.get(), {.item = s2it(part)});
}

Item fn_split_literal_items(Item str_item, Item sep_item) {
    GUARD_ERROR2(str_item, sep_item);
    String* source = get_type_id(str_item) == LMD_TYPE_STRING ? it2s(str_item) : NULL;
    String* separator = get_type_id(sep_item) == LMD_TYPE_STRING ? it2s(sep_item) : NULL;
    if (!source || !separator || !source->is_ascii || !separator->is_ascii ||
            source->len == 0 || separator->len == 0) {
        log_error("split-literal-items: expected nonempty ASCII strings");
        return ItemError;
    }
    uint32_t str_len = source->len;
    uint32_t sep_len = separator->len;
    RootFrame roots(3);
    Rooted<Item> rooted_str(roots, str_item);
    Rooted<Item> rooted_sep(roots, sep_item);
    Rooted<List*> rooted_result(roots, list());
    if (!rooted_result.get()) return ItemError;
    split_literal_string_into(rooted_str, rooted_sep, rooted_result,
        str_len, sep_len, true);
    return {.array = rooted_result.get()};
}

Item fn_split(Item str_item, Item sep_item) {
    // every split operand participates in dispatch, so no error may fall through to null or whitespace handling
    GUARD_ERROR2(str_item, sep_item);
    TypeId str_type = get_type_id(str_item);
    TypeId sep_type = get_type_id(sep_item);

    Item literal_pattern = {.item = 0};
    if (literal_type_pattern_item(sep_item, &literal_pattern)) {
        sep_item = literal_pattern;
        sep_type = LMD_TYPE_STRING;
    }

    // typed array split: split(arr, n) → n equal parts along axis 0
    if (str_type == LMD_TYPE_ARRAY_NUM) {
        int64_t n = 0;
        if (!lambda_item_to_int64_exact(sep_item, &n)) {
            log_error("split: section count must be an integer-valued number");
            return ItemError;
        }
        return fn_array_split(str_item, n, 0);
    }

    // null string splits to empty list
    if (str_type == LMD_TYPE_NULL) return {.array = split_string_list()};

    // null separator means split on whitespace (Python convention)
    bool null_sep = (sep_type == LMD_TYPE_NULL);

    // pattern-based split: split(str, pattern)
    if (sep_type == LMD_TYPE_TYPE) {
        Type* type = (Type*)(sep_item.item & 0x00FFFFFFFFFFFFFF);
        TypePattern* pattern = runtime_pattern_from_type(type);
        if (pattern) {
            if (pattern->is_symbol) {
                log_error("fn_split: symbol-domain patterns cannot search strings");
                return ItemError;
            }
            if (!is_text_type_id(str_type)) {
                log_debug("fn_split: first argument must be a string for pattern split");
                return ItemError;
            }
            List* ps = pattern_split(pattern, str_item, false);
            if (ps) split_adopt_string_lane(ps);
            return {.array = ps};
        }
    }

    if ((!is_text_type_id(str_type)) ||
        (!null_sep && !is_text_type_id(sep_type))) {
        log_debug("fn_split: arguments must be strings or symbols");
        return ItemError;
    }

    RootFrame roots(3);
    Rooted<Item> rooted_str(roots, str_item);
    Rooted<Item> rooted_sep(roots, sep_item);
    Rooted<List*> rooted_result(roots, (List*)NULL);

    uint32_t str_len = str_item.get_len();
    uint32_t sep_len = null_sep ? 0 : sep_item.get_len();

    // Segments are separate elements, so every append below uses array_push,
    // which stores the item verbatim (D2.6.5). list_push would concatenate each
    // string onto the previous one under S16.7's content rules.
    List* result = split_string_list();
    rooted_result.set(result);
    bool source_is_ascii = text_item_is_ascii(rooted_str.get());

    if (!rooted_str.get().get_chars() || str_len == 0) {
        // S17.1.1 (ECMAScript rule): an empty subject yields [] when the
        // delimiter matches the empty string — the empty separator, and the
        // Python-shaped whitespace form which has no JS analogue — and [""]
        // otherwise, matching "".split(",") === [""].
        if (!null_sep && sep_len != 0) {
            (void)array_reserve_append_slots((Array*)rooted_result.get(), 1);
            String* only = split_heap_string_slice(rooted_str, 0, 0, source_is_ascii);
            array_push((Array*)rooted_result.get(), {.item = s2it(only)});
        }
        return {.array = rooted_result.get()};
    }

    if (null_sep) {
        // null separator: split on whitespace (like Python str.split(None))
        // strips leading/trailing whitespace, splits on runs of whitespace
        const char* source_chars = rooted_str.get().get_chars();
        int64_t part_count = split_whitespace_part_count(source_chars, str_len);
        (void)array_reserve_append_slots((Array*)rooted_result.get(), part_count);
        size_t p = 0;
        while (p < str_len) {
            const char* str_chars = rooted_str.get().get_chars();
            // skip whitespace
            while (p < str_len && (str_chars[p] == ' ' || str_chars[p] == '\t' || str_chars[p] == '\n' ||
                    str_chars[p] == '\r' || str_chars[p] == '\f' || str_chars[p] == '\v')) {
                p++;
            }
            if (p >= str_len) break;
            // find end of word
            size_t word_start = p;
            while (p < str_len && str_chars[p] != ' ' && str_chars[p] != '\t' && str_chars[p] != '\n' &&
                    str_chars[p] != '\r' && str_chars[p] != '\f' && str_chars[p] != '\v') {
                p++;
            }
            String* part = split_heap_string_slice(rooted_str, word_start, p - word_start,
                source_is_ascii);
            array_push((Array*)rooted_result.get(), {.item = s2it(part)});
        }
        return {.array = rooted_result.get()};
    }

    if (!rooted_sep.get().get_chars() || sep_len == 0) {
        // empty string separator: split into individual characters
        const char* source_chars = rooted_str.get().get_chars();
        int64_t part_count = split_utf8_part_count(source_chars, str_len);
        (void)array_reserve_append_slots((Array*)rooted_result.get(), part_count);
        size_t p = 0;
        while (p < str_len) {
            const char* str_chars = rooted_str.get().get_chars();
            int char_len = (int)str_utf8_char_len((unsigned char)str_chars[p]);
            if (char_len <= 0) char_len = 1;  // fallback for invalid UTF-8
            String* part = split_heap_string_slice(rooted_str, p, (size_t)char_len,
                source_is_ascii);
            array_push((Array*)rooted_result.get(), {.item = s2it(part)});
            p += char_len;
        }
        return {.array = rooted_result.get()};
    }

    // Both Lambda's inferred lane and JS's tagged lane use one literal scan.
    split_literal_string_into(rooted_str, rooted_sep, rooted_result, str_len,
        sep_len, source_is_ascii);

    return {.array = rooted_result.get()};
}

// split(str, sep, keep_delim) - 3-arg version with keep_delim boolean
// split(arr, n, axis) - typed array split into n equal parts along axis
Item fn_split3(Item str_item, Item sep_item, Item keep_item) {
    GUARD_ERROR3(str_item, sep_item, keep_item);
    TypeId str_type = get_type_id(str_item);
    TypeId sep_type = get_type_id(sep_item);
    TypeId keep_type = get_type_id(keep_item);

    Item literal_pattern = {.item = 0};
    if (literal_type_pattern_item(sep_item, &literal_pattern)) {
        sep_item = literal_pattern;
        sep_type = LMD_TYPE_STRING;
    }

    // typed array split with explicit axis: split(arr, n, axis)
    if (str_type == LMD_TYPE_ARRAY_NUM) {
        int64_t n = 0, axis = 0;
        if (!lambda_item_to_int64_exact(sep_item, &n) ||
                !lambda_item_to_int64_exact(keep_item, &axis)) {
            log_error("split: section count and axis must be integer-valued numbers");
            return ItemError;
        }
        return fn_array_split(str_item, n, axis);
    }

    bool keep_delim = (keep_type == LMD_TYPE_BOOL && it2b(keep_item));

    // null string splits to empty list
    if (str_type == LMD_TYPE_NULL) return {.array = split_string_list()};

    // pattern-based split with keep_delim
    if (sep_type == LMD_TYPE_TYPE) {
        Type* type = (Type*)(sep_item.item & 0x00FFFFFFFFFFFFFF);
        TypePattern* pattern = runtime_pattern_from_type(type);
        if (pattern) {
            if (pattern->is_symbol) {
                log_error("fn_split3: symbol-domain patterns cannot search strings");
                return ItemError;
            }
            if (!is_text_type_id(str_type)) {
                log_debug("fn_split3: first argument must be a string for pattern split");
                return ItemError;
            }
            List* ps = pattern_split(pattern, str_item, keep_delim);
            if (ps) split_adopt_string_lane(ps);
            return {.array = ps};
        }
    }

    // string-based split with keep_delim
    if (!keep_delim) {
        // no keep_delim, delegate to 2-arg version
        return fn_split(str_item, sep_item);
    }

    // keep_delim string split
    if ((!is_text_type_id(str_type)) ||
        (!is_text_type_id(sep_type))) {
        log_debug("fn_split3: arguments must be strings or symbols");
        return ItemError;
    }

    uint32_t str_len = str_item.get_len();
    uint32_t sep_len = sep_item.get_len();

    RootFrame roots(3);
    Rooted<Item> rooted_str(roots, str_item);
    Rooted<Item> rooted_sep(roots, sep_item);
    Rooted<List*> rooted_result(roots, (List*)NULL);


    List* result = split_string_list();
    rooted_result.set(result);
    if (!rooted_str.get().get_chars() || str_len == 0 || !rooted_sep.get().get_chars() || sep_len == 0) {
        return {.array = rooted_result.get()};
    }

    bool source_is_ascii = text_item_is_ascii(rooted_str.get());
    bool separator_is_ascii = text_item_is_ascii(rooted_sep.get());
    int64_t match_count = count_literal_matches(rooted_str.get().get_chars(), str_len,
        rooted_sep.get().get_chars(), sep_len);
    (void)array_reserve_append_slots((Array*)rooted_result.get(),
        match_count * 2 + 1);
    size_t start = 0;
    size_t p = 0;

    for (;;) {
        // re-read after every allocating round, as in fn_split
        const char* str_chars = rooted_str.get().get_chars();
        const char* sep_chars = rooted_sep.get().get_chars();
        size_t at = literal_find(str_chars, str_len, p, sep_chars, sep_len);
        if (at == SIZE_MAX) break;
        // push part before separator
        String* part = split_heap_string_slice(rooted_str, start, at - start,
            source_is_ascii);
        array_push((Array*)rooted_result.get(), {.item = s2it(part)});

        // push the delimiter
        String* delim = split_heap_string_slice(rooted_sep, 0, sep_len,
            separator_is_ascii);
        array_push((Array*)rooted_result.get(), {.item = s2it(delim)});

        p = at + sep_len;
        start = p;
    }

    // add the last part
    String* part = split_heap_string_slice(rooted_str, start, str_len - start,
        source_is_ascii);
    array_push((Array*)rooted_result.get(), {.item = s2it(part)});

    return {.array = rooted_result.get()};
}

// ord raw helper — -1 is retained only for C/JS adapters.
// The public Lambda wrapper below converts absence to null.
int64_t fn_ord_str(String* str) {
    // 0 is U+0000, a real character, so it cannot stand for "no answer".
    if (!str || str->len == 0) return -1;
    uint32_t codepoint = 0;
    int decoded = str_utf8_decode(str->chars, str->len, &codepoint);
    if (decoded <= 0) return -1;
    return (int64_t)codepoint;
}

int64_t fn_ord_raw(Item str_item) {
    TypeId type = get_type_id(str_item);

    // Code points are non-negative, so the raw -1 sentinel cannot collide with
    // a real answer. The Lambda wrapper normalizes it to the uniform null value.
    if (!is_text_type_id(type)) {
        log_debug("fn_ord: argument must be a string or symbol, got type %d", type);
        return -1;
    }

    const char* chars = str_item.get_chars();
    uint32_t byte_len = str_item.get_len();

    // an empty string has no first character, so it has no ordinal
    if (!chars || byte_len == 0) {
        return -1;
    }

    uint32_t codepoint = 0;
    int decoded = str_utf8_decode(chars, byte_len, &codepoint);
    if (decoded <= 0) {
        return -1; // invalid UTF-8
    }
    return (int64_t)codepoint;
}

Item fn_ord(Item str_item) {
    GUARD_ERROR1(str_item);
    return fn_nullable_int_result(fn_ord_raw(str_item));
}

Item fn_ord_str_item(String* str) {
    return fn_nullable_int_result(fn_ord_str(str));
}

// chr(int) - return 1-char string from Unicode code point
Item fn_chr(Item cp_item) {
    GUARD_ERROR1(cp_item);
    TypeId type = get_type_id(cp_item);

    // return empty string for null/invalid input
    if (type == LMD_TYPE_NULL) {
        String* empty = heap_strcpy("", 0);
        return {.item = s2it(empty)};
    }

    int64_t codepoint = 0;
    if (!lambda_item_to_int64_exact(cp_item, &codepoint) ||
            codepoint < 0 || codepoint > 0x10FFFF) {
        log_debug("fn_chr: code point %lld out of range (0..0x10FFFF)", (long long)codepoint);
        String* empty = heap_strcpy("", 0);
        return {.item = s2it(empty)};
    }

    char buf[4];
    size_t len = str_utf8_encode((uint32_t)codepoint, buf, sizeof(buf));
    if (len == 0) {
        String* empty = heap_strcpy("", 0);
        return {.item = s2it(empty)};  // invalid code point (e.g., surrogate)
    }

    String* result = heap_strcpy(buf, len);
    return {.item = s2it(result)};
}

// Expose only Unicode metadata; terminal width accumulation stays in Lambda.
Item fn_io_cell_width(Item cp_item) {
    GUARD_ERROR1(cp_item);
    int64_t cp = 0;
    if (!lambda_item_to_int64_exact(cp_item, &cp) || cp < 0 || cp > 0x10FFFF ||
            (cp >= 0xD800 && cp <= 0xDFFF)) return ItemNull;
    return {.item = i2it(utf8proc_charwidth((utf8proc_int32_t)cp))};
}

Item fn_io_unicode_category(Item cp_item) {
    GUARD_ERROR1(cp_item);
    int64_t cp = 0;
    if (!lambda_item_to_int64_exact(cp_item, &cp) || cp < 0 || cp > 0x10FFFF ||
            (cp >= 0xD800 && cp <= 0xDFFF)) return ItemNull;
    const char* category = utf8proc_category_string((utf8proc_int32_t)cp);
    return {.item = s2it(heap_strcpy(category, strlen(category)))};
}

// join(strs, sep) - join list of strings with separator
Item fn_join2(Item list_item, Item sep_item) {
    GUARD_ERROR2(list_item, sep_item);
    TypeId list_type = get_type_id(list_item);
    TypeId sep_type = get_type_id(sep_item);

    // null list joins to null
    if (list_type == LMD_TYPE_NULL) return ItemNull;

    if (list_type != LMD_TYPE_ARRAY && list_type != LMD_TYPE_ARRAY) {
        log_debug("fn_join2: first argument must be a list or array");
        return ItemError;
    }

    // allow null/empty separator - treat as empty string
    const char* sep_chars = nullptr;
    size_t sep_len = 0;

    if (is_text_type_id(sep_type)) {
        sep_chars = sep_item.get_chars();
        sep_len = sep_chars ? sep_item.get_len() : 0;
    } else if (sep_type != LMD_TYPE_NULL) {
        log_debug("fn_join2: separator must be a string, symbol, or null");
        return ItemError;
    }

    RootFrame roots(2);
    if (!roots.valid()) return ItemError;
    Rooted<Item> rooted_list(roots, list_item);
    Rooted<Item> rooted_sep(roots, sep_item);

    // calculate total length and carry the conservative ASCII proof through
    // the existing pass so joined ASCII strings retain O(1) indexing.
    size_t total_len = 0;
    List* source = list_item.array;
    int64_t count = source->length;
    bool is_ascii = sep_type == LMD_TYPE_NULL || text_item_is_ascii(sep_item);
    for (int64_t i = 0; i < count; i++) {
        // A native-lane source stores raw payloads in `items[]`, so read it
        // through the lane accessor -- `split()` produces such a list (D2.6.5).
        Item item = array_item_read((Array*)source, i);
        TypeId item_type = get_type_id(item);
        if (is_text_type_id(item_type)) {
            if (!lam::checked_add(total_len, item.get_len(), &total_len)) return ItemError;
            is_ascii = is_ascii && text_item_is_ascii(item);
        }
    }

    if (count > 1 && sep_len > 0) {
        if (!lam::checked_mul_add((size_t)(count - 1), sep_len, total_len, &total_len)) return ItemError;
    }

    // the heap allocator takes a signed byte count; reject overflow before narrowing.
    if (total_len > (size_t)INT_MAX - sizeof(String) - 1) return ItemError;
    String* result = (String *)heap_alloc(sizeof(String) + total_len + 1, LMD_TYPE_STRING);
    if (!result) return ItemError;
    // Result allocation may compact container storage and can reclaim the
    // separator unless both semantic inputs remain exact-rooted.
    list_item = rooted_list.get();
    sep_item = rooted_sep.get();
    sep_chars = is_text_type_id(sep_type) ? sep_item.get_chars() : nullptr;
    result->len = total_len;
    result->flags = 0;
    result->is_ascii = is_ascii ? 1 : 0;

    // build result
    char* p = result->chars;

    source = list_item.array;
    for (int64_t i = 0; i < count; i++) {
        if (i > 0 && sep_len > 0) {
            memcpy(p, sep_chars, sep_len);
            p += sep_len;
        }
        // A native-lane source stores raw payloads in `items[]`, so read it
        // through the lane accessor -- `split()` produces such a list (D2.6.5).
        Item item = array_item_read((Array*)source, i);
        TypeId item_type = get_type_id(item);
        if (is_text_type_id(item_type)) {
            const char* item_chars = item.get_chars();
            uint32_t item_len = item.get_len();
            if (item_chars && item_len > 0) {
                memcpy(p, item_chars, item_len);
                p += item_len;
            }
        }
    }

    result->chars[total_len] = '\0';
    return {.item = s2it(result)};
}

typedef struct FindReplaceOptions {
    int64_t limit;
    int64_t last;
    bool has_limit;
    bool has_last;
    bool ignore_case;
} FindReplaceOptions;

static bool parse_find_replace_options(Item options_item, FindReplaceOptions* options) {
    options->limit = 0;
    options->last = 0;
    options->has_limit = false;
    options->has_last = false;
    options->ignore_case = false;
    TypeId options_type = get_type_id(options_item);
    if (options_type == LMD_TYPE_NULL) return true;
    if (options_type != LMD_TYPE_MAP) {
        log_debug("parse_find_replace_options: options must be a map");
        return false;
    }

    // D2.6.6: an object cannot be viewed as a Map* — its shape and buffer sit
    // at Element's offsets — so the attribute face is reached by kind.
    TypeMap* options_shape = lambda_attr_shape(options_type, options_item.map);
    void* options_data = lambda_attr_data(options_type, options_item.map);
    // an empty map has no shape or buffer, and sets no option; it was
    // rejected, so `replace(s, "a", "-", {})` returned an error
    if (!options_shape || !options_data) return true;
    bool is_found = false;
    Item limit_item = _map_get(options_shape, options_data, "limit", &is_found);
    if (is_found && get_type_id(limit_item) != LMD_TYPE_NULL) {
        int64_t limit = 0;
        if (!lambda_item_to_int64_exact(limit_item, &limit)) {
            log_debug("parse_find_replace_options: limit must be an integer");
            return false;
        }
        if (limit < 0) {
            log_debug("parse_find_replace_options: limit must be non-negative");
            return false;
        }
        options->limit = limit;
        options->has_limit = true;
    }

    is_found = false;
    Item last_item = _map_get(options_shape, options_data, "last", &is_found);
    if (is_found && get_type_id(last_item) != LMD_TYPE_NULL) {
        int64_t last = 0;
        if (!lambda_item_to_int64_exact(last_item, &last)) {
            log_debug("parse_find_replace_options: last must be an integer");
            return false;
        }
        if (last < 0) {
            log_debug("parse_find_replace_options: last must be non-negative");
            return false;
        }
        options->last = last;
        options->has_last = true;
    }
    if (options->has_limit && options->has_last) {
        log_debug("parse_find_replace_options: limit and last cannot be used together");
        return false;
    }

    is_found = false;
    Item ignore_item = _map_get(options_shape, options_data, "ignore_case", &is_found);
    if (is_found && get_type_id(ignore_item) != LMD_TYPE_NULL) {
        if (get_type_id(ignore_item) != LMD_TYPE_BOOL) {
            log_debug("parse_find_replace_options: ignore_case must be bool");
            return false;
        }
        options->ignore_case = it2b(ignore_item);
    }
    return true;
}

static int64_t options_legacy_pattern_limit(FindReplaceOptions options) {
    if (options.has_last) return options.last == 0 ? 0 : -options.last;
    if (options.has_limit) return options.limit;
    return 0;
}

static void select_match_window(int64_t total, FindReplaceOptions options, int64_t* first, int64_t* count) {
    *first = 0;
    if (total <= 0) {
        *count = 0;
        return;
    }
    if (options.has_last) {
        if (options.last <= 0) {
            *count = 0;
            return;
        }
        int64_t requested = options.last;
        if (requested < total) {
            *first = total - requested;
            *count = requested;
        } else {
            *count = total;
        }
    } else if (options.has_limit) {
        *count = options.limit < total ? options.limit : total;
    } else {
        *count = total;
    }
}

static bool item_string_is_ascii(Item item, TypeId item_type) {
    if (item_type == LMD_TYPE_NULL || item_type == LMD_TYPE_SYMBOL) return true;
    if (item_type != LMD_TYPE_STRING) return false;
    String* str = item.get_safe_string();
    return str && str->is_ascii != 0;
}

static bool literal_type_pattern_item(Item type_item, Item* literal_item) {
    if (!literal_item || get_type_id(type_item) != LMD_TYPE_TYPE) return false;
    Type* type = type_item.type;
    if (!type) return false;
    // TypePattern shares the TYPE tag but has no TypeType payload; only the
    // simple wrapper layout may be unwrapped before inspecting a literal.
    if (type->type_id == LMD_TYPE_TYPE && type->kind == TYPE_KIND_SIMPLE) {
        type = ((TypeType*)type)->type;
    }
    if (!type || !type->is_literal || type->type_id != LMD_TYPE_STRING) return false;
    String* literal = ((TypeString*)type)->string;
    if (!literal) return false;
    *literal_item = (Item){.item = s2it(literal)};
    return true;
}

TypePattern* runtime_pattern_from_type(Type* type) {
    if (!type) return nullptr;
    if (type->kind == TYPE_KIND_PATTERN) return (TypePattern*)type;
    const char* error_msg = nullptr;
    return compile_literal_type_pattern(context ? context->pool : nullptr,
        type, false, &error_msg);
}

// replace() of one byte by one byte at every match: a branch-free select over
// the whole source, which the compiler vectorizes (NEON/SSE2), instead of a
// search per match -- DNA complement chains match every third or fourth byte.
static void translate_byte(char* __restrict dest, const char* __restrict src,
        size_t len, char from, char to) {
    for (size_t i = 0; i < len; i++) dest[i] = src[i] == from ? to : src[i];
}

static Item fn_replace_impl(Item str_item, Item old_item, Item new_item, FindReplaceOptions options) {
    TypeId str_type = get_type_id(str_item);
    TypeId old_type = get_type_id(old_item);
    TypeId new_type = get_type_id(new_item);

    // null string has nothing to replace
    if (str_type == LMD_TYPE_NULL) return ItemNull;
    // null search pattern means nothing to find — return string unchanged
    if (old_type == LMD_TYPE_NULL) return str_item;
    // null replacement — treat as empty string (delete matches)
    // note: transpiler converts "" to ITEM_NULL, so we must handle this without calling get_chars on null
    bool new_is_null = (new_type == LMD_TYPE_NULL);
    if (new_is_null) new_type = LMD_TYPE_STRING;

    // Literal-only type aliases remain exact string needles for the search APIs.
    Item literal_pattern = {.item = 0};
    if (literal_type_pattern_item(old_item, &literal_pattern)) {
        old_item = literal_pattern;
        old_type = LMD_TYPE_STRING;
    }

    // pattern-based replacement: replace(str, pattern, repl_str[, options])
    if (old_type == LMD_TYPE_TYPE) {
        Type* type = (Type*)(old_item.item & 0x00FFFFFFFFFFFFFF);
        TypePattern* pattern = runtime_pattern_from_type(type);
        if (pattern) {
            if (pattern->is_symbol) {
                log_error("fn_replace: symbol-domain patterns cannot search strings");
                return ItemError;
            }
            if (!is_text_type_id(str_type)) {
                log_debug("fn_replace: first argument must be a string for pattern replace");
                return ItemError;
            }
            if (!is_text_type_id(new_type)) {
                log_debug("fn_replace: third argument must be a string for pattern replace");
                return ItemError;
            }
            // an empty subject still holds an empty match, which a pattern
            // like \(d*) replaces (S17.6.1): "" becomes "-", as in JS
            const char* str_chars = str_item.get_chars();
            uint32_t str_len = str_item.get_len();
            if (!str_chars) { str_chars = ""; str_len = 0; }
            const char* repl_chars = new_is_null ? "" : new_item.get_chars();
            uint32_t repl_len = new_is_null ? 0 : new_item.get_len();

            if ((options.has_limit && options.limit == 0) ||
                (options.has_last && options.last == 0)) return str_item;
            int64_t pattern_limit = options_legacy_pattern_limit(options);
            // S17.6.1: one semantics with or without options. Matches step as
            // ECMAScript replaceAll steps them, empty ones included, and the
            // replacement is literal text. The plain call used RE2's
            // GlobalReplace, which skipped an empty match after a non-empty one
            // and rewrote `\0`..`\9` in the replacement.
            String* result = pattern_replace_all_options(pattern, str_chars, str_len,
                repl_chars ? repl_chars : "", repl_chars ? repl_len : 0,
                pattern_limit, options.ignore_case);
            if (!result) return str_item;
            return {.item = s2it(result)};
        }
    }

    if ((!is_text_type_id(str_type)) ||
        (!is_text_type_id(old_type)) ||
        (!is_text_type_id(new_type))) {
        log_debug("fn_replace: all arguments must be strings or symbols");
        return ItemError;
    }

    const char* str_chars = str_item.get_chars();
    uint32_t str_len = str_item.get_len();
    const char* old_chars = old_item.get_chars();
    uint32_t old_len = old_item.get_len();
    const char* new_chars = new_is_null ? "" : new_item.get_chars();
    uint32_t new_len_val = new_is_null ? 0 : new_item.get_len();

    if (!str_chars || str_len == 0) return str_item;
    if (!old_chars || old_len == 0) return str_item;  // nothing to replace

    // S17.7.1: case-insensitive literal text folds as a pattern does, in RE2
    if (options.ignore_case) {
        if ((options.has_limit && options.limit == 0) ||
            (options.has_last && options.last == 0)) return str_item;
        String* replaced = literal_replace_all_ignore_case(str_chars, str_len, old_chars,
            old_len, new_chars ? new_chars : "", new_chars ? new_len_val : 0,
            options_legacy_pattern_limit(options));
        if (!replaced) return str_item;
        if (str_type != LMD_TYPE_SYMBOL) return {.item = s2it(replaced)};
        // copy the bytes out first: allocating the symbol may collect `replaced`
        StrBuf* bytes = strbuf_new_cap(replaced->len + 1);
        strbuf_append_str_n(bytes, replaced->chars, replaced->len);
        Symbol* symbol = heap_create_symbol(bytes->str, bytes->length);
        strbuf_free(bytes);
        return {.item = y2it(symbol)};
    }

    int64_t total = count_literal_matches(str_chars, str_len, old_chars, old_len);
    int64_t first = 0, replace_count = 0;
    // Limit is applied before replacement so first/last-N semantics match find().
    select_match_window(total, options, &first, &replace_count);
    if (replace_count == 0) return str_item;

    size_t replacement_len = new_chars ? new_len_val : 0;
    size_t new_len = str_len + (size_t)replace_count * (replacement_len - old_len);

    char* dest = NULL;
    String* result = NULL;
    char* symbol_buf = NULL;
    if (str_type == LMD_TYPE_SYMBOL) {
        symbol_buf = (char*)pool_alloc(context->pool, new_len + 1);
        dest = symbol_buf;
    } else {
        result = (String *)heap_alloc(sizeof(String) + new_len + 1, LMD_TYPE_STRING);
        result->len = new_len;
        // Preserve is_ascii when both source and replacement are ASCII; otherwise byte-indexing callers may fall back to UTF-8 scans.
        bool src_ascii = item_string_is_ascii(str_item, str_type);
        bool repl_ascii = new_is_null || item_string_is_ascii(new_item, new_type);
        result->flags = 0;
        result->is_ascii = (src_ascii && repl_ascii) ? 1 : 0;
        dest = result->chars;
    }

    if (old_len == 1 && replacement_len == 1 && replace_count == total) {
        translate_byte(dest, str_chars, str_len, old_chars[0], new_chars[0]);
        dest += str_len;
    } else {
        // Copy the span before each selected match, then its replacement;
        // matches outside the window stay inside the copied spans.
        size_t copied = 0;
        size_t pos = 0;
        int64_t ordinal = 0;
        int64_t replaced = 0;
        while (replaced < replace_count) {
            size_t at = literal_find(str_chars, str_len, pos, old_chars, old_len);
            if (at == SIZE_MAX) break;
            if (ordinal >= first) {
                memcpy(dest, str_chars + copied, at - copied);
                dest += at - copied;
                if (replacement_len > 0) {
                    memcpy(dest, new_chars, replacement_len);
                    dest += replacement_len;
                }
                copied = at + old_len;
                replaced++;
            }
            ordinal++;
            pos = at + old_len;
        }
        memcpy(dest, str_chars + copied, str_len - copied);
        dest += str_len - copied;
    }
    *dest = '\0';

    if (str_type == LMD_TYPE_SYMBOL) return {.item = y2it(heap_create_symbol(symbol_buf, new_len))};
    return {.item = s2it(result)};
}

// replace(str, old, new) - replace all occurrences of old with new
Item fn_replace(Item str_item, Item old_item, Item new_item) {
    GUARD_ERROR3(str_item, old_item, new_item);
    FindReplaceOptions options = {0, 0, false, false, false};
    return fn_replace_impl(str_item, old_item, new_item, options);
}

Item fn_replace3(Item str_item, Item old_item, Item new_item) {
