        "string_append_calls", "string_append_pieces", "string_inplace_appends",
        "string_growth_copies", "string_copied_bytes", "string_freezes",
        "string_generic_joins"
    };
    for (int i = 0; i < STRING_BUILDER_COUNTER_COUNT; i++) {
        strbuf_append_all(output, 2, "\n", string_counters[i]);
        strbuf_append_char(output, '\t');
        strbuf_append_uint64(output, g_cow_profile.string_builder[i]);
    }
    strbuf_append_char(output, '\n');
    if (write_text_file_atomic(output_path, output->str ? output->str : "") != 0) {
        log_error("cow profile: failed to write '%s'", output_path);
    }
    strbuf_free(output);

    if (!g_cow_profile_sites_enabled) return;
    const char* sites_path = getenv("COW_EXEC_PROFILE_SITES_OUT");
    if (!sites_path || !sites_path[0]) sites_path = "temp/cow_exec_sites.tsv";
    StrBuf* sites = strbuf_new();
    if (!sites) return;
    strbuf_append_str(sites, "event\ttype\tcaller_pc\tcount\tbytes\tnative_symbol\tsymbol_offset\n");
    uint64_t site_counts[LMD_TYPE_COUNT][3] = {};
    uint64_t site_bytes[LMD_TYPE_COUNT][3] = {};
    for (size_t index = 0; index < 16384; index++) {
        CowProfileSiteCounters* site = &g_cow_profile_sites[index];
        if (__atomic_load_n(&site->state, __ATOMIC_ACQUIRE) != 2 ||
                !site->count) continue;
        const char* event = site->event == COW_SITE_SHARE_MARK ? "share_mark" :
            site->event == COW_SITE_UNIQUE_WRITE ? "unique_write" : "shared_copy";
        const char* symbol = "";
        uintptr_t symbol_offset = 0;
#if !defined(_WIN32)
        Dl_info info = {};
        if (site->caller && dladdr((void*)site->caller, &info) && info.dli_sname) {
            symbol = info.dli_sname;
            symbol_offset = site->caller - (uintptr_t)info.dli_saddr;
        }
#endif
        strbuf_append_format(sites, "%s\t%s\t0x%llx\t%llu\t%llu\t%s\t0x%llx\n",
            event, get_type_name(site->type_id),
            (unsigned long long)site->caller,
            (unsigned long long)site->count,
            (unsigned long long)site->bytes, symbol,
            (unsigned long long)symbol_offset);
        if (site->type_id < LMD_TYPE_COUNT) {
            site_counts[site->type_id][site->event] += site->count;
            site_bytes[site->type_id][site->event] += site->bytes;
        }
    }
    // Runtime-only calls have no MIR return PC. Keep their aggregate as a
    // visible fallback so the site census never silently drops COW work.
    for (int type = 0; type < LMD_TYPE_COUNT; type++) {
        const CowProfileTypeCounters* counters = &g_cow_profile.by_type[type];
        const uint64_t totals[] = {counters->share_marks,
            counters->unique_mutations, counters->shared_copies};
        const char* events[] = {"share_mark", "unique_write", "shared_copy"};
        for (int event = 0; event < 3; event++) {
            uint64_t total_bytes = event == COW_SITE_SHARED_COPY
                ? counters->copied_bytes : 0;
            if (totals[event] < site_counts[type][event] ||
                    total_bytes < site_bytes[type][event]) {
                log_error("cow profile sites: site totals exceed aggregate for type %d event %d",
                    type, event);
                continue;
            }
            uint64_t missing = totals[event] - site_counts[type][event];
            uint64_t missing_bytes = total_bytes - site_bytes[type][event];
            if (missing || missing_bytes) {
                strbuf_append_format(sites, "%s\t%s\t0x0\t%llu\t%llu\t\t0x0\n",
                    events[event], get_type_name((TypeId)type),
                    (unsigned long long)missing,
                    (unsigned long long)missing_bytes);
            }
        }
    }
    strbuf_append_format(sites, "overflow\t-\t-\t%llu\t0\t\t\n",
        (unsigned long long)g_cow_profile_site_overflow);
    if (write_text_file_atomic(sites_path, sites->str ? sites->str : "") != 0) {
        log_error("cow profile sites: failed to write '%s'", sites_path);
    }
    strbuf_free(sites);
#endif
}

typedef struct LambdaExecCallRow {
    uint8_t state;
    uint8_t kind;
    const char* name;
    uint64_t count;
} LambdaExecCallRow;

// Compilation registers names once; diagnostic MIR increments only its fixed
// row. No lookup, lock, or counter instruction exists in ordinary MIR
// (D5.4.4). A saturated table has an explicit overflow row in the report.
static LambdaExecCallRow g_lambda_exec_calls[8192] = {};
static uint64_t g_lambda_exec_call_overflow = 0;
static int g_lambda_exec_profile_enabled = -1;

static void lambda_exec_profile_dump(void) {
#ifndef LAMBDA_NO_CONSOLE_DUMP
    const char* path = getenv("LAMBDA_EXEC_PROFILE_OUT");
    if (!path || !path[0]) path = "temp/lambda_exec_profile.tsv";
    StrBuf* output = strbuf_new();
    if (!output) return;
    strbuf_append_str(output, "kind\tname\tcount\n");
    static const char* kinds[] = {"unknown", "helper", "raw", "boxed",
        "indirect", "unknown", "root_store", "root_reload", "frame_entry",
        "dense_attempt", "dense_fast", "field_attempt", "field_fast",
        "layout_items_reload", "layout_length_reload"};
    for (size_t i = 0; i < 8192; i++) {
        LambdaExecCallRow* row = &g_lambda_exec_calls[i];
        if (__atomic_load_n(&row->state, __ATOMIC_ACQUIRE) != 2) continue;
        uint64_t count = __atomic_load_n(&row->count, __ATOMIC_RELAXED);
        if (!count) continue;
        const char* kind = row->kind <= LAMBDA_EXEC_LAYOUT_LENGTH_RELOAD
            ? kinds[row->kind] : kinds[0];
        strbuf_append_format(output, "%s\t%s\t%llu\n", kind,
            row->name ? row->name : "<unnamed>",
            (unsigned long long)count);
    }
    strbuf_append_format(output, "overflow\t-\t%llu\n",
        (unsigned long long)__atomic_load_n(&g_lambda_exec_call_overflow,
            __ATOMIC_RELAXED));
    if (write_text_file_atomic(path, output->str ? output->str : "") != 0) {
        log_error("lambda-exec-profile: failed to write '%s'", path);
    }
    strbuf_free(output);
    for (size_t i = 0; i < 8192; i++) {
        if (__atomic_load_n(&g_lambda_exec_calls[i].state,
                __ATOMIC_ACQUIRE) == 2) free((void*)g_lambda_exec_calls[i].name);
    }
#endif
}

extern "C" bool lambda_exec_profile_enabled(void) {
#ifdef LAMBDA_NO_FILE_IO
    return false;
#else
    int state = __atomic_load_n(&g_lambda_exec_profile_enabled,
        __ATOMIC_ACQUIRE);
    if (state >= 0) return state != 0;
    int uninitialized = -1;
    if (__atomic_compare_exchange_n(&g_lambda_exec_profile_enabled,
            &uninitialized, -2, false, __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
        bool enabled = cow_profile_truthy(getenv("LAMBDA_EXEC_PROFILE"));
        if (enabled) atexit(lambda_exec_profile_dump);
        __atomic_store_n(&g_lambda_exec_profile_enabled, enabled ? 1 : 0,
            __ATOMIC_RELEASE);
        return enabled;
    }
    do {
        state = __atomic_load_n(&g_lambda_exec_profile_enabled,
            __ATOMIC_ACQUIRE);
    } while (state == -2);
    return state != 0;
#endif
}

extern "C" uint64_t lambda_exec_profile_register_call(const char* name,
        uint64_t kind) {
    if (!lambda_exec_profile_enabled() || !name || !name[0] ||
            kind < LAMBDA_EXEC_CALL_HELPER ||
            kind > LAMBDA_EXEC_LAYOUT_LENGTH_RELOAD) return 0;
    uint64_t hash = UINT64_C(1469598103934665603) ^ kind;
    for (const unsigned char* p = (const unsigned char*)name; *p; p++) {
        hash = (hash ^ *p) * UINT64_C(1099511628211);
    }
    for (size_t probe = 0; probe < 8192; probe++) {
        size_t index = (hash + probe) & 8191;
        LambdaExecCallRow* row = &g_lambda_exec_calls[index];
        uint8_t state = __atomic_load_n(&row->state, __ATOMIC_ACQUIRE);
        if (state == 0) {
            uint8_t empty = 0;
            if (__atomic_compare_exchange_n(&row->state, &empty, 1, false,
                    __ATOMIC_ACQ_REL, __ATOMIC_ACQUIRE)) {
                row->name = str_dup(name, strlen(name));
                if (!row->name) {
                    // leave the slot occupied so concurrent probes cannot reuse it.
                    __atomic_store_n(&row->state, 3, __ATOMIC_RELEASE);
                    return 0;
                }
                row->kind = (uint8_t)kind;
                __atomic_store_n(&row->state, 2, __ATOMIC_RELEASE);
                return index + 1;
            }
            state = empty;
        }
        while (state == 1) {
            state = __atomic_load_n(&row->state, __ATOMIC_ACQUIRE);
        }
        if (state == 2 && row->kind == kind && row->name &&
                strcmp(row->name, name) == 0) return index + 1;
    }
    return 0;
}

extern "C" uint64_t lambda_exec_profile_note_call(uint64_t id) {
    if (id == 0 || id > 8192) {
        __atomic_fetch_add(&g_lambda_exec_call_overflow, 1,
            __ATOMIC_RELAXED);
    } else {
        __atomic_fetch_add(&g_lambda_exec_calls[id - 1].count, 1,
            __ATOMIC_RELAXED);
    }
    return 0;
}

Item cow_mark_shared(Item value) {
    Container* container = cow_item_container(value);
    if (container && (container->cow_state & COW_STATE_SHARED) == 0) {
        if (cow_profile_enabled()) {
            CowProfileTypeCounters* counters = cow_profile_for(value);
            if (counters) counters->share_marks++;
        }
        container->cow_state |= COW_STATE_SHARED;
    }
    return value;
}

// S9.1.2/S9.3.1: a value that reaches a second owner -- another binding, a
// container slot, or a plain (non-`var`) parameter -- is captured BY VALUE.
// Under COW that capture is a share-mark, so the next write through EITHER
// handle detaches at cow_prepare_write and neither observer sees the other's
// update. Binding only marks the header; a later write owns any allocation.
Item cow_bind_var(Item value) {
    if (get_type_id(value) == LMD_TYPE_ARRAY_NUM) {
        ArrayNum* an = value.array_num;
        // CW32v2: mutable views keep their write-through contract (open/todo
        // by designer ruling 2026-08-29) -- marking one would make its first
        // write detach and stop reaching the base. The old eager clone also
        // returned views unclonied, so behavior is unchanged for them.
        if (an && an->is_view) return value;
        // plain ArrayNum joins the uniform mark: O(1) bind, one memcpy detach
        // at the first COW-aware write. This retires the last Stage-1
        // eager-clone exception.
    }
    return cow_mark_shared(value);
}

// S9.3.1: placing a value into a container captures it BY VALUE. Under COW the
// capture is a share-mark; the copy is deferred to whichever side writes first,
// where cow_prepare_write detaches it.
//
// Unlike cow_bind_var this does NOT copy ArrayNum eagerly. An insertion capture
// is the value's own flag, so it costs one bit and cannot allocate -- which is
// what lets every insertion site call it without rooting. ArrayNum still
// detaches correctly when a COW-aware setter writes it (clone_mutable_array_num
// via cow_prepare_write); what stays open is the raw/native-lane store paths
// that never consult the flag, and those are Stage-2 ArrayNum work either way.
// The escape hatch is RETIRED (2026-08-29, after the flip soaked): insertion
// capture (S9.3.1), plain-param snapshots (S9.1.3/CW29), and the CW24v2
// place diagnostics are unconditionally the semantics. LAMBDA_COW_CAPTURE is
// no longer consulted anywhere.
Item cow_capture_value(Item value) {
    return cow_mark_shared(value);
}

static Item cow_profile_mark_with_caller(Item value, uintptr_t caller,
        bool binding) {
    TypeId type_id = get_type_id(value);
    CowProfileTypeCounters* counters = cow_profile_for(value);
    uint64_t before = counters ? counters->share_marks : 0;
    Item result = binding ? cow_bind_var(value) : cow_capture_value(value);
    if (counters) cow_profile_note_site(COW_SITE_SHARE_MARK, type_id, caller,
        counters->share_marks - before);
    return result;
}

Item cow_bind_var_profiled(Item value) {
    return cow_profile_mark_with_caller(value, COW_PROFILE_CALLER(), true);
}

Item cow_capture_value_profiled(Item value) {
    return cow_profile_mark_with_caller(value, COW_PROFILE_CALLER(), false);
}

Item cow_mark_shared_profiled(Item value) {
    return cow_profile_mark_with_caller(value, COW_PROFILE_CALLER(), false);
}

// CW34 (COW §11.11): bind a read-modify-write handle. `value` was just read
// from `root` through `count` intermediate keys (at most two). The handle
// may alias the place -- no share-mark, so its writes land in place and the
// store-back is a no-op -- only while EVERY container on that spine is
// unshared: an outside observer of the root or of an intermediate level would
// see the in-place writes. A static or immortal link counts as shared. Any
// other spine takes the ordinary snapshot bind. No allocation happens here:
// the marks are bits and fn_index on a container is a read.
Item cow_bind_rmw_handle(Item root, Item value, int64_t count, Item key1, Item key2) {
    Item current = root;
    for (int64_t link = 0; ; link++) {
        Container* container = cow_item_container(current);
        if (!container || container->is_static || container->is_immortal ||
                (container->cow_state & COW_STATE_SHARED)) {
            return cow_bind_var(value);
        }
        if (link >= count) break;
        current = fn_index(current, link == 0 ? key1 : key2);
    }
    return value;
}

// A one-level clone marks the source's children shared because two maps now
// reference them. When the pre-image is UNIQUE, though, the caller is about to
// replace it at its only binding, so it dies in the same step and no second
// observer of those children ever exists -- the marks are an artifact of the
// transaction, not a record of real sharing.
//
// Leaving them cost correctness, not just copies. Under CW3's monotonic 1-bit
// flag a mark is never cleared, so the next element write through a child --
// `var xs = h.xs; xs[i] = v`, which BOTH tiers otherwise alias (the C4.1
// field-read behaviour) -- took the copy-on-write path in T0 and published to
// the local instead of the map, while MIR Direct wrote in place. That is how
// typed jetstream/hashmap2 lost every store on the interpreter tier and
// returned the EMPTY sentinel for every lookup.
//
// Clearing is gated on the pre-image being unshared, which is exactly the
// condition under which it is unreachable after the swap. If anything else
// still observes the old root (`var snap = h` before the write), the root
// carries COW_STATE_SHARED, the marks stay, and COW keeps its guarantee (S9.1.2).
static void cow_unmark_shape_children(TypeMap* type, void* data) {
    if (!type || !data) return;
    FOR_EACH_MAP_FIELD(type, entry) {
        if (entry->byte_offset < 0) continue;
        Item child = entry->name ? _map_read_field(entry, data)
                                 : (Item){.map = map_shape_field_to_map(data, entry)};
        Container* container = cow_item_container(child);
        if (container && !container->is_static && !container->is_immortal) {
            container->cow_state &= ~COW_STATE_SHARED;
        }
    }
}

// Also the S9.3.1 capture for a freshly built shaped literal: every field of a
// new map/object/element holds a value that just entered a second owner, so one
// walk over the finished shape captures the whole literal.
void cow_mark_shape_children(TypeMap* type, void* data) {
    if (!type || !data) return;
    FOR_EACH_MAP_FIELD(type, entry) {
        if (entry->byte_offset < 0) continue;
        if (!entry->name) {
            Map* spread = map_shape_field_to_map(data, entry);
            if (spread) cow_mark_shared({.map = spread});
            continue;
        }
        cow_mark_shared(_map_read_field(entry, data));
    }
}

static Item cow_clone_array_one_level(Array* source) {
    if (!source) return ItemError;
    RootFrame roots(2);
    Rooted<Array*> rooted_source(roots, source);
    Rooted<Array*> rooted_copy(roots, array_plain());
    if (!rooted_copy.get()) return ItemError;
    source = rooted_source.get();
    clone_mutable_container_flags((Container*)rooted_copy.get(), (Container*)source);
    if (array_has_native_lane(source)) {
        // Nullable typed-array reification stores raw lane words in a generic
        // Array. Treating those words as Items during COW cloning makes values
        // such as integer lane `1` look like a pointer and dereferences it in
        // get_type_id; copy the physical lane and mark only decoded references.
        Array* copy = rooted_copy.get();
        copy->array_flags = source->array_flags;
        copy->map_kind = source->map_kind;
        copy->reserved_state = source->reserved_state;
        copy->length = source->length;
        copy->capacity = source->capacity;
        if (source->capacity > 0) {
            size_t bytes = 0;
            if (!lam::checked_mul((size_t)source->capacity,
                    array_native_lane_slot_size(source), &bytes)) {
                return ItemError;
            }
            copy->items = (Item*)heap_data_alloc(bytes);
            if (!copy->items) return ItemError;
            memcpy(copy->items, source->items, bytes);
        }
        for (int64_t index = 0; index < source->length; index++) {
            cow_mark_shared(array_native_lane_read(source, index));
        }
        copy->cow_state &= ~COW_STATE_SHARED;
        // identical lanes and children retain the full layout proof (D3.3.3v3).
        copy->rep_cert = source->rep_cert;
        return {.array = copy};
    }
    for (int64_t index = 0; index < source->length; index++) {
        source = rooted_source.get();
        Item child = source->items[index];
        cow_mark_shared(child);
        array_push_verbatim(rooted_copy.get(), child);
    }
    rooted_copy.get()->cow_state &= ~COW_STATE_SHARED;
    rooted_copy.get()->rep_cert = rooted_source.get()->rep_cert;
    return {.array = rooted_copy.get()};
}

static Item cow_clone_map_like_one_level(Item source_item) {
    TypeId type_id = get_type_id(source_item);
    Container* source = source_item.container;
    if (!source) return ItemError;
    RootFrame roots(2);
    Rooted<Item> rooted_source(roots, source_item);
    Rooted<Item> rooted_copy(roots, ItemNull);
    size_t size = type_id == LMD_TYPE_MAP ? sizeof(Map) :
        sizeof(Element);
    Container* copy = (Container*)heap_calloc(size, type_id);
    if (!copy) return ItemError;
    rooted_copy.set({.container = copy});
    source = rooted_source.get().container;
    clone_mutable_container_flags(copy, source);
    copy->type_id = type_id;
    copy->map_kind = source->map_kind;

    TypeMap* type = NULL;
    void* source_data = NULL;
    void** copy_data = NULL;
    int* copy_cap = NULL;
    int source_cap = 0;
    if (type_id == LMD_TYPE_MAP) {
        Map* src = rooted_source.get().map;
        Map* dst = rooted_copy.get().map;
        dst->type = src->type;
        type = mutable_shape_type(type_id, (Type*)src->type);
        source_data = src->data;
        copy_data = &dst->data;
        copy_cap = &dst->data_cap;
        source_cap = src->data_cap;
    } else if (false) {
        Object* src = rooted_source.get().object;
        Object* dst = rooted_copy.get().object;
        dst->type = src->type;
        type = mutable_shape_type(type_id, (Type*)src->type);
        source_data = src->data;
        copy_data = &dst->data;
        copy_cap = &dst->data_cap;
        source_cap = src->data_cap;
        // D2.6.6: content is the object's own items — same one-level copy with
        // child marks the element branch does below. Without it the detached
        // copy would share the source's children, and a write through either
        // alias would be visible in both (S9.1.2).
        for (int64_t index = 0; index < src->length; index++) {
            src = rooted_source.get().object;
            Object* live_dst = rooted_copy.get().object;
            Item child = src->items[index];
            cow_mark_shared(child);
            array_push_verbatim((Array*)live_dst, child);
        }
        source_data = rooted_source.get().object->data;
        copy_data = &rooted_copy.get().object->data;
        copy_cap = &rooted_copy.get().object->data_cap;
    } else {
        Element* src = rooted_source.get().element;
        Element* dst = rooted_copy.get().element;
        dst->type = src->type;
        type = mutable_shape_type(type_id, (Type*)src->type);
        source_data = src->data;
        copy_data = &dst->data;
        copy_cap = &dst->data_cap;
        source_cap = src->data_cap;
        for (int64_t index = 0; index < src->length; index++) {
            src = rooted_source.get().element;
            dst = rooted_copy.get().element;
            Item child = src->items[index];
            cow_mark_shared(child);
            array_push_verbatim((Array*)dst, child);
        }
    }
    int data_cap = source_cap > 0 ? source_cap : (type ? type->byte_size : 0);
    if (source_data && data_cap > 0) {
        // memcpy fills the entire packed buffer before its first safepoint;
        // zeroing it first doubles the bytes written by shared-map copies.
        *copy_data = heap_data_alloc_uninit((size_t)data_cap);
        if (!*copy_data) return ItemError;
        if (type_id == LMD_TYPE_MAP) {
            source_data = rooted_source.get().map->data;
            copy_data = &rooted_copy.get().map->data;
            copy_cap = &rooted_copy.get().map->data_cap;
        } else if (false) {
            source_data = rooted_source.get().object->data;
            copy_data = &rooted_copy.get().object->data;
            copy_cap = &rooted_copy.get().object->data_cap;
        } else {
            source_data = rooted_source.get().element->data;
            copy_data = &rooted_copy.get().element->data;
            copy_cap = &rooted_copy.get().element->data_cap;
        }
        // Shape data stores scalar payloads by value and container references by
        // pointer, so byte-copying preserves layout while child marks establish COW.
        memcpy(*copy_data, source_data, (size_t)data_cap);
        *copy_cap = data_cap;
        cow_mark_shape_children(type, source_data);
    }
    rooted_copy.get().container->cow_state &= ~COW_STATE_SHARED;
    return rooted_copy.get();
}

static Item cow_clone_one_level(Item source) {
    switch (get_type_id(source)) {
    case LMD_TYPE_ARRAY: return cow_clone_array_one_level(source.array);
    case LMD_TYPE_ARRAY_NUM: return clone_mutable_array_num(source.array_num, NULL);
    case LMD_TYPE_MAP:
    case LMD_TYPE_ELEMENT: return cow_clone_map_like_one_level(source);
    default: return source;
    }
}

Item slot_image(Item value) {
    // S2.5.6: a single-value slot of a persistent container -- a map field, an
    // attribute, an object field -- holds no list; the list is stored as the
    // array it is. The image is a one-level copy, so the list itself, which may
    // still be bound and spread elsewhere, keeps its kind.
    if (!item_is_list(value)) return value;
    return seq_finish_kind(cow_clone_one_level(value), false);
}

void lambda_direct_field_store_image(Item owner, int64_t byte_offset, Item list) {
    // The raw writer had loaded the slot address before this call; the image
    // copy may move the owner, so the address is re-read from the rooted owner.
    RootFrame roots(1);
    Rooted<Item> rooted_owner(roots, owner);
    Item image = slot_image(list);
    Map* live = rooted_owner.get().map;
    if (!live || !live->data) return;
    *(Container**)((char*)live->data + byte_offset) = image.container;
}

Item cow_prepare_write(Item old) {
    Container* container = cow_item_container(old);
    if (!container) return old;
    // The MVP file has no mutable child storage; do not detach a truncated
    // base-sized copy or share an active native builder through COW.
    if (container_is_virtual_list(container)) return ItemError;
    if (!container->is_static && !container->is_immortal &&
            (container->cow_state & COW_STATE_SHARED) == 0) {
        if (cow_profile_enabled()) {
            CowProfileTypeCounters* counters = cow_profile_for(old);
            if (counters) counters->unique_mutations++;
        }
        return old;
    }

    Item replacement = get_type_id(old) == LMD_TYPE_VMAP
        ? vmap_clone_for_cow(old) : cow_clone_one_level(old);
    if (get_type_id(replacement) == LMD_TYPE_ERROR) return replacement;
    if (cow_profile_enabled()) {
        CowProfileTypeCounters* counters = cow_profile_for(old);
        if (counters) {
            counters->shared_copies++;
            uint64_t bytes = cow_one_level_copy_bytes(old);
            counters->copied_bytes += bytes;
        }
    }

    Container* replacement_container = cow_item_container(replacement);
    if (replacement_container) replacement_container->cow_state &= ~COW_STATE_SHARED;
    return replacement;
}

Item cow_prepare_write_profiled(Item old) {
    uintptr_t caller = COW_PROFILE_CALLER();
    TypeId type_id = get_type_id(old);
    CowProfileTypeCounters* counters = cow_profile_for(old);
    uint64_t unique_before = counters ? counters->unique_mutations : 0;
    uint64_t copies_before = counters ? counters->shared_copies : 0;
    uint64_t bytes_before = counters ? counters->copied_bytes : 0;
    Item result = cow_prepare_write(old);
    if (counters) {
        cow_profile_note_site(COW_SITE_UNIQUE_WRITE, type_id, caller,
            counters->unique_mutations - unique_before);
        cow_profile_note_site(COW_SITE_SHARED_COPY, type_id, caller,
            counters->shared_copies - copies_before,
            counters->copied_bytes - bytes_before);
    }
    return result;
}

static ShapeEntry* map_find_shape_entry(TypeMap* tm, const char* key_cstr,
    size_t key_len);
Item cow_path_set(Item owner, Item path, Item value);
static MapContractRelation runtime_map_contract_relation_cached(
    const TypeMap* candidate, const TypeMap* expected);

static ShapeEntry* runtime_named_map_field(Type* expected, Item key) {
    expected = runtime_boundary_unwrap_type(expected);
    // The open `map` annotation is the plain TYPE_MAP singleton, not a TypeMap:
    // it declares no fields, and reading it as one walked past the struct
    // (`var m: map = {}; m["a"] = 1` segfaulted on the JIT).
    if (!expected || expected->type_id != LMD_TYPE_MAP || expected == &TYPE_MAP) return NULL;
    const char* chars = NULL;
    uint32_t length = 0;
    TypeId key_type = get_type_id(key);
    if (key_type == LMD_TYPE_STRING || key_type == LMD_TYPE_SYMBOL) {
        chars = key.get_chars();
        length = key.get_len();
    }
    if (!chars) return NULL;
    return map_find_shape_entry((TypeMap*)expected, chars, length);
}

// Resolve a declared map/array path before its write. This is deliberately
// contract-only: the caller separately proves the current root's physical
// layout, then validates the selected leaf before the raw COW walk publishes
// it (D3.2.4v3).
Type* lambda_map_path_contract_step(Type* current, Item key, bool* open_leaf) {
    *open_leaf = false;
    current = runtime_boundary_unwrap_type(current);
    if (!current) return NULL;
    Type* map_contract = lambda_type_nonnull_map_contract(current);
    if (map_contract) {
        ShapeEntry* field = runtime_named_map_field(map_contract, key);
        return field ? field->type : NULL;
    }
    LambdaArrayContractInfo array_info = {};
    int64_t array_index = 0;
    // an open array constrains the carrier, not its descendants. A valid
    // indexed write below it cannot invalidate the declared outer record;
    // the COW walker still checks the entire path before the leaf store
    // (D3.2.4v3, S7.1.3v2).
    if (current->type_id == LMD_TYPE_ANY) {
        // an `any` step is open the same way: nothing below it is declared
        *open_leaf = true;
        return &TYPE_ANY;
    }
    if (current == &TYPE_ARRAY && lambda_item_to_int64_exact(key, &array_index)) {
        *open_leaf = true;
        return &TYPE_ANY;
    }
    if (!lambda_array_contract_info(current, &array_info) ||
            !lambda_item_to_int64_exact(key, &array_index)) {
        return NULL;
    }
    return array_info.immediate_element;
}

static Type* runtime_map_path_leaf_contract(Type* root_contract, Item path) {
    if (get_type_id(path) != LMD_TYPE_ARRAY || !path.array || path.array->length <= 0) {
        return NULL;
    }
    Type* current = root_contract;
    for (int64_t index = 0; index < path.array->length && current; index++) {
        bool open_leaf = false;
        current = lambda_map_path_contract_step(current, item_at(path, index), &open_leaf);
        if (open_leaf) return current;
    }
    return current;
}

bool lambda_map_rep_proves_contract(Item value, TypeMap* expected) {
    if (get_type_id(value) != LMD_TYPE_MAP || !value.map || !expected) return false;
    TypeMap* candidate = (TypeMap*)value.map->type;
    if (!candidate || !typemap_ptr_is_plausible(candidate)) return false;
    MapContractRelation relation = runtime_map_contract_relation_cached(candidate,
        expected);
    return relation == MAP_CONTRACT_EXACT_TRUSTED ||
        relation == MAP_CONTRACT_STORAGE_COMPATIBLE;
}

// A raw COW relink may retain a proof only when the replacement already has
// the same representation. This never turns an open write into a contract.
bool lambda_value_rep_proves_contract(Item value, Type* contract) {
    if (!contract) return false;
    // an open leaf carries no representation to prove (T27-4)
    if (contract->type_id == LMD_TYPE_ANY) return get_type_id(value) != LMD_TYPE_ERROR;
    // a builtin scalar contract is proven by the value's own tag (T27-4)
    Type* bare = runtime_boundary_unwrap_type(contract);
    if ((bare == &TYPE_INT || bare == &TYPE_BOOL || bare == &TYPE_FLOAT) &&
            get_type_id(value) == bare->type_id) {
        return true;
    }
    if (get_type_id(value) == LMD_TYPE_NULL) return lambda_type_accepts_null(contract);
    LambdaArrayContractInfo array_info = {};
    if (lambda_array_contract_info(contract, &array_info)) {
        return lambda_array_rep_proves(value, contract, true);
    }
    if (lambda_type_nonnull_map_contract(contract)) {
        return lambda_map_rep_proves_contract(value,
            (TypeMap*)runtime_boundary_nonnull_map_arm(contract));
    }
    LaneStorageDesc lane = lambda_lane_storage_desc_for(contract);
    return lane.base_contract && lane.base_contract->kind == TYPE_KIND_SIMPLE &&
        lane.value_domain == get_type_id(value) && lambda_type_matches(value, contract);
}

static Item cow_path_set_impl(Item owner, Item path, int64_t fixed_count,
    const Item* fixed_keys, Item value, bool publish_in_place);

// `path` is the dynamic descriptor; a NULL path writes through `fixed_count`
// fixed keys (cow_path_set_impl's two ABI shapes).
static Item runtime_map_path_write_proven(Item owner, Item path, int64_t fixed_count,
        const Item* fixed_keys, Item value, Type* leaf_contract, const char* boundary,
        bool inplace) {
    // Admit only the incoming leaf. All other fields retain the root's
    // established contract; COW relinks preserve its layouts (D3.2.4v3).
    if (lambda_value_rep_proves_contract(value, leaf_contract)) {
        return cow_path_set_impl(owner, path, fixed_count, fixed_keys, value, inplace);
    }
    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_path(roots, path);
    Rooted<Item> rooted_value(roots, value);
    // the leaf check may allocate; keep the caller's fixed keys alive across it
    RootSpan key_roots((size_t)fixed_count);
    Item local_keys[LAMBDA_PATH_KEYS_MAX];
    Item* keys = key_roots.valid() ? key_roots.items() : local_keys;
    for (int64_t i = 0; i < fixed_count; i++) keys[i] = fixed_keys[i];
    rooted_value.set(lambda_type_check(rooted_value.get(), leaf_contract, boundary));
    if (get_type_id(rooted_value.get()) == LMD_TYPE_ERROR) return rooted_value.get();
    return cow_path_set_impl(rooted_owner.get(), rooted_path.get(), fixed_count, keys,
        rooted_value.get(), inplace);
}

// D3.4.3v4: runtime-grown plain maps share their types through one transition
// tree per heap generation of a context. It is a capsule extension rather than
// an EvalContext slot, so the context layout that separately built modules read
// is unchanged.
#define RUNTIME_SHAPE_TREE_OWNER 0x53485054u  // 'SHPT'
// Every runtime-grown map shares this one tree, so its budget sits far above an
// Input's 1,024 map types; past it a map keeps a private type (D3.4.3v4).
static const int RUNTIME_SHAPE_GRAPH_BUDGET = 65536;

static void runtime_shape_tree_destroy(void* capsule) {
    // D4.2.6: the Input's arena holds every tree node, so it goes as a whole.
    // Destroying the tree's own pool runs the Input's registered cleanup
    // (input_pool_cleanup), which releases the document resources once.
    mem_pool_destroy(((Input*)capsule)->pool);
}

static const ContextCapsuleOps runtime_shape_tree_ops = {
    "runtime_shape_tree", CONTEXT_CAPSULE_LIFETIME_REALM, 0, NULL, NULL,
    runtime_shape_tree_destroy
};

void runtime_shape_tree_release(EvalContext* owner) {
    // LR03-43: the tree's edges and entries carry NameIds of the runtime name
    // pool, and every map on a tree node lives on the heap, so the tree ends
    // with that heap generation. Kept across runtime_reset_heap, the next
    // pool's recycled ids matched stale edges: a batch script's group-by
    // `region` followed the previous script's `r` edge.
    context_capsule_extensions_drop_owner(owner, RUNTIME_SHAPE_TREE_OWNER);
}

Input* runtime_shape_tree(void) {
    if (!context) return NULL;
    Input* tree = (Input*)context_capsule_extension(context, RUNTIME_SHAPE_TREE_OWNER, 0);
    if (tree) return tree;
    // The tree owns a pool of its own, as InputManager's global_pool does, so
    // its teardown is the capsule's alone: in context->pool (the heap's pool) a
    // heap reset ran the Input's pool cleanup and freed its struct while the
    // capsule still pointed at it.
    Pool* tree_pool = mem_pool_create(NULL, MEM_ROLE_INPUT, "runtime.shape_tree.pool");
    if (!tree_pool) return NULL;
    tree = Input::create(tree_pool, nullptr, nullptr);
    if (!tree || !tree->arena || !tree->type_list ||
            !context_capsule_extension_install(context, RUNTIME_SHAPE_TREE_OWNER, 0, tree,
                &runtime_shape_tree_ops)) {
        mem_pool_destroy(tree_pool);
        return NULL;
    }
    tree->shape_graph_budget = RUNTIME_SHAPE_GRAPH_BUDGET;
    // D3.4.3v5: maps grow from literal, contract, nominal, parsed and private
    // types too, through edges this tree keeps in its own table
    tree->keeps_external_edges = true;
    return tree;
}

// Impl_Map_Transition_Coverage P3: the runtime tree's root for elements of one
// tag, so runtime-built elements (group-by groups, join tuples) start on a
// shared node; NULL keeps the caller on a private type.
TypeElmt* runtime_shape_tree_element_root(const char* tag, size_t length, Target* ns) {
    Input* tree = runtime_shape_tree();
    if (!tree || !tree->name_pool || !tag) return NULL;
    String* name = name_pool_create_len(tree->name_pool, tag, length);
    return name ? elmt_tree_root(tree, name, ns) : NULL;
}

// D3.4.3v5: an add to a plain map or an element follows (or mints) an edge of
// the runtime tree. An empty plain map starts at the root; a node of the tree
// follows its own edges; any other type -- a literal's, a contract's, a
// nominal type's, a parsed document's or a private type -- is an external
// parent, which the tree grows from without writing it. Maps built from the
// same start by the same adds then share one type, and a path of n fields
// holds n entries; copying the whole shape into the pool per add cost O(n²)
// entries that were never reclaimed (LR03-38). Data grows by doubling. A type
// the tree declines -- fan-out, budget, JS shape metadata, spread slots --
// keeps the private path.
static bool map_extend_via_runtime_tree(Item map_item, Item key, Item value) {
    TypeId container_type = get_type_id(map_item);
    TypeId key_type = get_type_id(key);
    if ((container_type != LMD_TYPE_MAP && container_type != LMD_TYPE_ELEMENT) ||
            (key_type != LMD_TYPE_STRING && key_type != LMD_TYPE_SYMBOL)) {
        return false;
    }
    // S8.2.2v4: a Lambda symbol without a namespace is the global STRING name
    // of its characters, so `m['k'] = v` and every spread key share the edges
    // `m["k"] = v` takes. A qualified symbol keeps the private path until keys
    // carry their namespace (LR03-40); a JS Symbol never reaches a plain
    // Lambda map's growth path.
    String* key_string = NULL;
    Symbol* key_symbol = NULL;
    if (key_type == LMD_TYPE_STRING) {
        key_string = key.get_safe_string();
        if (!key_string) return false;
    } else {
        key_symbol = key.get_safe_symbol();
        if (!key_symbol || !symbol_is_lambda_name(key_symbol) ||
                symbol_lambda_namespace(key_symbol)) return false;
    }
    TypeId value_type = get_type_id(value);
    bool is_element = container_type == LMD_TYPE_ELEMENT;
    // D2.6.6v2: an element shares Map's attribute face (type, data, data_cap)
    Map* map = map_item.map;
    if (!map || value_type == LMD_TYPE_ERROR) return false;
    if (!is_element && map->map_kind != MAP_KIND_PLAIN &&
            map->map_kind != MAP_KIND_ORDERED) return false;
    // UI-mode elements keep their attribute buffers in the context arena, which
    // only the private path allocates from
    if (is_element && context && context->ui_mode && context->arena) return false;
    TypeMap* old_type = (TypeMap*)map->type;
    Input* tree = runtime_shape_tree();
    // a tree node takes its kind from its parent, so a container whose type is
    // of the other kind keeps the private path
    if (!old_type || !tree || old_type->type_id != container_type) return false;
    // `{}`, a fresh map and a computed-key literal all start at the root, so
    // they share one path; every other type is the parent itself
    bool empty_plain = !is_element && old_type->length == 0 && !old_type->shape &&
        !old_type->nominal && !old_type->is_trusted_contract && !old_type->has_spread;
    TypeMap* parent = empty_plain ? NULL : old_type;
    ShapeEntry* entry = NULL;
    TypeMap* target = key_string
        ? type_tree_add_map_field(tree, parent, key_string, value_type, &entry)
        : type_tree_add_map_field_chars(tree, parent, key_symbol->chars,
            key_symbol->len, value_type, &entry);
    if (!target || !entry) return false;

    int64_t old_size = empty_plain ? 0 : old_type->byte_size;
    int64_t needed = target->byte_size;
    if (!map->data || map->data_cap < needed) {
        int64_t capacity = map->data_cap > 0 ? (int64_t)map->data_cap : 32;
        while (capacity < needed) capacity *= 2;
        if (capacity > INT_MAX) return false;
        RootFrame roots(2);
        Rooted<Map*> rooted_map(roots, map);
        Rooted<Item> rooted_value(roots, value);
        void* new_data = heap_data_calloc((size_t)capacity);
        if (!new_data) return false;
        map = rooted_map.get();
        value = rooted_value.get();
        if (map->data && old_size > 0) memcpy(new_data, map->data, (size_t)old_size);
        map->data = new_data;
        map->data_cap = (int)capacity;
    }
    map_field_store((char*)map->data + entry->byte_offset, value, value_type);
    map->type = target;
    return true;
}

static bool map_extend_open_shape(Item map_item, Item key, Item value) {
    if (map_extend_via_runtime_tree(map_item, key, value)) return true;
    // S2.1.4 part 3: a nominal instance is OPEN — it may hold fields its type
    // does not declare. Element-shaped values are admitted too: since D2.6.6v2
    // every container shares Map's attribute face at the same offsets, so the
    // upcast below is valid and only the attribute face is touched (the content
    // items are left alone).
    TypeId extend_tid = get_type_id(map_item);
    if (!lambda_type_id_has_attr_face(extend_tid)) return false;
    Map* map = map_item.map;
    if (!map || !map->type || !context || !context->pool) return false;
    const char* key_chars = NULL;
    uint32_t key_length = 0;
    TypeId key_type = get_type_id(key);
    if (key_type == LMD_TYPE_STRING) {
        String* key_string = key.get_safe_string();
        key_chars = key_string ? key_string->chars : NULL;
        key_length = key_string ? key_string->len : 0;
    } else if (key_type == LMD_TYPE_SYMBOL) {
        Symbol* key_symbol = key.get_safe_symbol();
        key_chars = key_symbol ? key_symbol->chars : NULL;
        key_length = key_symbol ? key_symbol->len : 0;
    }
    if (!key_chars) return false;

    TypeMap* old_type = (TypeMap*)map->type;
    if (!map->data && old_type->byte_size > 0) return false;
    int old_count = 0;
    int64_t new_size = 0;
    FOR_EACH_MAP_FIELD(old_type, entry) {
        old_count++;
        if (entry->byte_offset >= 0) new_size += shape_entry_storage_size(entry);
    }
    TypeId value_type = get_type_id(value);
    new_size += type_info[value_type].byte_size;
    shape_tree_stats_note_private_copy(old_count);

    RootFrame roots(2);
    Rooted<Map*> rooted_map(roots, map);
    Rooted<Item> rooted_value(roots, value);
    bool is_element = extend_tid == LMD_TYPE_ELEMENT;
    bool arena_element = is_element && context->ui_mode && context->arena;
    if (arena_element) {
        Item held = rooted_value.get();
        if (!ui_prepare_element_field(&held)) return false;
        rooted_value.set(held);
    }
    TypeMap* new_type = (TypeMap*)alloc_type(context->pool,
        is_element ? LMD_TYPE_ELEMENT : LMD_TYPE_MAP,
        is_element ? sizeof(TypeElmt) : sizeof(TypeMap));
    if (!new_type) return false;
    if (is_element) {
        TypeElmt* old_element = (TypeElmt*)old_type;
        TypeElmt* new_element = (TypeElmt*)new_type;
        // a plain map type on an element container has no element fields
        if (typemap_has_element_layout(old_type)) {
            new_element->name = old_element->name;
            new_element->name_id = old_element->name_id;
            new_element->content_list = old_element->content_list;
            new_element->ns = old_element->ns;
        }
    }
    // ui elements live in an arena; their dynamic attribute buffers must have
    // the same owner because the collector cannot trace pointers from that arena.
    void* new_data = arena_element
        ? arena_calloc(context->arena, new_size > 0 ? (size_t)new_size : 1)
        : heap_data_calloc(new_size > 0 ? (size_t)new_size : 1);
    if (!new_data) return false;
    map = rooted_map.get();
    old_type = (TypeMap*)map->type;

    ShapeEntry* first = NULL;
    ShapeEntry* last = NULL;
    int64_t offset = 0;
    FOR_EACH_MAP_FIELD(old_type, old) {
        ShapeEntry* entry = (ShapeEntry*)pool_calloc(context->pool, sizeof(ShapeEntry));
        if (!entry) return false;
        *entry = *old;
        entry->chain_next = NULL;
        entry->chain_index = 0;  // a private chain holds no tree positions (D3.4.3v3)
        if (old->byte_offset >= 0) {
            entry->byte_offset = offset;
            int size = shape_entry_storage_size(old);
            memcpy((char*)new_data + offset, (char*)map->data + old->byte_offset,
                (size_t)size);
            offset += size;
        } else {
            entry->byte_offset = -1;
        }
        if (last) last->chain_next = entry;
        else first = entry;
        last = entry;
    }

    ShapeEntry* added = (ShapeEntry*)pool_calloc(context->pool,
        sizeof(ShapeEntry) + sizeof(StrView));
    if (!added) return false;
    StrView* name = (StrView*)((char*)added + sizeof(ShapeEntry));
    char* name_copy = (char*)pool_calloc(context->pool, (size_t)key_length + 1);
    if (!name_copy) return false;
    memcpy(name_copy, key_chars, key_length);
    name->str = name_copy;
    name->length = key_length;
    added->name = name;
    added->name_hash = typemap_name_hash(name->str, (int)name->length);
    added->name_id = NAME_ID_NONE;
    added->key_kind = NAME_KEY_STRING;
    shape_entry_set_type(added, type_info[value_type].type);
    added->byte_offset = offset;
    map_field_store((char*)new_data + offset, rooted_value.get(), value_type);
    if (last) last->chain_next = added;
    else first = added;

    new_type->shape = first;
    new_type->last = added;
    new_type->length = old_count + 1;
    new_type->byte_size = new_size;
    // execution-owned shapes are reached through their container, never the
    // cached compiler type list or its concurrent satellite readers (D8.5.1v7).
    new_type->type_index = -1;
    // the copied chain above carries old_type's entries verbatim, spread slots included
    new_type->has_spread = old_type->has_spread;
    new_type->has_named_shape = old_type->has_named_shape;
    // A grown shape no longer proves the declared physical layout to the
    // emitter's direct-access path (D3.2.4v2), but it is STILL an instance of
    // its nominal type: the record travels with it, so `is T` and method
    // resolution survive the extension (S2.1.4, OB16 — this is LR03-8's fix at
    // the growth site, the one place that actually produces a grown shape).
    new_type->is_trusted_contract = false;
    new_type->nominal = old_type->nominal;
    new_type->is_nominal = old_type->is_nominal;
    new_type->struct_name = old_type->struct_name;
    new_type->is_private_clone = true;
    typemap_hash_build(new_type, context->pool);

    // The candidate is private. Publishing the new shape/data pair together
    // makes the additional open field immediately match its physical slot.
    map = rooted_map.get();
    map->type = new_type;
    map->data = new_data;
    map->data_cap = (int)new_size;
    return true;
}

static Item lambda_map_set_checked_impl(Item owner, Item key, Item value, Type* expected,
        const char* boundary, bool publish_in_place) {
    // The open `map` annotation admits every map, so a write needs no field or
    // post-state check and therefore no cloned transaction: it is the untyped
    // COW write. The transactional path cloned the whole map per store, which
    // made a counting loop over a `var m: map` quadratic.
    if (runtime_boundary_unwrap_type(expected) == &TYPE_MAP) {
        TypeId owner_type = get_type_id(owner);
        if (owner_type == LMD_TYPE_MAP || owner_type == LMD_TYPE_VMAP) {
            return map_set_cow(owner, key, value);
        }
    }
    // A declared field write preserves every other field's established proof;
    // admit only the replacement, including T[] fields (D3.2.4v3/D3.3.3v3).
    Type* proven_contract = runtime_boundary_unwrap_type(expected);
    ShapeEntry* proven_field = runtime_named_map_field(proven_contract, key);
    if (proven_field && lambda_map_rep_proves_contract(owner,
            (TypeMap*)runtime_boundary_nonnull_map_arm(proven_contract))) {
        RootFrame roots(3);
        Rooted<Item> rooted_owner(roots, owner);
        Rooted<Item> rooted_key(roots, key);
        Rooted<Item> rooted_value(roots, value);
        if (!lambda_value_rep_proves_contract(rooted_value.get(), proven_field->type)) {
            rooted_value.set(lambda_type_check(rooted_value.get(), proven_field->type, boundary));
            if (get_type_id(rooted_value.get()) == LMD_TYPE_ERROR) return rooted_value.get();
        }
        if (!publish_in_place) rooted_owner.set(cow_prepare_write(rooted_owner.get()));
        if (get_type_id(rooted_owner.get()) == LMD_TYPE_ERROR) return rooted_owner.get();
        Item status = fn_map_set(rooted_owner.get(), rooted_key.get(), rooted_value.get());
        return get_type_id(status) == LMD_TYPE_ERROR ? status : rooted_owner.get();
    }
    // Typed map writes are transactional at the root boundary. Clone first,
    // then validate/store on the private candidate; a failed field check or
    // post-state check therefore cannot corrupt the original map or a COW
    // snapshot that still observes it.
    Type* contract = runtime_boundary_unwrap_type(expected);
    ShapeEntry* field = runtime_named_map_field(contract, key);
    Item checked_value = field ? lambda_type_check(value, field->type, boundary) : value;
    if (get_type_id(checked_value) == LMD_TYPE_ERROR) return checked_value;

    // A var parameter arrives after the caller has detached its writable root.
    // Check the pre-state before a direct store: known members are already
    // checked above and open members preserve map conformance, so this keeps
    // the in/out write transactional without hiding the replacement in the
    // callee's local binding.
    if (publish_in_place && !lambda_type_matches(owner, contract)) {
        return lambda_type_error(owner, contract, boundary);
    }

    RootFrame roots(4);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_key(roots, key);
    Rooted<Item> rooted_value(roots, checked_value);
    // Whether the pre-image had another observer, sampled BEFORE the clone marks
    // anything. A unique pre-image is dead the moment the caller publishes the
    // candidate, so the marks its clone leaves on the shared children are an
    // artifact of this transaction -- see cow_unmark_shape_children.
    Container* owner_container = cow_item_container(rooted_owner.get());
    bool owner_was_unique = owner_container &&
        (owner_container->cow_state & COW_STATE_SHARED) == 0;
    Rooted<Item> rooted_candidate(roots, publish_in_place ? rooted_owner.get() :
        cow_clone_one_level(rooted_owner.get()));
    if (get_type_id(rooted_candidate.get()) == LMD_TYPE_ERROR) return rooted_candidate.get();
    if (!publish_in_place && rooted_candidate.get().item == rooted_owner.get().item) {
        // Only VMap currently falls through the generic clone helper. Its
        // separate COW implementation is already private-by-construction.
        rooted_candidate.set(vmap_clone_for_cow(rooted_owner.get()));
        if (get_type_id(rooted_candidate.get()) == LMD_TYPE_ERROR) return rooted_candidate.get();
    }
    // An undeclared key the map already holds is an open member written before:
    // update it in place. Extending the shape again stored a duplicate entry per
    // write (S2.1.4 open instances), as the COW path writer below already avoids.
    TypeId candidate_type = get_type_id(rooted_candidate.get());
    bool open_member_present = !field &&
        (candidate_type == LMD_TYPE_MAP || candidate_type == LMD_TYPE_ELEMENT) &&
        runtime_named_map_field((Type*)lambda_attr_shape(candidate_type,
            rooted_candidate.get().map), rooted_key.get());
    if (field || open_member_present) {
        Item set_result = fn_map_set(rooted_candidate.get(), rooted_key.get(), rooted_value.get());
        if (get_type_id(set_result) == LMD_TYPE_ERROR) return set_result;
    } else if (!map_extend_open_shape(rooted_candidate.get(), rooted_key.get(),
                   rooted_value.get())) {
        return lambda_type_error(rooted_value.get(), contract, boundary);
    }
    if (!lambda_type_matches(rooted_candidate.get(), contract)) {
        ValidationResult* validation = NULL;
        (void)runtime_validate_value_against_type(rooted_candidate.get(), contract, &validation);
        return lambda_type_error_with_validation(rooted_candidate.get(), contract, boundary, validation);
    }
    // The candidate is about to replace a pre-image nothing else could observe,
    // so hand it back owning its children outright rather than carrying the
    // clone's transactional marks forward.
    if (!publish_in_place && owner_was_unique &&
            get_type_id(rooted_candidate.get()) == LMD_TYPE_MAP) {
        Map* candidate_map = rooted_candidate.get().map;
        if (candidate_map) {
            cow_unmark_shape_children((TypeMap*)candidate_map->type, candidate_map->data);
        }
    }
    return rooted_candidate.get();
}

Item lambda_map_set_checked(Item owner, Item key, Item value, Type* expected,
        const char* boundary) {
    return lambda_map_set_checked_impl(owner, key, value, expected, boundary, false);
}

Item lambda_map_set_checked_inplace(Item owner, Item key, Item value, Type* expected,
        const char* boundary) {
    return lambda_map_set_checked_impl(owner, key, value, expected, boundary, true);
}

// The contract-generic body of the nested checked setters. `contract` is the
// unwrapped root contract: a record, or an array whose path steps through a
// record (`bag[0].size = v` on `Box[]`, LR12-13). Every step resolves through
// lambda_map_path_contract_step, which walks both kinds (D3.2.4v3).
static Item runtime_container_path_set_checked(Item owner, Item path, Item value,
        Type* contract, const char* boundary) {
    // Nested annotated writes validate the proposed root, not merely the final
    // slot. Start from a detached top-level container so a failed post-state
    // check cannot mutate the old root or a snapshot that still observes it.
    Type* leaf_contract = runtime_map_path_leaf_contract(contract, path);
    // a certified array root proves its element layouts as a record does its
    // fields, so either kind takes the leaf-only admission (D3.2.4v4)
    if (leaf_contract && lambda_value_rep_proves_contract(owner, contract)) {
        return runtime_map_path_write_proven(owner, path, 0, NULL, value,
            leaf_contract, boundary, false);
    }
    RootFrame roots(4);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_path(roots, path);
    Rooted<Item> rooted_value(roots, value);
    Rooted<Item> rooted_candidate(roots, cow_clone_one_level(rooted_owner.get()));
    if (get_type_id(rooted_candidate.get()) == LMD_TYPE_ERROR ||
            rooted_candidate.get().item == rooted_owner.get().item) {
        return lambda_type_error(rooted_owner.get(), contract, boundary);
    }
    Item write_result = cow_path_set(rooted_candidate.get(), rooted_path.get(),
        rooted_value.get());
    if (get_type_id(write_result) == LMD_TYPE_ERROR) return write_result;
    Item converted_root = lambda_type_check(rooted_candidate.get(), contract, boundary);
    if (get_type_id(converted_root) == LMD_TYPE_ERROR) return converted_root;
    return converted_root;
}

// NM-O8, typed arm. A `var`/plain-`pn` parameter root writes through to the
// caller, so it cannot be validated by swapping in a detached candidate -- the
// caller would never see the swap. Check the pre-state conforms (the same
// contract lambda_map_set_checked_inplace relies on for the flat store), write
// in place, then re-check the post-state.
static Item runtime_container_path_set_checked_inplace(Item owner, Item path,
        Item value, Type* contract, const char* boundary) {
    RootFrame roots(6);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_path(roots, path);
    Rooted<Item> rooted_value(roots, value);
    Type* leaf_contract = runtime_map_path_leaf_contract(contract, rooted_path.get());
    if (leaf_contract &&
            lambda_value_rep_proves_contract(rooted_owner.get(), contract)) {
        return runtime_map_path_write_proven(rooted_owner.get(), rooted_path.get(),
            0, NULL, rooted_value.get(), leaf_contract, boundary, true);
    }
    if (!lambda_type_matches(rooted_owner.get(), contract)) {
        return lambda_type_error(rooted_owner.get(), contract, boundary);
    }
    // Validate and coerce on a detached candidate FIRST: a rejected nested
    // write must leave the caller's record untouched (writing 3.5 into an
    // `int` field in place and then failing the post-check left the lane
    // holding float bits -- proc_type_numeric_structural_admission read
    // `inf`), and the candidate's post-check is also where numeric structural
    // admission converts the stored value (3 -> 3.0 into a `float` field).
    Rooted<Item> rooted_candidate(roots, cow_clone_one_level(rooted_owner.get()));
    if (get_type_id(rooted_candidate.get()) == LMD_TYPE_ERROR ||
            rooted_candidate.get().item == rooted_owner.get().item) {
        return lambda_type_error(rooted_owner.get(), contract, boundary);
    }
    Item staged = cow_path_set(rooted_candidate.get(), rooted_path.get(),
        rooted_value.get());
    if (get_type_id(staged) == LMD_TYPE_ERROR) return staged;
    Rooted<Item> rooted_converted(roots,
        lambda_type_check(rooted_candidate.get(), contract, boundary));
    if (get_type_id(rooted_converted.get()) == LMD_TYPE_ERROR) return rooted_converted.get();
    // then land the COERCED leaf in the caller's own record through the same path
    Rooted<Item> rooted_leaf(roots, rooted_converted.get());
    for (int64_t i = 0; i < rooted_path.get().array->length; i++) {
        Item key = rooted_path.get().array->items[i];
        rooted_leaf.set(fn_index(rooted_leaf.get(), key));
        if (get_type_id(rooted_leaf.get()) == LMD_TYPE_ERROR) return rooted_leaf.get();
    }
    Item write_result = cow_path_set_inplace(rooted_owner.get(), rooted_path.get(),
        rooted_leaf.get());
    if (get_type_id(write_result) == LMD_TYPE_ERROR) return write_result;
    return rooted_owner.get();
}

Item lambda_map_path_set_checked(Item owner, Item path, Item value, Type* expected,
        const char* boundary) {
    Type* contract = runtime_boundary_unwrap_type(expected);
    if (!contract || contract->type_id != LMD_TYPE_MAP) {
        return lambda_type_error(value, expected, boundary);
    }
    return runtime_container_path_set_checked(owner, path, value, contract, boundary);
}

Item lambda_map_path_set_checked_inplace(Item owner, Item path, Item value,
        Type* expected, const char* boundary) {
    Type* contract = runtime_boundary_unwrap_type(expected);
    if (!contract || contract->type_id != LMD_TYPE_MAP) {
        return lambda_type_error(value, expected, boundary);
    }
    return runtime_container_path_set_checked_inplace(owner, path, value, contract,
        boundary);
}

// T27-4: the fixed-descriptor twin of the two checked path setters above. The
// compiler resolved `leaf_contract` from the declared root and the key kinds;
// bit 16+i of `shape` marks key i as an index, whose exactness is the one part
// of that resolution only the runtime can confirm. A proven root writes through
// one rooted walk with no path array and no per-store contract walk; everything
// else materializes the descriptor and takes the unchanged transactional path
// (D3.2.4v3). `keys` is a caller span of any length up to LAMBDA_PATH_KEYS_MAX:
// the cap used to be three keys, and a deeper typed store (`a.l0[i][j][k].f`)
// then built a heap path array on every write.
Item lambda_container_path_set_checked_keys(Item owner, Item value, const Item* keys,
        int64_t shape, Type* expected, Type* leaf_contract, const char* boundary) {
    int64_t count = shape & 0xff;
    bool inplace = (shape & 0x100) != 0;
    Type* contract = runtime_boundary_unwrap_type(expected);
    if (count < 1 || count > LAMBDA_PATH_KEYS_MAX) {
        return lambda_type_error(value, expected, boundary);
    }
    bool keys_match_leaf = leaf_contract &&
        contract && (contract->type_id == LMD_TYPE_MAP ||
            lambda_array_contract_canonical(contract));
    for (int64_t i = 0; keys_match_leaf && i < count; i++) {
        int64_t ignored = 0;
        if ((shape >> (16 + i)) & 1) {
            keys_match_leaf = lambda_item_to_int64_exact(keys[i], &ignored);
        }
    }
    bool ndim_root = get_type_id(owner) == LMD_TYPE_ARRAY_NUM && owner.array_num->is_ndim;
    if (keys_match_leaf && !ndim_root && lambda_value_rep_proves_contract(owner, contract)) {
        return runtime_map_path_write_proven(owner, ItemNull, count, keys, value,
            leaf_contract, boundary, inplace);
    }
    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_value(roots, value);
    // array_plain may collect; root the caller's keys before building the path
    RootSpan key_roots((size_t)count);
    Item local_keys[LAMBDA_PATH_KEYS_MAX];
    Item* rooted_keys = key_roots.valid() ? key_roots.items() : local_keys;
    for (int64_t i = 0; i < count; i++) rooted_keys[i] = keys[i];
    Rooted<Item> rooted_path(roots, {.array = array_plain()});
    for (int64_t i = 0; i < count; i++) {
        array_push_verbatim(rooted_path.get().array, rooted_keys[i]);
    }
    if (lambda_array_contract_canonical(contract)) {
        return inplace
            ? lambda_array_path_set_checked_inplace(rooted_owner.get(), rooted_path.get(),
                rooted_value.get(), expected, boundary)
            : lambda_array_path_set_checked(rooted_owner.get(), rooted_path.get(),
                rooted_value.get(), expected, boundary);
    }
    return inplace
        ? lambda_map_path_set_checked_inplace(rooted_owner.get(), rooted_path.get(),
            rooted_value.get(), expected, boundary)
        : lambda_map_path_set_checked(rooted_owner.get(), rooted_path.get(),
            rooted_value.get(), expected, boundary);
}

Item lambda_map_path_set_checked_keys(Item owner, Item value, const Item* keys,
        int64_t shape, Type* expected, Type* leaf_contract) {
    return lambda_container_path_set_checked_keys(owner, value, keys, shape, expected,
        leaf_contract, "typed nested map assignment");
}

static Type* runtime_array_contract_element(Type* expected) {
    return runtime_boundary_unwrap_type(lambda_array_contract_element(expected));
}

HASHMAP_DEFINE_PTRKEY_HASH(array_rep_contract, LambdaArrayRepCertCacheEntry, contract,
    hashmap_hash_pointer_fast_identity)

ArrayRepCert* lambda_array_rep_cert_resolve(Type* contract) {
    Pool* pool = eval_context_get_pool();
    if (!pool || !contract) return NULL;
    Heap* heap = context ? context->heap : NULL;
    if (!heap) return lambda_array_rep_cert_create(pool, contract);

    // every spelling stays resolved for this heap lifetime, including modules
    // with more contracts than the old bounded cache could retain
    if (!heap->array_rep_cert_by_contract)
        heap->array_rep_cert_by_contract = array_rep_contract_new(0);
    HashMap* contracts = heap->array_rep_cert_by_contract;
    if (!contracts) return lambda_array_rep_cert_create(pool, contract);
    LambdaArrayRepCertCacheEntry key = {contract, NULL};
    const LambdaArrayRepCertCacheEntry* existing =
        (const LambdaArrayRepCertCacheEntry*)hashmap_get(contracts, &key);
    if (existing) return existing->cert;
    ArrayRepCert* cert = NULL;
    size_t cursor = 0;
    void* item = NULL;
    while (hashmap_iter(contracts, &cursor, &item)) {
        const LambdaArrayRepCertCacheEntry* entry = (const LambdaArrayRepCertCacheEntry*)item;
        if (entry->cert && entry->contract &&
                lambda_array_contract_compatible(entry->contract, contract, true)) {
            cert = entry->cert;
            break;
        }
    }

    if (!cert) cert = lambda_array_rep_cert_create(pool, contract);
    if (!cert) return NULL;
    key.cert = cert;
    hashmap_set(contracts, &key);
    return cert;
}

static bool runtime_array_cert_proves_primitive_values(const ArrayRepCert* cert) {
    // a scalar carrier alone cannot prove a literal element value (D3.3.3v3)
    return cert && (cert->flags & ARRAY_REP_CERT_PRIMITIVE_VALUES);
}

// A packed primitive lane plus an owned exact-rank shape is an exact decoder
// for its matching nested array contract. Keep certificate installation in
// this shared runtime helper so compiler fast paths cannot publish a raw
// ArrayNum to later borrowed-write boundaries (D3.3.3v3, S9.2.2).
static bool runtime_array_admit_primitive_contract(Item value, Type* expected,
        Item* converted) {
    if (!lambda_array_contract_is_plain(expected)) return false;
    if (get_type_id(value) != LMD_TYPE_ARRAY_NUM || !value.array_num) return false;
    // T29-5: intern first -- a warm boundary hits the pointer cache -- and let
    // the certificate's resolved lane and rank decide, instead of re-deriving
    // them from the contract on every fill (nqueens2's per-call admissions)
    ArrayRepCert* cert = lambda_array_rep_cert_resolve(expected);
    if (!runtime_array_cert_proves_primitive_values(cert) ||
            !lambda_array_num_matches_cert(value, cert)) return false;
    lambda_array_install_rep_cert(value, cert);
    *converted = value;
    return true;
}

// The empty array reified straight into `expected`'s certified numeric lane.
// Returns false when the contract has no numeric lane (the caller admits the
// generic empty array through the full check); a lane that fails to certify
// leaves *admitted null.
static bool runtime_array_new_empty_numeric(Type* expected, Item* admitted,
        ArrayRepCert* known_cert = NULL) {
    *admitted = ItemNull;
    ArrayNumElemType element = ELEM_INT;
    if (known_cert && known_cert->rank == 1 && known_cert->has_array_num_lane) {
        element = known_cert->array_num_elem;
    } else {
        Type* element_type = runtime_array_contract_element(expected);
        if (!element_type || !lambda_array_num_elem_type_for_contract(element_type, &element))
            return false;
    }
    ArrayNum* reified = array_num_new(element, 0);
    Item reified_value = {.array_num = reified};
    if (reified && known_cert && lambda_array_num_matches_cert(reified_value, known_cert)) {
        lambda_array_install_rep_cert(reified_value, known_cert);
        *admitted = reified_value;
    } else if (reified) {
        runtime_array_admit_primitive_contract(reified_value, expected, admitted);
    }
    return true;
}

Item lambda_array_admit_numeric_contract(Item value, Type* expected,
        const char* boundary) {
    if (get_type_id(value) == LMD_TYPE_ERROR) return value;
    if (!lambda_array_contract_is_plain(expected))
        return lambda_type_check(value, expected, boundary);

    Item admitted = ItemNull;
    if (runtime_array_admit_primitive_contract(value, expected, &admitted)) {
        return admitted;
    }

    if (get_type_id(value) == LMD_TYPE_ARRAY && value.array &&
            value.array->length == 0 && !value.array->is_view &&
            runtime_array_new_empty_numeric(expected, &admitted)) {
        return admitted.item != ITEM_NULL ? admitted
            : lambda_type_error(value, expected, boundary);
    }

    return lambda_type_check(value, expected, boundary);
}

static bool runtime_try_primitive_fill_length(int64_t length, Item value,
        ArrayRepCert* cert, Item* result) {
    TypeId value_type = get_type_id(value);
    if (runtime_array_cert_proves_primitive_values(cert) && cert->rank == 1 &&
            !(cert->flags & ARRAY_REP_CERT_COUNTED) &&
            ((cert->array_num_elem == ELEM_INT && value_type == LMD_TYPE_INT) ||
             (cert->array_num_elem == ELEM_BOOL && value_type == LMD_TYPE_BOOL) ||
             (cert->array_num_elem == ELEM_FLOAT64 && value_type == LMD_TYPE_FLOAT) ||
             (cert->array_num_elem == ELEM_UINT64 && value_type == LMD_TYPE_UINT64))) {
        // metadata resolution cannot collect; the kernel copies scalar bits before
        // allocation and never reads the source again, so no argument roots are needed
        Item built = lambda_fill_primitive(length, value, cert->array_num_elem);
        if (get_type_id(built) != LMD_TYPE_ERROR) lambda_array_install_rep_cert(built, cert);
        *result = built;
        return true;
    }
    return false;
}

static bool runtime_try_primitive_fill_contract(Item count, Item value, Type* expected,
        ArrayRepCert** resolved, Item* result) {
    if (!lambda_array_contract_is_plain(expected)) { *resolved = NULL; return false; }
    int64_t length = -1;
    ArrayRepCert* cert = get_type_id(value) != LMD_TYPE_ERROR && !item_is_list(value) &&
            lambda_item_to_int64_exact(count, &length) && length >= 0
        ? lambda_array_rep_cert_resolve(expected) : NULL;
    *resolved = cert;
    return runtime_try_primitive_fill_length(length, value, cert, result);
}

bool lambda_try_fill_for_contract(Item count, Item value, Type* expected, Item* result) {
    ArrayRepCert* cert = NULL;
    return runtime_try_primitive_fill_contract(count, value, expected, &cert, result);
}

// A fresh fill can establish its destination certificate before returning;
// the existing admission owns empty, counted and incompatible carrier cases.
Item lambda_fill_for_contract(Item count, Item value, Type* expected, const char* boundary) {
    ArrayRepCert* cert = NULL;
    Item exact = ItemNull;
    if (runtime_try_primitive_fill_contract(count, value, expected, &cert, &exact)) return exact;
    RootSpan argument_roots(2);
    if (!argument_roots.valid()) return ItemError;
    Item* arguments = argument_roots.items();
    arguments[0] = count;
    arguments[1] = value;
    int64_t length = -1;
    if (cert && lambda_item_to_int64_exact(count, &length) && length == 0) {
        Item empty = ItemNull;
        if (runtime_array_new_empty_numeric(expected, &empty, cert) &&
                empty.item != ITEM_NULL) return empty;
    }
    Item filled = fn_fill(arguments[0], arguments[1]);
    // the matching carrier check and publication cannot allocate; only the
    // dynamic admission below needs a live result root
    if (runtime_array_cert_proves_primitive_values(cert) &&
            lambda_array_num_matches_cert(filled, cert)) {
        lambda_array_install_rep_cert(filled, cert);
        return filled;
    }
    RootFrame roots(1);
    Rooted<Item> built(roots, filled);
    return lambda_array_admit_numeric_contract(built.get(), expected, boundary);
}

Item lambda_fill_for_contract_int_lane_resolved(int64_t count, Item value,
        Type* expected, const char* boundary, ArrayRepCert* cert) {
    // the compiler proved a plain primitive T[] destination and an int lane;
    // poison, negative counts and metadata misses retain the full diagnostic path
    if (count >= 0 && count <= INT53_MAX) {
        Item exact = ItemNull;
        if (runtime_try_primitive_fill_length(count, value, cert, &exact)) return exact;
    }
    return lambda_fill_for_contract({.item = i2it(count)}, value, expected, boundary);
}

Item lambda_fill_for_contract_int_lane(int64_t count, Item value, Type* expected,
        const char* boundary) {
    ArrayRepCert* cert = count >= 0 && count <= INT53_MAX
        ? lambda_array_rep_cert_resolve(expected) : NULL;
    return lambda_fill_for_contract_int_lane_resolved(count, value, expected, boundary, cert);
}

// Tune29 §19.1 item 2: `[]` crossing a primitive T[] boundary (`return []`
// from `pn vec_new() int[]`, `var keys: int[] = []`) allocated a generic
// array and then ran the admission ladder to replace it. Build the certified
// ArrayNum directly; any other contract admits the literal as before.
Item lambda_array_empty_for_contract(Type* expected, const char* boundary) {
    Item admitted = ItemNull;
    if (runtime_array_new_empty_numeric(expected, &admitted) &&
            admitted.item != ITEM_NULL) return admitted;
    Array* empty = array();
    return lambda_type_check({.array = empty}, expected, boundary);
}

// A list written into a typed array splices its items there (S2.5.6), so
// each item -- not the list -- crosses the element contract. The admitted
// items stay a list, which the store then splices.
static Item runtime_admit_list_items(Item list, Type* element_type, const char* boundary) {
    RootFrame roots(2);
    Rooted<Item> rooted_list(roots, list);
    Rooted<Array*> rooted_admitted(roots, array_plain());
    if (!rooted_admitted.get()) return ItemError;
    int64_t count = fn_seq_count(list);
    for (int64_t j = 0; j < count; j++) {
        Item checked = lambda_type_check(item_at(rooted_list.get(), j), element_type, boundary);
        if (get_type_id(checked) == LMD_TYPE_ERROR) return checked;
        array_push_verbatim(rooted_admitted.get(), checked);
    }
    rooted_admitted.get()->is_spreadable = 1;
    return {.array = rooted_admitted.get()};
}

static Item lambda_array_set_checked_impl(Item owner, int64_t index, Item value, Type* expected,
        const char* boundary, bool publish_in_place, const LaneStorageDesc* lane_hint,
        Type* element_hint = NULL, bool uncounted_primitive = false) {
    if (cow_profile_enabled()) {
        g_cow_profile.array_checked_store_calls++;
        if (publish_in_place) g_cow_profile.array_checked_store_unique_inplace++;
    }
    ArrayNum* direct = get_type_id(owner) == LMD_TYPE_ARRAY_NUM ? owner.array_num : NULL;
    if (direct && direct->rep_cert && !direct->is_ndim && !direct->is_view &&
            !direct->is_static && !direct->is_immortal &&
            !(direct->cow_state & COW_STATE_SHARED) && index >= 0 && index < direct->length) {
        Type* leaf = direct->rep_cert->leaf_element;
        // a bounded scalar write preserves rank/count; refined leaves retain admission
        if ((leaf == &TYPE_INT || leaf == &TYPE_BOOL || leaf == &TYPE_FLOAT) &&
                get_type_id(value) == leaf->type_id &&
                (uncounted_primitive
                    ? lambda_array_rep_proves_uncounted_primitive(owner, element_hint)
                    : lambda_array_rep_proves(owner, expected, true))) {
            if (!publish_in_place) (void)cow_prepare_write(owner); // unique; diagnostic accounting only
            if (array_num_store_admitted(direct, index, value)) {
                if (cow_profile_enabled()) g_cow_profile.array_checked_store_direct++;
                return owner;
            }
        }
    }
    // An annotated array owns a clean element contract. Create the candidate
    // before touching the original so a bad dynamic value cannot trigger
    // ArrayNum-to-Array degradation or leak through a COW snapshot.
    Type* element_type = element_hint ? element_hint : runtime_array_contract_element(expected);
    if (!element_type) return lambda_type_error(value, expected, boundary);
    Item checked_value = item_is_list(value)
        ? runtime_admit_list_items(value, element_type, boundary)
        : lambda_value_rep_proves_contract(value, element_type) ? value
            : lambda_type_check(value, element_type, boundary);
    if (get_type_id(checked_value) == LMD_TYPE_ERROR) return checked_value;

    // A lane tag proves neither rank nor a named record's field layout. Admit
    // an erased source before the checked write; in-place pn stores cannot
    // replace their ABI-owned object and must already carry this proof.
    if (!lambda_array_rep_proves(owner, expected, true)) {
        if (publish_in_place) return lambda_type_error(owner, expected, boundary);
        Item admitted_owner = ItemNull;
        if (!runtime_type_admit_array(owner, expected, &admitted_owner)) {
            return lambda_type_error(owner, expected, boundary);
        }
        owner = admitted_owner;
    }

    LaneStorageDesc lane_desc = {};
    bool has_lane_contract = false;
    if (lane_hint) {
        lane_desc = *lane_hint;
        has_lane_contract = true;
    } else {
        has_lane_contract = lambda_type_array_lane_storage_desc(element_type, &lane_desc);
    }
    bool owner_representation_proven = has_lane_contract &&
        runtime_array_representation_matches_contract(owner, &lane_desc);
    if (publish_in_place && !owner_representation_proven &&
            !lambda_type_matches(owner, expected)) {
        return lambda_type_error(owner, expected, boundary);
    }

    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_value(roots, checked_value);
    Item candidate = publish_in_place ? rooted_owner.get() :
        cow_prepare_write(rooted_owner.get());
    Rooted<Item> rooted_candidate(roots, candidate);
    if (!publish_in_place && cow_profile_enabled() &&
            rooted_candidate.get().item != rooted_owner.get().item) {
        if (get_type_id(rooted_owner.get()) == LMD_TYPE_ARRAY_NUM) {
            g_cow_profile.array_checked_store_full_clone++;
        } else {
            g_cow_profile.array_checked_store_cow_detach++;
        }
        g_cow_profile.array_checked_store_bytes_copied +=
            cow_one_level_copy_bytes(rooted_owner.get());
    }
    TypeId candidate_type = get_type_id(rooted_candidate.get());
    if (candidate_type != LMD_TYPE_ARRAY && candidate_type != LMD_TYPE_ARRAY_NUM &&
            candidate_type != LMD_TYPE_ELEMENT) {
        return lambda_type_error(rooted_owner.get(), expected, boundary);
    }
    if (candidate_type == LMD_TYPE_ARRAY_NUM && array_native_lane_supported(&lane_desc) &&
            !runtime_array_representation_matches_contract(rooted_candidate.get(), &lane_desc)) {
        if (publish_in_place) {
            // The current pn-var ABI owns an ArrayNum pointer. Publishing an
            // Array replacement needs a separate ABI transition, so reject it.
            set_runtime_error(ERR_TYPE_MISMATCH,
                "nullable native array write through pn var is not implemented");
            return ItemError;
        }
        Item rebuilt = ItemNull;
        if (cow_profile_enabled()) g_cow_profile.array_checked_store_rebuild++;
        if (!array_rebuild_native_lane(rooted_candidate.get(), &lane_desc, &rebuilt)) {
            return lambda_type_error(rooted_candidate.get(), expected, boundary);
        }
        rooted_candidate.set(rebuilt);
        candidate_type = LMD_TYPE_ARRAY;
    }
    // fn_array_set deliberately clears a proof for raw callers. Retain the
    // old exact certificate across this already-admitted write so hot typed
    // loops do not allocate a replacement proof per element (D3.3.3).
    ArrayRepCert* prior_cert = rooted_candidate.get().array->rep_cert;
    // COW preserves the admitted layout. A bounded scalar store cannot change
    // its rank, count or lane, so retain that certificate (D3.3.3v3).
    if (candidate_type == LMD_TYPE_ARRAY_NUM && owner_representation_proven &&
            prior_cert && prior_cert == rooted_owner.get().array->rep_cert &&
            !rooted_candidate.get().array_num->is_ndim &&
            !rooted_candidate.get().array_num->is_view &&
            !rooted_candidate.get().array_num->is_static &&
            index >= 0 && index < rooted_candidate.get().array_num->length &&
            array_num_store_admitted(rooted_candidate.get().array_num, index,
                rooted_value.get())) {
        if (cow_profile_enabled()) g_cow_profile.array_checked_store_direct++;
        return rooted_candidate.get();
    }
    Item set_result = fn_array_set(rooted_candidate.get().array, index, rooted_value.get());
    if (get_type_id(set_result) == LMD_TYPE_ERROR) return set_result;
    bool post_store_proven = has_lane_contract &&
        runtime_array_representation_matches_contract(rooted_candidate.get(), &lane_desc);
    if (cow_profile_enabled() && post_store_proven) {
        g_cow_profile.array_checked_store_direct++;
    }
    if (!post_store_proven && !lambda_type_matches(rooted_candidate.get(), expected)) {
        ValidationResult* validation = NULL;
        (void)runtime_validate_value_against_type(rooted_candidate.get(), expected, &validation);
        // The validator inspected the rebuilt array. Reporting only the leaf
        // value hid that candidate context even though its path identifies the
        // failed index.
        return lambda_type_error_with_validation(rooted_candidate.get(), expected, boundary,
            validation);
    }
    ArrayRepCert* cert = prior_cert && prior_cert->array_contract &&
            (prior_cert->array_contract == lambda_array_contract_canonical(expected) ||
             lambda_array_contract_compatible(prior_cert->array_contract, expected, true))
        ? prior_cert : lambda_array_rep_cert_resolve(expected);
    if (!cert) return lambda_type_error(rooted_candidate.get(), expected, boundary);
    lambda_array_install_rep_cert(rooted_candidate.get(), cert);
    return rooted_candidate.get();
}

