}

static Item lambda_array_push_checked_impl(Item owner, Item value, Type* expected,
        const char* boundary, bool publish_in_place) {
    Type* element_type = runtime_array_contract_element(expected);
    if (!element_type) return lambda_type_error(value, expected, boundary);
    if (item_is_list(value)) {
        // S2.5.6: a pushed list splices. Every item is admitted before the
        // first is pushed, so a bad item cannot leave a partial append.
        RootFrame roots(2);
        Rooted<Item> rooted_owner(roots, owner);
        Rooted<Item> rooted_items(roots, runtime_admit_list_items(value, element_type,
            boundary));
        if (item_is_error(rooted_items.get())) return rooted_items.get();
        int64_t count = fn_seq_count(rooted_items.get());
        for (int64_t j = 0; j < count; j++) {
            Item next = lambda_array_push_checked_impl(rooted_owner.get(),
                item_at(rooted_items.get(), j), expected, boundary, publish_in_place);
            if (item_is_error(next)) return next;
            rooted_owner.set(next);
        }
        return rooted_owner.get();
    }

    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_value(roots, value);
    Rooted<Item> rooted_candidate(roots, ItemNull);
    Item admitted_value = lambda_type_check(rooted_value.get(), element_type, boundary);
    if (item_is_error(admitted_value)) return admitted_value;
    rooted_value.set(admitted_value);

    if (!lambda_array_rep_proves(rooted_owner.get(), expected, true)) {
        if (publish_in_place) return lambda_type_error(rooted_owner.get(), expected, boundary);
        Item admitted_owner = ItemNull;
        if (!runtime_type_admit_array(rooted_owner.get(), expected, &admitted_owner)) {
            return lambda_type_error(rooted_owner.get(), expected, boundary);
        }
        rooted_owner.set(admitted_owner);
    }

    rooted_candidate.set(publish_in_place ? rooted_owner.get() :
        cow_prepare_write(rooted_owner.get()));
    TypeId candidate_type = get_type_id(rooted_candidate.get());
    if (candidate_type == LMD_TYPE_ARRAY_NUM) {
        ArrayNum* array = rooted_candidate.get().array_num;
        if (array->is_view || array->is_ndim || array->length == INT64_MAX) {
            return lambda_type_error(rooted_candidate.get(), expected, boundary);
        }
        ArrayNum* grown = array_num_reserve_capacity(array, array->length + 1);
        if (!grown) return lambda_type_error(rooted_candidate.get(), expected, boundary);
        rooted_candidate.set({.array_num = grown});
        array = rooted_candidate.get().array_num;
        if (!array_num_store_admitted(array, array->length, rooted_value.get())) {
            return lambda_type_error(rooted_value.get(), element_type, boundary);
        }
    } else if (candidate_type == LMD_TYPE_ARRAY) {
        Array* array = rooted_candidate.get().array;
        if (!array || array->is_view || array->length == INT64_MAX ||
                !array_reserve_append_slots(array, 1)) {
            return lambda_type_error(rooted_candidate.get(), expected, boundary);
        }
        array = rooted_candidate.get().array;
        if (array_has_native_lane(array)) {
            if (!array_native_lane_store(array, array->length, rooted_value.get())) {
                return lambda_type_error(rooted_value.get(), element_type, boundary);
            }
        } else {
            array_set(array, array->length, rooted_value.get());
        }
        array->length++;
    } else {
        return lambda_type_error(rooted_candidate.get(), expected, boundary);
    }

    if (!lambda_array_rep_proves(rooted_candidate.get(), expected, true)) {
        ArrayRepCert* cert = lambda_array_rep_cert_resolve(expected);
        if (!cert) return lambda_type_error(rooted_candidate.get(), expected, boundary);
        lambda_array_install_rep_cert(rooted_candidate.get(), cert);
    }
    return rooted_candidate.get();
}

Item lambda_array_push_checked(Item owner, Item value, Type* expected,
        const char* boundary) {
    return lambda_array_push_checked_impl(owner, value, expected, boundary, false);
}

Item lambda_array_push_checked_inplace(Item owner, Item value, Type* expected,
        const char* boundary) {
    return lambda_array_push_checked_impl(owner, value, expected, boundary, true);
}

// CW32v2: numeric mask stores (`arr[mask] = v`) mutate the packed buffer in
// place. Under mark-only binds the owner may be shared, so the wrapper
// prepares first and returns the (possibly replaced) owner for mandatory
// republication -- the raw fn_index_assign keeps reference semantics (CW21).
Item index_assign_cow(Item owner, Item key, Item value) {
    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_key(roots, key);
    Rooted<Item> rooted_value(roots, value);
    Item replacement = cow_prepare_write(rooted_owner.get());
    if (get_type_id(replacement) == LMD_TYPE_ERROR) return replacement;
    rooted_owner.set(replacement);
    Item result = fn_index_assign(rooted_owner.get(), rooted_key.get(),
        rooted_value.get());
    if (item_is_error(result)) return result;
    return rooted_owner.get();
}

// CW32v2: the MIR lane-store cold arm's entry -- machine index, no key
// decode. Prepares (detaching a shared owner with one packed memcpy), then
// delegates to the raw setter (CW21) and returns the owner for mandatory
// republication into the binding.
Item array_num_set_cow_idx(Item owner, int64_t index, Item value) {
    Item replacement = cow_prepare_write(owner);
    if (get_type_id(replacement) == LMD_TYPE_ERROR) return replacement;
    TypeId type_id = get_type_id(replacement);
    if (type_id != LMD_TYPE_ARRAY && type_id != LMD_TYPE_ARRAY_NUM) {
        log_error("cow lane store rejected non-array owner type %d", type_id);
        return ItemError;
    }
    if (fn_array_set(replacement.array, index, value).item == ItemError.item) return ItemError;
    return replacement;
}

Item array_set_cow(Item owner, Item key, Item value) {
    Item replacement = cow_prepare_write(owner);
    if (get_type_id(replacement) == LMD_TYPE_ERROR) return replacement;
    TypeId type_id = get_type_id(replacement);
    if (type_id != LMD_TYPE_ARRAY && type_id != LMD_TYPE_ARRAY_NUM &&
            type_id != LMD_TYPE_ELEMENT) {
        log_error("cow array mutation rejected non-array owner type %d", type_id);
        return ItemError;
    }
    int64_t index = 0;
    if (!lambda_item_to_int64_exact(key, &index)) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "invalid sequence member write: key must be an exact integer");
        return ItemError;
    }
    // COW receives the semantic Item value from a procedural assignment. The
    // canonical setter must decide whether the compact lane can admit it or
    // whether the array must widen; calling array_num_set_item directly would
    // coerce an incompatible value and silently lose the required Item shape.
    if (fn_array_set(replacement.array, index, value).item == ItemError.item) return ItemError;
    return replacement;
}

Item member_set_cow(Item owner, Item key, Item value) {
    Item replacement = cow_prepare_write(owner);
    if (get_type_id(replacement) == LMD_TYPE_ERROR) return replacement;

    Item result = fn_index_set(replacement, key, value);
    if (get_type_id(result) == LMD_TYPE_ERROR) return result;
    return replacement;
}

Item map_set_cow(Item owner, Item key, Item value) {
    Item replacement = cow_prepare_write(owner);
    if (get_type_id(replacement) == LMD_TYPE_ERROR) return replacement;
    TypeId type_id = get_type_id(replacement);
    if (type_id != LMD_TYPE_MAP &&
            type_id != LMD_TYPE_ELEMENT && type_id != LMD_TYPE_VMAP) {
        log_error("cow map mutation rejected non-map owner type %d", type_id);
        return ItemError;
    }
    if (type_id == LMD_TYPE_VMAP) return vmap_set_cow(replacement, key, value);
    Item result = fn_map_set(replacement, key, value);
    if (get_type_id(result) == LMD_TYPE_ERROR) return result;
    return replacement;
}

// Diagnostic entries carry the MIR call PC through a native setter without
// putting stack inspection in the ordinary helper path.
static Item cow_profile_set_with_caller(Item owner, Item key, Item value,
        uintptr_t caller, Item (*setter)(Item, Item, Item)) {
    TypeId type_id = get_type_id(owner);
    CowProfileTypeCounters* counters = cow_profile_for(owner);
    uint64_t unique_before = counters ? counters->unique_mutations : 0;
    uint64_t copies_before = counters ? counters->shared_copies : 0;
    uint64_t bytes_before = counters ? counters->copied_bytes : 0;
    Item result = setter(owner, key, value);
    if (counters) {
        cow_profile_note_site(COW_SITE_UNIQUE_WRITE, type_id, caller,
            counters->unique_mutations - unique_before);
        cow_profile_note_site(COW_SITE_SHARED_COPY, type_id, caller,
            counters->shared_copies - copies_before,
            counters->copied_bytes - bytes_before);
    }
    return result;
}

Item map_set_cow_profiled(Item owner, Item key, Item value) {
    return cow_profile_set_with_caller(owner, key, value,
        COW_PROFILE_CALLER(), map_set_cow);
}

Item member_set_cow_profiled(Item owner, Item key, Item value) {
    return cow_profile_set_with_caller(owner, key, value,
        COW_PROFILE_CALLER(), member_set_cow);
}

Item cow_path_set_raw(Item owner, Item key, Item value) {
    // The compiler links each copied child before descending, so this helper
    // must remain a rooted raw write and never perform another COW decision.
    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_key(roots, key);
    Rooted<Item> rooted_value(roots, value);
    TypeId owner_type = get_type_id(rooted_owner.get());
    int64_t index = 0;
    if ((owner_type == LMD_TYPE_ARRAY || owner_type == LMD_TYPE_ELEMENT ||
            owner_type == LMD_TYPE_ARRAY_NUM) &&
            lambda_item_to_int64_exact(rooted_key.get(), &index)) {
        // The common setter checks logical bounds and stores admitted integer
        // lanes exactly; the legacy coercing setter loses full-width bits.
        if (get_type_id(fn_array_set(rooted_owner.get().array, index,
                rooted_value.get())) == LMD_TYPE_ERROR) {
            return ItemError;
        }
        return rooted_owner.get();
    }
    if (owner_type == LMD_TYPE_MAP ||
            owner_type == LMD_TYPE_ELEMENT || owner_type == LMD_TYPE_VMAP) {
        if (owner_type == LMD_TYPE_MAP &&
                !runtime_named_map_field((Type*)lambda_attr_shape(owner_type,
                        rooted_owner.get().map),
                    rooted_key.get()) &&
                !map_extend_open_shape(rooted_owner.get(), rooted_key.get(),
                    rooted_value.get())) {
            log_error("cow path mutation could not extend map shape");
            return ItemError;
        }
        fn_map_set(rooted_owner.get(), rooted_key.get(), rooted_value.get());
        return rooted_owner.get();
    }
    log_error("cow path mutation rejected owner type %d", owner_type);
    return ItemError;
}

// CW25 / S9.2.2: a `var` argument that names a PLACE (`f(var m.rows[i])`) must
// borrow that place, and "creating a mutable borrow over shared storage
// un-shares first". Both tiers already detach the borrowed ROOT before the
// call and then let the callee mutate in place -- no replacement channel is
// needed because `var` parameters use the in-place setters. A path borrow is
// the same protocol one level deeper: detach every link from the root down to
// the leaf, reinstalling each replacement in its parent, and hand the callee
// the detached leaf. It is already installed where it belongs, so the callee's
// in-place writes land in the caller's container and no writeback is required.
//
// `owner` must already be the caller's detached root.  `path` selects the
// dynamic descriptor form; otherwise `fixed_count` keys arrive in a caller span
// (rooted here, since the caller's memory need not be GC-visible).  Keeping one
// walker makes both ABI shapes obey the same S9.2.2 ownership and shape checks.
// `value_leaf` serves a builtin mutator's place (`push(m.a, v)`): a link that
// holds no container ends the walk and is returned as the value the mutator
// would have read, so the mutator reports its own error exactly as before.
static Item cow_path_borrow_impl(Item owner, Item path, int64_t fixed_count,
        const Item* fixed_keys, bool value_leaf = false) {
    bool dynamic_path = get_type_id(path) != LMD_TYPE_NULL;
    if (dynamic_path && (get_type_id(path) != LMD_TYPE_ARRAY || !path.array ||
            path.array->length <= 0)) {
        log_error("cow path borrow requires a non-empty array path");
        return ItemError;
    }
    if (!dynamic_path && (fixed_count < 1 || fixed_count > LAMBDA_PATH_KEYS_MAX)) {
        log_error("cow fixed path borrow requires 1..%d keys", (int)LAMBDA_PATH_KEYS_MAX);
        return ItemError;
    }
    RootFrame roots(5);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_path(roots, path);
    Rooted<Item> rooted_current(roots, owner);
    Rooted<Item> rooted_child(roots, ItemNull);
    Rooted<Item> rooted_key(roots, ItemNull);
    // a GC-free context (no runtime) has no span and needs no root
    RootSpan key_roots(dynamic_path ? 0 : (size_t)fixed_count);
    Item local_keys[LAMBDA_PATH_KEYS_MAX];
    Item* fixed_rooted = dynamic_path ? NULL
        : key_roots.valid() ? key_roots.items() : local_keys;
    for (int64_t i = 0; !dynamic_path && i < fixed_count; i++) {
        fixed_rooted[i] = fixed_keys[i];
    }
    int64_t count = dynamic_path ? rooted_path.get().array->length : fixed_count;

    for (int64_t i = 0; i < count; i++) {
        rooted_key.set(dynamic_path ? item_at(rooted_path.get(), i) : fixed_rooted[i]);
        if (get_type_id(rooted_key.get()) == LMD_TYPE_NULL) {
            return value_leaf ? ItemNull : ItemError;
        }
        rooted_child.set(fn_index(rooted_current.get(), rooted_key.get()));
        if (!cow_item_is_container(rooted_child.get())) {
            if (value_leaf) return rooted_child.get();
            // A borrow of a scalar slot has no storage to write through; the
            // caller must reject it rather than hand the callee a value copy.
            log_error("cow path borrow encountered a non-container link");
            return ItemError;
        }
        Item pre_detach = rooted_child.get();
        rooted_child.set(cow_prepare_write(rooted_child.get()));
        if (get_type_id(rooted_child.get()) == LMD_TYPE_ERROR) return ItemError;
        if (rooted_child.get().item != pre_detach.item &&
                get_type_id(cow_path_set_raw(rooted_current.get(), rooted_key.get(),
                    rooted_child.get())) == LMD_TYPE_ERROR) return ItemError;
        rooted_current.set(rooted_child.get());
    }
    return rooted_current.get();
}

Item cow_path_borrow(Item owner, Item path) {
    return cow_path_borrow_impl(owner, path, 0, NULL);
}

Item cow_path_borrow_fixed(Item owner, int64_t count, Item key0, Item key1,
        Item key2) {
    Item keys[3] = {key0, key1, key2};
    return cow_path_borrow_impl(owner, ItemNull, count, keys);
}

// the key-span form, for a descriptor of any length the compiler evaluated
Item cow_path_borrow_keys(Item owner, const Item* keys, int64_t count) {
    return cow_path_borrow_impl(owner, ItemNull, count, keys);
}

// Tune31 Phase III A1: a typed `var record.field` borrow can read its known
// packed field directly. A changed carrier retains the fixed generic walk, so
// the layout is still checked at the runtime boundary (D3.3.3v3, D4.4.4v4).
Item cow_path_borrow_typed_map_field(Item owner, TypeMap* expected_shape,
        ShapeEntry* expected_field, Item fallback_key) {
    if (get_type_id(owner) != LMD_TYPE_MAP || !owner.map ||
            owner.map->type != expected_shape || !expected_field ||
            expected_field->byte_offset < 0 || !owner.map->data ||
            !shape_entry_storage_fits_data(expected_field, owner.map->data_cap)) {
        return cow_path_borrow_fixed(owner, 1, fallback_key, ItemNull, ItemNull);
    }

    RootFrame roots(4);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_key(roots, fallback_key);
    Rooted<Item> rooted_child(roots, map_shape_field_to_item(owner.map->data,
        expected_field));
    if (!cow_item_is_container(rooted_child.get())) {
        // Preserve the ordinary helper's diagnostic and error transport for a
        // malformed typed carrier instead of treating it as an unchecked slot.
        return cow_path_borrow_fixed(rooted_owner.get(), 1, rooted_key.get(),
            ItemNull, ItemNull);
    }

    Item pre_detach = rooted_child.get();
    rooted_child.set(cow_prepare_write(rooted_child.get()));
    if (get_type_id(rooted_child.get()) == LMD_TYPE_ERROR) return ItemError;
    if (rooted_child.get().item == pre_detach.item) return rooted_child.get();

    // `cow_prepare_write` may collect. Reload the rooted map and its data
    // before storing the detached child (D4.4.4v4, D5.3.1-4).
    Map* live_owner = rooted_owner.get().map;
    if (!live_owner || live_owner->type != expected_shape || !live_owner->data ||
            !shape_entry_storage_fits_data(expected_field, live_owner->data_cap)) {
        return ItemError;
    }
    void* field_ptr = map_field_ptr(live_owner->data, expected_field);
    if (!map_shape_field_store_native_lane(field_ptr, expected_field,
            rooted_child.get()) && !map_field_store(field_ptr, rooted_child.get(),
            shape_entry_storage_type_id(expected_field))) {
        return ItemError;
    }
    return rooted_child.get();
}

// S9.2.2 for builtin in-place mutators: the same spine detach as a `var`
// place borrow, yielding the installed private leaf -- or, for a place that
// holds no container, the value itself for the mutator to reject.
Item cow_place_leaf(Item owner, Item path) {
    return cow_path_borrow_impl(owner, path, 0, NULL, true);
}

Item cow_place_leaf_fixed(Item owner, int64_t count, Item key0, Item key1,
        Item key2) {
    Item keys[3] = {key0, key1, key2};
    return cow_path_borrow_impl(owner, ItemNull, count, keys, true);
}

Item cow_place_leaf_keys(Item owner, const Item* keys, int64_t count) {
    return cow_path_borrow_impl(owner, ItemNull, count, keys, true);
}

// NM-O8: `publish_in_place` skips the ROOT detach. A `var` parameter's root was
// already detached by the caller before the call, and a plain `pn` parameter
// writes through to the caller under the current pn ABI -- which is exactly the
// selection the FLAT member/element store already makes via
// `is_var_param` (lambda_map_set_checked_inplace). The nested
// path store never made it, so it detached the callee's own root and published
// the replacement into the callee's binding: `b.xs[0] = 99` was visible inside
// the procedure and lost at the caller, while `b.cur = "X"` was not. Children
// are still detached and reinstalled either way; only the root is left alone.
// `path` selects the dynamic descriptor; a NULL path takes `fixed_count` rooted
// keys instead, the same two ABI shapes cow_path_borrow_impl accepts (T27-4).
// T29-5: an index path whose owner is a packed N-D ArrayNum (a comprehension
// of equal numeric rows builds one) stores the leaf at its full coordinate.
// The per-link walk materialized a row view per store through fn_index only
// to write through it into the same buffer -- an allocation per write. The
// owner must already be prepared (unique, or a caller-detached `var` root).
// Anything this does not cover -- a rank mismatch, a view, an out-of-range
// coordinate, a value outside the lane -- returns false with no effect, and
// the caller's per-link walk keeps its semantics and diagnostics.
static bool cow_packed_index_store(Item owner, int64_t count, const Item* keys,
        Item value) {
    if (get_type_id(owner) != LMD_TYPE_ARRAY_NUM || count < 2 ||
            count > LAMBDA_ARRAY_NUM_MAX_NDIM) return false;
    ArrayNum* arr = owner.array_num;
    if (!arr || !arr->is_ndim || arr->is_view || arr->is_static) return false;
    ArrayNumShape* shape = (ArrayNumShape*)(uintptr_t)arr->extra;
    if (!shape || shape->ndim != count || shape->base) return false;
    int64_t* dims = array_num_shape_dims(shape);
    int64_t* strides = array_num_shape_strides(shape);
    int64_t offset = 0;
    for (int64_t axis = 0; axis < count; axis++) {
        int64_t index = 0;
        if (!lambda_item_to_int64_exact(keys[axis], &index) || index < 0 ||
                index >= dims[axis]) return false;
        offset += index * strides[axis];
    }
    // the same certificate rule as fn_array_set: keep the proof only when the
    // stored value proves the certified leaf element
    ArrayRepCert* prior_cert = arr->rep_cert;
    LambdaArrayContractInfo info = {};
    bool preserve_cert = prior_cert && prior_cert->array_contract &&
        lambda_array_contract_info(prior_cert->array_contract, &info) &&
        info.leaf_element && lambda_value_rep_proves_contract(value, info.leaf_element);
    if (!array_num_store_admitted(arr, offset, value)) return false;
    if (!preserve_cert) lambda_array_clear_rep_cert(owner);
    return true;
}

int64_t cow_path_set_packed_index(Item owner, int64_t count, Item key0, Item key1,
        Item key2, Item value) {
    Item keys[3] = {key0, key1, key2};
    return count <= 3 && cow_packed_index_store(owner, count, keys, value) ? 1 : 0;
}

static Item cow_path_set_impl(Item owner, Item path, int64_t fixed_count,
        const Item* fixed_keys, Item value, bool publish_in_place) {
    bool dynamic_path = get_type_id(path) != LMD_TYPE_NULL;
    if (dynamic_path && (get_type_id(path) != LMD_TYPE_ARRAY || !path.array ||
            path.array->length <= 0)) {
        log_error("cow path mutation requires a non-empty array path");
        return ItemError;
    }
    if (!dynamic_path && (fixed_count < 1 || fixed_count > LAMBDA_PATH_KEYS_MAX)) {
        log_error("cow fixed path mutation requires 1..%d keys", (int)LAMBDA_PATH_KEYS_MAX);
        return ItemError;
    }

    // Every spine link may allocate while it is detached, so all live owners,
    // keys, and the incoming value need exact roots across raw setter calls.
    RootFrame roots(7);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_path(roots, path);
    Rooted<Item> rooted_value(roots, value);
    Rooted<Item> rooted_current(roots, ItemNull);
    Rooted<Item> rooted_child(roots, ItemNull);
    Rooted<Item> rooted_key(roots, ItemNull);
    Rooted<Item> rooted_replacement(roots, ItemNull);
    // fixed keys arrive in caller memory the collector cannot see; a GC-free
    // context (no runtime) has no span and needs no root, as for RootFrame
    RootSpan key_roots(dynamic_path ? 0 : (size_t)fixed_count);
    Item local_keys[LAMBDA_PATH_KEYS_MAX];
    Item* fixed_rooted = dynamic_path ? NULL
        : key_roots.valid() ? key_roots.items() : local_keys;
    for (int64_t i = 0; !dynamic_path && i < fixed_count; i++) {
        fixed_rooted[i] = fixed_keys[i];
    }
    int64_t count = dynamic_path ? rooted_path.get().array->length : fixed_count;

    rooted_current.set(publish_in_place ? rooted_owner.get()
                                        : cow_prepare_write(rooted_owner.get()));
    if (get_type_id(rooted_current.get()) == LMD_TYPE_ERROR) return ItemError;
    // The top-level replacement survives every child detach; returning an
    // unrooted local here used a pre-compaction address for nested writes.
    rooted_replacement.set(rooted_current.get());
    if (count >= 2 && count <= LAMBDA_ARRAY_NUM_MAX_NDIM &&
            get_type_id(rooted_current.get()) == LMD_TYPE_ARRAY_NUM) {
        // T29-5: a packed N-D owner takes the whole coordinate at once
        Item packed_keys[LAMBDA_ARRAY_NUM_MAX_NDIM];
        for (int64_t i = 0; i < count; i++) {
            packed_keys[i] = dynamic_path ? item_at(rooted_path.get(), i)
                : fixed_rooted[i];
        }
        if (cow_packed_index_store(rooted_current.get(), count, packed_keys,
                rooted_value.get())) {
            return rooted_replacement.get();
        }
    }

    for (int64_t i = 0; i < count; i++) {
        rooted_key.set(dynamic_path ? item_at(rooted_path.get(), i) : fixed_rooted[i]);
        if (get_type_id(rooted_key.get()) == LMD_TYPE_NULL) return ItemError;
        if (i + 1 == count) {
            if (get_type_id(cow_path_set_raw(rooted_current.get(), rooted_key.get(), rooted_value.get())) ==
                    LMD_TYPE_ERROR) return ItemError;
            return rooted_replacement.get();
        }

        rooted_child.set(fn_index(rooted_current.get(), rooted_key.get()));
        if (!cow_item_is_container(rooted_child.get()) &&
                get_type_id(rooted_child.get()) != LMD_TYPE_ARRAY_NUM) {
            log_error("cow path mutation encountered a non-container child");
            return ItemError;
        }
        Item pre_detach = rooted_child.get();
        rooted_child.set(cow_prepare_write(rooted_child.get()));
        if (get_type_id(rooted_child.get()) == LMD_TYPE_ERROR) return ItemError;
        // Reinstall only when the child actually moved. In the steady state
        // the whole spine is already unique, so cow_prepare_write is the
        // identity and this store would rewrite the slot with the value it
        // already holds -- a dynamic shape lookup per link per write, wasted.
        if (rooted_child.get().item != pre_detach.item &&
                get_type_id(cow_path_set_raw(rooted_current.get(), rooted_key.get(),
                    rooted_child.get())) == LMD_TYPE_ERROR) return ItemError;
        rooted_current.set(rooted_child.get());
    }
    return ItemError;
}

Item cow_path_set_keys(Item owner, Item value, const Item* keys, int count, bool inplace) {
    return cow_path_set_impl(owner, ItemNull, count, keys, value, inplace);
}

Item cow_path_set(Item owner, Item path, Item value) {
    return cow_path_set_impl(owner, path, 0, NULL, value, false);
}

Item cow_path_set_inplace(Item owner, Item path, Item value) {
    return cow_path_set_impl(owner, path, 0, NULL, value, true);
}

// A shape rebuild's replacement data buffer: the GC data zone for a heap
// container, the runtime pool for a markup one (never the input pool that owns
// its original data).
static void* container_rebuild_data_alloc(const Container* container, int64_t byte_size) {
    size_t bytes = byte_size > 0 ? (size_t)byte_size : 1;
    return container->is_heap ? heap_data_calloc(bytes)
        : pool_calloc(context->pool, bytes);
}

// Publish a rebuilt data buffer and retire the old one by its allocator: GC data
// is abandoned to the collector, a markup container's earlier runtime-pool
// migration is freed, and input-pool data is left to its input's lifecycle.
static void container_rebuild_data_install(Container* container, void** data_slot,
        int* cap_slot, void* new_data, int64_t byte_size) {
    void* old_data = *data_slot;
    *data_slot = new_data;
    *cap_slot = (int)byte_size;
    if (container->is_heap) return;
    if (old_data && container->is_data_migrated) pool_free(context->pool, old_data);
    // mark data as migrated for future mutations
    container->is_data_migrated = 1;
}

// rebuild a map/element shape when a field's type changes
// creates new ShapeEntry chain + TypeMap/TypeElmt, allocates new data buffer, copies fields
// For markup containers (!is_heap), uses runtime pool instead of calloc/free to avoid
// corrupting input pool memory. The is_data_migrated flag tracks this transition.
// D3.4.5: move a container's fields from `old_map_type` onto `new_type` --
// the same fields in order, `changed_entry` laid out anew and holding
// `new_value` -- and install the pair. This is the shared half of a
// type-changing write, whether `new_type` is a private rebuild or a shared
// tree target (Impl_Map_Transition_Coverage P2).
static bool container_move_to_type(void** type_slot, void** data_slot, int* cap_slot,
        Container* container, TypeMap* old_map_type, TypeMap* new_type,
        ShapeEntry* changed_entry, Item new_value, int fixed_slot_count, ShapeEntry* removed_entry = NULL,
        const TypeMapRetypePlan* plan = NULL) {
    // a heap-owned payload can stay in place when every surviving field keeps its lane.
    // validate the entire layout before the no-GC value/type commit (D3.4.5, D5.3).
    if (container->is_heap && *data_slot && !fixed_slot_count &&
            new_type->byte_size <= *cap_slot) {
        ShapeEntry* replacement = plan ? plan->replacement : NULL;
        bool compatible = plan ? plan->reuse_payload :
            typemap_payload_reusable(old_map_type, new_type, changed_entry, removed_entry, &replacement);
        // the immutable plan already classified this lane with the shared storage resolver.
        TypeId storage = replacement ? (plan ? plan->storage_type : shape_entry_storage_type_id(replacement)) : LMD_TYPE_NULL;
        // these simple stores neither allocate nor retain a borrowed numeric home.
        bool immediate_store = !replacement || (replacement->type == type_info[storage].type &&
            (storage == LMD_TYPE_INT || storage == LMD_TYPE_FLOAT || storage == LMD_TYPE_NULL ||
             storage == LMD_TYPE_BOOL || storage == LMD_TYPE_UNDEFINED || storage == LMD_TYPE_STRING ||
             storage == LMD_TYPE_ARRAY || storage == LMD_TYPE_MAP));
        if (compatible && immediate_store && (!changed_entry || replacement)) {
            uint64_t value_home = 0;
            Item held = lambda_item_adopt_scalar_home(new_value, &value_home);
            if (replacement && !map_field_store((char*)*data_slot + replacement->byte_offset, held, storage))
                return false;
            *type_slot = new_type;
            return true;
        }
    }
    void* old_data = NULL;
    int64_t new_byte_size = new_type->byte_size;
    int field_index = 0;
    // allocate new data buffer
    // Shape rebuild is already a cold path. A structured frame avoids leaving
    // registered native addresses behind on a non-local recovery edge while
    // keeping both unpublished owners exact through the data allocation.
    RootFrame roots(2);
    if (!roots.valid()) return false;
    Rooted<Container*> rooted_container(roots, container);
    // a borrowed scalar may point inside the old data buffer that GC moves.
    uint64_t value_home = 0;
    Rooted<Item> rooted_value(roots, lambda_item_adopt_scalar_home(new_value, &value_home));

    void* new_data = container_rebuild_data_alloc(container, new_byte_size);
    if (!new_data) {
        log_error("map_rebuild: data allocation failed");
        return false;
    }
    container = rooted_container.get();
    new_value = rooted_value.get();

    // Re-read old_data after allocation: GC may have fired during
    // heap_data_calloc, compacting *data_slot from nursery to tenured.
    // The local old_data would then point to freed nursery memory.
    old_data = *data_slot;

    // copy field values from old buffer to new buffer
    ShapeEntry* old_e = old_map_type->shape;
    ShapeEntry* new_e = new_type->shape;
    field_index = 0;
    while (old_e && new_e) {
        if (old_e == removed_entry) { old_e = typemap_next_field(old_map_type, old_e); continue; }
        if (old_e->byte_offset < 0 || new_e->byte_offset < 0) {
            old_e = typemap_next_field(old_map_type, old_e);
            new_e = typemap_next_field(new_type, new_e);
            field_index++;
            continue;
        }
        void* old_field = (char*)old_data + old_e->byte_offset;
        void* new_field = (char*)new_data + new_e->byte_offset;

        if (old_e == changed_entry) {
            // The new ShapeEntry owns the semantic contract. In particular,
            // `int?` must encode null as its lane sentinel rather than using
            // the historical raw Item fallback selected by TypeId alone.
            if (!map_shape_field_store_native_lane(new_field, new_e, new_value)) {
            // Store according to the rebuilt shape, not the source Item tag.
            // Composite contracts such as `int[]` use the self-describing
            // TypedItem slot even though their current value is an Array
            // pointer; using the value tag here leaves `_map_read_field`
            // interpreting that pointer as an uninitialized TypedItem.
            map_field_store(new_field, new_value,
                shape_entry_storage_type_id(new_e));
            }
        } else {
            // unchanged field — copy the bytes across unchanged
            int sz = field_index < fixed_slot_count ? (int)sizeof(void*) :
                shape_entry_storage_size(old_e);
            memcpy(new_field, old_field, sz);
        }
        field_index++;
        old_e = typemap_next_field(old_map_type, old_e);
        new_e = typemap_next_field(new_type, new_e);
    }

    *type_slot = new_type;

    // replace data, retiring the old buffer with its allocator
    container_rebuild_data_install(container, data_slot, cap_slot, new_data,
        new_byte_size);

    log_debug("map_rebuild: type change complete, fields=%lld, byte_size=%ld, migrated=%d",
              (long long)new_type->length, new_byte_size, container->is_data_migrated);
    return true;
}

static bool map_rebuild_for_type_change(void** type_slot, void** data_slot, int* cap_slot,
                                        TypeId container_type_id,
                                        Container* container,
                                        ShapeEntry* changed_entry,
                                        Type* new_field_contract, Item new_value) {
    TypeMap* old_map_type = (TypeMap*)*type_slot;
    if (!new_field_contract) {
        log_error("map_rebuild: missing replacement field contract");
        return false;
    }

    // count existing fields
    int field_count = 0;
    ShapeEntry* e = old_map_type->shape;
    while (e) { field_count++; e = typemap_next_field(old_map_type, e); }
    // No artificial upper bound: rebuild only uses heap/pool allocation per field,
    // no stack arrays or fixed-size buffers. globalThis legitimately has 100+ fields.
    if (field_count <= 0) {
        log_error("map_rebuild: invalid field count %d", field_count);
        return false;
    }

    // Constructor fields form a fixed-width prefix; properties appended later
    // remain packed and must not inherit the prefix's 8-byte write invariant.
    int fixed_slot_count = typemap_fixed_slot_prefix_count(old_map_type);

    // build new shape chain with updated type for the changed field
    ShapeEntry* first = NULL;
    ShapeEntry* prev = NULL;
    ShapeEntry* last = NULL;

    e = old_map_type->shape;
    int field_index = 0;
    int64_t byte_offset = (int64_t)fixed_slot_count * (int64_t)sizeof(void*);
    while (e) {
        Type* field_contract = e == changed_entry ? new_field_contract : e->type;

        // allocate ShapeEntry + embedded StrView
        ShapeEntry* ne = (ShapeEntry*)pool_calloc(context->pool,
            sizeof(ShapeEntry) + sizeof(StrView));
        if (!ne) {
            log_error("map_rebuild: ShapeEntry allocation failed");
            return false;
        }
        StrView* nv = (StrView*)((char*)ne + sizeof(ShapeEntry));
        nv->str = e->name->str;
        nv->length = e->name->length;
        ne->name = nv;
        ne->name_hash = e->name_hash ? e->name_hash : typemap_name_hash(nv->str, (int)nv->length);
        ne->name_id = e->name_id;
        ne->key_kind = e->key_kind;
        // Retain an unchanged field's full contract. Replacing `number` or a
        // union with its LMD_TYPE_TYPE carrier makes the packed Item look like
        // a Type* and corrupts it on the next validation read.
        shape_entry_set_type(ne, field_contract);
        bool virtual_field = e->byte_offset < 0;
        bool fixed_slot = !virtual_field && field_index < fixed_slot_count;
        ne->byte_offset = virtual_field ? -1 : (fixed_slot ? e->byte_offset : byte_offset);
        ne->ns = e->ns;
        // Preserve property attribute flags (JSPD_IS_ACCESSOR, NW, NE, NC, etc.)
        // and default_value across shape rebuild. Without this, accessors lose
        // their IS_ACCESSOR flag and writable/enum/config flags get reset to JS
        // defaults whenever a sibling field's type transitions trigger a rebuild.
        ne->flags = e->flags;
        ne->default_value = e->default_value;
        ne->accessor = e->accessor;

        if (!first) first = ne;
        if (prev) prev->chain_next = ne;
        last = ne;
        prev = ne;
        if (!fixed_slot && !virtual_field) {
            byte_offset += ne->storage.byte_size;
        }
        field_index++;
        e = typemap_next_field(old_map_type, e);
    }
    int64_t new_byte_size = byte_offset;

    TypeMap* new_type = NULL;
    // rebuilt shapes belong to this execution pool, not the retained module's
    // compiler registry; the container owns their direct reference (D8.5.1v7).

    if (container_type_id == LMD_TYPE_ELEMENT) {
        TypeElmt* old_et = (TypeElmt*)old_map_type;
        TypeElmt* new_et = (TypeElmt*)alloc_type(context->pool,
            LMD_TYPE_ELEMENT, sizeof(TypeElmt));
        new_et->shape = first;
        new_et->last = last;
        new_et->length = field_count;
        new_et->byte_size = new_byte_size;
        // an element container may carry a plain map type, whose allocation
        // ends before these fields; reading them copied garbage into the tag
        if (typemap_has_element_layout(old_map_type)) {
            new_et->name = old_et->name;
            new_et->content_list = old_et->content_list;
            new_et->ns = old_et->ns;
        }
        // S2.1.4/OB16: a nominal instance is OPEN — extending it with a field is
        // an ordinary member addition, and every shape reached that way must
        // keep pointing at the SAME nominal record, or the value would silently
        // stop being an instance of its type and lose its methods (LR03-8).
        new_et->nominal = old_map_type->nominal;
        new_et->is_nominal = old_map_type->is_nominal;
        new_et->type_index = -1;

        // Populate/grow hash table for O(1) property lookup.
        typemap_hash_build((TypeMap*)new_et, context->pool);

        new_type = (TypeMap*)new_et;
    } else {
        TypeMap* new_mt = (TypeMap*)alloc_type(context->pool,
            LMD_TYPE_MAP, sizeof(TypeMap));
        new_mt->shape = first;
        new_mt->last = last;
        new_mt->length = field_count;
        new_mt->byte_size = new_byte_size;
        new_mt->nominal = old_map_type->nominal;   // S2.1.4/OB16, see above
        new_mt->is_nominal = old_map_type->is_nominal;
        new_mt->type_index = -1;
        new_mt->has_named_shape = old_map_type->has_named_shape;
        new_mt->is_trusted_contract = false;
        new_mt->struct_name = old_map_type->struct_name;
        new_mt->is_private_clone = old_map_type->is_private_clone;
        new_mt->is_shared_constructor_shape = false;
        new_mt->is_transition_shared_shape = false;
        new_mt->transitions = NULL;
        new_mt->js_meta = old_map_type->js_meta;

        // Populate/grow hash table for O(1) property lookup.
        typemap_hash_build(new_mt, context->pool);

        // Preserve only the verified fixed constructor prefix. Appended packed
        // fields are never valid targets for slot-indexed stores.
        if (fixed_slot_count > 0) {
            ShapeEntry** entries = (ShapeEntry**)pool_calloc(context->pool,
                fixed_slot_count * sizeof(ShapeEntry*));
            if (entries) {
                ShapeEntry* se = first;
                for (int i = 0; i < fixed_slot_count && se; i++, se = typemap_next_field(new_mt, se)) {
                    entries[i] = se;
                }
                new_mt->slot_entries = entries;
                new_mt->slot_count = fixed_slot_count;
            }
        }

        new_type = new_mt;
    }

    return container_move_to_type(type_slot, data_slot, cap_slot, container, old_map_type,
        new_type, changed_entry, new_value, fixed_slot_count);
}

static bool container_retype_field(Container* owner, TypeId kind, void** type_slot,
        void** data_slot, int* cap_slot, ShapeEntry* field, Item value) {
    TypeMap* source = (TypeMap*)*type_slot;
    TypeId tid = get_type_id(value);
    Input* tree = runtime_shape_tree();
    const TypeMapRetypePlan* plan = NULL;
    TypeMap* target = tree ? type_tree_retype_field(tree, source, field, tid, &plan) : NULL;
    if (target) return container_move_to_type(type_slot, data_slot, cap_slot,
        owner, source, target, field, value, 0, NULL, plan);
    return map_rebuild_for_type_change(type_slot, data_slot, cap_slot,
        kind, owner, field, type_info[tid].type, value);
}

// D3.4.3/D3.4.5: immutable transitions for packed plain maps, without JS policy hooks.
bool map_shape_set(Map* map, String* key, Item value) {
    TypeMap* type = (TypeMap*)map->type;
    if (!type || type->js_meta || !key || get_type_id(value) == LMD_TYPE_ERROR) return false;
    ShapeEntry* field = typemap_hash_lookup(type, key->chars, (int)key->len);
    if (!field) return map_extend_open_shape(Item{.map = map}, Item{.item = s2it(key)}, value);
    TypeId tid = get_type_id(value);
    if (field->type->type_id == tid)
        return map_field_store((char*)map->data + field->byte_offset, value, tid);
    return container_retype_field(map, LMD_TYPE_MAP, &map->type, &map->data,
        &map->data_cap, field, value);
}

bool map_shape_delete(Map* map, String* key) {
    TypeMap* old = (TypeMap*)map->type;
    if (!old || old->js_meta || !key) return false;
    ShapeEntry* removed = typemap_hash_lookup(old, key->chars, (int)key->len);
    if (!removed) return true;
    Input* tree = runtime_shape_tree();
    const TypeMapRetypePlan* plan = NULL;
    TypeMap* target = tree ? type_tree_delete_field(tree, map, removed, &plan) : NULL;
    if (!target) {
        // the bounded tree declined: retain family identity in a private filtered chain.
        target = (TypeMap*)alloc_type(context->pool, LMD_TYPE_MAP, sizeof(TypeMap));
        if (!target) return false;
        target->nominal = old->nominal; target->is_nominal = old->is_nominal;
        target->type_index = -1; target->is_private_clone = true;
        FOR_EACH_MAP_FIELD(old, field) {
            if (field == removed) continue;
            ShapeEntry* copy = (ShapeEntry*)pool_calloc(context->pool, sizeof(ShapeEntry));
            if (!copy) return false;
            *copy = *field; copy->chain_next = NULL; copy->chain_index = 0;
            copy->byte_offset = target->byte_size;
            target->byte_size += shape_entry_storage_size(copy);
            if (target->last) target->last->chain_next = copy;
            else target->shape = copy;
            target->last = copy; target->length++;
        }
        typemap_hash_build(target, context->pool);
    }
    if (!target->length) {
        // empty shapes have no traced data buffer; leave the old storage for GC.
        map->type = target; map->data = NULL; map->data_cap = 0;
        return true;
    }
    return container_move_to_type(&map->type, &map->data, &map->data_cap,
        map, old, target, NULL, ItemNull, 0, removed, plan);
}

// map/element field assignment: obj.field = val
// Supports in-place update (same type), numeric coercion (INT↔FLOAT, INT↔INT64),
// and shape rebuild for type changes (e.g. int→string, null→container).
static bool map_shared_ctor_shape_should_detach_for_type(TypeMap* tm,
        TypeId field_type, TypeId value_type) {
    if (!typemap_is_shared_shape(tm)) return false;
    if (field_type == value_type) return false;
    // The null placeholder is the dynamic Item lane. It preserves each
    // instance's tagged value and has precise GC tracing, so a first source
    // write must not turn the shared constructor recipe into a type transition.
    if (field_type == LMD_TYPE_NULL) return false;
    // A Map pointer lane already represents a null child as a null pointer,
    // which `_map_read_field` reboxes as ItemNull. Keep the immutable recipe
    // for recursive object-literal base cases instead of creating a null-tagged
    // transition that makes their guarded field reads miss.
    if (field_type == LMD_TYPE_MAP && value_type == LMD_TYPE_NULL) return false;
    // FLOAT stores its numeric payload in the same double carrier as INT.
    if (field_type == LMD_TYPE_FLOAT && value_type == LMD_TYPE_INT) return false;
    return true;
}

static ShapeEntry* map_find_shape_entry(TypeMap* tm, const char* key_cstr, size_t key_len) {
    if (!tm || !key_cstr) return NULL;
    if (key_len <= INT_MAX) {
        ShapeEntry* hit = typemap_hash_lookup(tm, key_cstr, (int)key_len);
        if (hit) return hit;
    }
    ShapeEntry* entry = tm->shape;
    while (entry) {
        if (entry->name && entry->name->str && entry->name->length == key_len &&
                memcmp(entry->name->str, key_cstr, key_len) == 0) {
            return entry;
        }
        entry = typemap_next_field(tm, entry);
    }
    return NULL;
}

// D3.2.4v4: admission into a named map contract reifies into the contract's
// declared layout. Field admission converts each value where it lies, so a map
// whose fields sit in another order (`{b: "s", a: 1}` for `{a: int, b: string}`)
// kept its own offsets, and publishing the contract over them misaddressed every
// direct read -- `p.b` read the `1` as a string pointer. Move each field by name
// into a buffer laid out by the contract. `map` is the unique admission candidate.
static bool map_relayout_to_contract(Map* map, TypeMap* contract) {
    RootFrame roots(1);
    Rooted<Container*> rooted_map(roots, (Container*)map);
    void* new_data = container_rebuild_data_alloc((Container*)map, contract->byte_size);
    if (!new_data) return false;
    // the allocation may have collected, moving the map's old buffer
    map = (Map*)rooted_map.get();
    TypeMap* current = (TypeMap*)map->type;
    FOR_EACH_MAP_FIELD(contract, field) {
        if (!field->name || field->byte_offset < 0) continue;
        ShapeEntry* source = map_find_shape_entry(current, field->name->str,
            field->name->length);
        if (!source) return false;
        // neither the read nor the store allocates, so the old buffer stays put
        Item value = map_shape_field_to_item(map->data, source);
        void* slot = (char*)new_data + field->byte_offset;
        if (!map_shape_field_store_native_lane(slot, field, value)) {
            map_field_store(slot, value, shape_entry_storage_type_id(field));
        }
    }
    container_rebuild_data_install((Container*)map, &map->data, &map->data_cap,
        new_data, contract->byte_size);
    map->type = contract;
    return true;
}

static bool runtime_type_admit_map_env(Item value, Type* expected, Type** env,
        Item* converted, bool relation_proven = false) {
    if (get_type_id(value) != LMD_TYPE_MAP || !value.map || !expected ||
            expected->type_id != LMD_TYPE_MAP) {
        return false;
    }

    // A map conversion must isolate only the root being reified. Its fields and
    // unchanged nested containers remain shared until a later write detaches
    // them; deep cloning here made validation cost grow with the full graph.
    if (cow_profile_enabled()) {
        cow_profile_note_map_admit_bytes(cow_one_level_copy_bytes(value));
    }
    RootFrame roots(3);
    // COW already records whether this root has aliases. Reifying a unique
    // map in place publishes the verified contract to later boundary reads;
    // cloning every admission kept the original generic shape alive and made
    // the same recursive tree node pay the conversion repeatedly. Shared or
    // static roots still detach through the normal COW path.
    Rooted<Item> rooted_candidate(roots, cow_prepare_write(value));
    Rooted<Item> rooted_field(roots, ItemNull);
    Rooted<Item> rooted_converted(roots, ItemNull);
    if (get_type_id(rooted_candidate.get()) != LMD_TYPE_MAP) {
        return false;
    }

    TypeMap* expected_map = (TypeMap*)expected;
    FOR_EACH_MAP_FIELD(expected_map, expected_field) {
        if (!expected_field->name || !expected_field->name->str || !expected_field->type) {
            continue;
        }
        if (cow_profile_enabled()) g_cow_profile.map_admit_fields_visited++;
        Map* candidate_map = rooted_candidate.get().map;
        TypeMap* candidate_type = candidate_map ? (TypeMap*)candidate_map->type : NULL;
        ShapeEntry* candidate_field = map_find_shape_entry(candidate_type,
            expected_field->name->str, expected_field->name->length);
        if (!candidate_field) return false;

        rooted_field.set(_map_read_field(candidate_field, candidate_map->data));
        Item field_converted = ItemNull;
        if (!runtime_type_admit_value_env(rooted_field.get(), expected_field->type,
                env, &field_converted)) {
            return false;
        }
        rooted_converted.set(field_converted);

        candidate_map = rooted_candidate.get().map;
        candidate_type = candidate_map ? (TypeMap*)candidate_map->type : NULL;
        candidate_field = map_find_shape_entry(candidate_type,
            expected_field->name->str, expected_field->name->length);
        if (!candidate_field || !candidate_field->type) return false;
        LaneStorageDesc expected_lane = {};
        LaneStorageDesc candidate_lane = {};
        bool expected_native_lane = shape_entry_uses_native_lane(expected_field,
            &expected_lane);
        bool candidate_native_lane = shape_entry_uses_native_lane(candidate_field,
            &candidate_lane);
        bool value_changed = rooted_converted.get().item != rooted_field.get().item;
        // A dynamic ANY field can hold the right value while retaining a
        // different packed width/offset. Direct MIR reads use the admitted
        // contract's layout, so publish that layout instead of accepting the
        // value-only match and letting later fields be read at the wrong byte.
        bool semantic_reification = !lambda_type_contract_semantically_compatible(
            candidate_field->type, expected_field->type);
        bool storage_reification = candidate_field->byte_offset != expected_field->byte_offset ||
            shape_entry_storage_type_id(candidate_field) !=
                shape_entry_storage_type_id(expected_field);
        if (candidate_native_lane != expected_native_lane) storage_reification = true;
        if (candidate_native_lane && expected_native_lane &&
                (candidate_lane.kind != expected_lane.kind ||
                    candidate_lane.byte_size != expected_lane.byte_size ||
                    candidate_lane.nullable != expected_lane.nullable ||
                    candidate_lane.base_contract != expected_lane.base_contract)) {
            storage_reification = true;
        }
        bool needs_reification = semantic_reification || storage_reification ||
            (expected_native_lane && !candidate_native_lane);
        if (!value_changed && !needs_reification) continue;

        if (needs_reification) {
            // `fn_map_set` deliberately widens an int back into a float slot.
            // Boundary admission instead changes the detached candidate shape so
            // the stored field's observable tag satisfies the named contract.
            // The nullable case also changes its physical carrier even though
            // the source int already satisfies the optional semantic contract.
            map_rebuild_for_type_change((void**)&candidate_map->type,
                &candidate_map->data, &candidate_map->data_cap, LMD_TYPE_MAP,
                (Container*)candidate_map, candidate_field,
                expected_field->type,
                rooted_converted.get());
        } else {
            String* field_name = heap_create_name(expected_field->name->str,
                expected_field->name->length);
            if (!field_name) return false;
            rooted_field.set({.item = s2it(field_name)});
            fn_map_set(rooted_candidate.get(), rooted_field.get(), rooted_converted.get());
        }
    }

    // relation_proven means every field already passed the structural semantic
    // relation; the loop above owns the conversion proof and a graph-wide
    // validator would rescan unchanged child maps.
    if (!relation_proven && !lambda_type_matches(rooted_candidate.get(), expected)) return false;
    Map* admitted = rooted_candidate.get().map;
    // The loop converts each field where it lies; fields written in another
    // order still sit at other offsets, so the contract's layout is reached
    // only by moving them (D3.2.4v4).
    TypeMap* reified = (TypeMap*)admitted->type;
    MapContractRelation final_relation = lambda_map_contract_relation(reified, expected_map);
    // the buffer's real size: a zero cap means the current type's byte size
    int64_t data_size = admitted->data_cap > 0 ? admitted->data_cap : reified->byte_size;
    if (final_relation == MAP_CONTRACT_NEEDS_REIFICATION) {
        if (!map_relayout_to_contract(admitted, expected_map)) return false;
    } else if (data_size >= expected_map->byte_size && (relation_proven ||
            (final_relation == MAP_CONTRACT_STORAGE_COMPATIBLE &&
             reified->length == expected_map->length))) {
        // Reification constructed the expected lane layout field by field; use
        // the canonical contract descriptor so later exact admissions remain
        // O(1) instead of validating this freshly converted root again. A root
        // that ends storage-compatible with no open extras adopts it too
        // (D3.2.4v4): kept on its private copy, every typed write missed the
        // direct store's shape guard and took the checked setter (LR07-44).
        admitted->data_cap = (int)data_size;
        admitted->type = expected_map;
    }
    *converted = rooted_candidate.get();
    return true;
}

// A plain unary `T[]` -- spelled as the array operator or as the homogeneous
// TypeArray carrier (`nested`, no per-slot tuple patterns) -- constrains only
// its elements: the validator checks a TypeArray's length for tuple patterns
// alone, and a refined contract keeps its constrained wrapper here. A counted
// `T[n]` qualifies too: admission checks its lengths up front
// (lambda_array_value_meets_counts). Once every element is admitted under T,
// the whole-array validator walk only repeats that proof, deeply, through
// every nested element graph (T27-1). Missing the
// TypeArray spelling sent every empty `[]` bound to a declared `int[]` or
// `Node[]` field through a full validator setup.
bool lambda_array_contract_is_plain(Type* expected) {
    Type* outer = runtime_boundary_unwrap_type(expected);
    if (!outer) return false;
    if (outer->type_id == LMD_TYPE_TYPE && outer->kind == TYPE_KIND_UNARY) {
        return ((TypeUnary*)outer)->op == OPERATOR_ARRAY;
    }
    if (outer == &TYPE_ARRAY || outer == &TYPE_LIST ||
            (outer->type_id != LMD_TYPE_ARRAY && outer->type_id != LMD_TYPE_ARRAY_NUM)) {
        return false;
    }
    TypeArray* homogeneous = (TypeArray*)outer;
    return homogeneous->nested && !homogeneous->item_patterns;
}

static bool runtime_type_admit_array_env_impl(Item value, Type* expected, Type** env,
        Item* converted);

// S11.1.6v2/S2.5.6: an annotation checks a list without changing its kind. When
// admission packs or rebuilds the list, the fresh container inherits the bit.
static bool runtime_type_admit_array_env(Item value, Type* expected, Type** env,
        Item* converted) {
    bool is_list = item_is_list(value);
    if (!runtime_type_admit_array_env_impl(value, expected, env, converted)) return false;
    if (is_list) {
        TypeId type_id = get_type_id(*converted);
        if (type_id == LMD_TYPE_ARRAY) converted->array->is_spreadable = 1;
        else if (type_id == LMD_TYPE_ARRAY_NUM) converted->array_num->is_spreadable = 1;
    }
    return true;
}

// The candidate the element-wise admission below checks and may rewrite: its
// elements, in a container the source does not share. An owned rank-one
// ArrayNum is its own flat lane, so a one-level copy presents them. A view's
// lane aliases its base -- a copy never taken, since the clone returns a view
// as is -- and an N-D carrier's elements are its leading-axis rows while its
// `length` counts leaves (S11.1.1v3), so both present their elements, scalars
// or rows, as a fresh boxed sequence. Copying a view here is observably right:
// a view in value position is a snapshot (S9.2.2), and a `var` parameter, the
// one borrow position, never crosses a contract it would re-represent -- E207
// demands an exact argument type there.
static Item runtime_array_admission_candidate(Item value) {
    if (get_type_id(value) == LMD_TYPE_ARRAY_NUM && value.array_num &&
            (value.array_num->is_view || value.array_num->is_ndim)) {
        void* boxed = ensure_typed_array(value, LMD_TYPE_ANY);
        return boxed ? (Item){.array = (Array*)boxed} : ItemNull;
    }
    return cow_clone_one_level(value);
}

static bool runtime_type_admit_array_env_impl(Item value, Type* expected, Type** env,
        Item* converted) {
    Type* element_type = runtime_array_contract_element(expected);
    TypeId source_type = get_type_id(value);
    bool binder_dependent = runtime_contract_uses_binder(expected);
    if (!element_type) {
        return false;
    }
    if (source_type == LMD_TYPE_RANGE) {
        // A range is array-like at the language boundary but has no mutable
        // element storage. Materialize it through the same recursive element
        // admission used for an open Array, then let the normal lane rebuild
        // establish the target representation/certificate (D3.1.1v2).
        Range* range = value.range;
        if (!range || range->length < 0) return false;
        RootFrame roots(3);
        Rooted<Range*> rooted_range(roots, range);
        Rooted<Array*> rooted_materialized(roots, array());
        Rooted<Item> rooted_element(roots, ItemNull);
        if (!rooted_materialized.get() || !array_reserve_append_slots(
                rooted_materialized.get(), rooted_range.get()->length)) {
            return false;
        }
        for (int64_t index = 0; index < rooted_range.get()->length; index++) {
            Range* live_range = rooted_range.get();
            Item source_element = live_range->is_char
                ? fn_chr({.item = i2it(live_range->start + index)})
                : (Item){.item = i2it(live_range->start + index)};
            rooted_element.set(source_element);
            Item admitted = ItemNull;
            if (!runtime_type_admit_value_env(rooted_element.get(), element_type,
                    env, &admitted)) {
                return false;
            }
            rooted_element.set(admitted);
            Array* materialized = rooted_materialized.get();
            array_set(materialized, materialized->length, rooted_element.get());
            materialized->length++;
        }
        return runtime_type_admit_array_env({.array = rooted_materialized.get()},
            expected, env, converted);
    }
    if (source_type != LMD_TYPE_ARRAY && source_type != LMD_TYPE_ARRAY_NUM &&
            source_type != LMD_TYPE_ELEMENT) {
        return false;
    }
    Type* semantic_element = type_field_unwrap_simple_decl(element_type);
    if (semantic_element && semantic_element->type_id == LMD_TYPE_ANY &&
            source_type == LMD_TYPE_ARRAY_NUM) {
        // `any[]` needs a boxed outer sequence: an N-D ArrayNum's scalar
        // `items` buffer would flatten its rows during a later open write.
        // Re-enter through the normal Array path so the boxed result receives
        // the same in-place boundary certificate a `var any[]` callee needs
        // to make checked writes through its caller-owned header (D3.3.3v3,
        // S9.2.2).
        RootFrame roots(1);
        Rooted<Item> rooted_value(roots, value);
        void* boxed = ensure_typed_array(rooted_value.get(), LMD_TYPE_ANY);
        if (!boxed) return false;
        return runtime_type_admit_array_env({.array = (Array*)boxed}, expected, env,
            converted);
    }
    if (!binder_dependent && lambda_array_rep_proves(value, expected, true)) {
        *converted = value;
        return true;
    }

    // ArrayNum's lane is an exact scalar decoder, not a hint. Once the owned
    // rank-one carrier matches the full primitive T[] contract, walking every
    // element only reconstructs the proof that the carrier already provides.
    // Keep views, shaped arrays, nullable/refined contracts, and all lane
    // conversions on the checked path in the helper.
    if (!binder_dependent && runtime_array_admit_primitive_contract(value, expected,
            converted)) return true;

    // Every path below certifies through this one interned certificate.
    // S11.1.1v3: `T[n]` is `T[]` with a fixed length, per axis -- `int[2][3]`
    // is three arrays of two. The two certificate paths above check a counted
    // contract's lengths through ARRAY_REP_CERT_COUNTED; the paths below prove
    // elements only, so each counted axis is checked here, once, and the flag
    // spares an uncounted contract the walk. A range or an `any[]` packed
    // source re-enters admission, reaching this.
    ArrayRepCert* cert = lambda_array_rep_cert_resolve(expected);
    if (!cert) return false;
    if ((cert->flags & ARRAY_REP_CERT_COUNTED) &&
            !lambda_array_value_meets_counts(value, expected)) return false;

    LambdaArrayContractInfo contract_info = {};
    ArrayNumElemType compact_type = ELEM_INT;
    bool target_has_numeric_lane = lambda_array_num_elem_type_for_contract(
        element_type, &compact_type);
    LaneStorageDesc target_lane = {};
    // A lane is a carrier proof. A literal element contract selects one value
    // out of that carrier, so it keeps the per-element admission below rather
    // than certifying the source in place (D3.3.3v3, D8.3.2).
    bool target_has_native_lane = lambda_type_layout_proves_contract(element_type) &&
        lambda_type_array_lane_storage_desc(element_type, &target_lane) &&
        array_native_lane_supported(&target_lane);
    if (!binder_dependent && source_type == LMD_TYPE_ARRAY && value.array &&
            !value.array->is_ndim && !value.array->is_view &&
            target_has_native_lane &&
            array_native_lane_matches_desc(value.array, &target_lane) &&
            lambda_array_contract_info(expected, &contract_info) &&
            contract_info.rank == 1) {
        // A matching producer-maintained lane is the same physical proof as
        // an ArrayNum element tag. The explicit crossing installs the full
        // contract certificate without cloning and rescanning every element
        // (D3.3.3v3, D3.3.4).
        lambda_array_install_rep_cert(value, cert);
        *converted = value;
        return true;
    }
    if (source_type == LMD_TYPE_ARRAY && value.array && !array_has_native_lane(value.array) &&
            !target_has_native_lane && !target_has_numeric_lane) {
        // A boxed target (including a union element) needs no replacement when
        // every admitted Item is unchanged. Publish the certificate on that
        // same carrier so later reads do not copy and revalidate its graph.
        // Element conversions still take the transactional copy path below;
        // pointer lanes and compact ArrayNum lanes both need their physical
        // rebuild, including empty numeric arrays (D3.3.3v3, S9.2.2).
        RootFrame roots(2);
        Rooted<Item> rooted_value(roots, value);
        Rooted<Item> rooted_element(roots, ItemNull);
        bool needs_copy = false;
        for (int64_t index = 0; index < rooted_value.get().array->length; index++) {
            rooted_element.set(item_at(rooted_value.get(), index));
            Item admitted = ItemNull;
            if (!runtime_type_admit_value_env(rooted_element.get(), element_type,
                    env, &admitted)) {
                return false;
            }
            if (admitted.item != rooted_element.get().item) {
                needs_copy = true;
                break;
            }
        }
        if (!needs_copy) {
            // Element identity alone does not prove occurrence/rank constraints.
            // A plain unary `T[]` has none: every element was just admitted
            // under T, so the whole-array validator walk only repeats that
            // proof -- deeply, through every nested element graph. prettier_ast
            // rebuilt uncertified `Doc[]` accumulators per step and paid the
            // walk each time (T27-1, D3.2.2 "on first crossing").
            if (!lambda_array_contract_is_plain(expected) &&
                    !lambda_type_matches(rooted_value.get(), expected)) {
                return false;
            }
            lambda_array_install_rep_cert(rooted_value.get(), cert);
            *converted = rooted_value.get();
            return true;
        }
    }

    // S11.1.1v3 preserves rank: an ArrayNum of rank r is exactly a rank-r
    // contract over its leaf lane -- `reshape(v, [2, 2])` is an `int[][]`,
    // never an `int[]`, whose elements would be its rows. The rows are
    // leading-axis views, but every leaf lives in one flat, exact scalar
    // lane: validate that lane directly and certify the same array without
    // breaking its reshape/write-through semantics. A rank mismatch falls
    // through and is rejected below, as `[[1]] is int[]` is false. Only a
    // dense array is its flat lane: a strided view (a transposed matrix or
    // its row) is copied below into the lane a typed read assumes.
    ArrayNumElemType leaf_type = ELEM_INT;
    if (source_type == LMD_TYPE_ARRAY_NUM && value.array_num &&
            array_num_is_dense(value.array_num) &&
            lambda_array_contract_info(expected, &contract_info) &&
            contract_info.rank == array_num_rank(value.array_num) &&
            lambda_array_num_elem_type_for_contract(contract_info.leaf_element,
                &leaf_type) &&
            value.array_num->get_elem_type() == leaf_type) {
        Type* leaf_element = runtime_boundary_unwrap_type(contract_info.leaf_element);
        RootFrame roots(2);
        Rooted<Item> rooted_value(roots, value);
        Rooted<Item> rooted_element(roots, ItemNull);
        for (int64_t index = 0; index < rooted_value.get().array_num->length; index++) {
            rooted_element.set(array_num_read_item(rooted_value.get().array_num, index));
            Item admitted = ItemNull;
            if (!runtime_type_admit_value_env(rooted_element.get(), leaf_element,
                    env, &admitted) ||
                    get_type_id(admitted) != get_type_id(rooted_element.get())) {
                return false;
            }
        }
        lambda_array_install_rep_cert(rooted_value.get(), cert);
        *converted = rooted_value.get();
        return true;
    }

    // The candidate only has to leave the source untouched while its elements
    // are admitted and replaced, which a one-level COW copy does (D4.4.2): its
    // children are shared and marked, never rewritten here. fn_mutable_value
    // deep-cloned the whole element graph instead -- every admission of an
    // uncertified `Doc[]` copied the entire document subtree (prettier_ast2).
    RootFrame roots(4);
    Rooted<Item> rooted_candidate(roots, runtime_array_admission_candidate(value));
    Rooted<Item> rooted_element(roots, ItemNull);
    Rooted<Item> rooted_converted(roots, ItemNull);
    Rooted<ArrayNum*> rooted_packed(roots, (ArrayNum*)NULL);
    TypeId candidate_type = get_type_id(rooted_candidate.get());
    if ((candidate_type != LMD_TYPE_ARRAY && candidate_type != LMD_TYPE_ARRAY_NUM &&
            candidate_type != LMD_TYPE_ELEMENT) || rooted_candidate.get().item == value.item) {
        return false;
    }

    int64_t length = rooted_candidate.get().array->length;
    for (int64_t index = 0; index < length; index++) {
        rooted_element.set(item_at(rooted_candidate.get(), index));
        Item element_converted = ItemNull;
        if (!runtime_type_admit_value_env(rooted_element.get(), element_type, env,
                &element_converted)) {
            return false;
        }
        rooted_converted.set(element_converted);
        if (rooted_converted.get().item == rooted_element.get().item) continue;

        if (get_type_id(rooted_candidate.get()) == LMD_TYPE_ARRAY_NUM ||
                array_has_native_lane(rooted_candidate.get().array)) {
            // A Float ArrayNum has no per-item tags. Reify it before publishing
            // converted elements so `3.0 -> int` cannot remain physically float.
            // A native lane holds only its own layout: the one-level clone of
            // an `int?[]` refused the `i8` or `float` its element converts to,
            // rejecting a value a boxed source admits. The target lane is
            // rebuilt below either way.
            convert_specialized_to_generic(rooted_candidate.get().array);
        }
        if (get_type_id(fn_array_set(rooted_candidate.get().array, index,
                rooted_converted.get())) == LMD_TYPE_ERROR) {
            return false;
        }
    }

    if (target_has_numeric_lane &&
            (get_type_id(rooted_candidate.get()) != LMD_TYPE_ARRAY_NUM ||
             rooted_candidate.get().array_num->get_elem_type() != compact_type)) {
        ArrayNum* packed = array_num_new(compact_type, length);
        if (!packed) return false;
        rooted_packed.set(packed);
        for (int64_t index = 0; index < length; index++) {
            Item admitted = item_at(rooted_candidate.get(), index);
            if (!array_num_store_admitted(rooted_packed.get(), index, admitted)) {
                return false;
            }
        }
        rooted_candidate.set({.array_num = rooted_packed.get()});
    }

    LaneStorageDesc lane_desc = {};
    if (lambda_type_array_lane_storage_desc(element_type, &lane_desc) &&
            array_native_lane_supported(&lane_desc) &&
            !array_native_lane_matches_desc(rooted_candidate.get().array, &lane_desc)) {
        Item rebuilt = ItemNull;
        if (!array_rebuild_native_lane(rooted_candidate.get(), &lane_desc, &rebuilt)) {
            return false;
        }
        rooted_candidate.set(rebuilt);
    }
    // every element was admitted above; only a non-plain contract adds a
    // whole-array constraint for the validator to check (T27-1)
    if (!lambda_array_contract_is_plain(expected) &&
            !lambda_type_matches(rooted_candidate.get(), expected)) return false;
    lambda_array_install_rep_cert(rooted_candidate.get(), cert);
    *converted = rooted_candidate.get();
    return true;
}

static uint32_t runtime_map_contract_cache_base(const TypeMap* candidate,
        const Type* expected) {
    uintptr_t candidate_bits = (uintptr_t)candidate >> 4;
    uintptr_t expected_bits = (uintptr_t)expected >> 4;
    uint64_t hash = (uint64_t)candidate_bits ^ ((uint64_t)expected_bits << 1);
    hash ^= hash >> 33;
    hash *= UINT64_C(0xff51afd7ed558ccd);
    hash ^= hash >> 33;
    return (uint32_t)hash & (LAMBDA_MAP_CONTRACT_CACHE_CAPACITY - 1);
}

static MapContractRelation runtime_map_contract_relation_cached(
        const TypeMap* candidate, const TypeMap* expected) {
    if (!candidate || !expected) return MAP_CONTRACT_INCOMPATIBLE;
    // An exact trusted shape is already the answer; hashing it only repeats
    // the proof every time a typed node crosses a boundary (D3.2.4v3).
    if (candidate == expected && expected->is_trusted_contract)
        return MAP_CONTRACT_EXACT_TRUSTED;
    Heap* heap = context ? context->heap : NULL;
    if (!heap) return lambda_map_contract_relation(candidate, expected);

    // Map admission is a hot nested-store operation. A full table scan made a
    // larger cache slower than a miss: a compact bounded probe keeps repeated
    // typed record paths O(1) while a round-robin fallback preserves progress
    // under adversarial shape churn (D3.2.4v3).
    uint32_t base = runtime_map_contract_cache_base(candidate, expected);
    for (uint32_t probe = 0; probe < 8; probe++) {
        LambdaMapContractCacheEntry* entry = &heap->map_contract_cache[
            (base + probe) & (LAMBDA_MAP_CONTRACT_CACHE_CAPACITY - 1)];
        if (entry->candidate == candidate && entry->expected == expected) {
            if (cow_profile_enabled()) {
                g_cow_profile.map_admit_relation_cache_hits++;
            }
            return (MapContractRelation)entry->relation;
        }
        if (!entry->candidate) {
            if (cow_profile_enabled()) g_cow_profile.map_admit_relation_cache_misses++;
            MapContractRelation relation = lambda_map_contract_relation(candidate, expected);
            entry->candidate = candidate;
            entry->expected = expected;
            entry->relation = (uint8_t)relation;
            return relation;
        }
    }

    if (cow_profile_enabled()) g_cow_profile.map_admit_relation_cache_misses++;
    MapContractRelation relation = lambda_map_contract_relation(candidate, expected);
    uint32_t slot = heap->map_contract_cache_next++ %
        LAMBDA_MAP_CONTRACT_CACHE_CAPACITY;
    heap->map_contract_cache[slot].candidate = candidate;
    heap->map_contract_cache[slot].expected = expected;
    heap->map_contract_cache[slot].relation = (uint8_t)relation;
    return relation;
}

// A union has no shared packed layout, so it preserves the carrier of the
// selected member.  When a map already has the exact or storage-compatible
// layout of one trusted arm, that shape is the admission proof; recursively
// walking its fields would only re-establish an invariant maintained by every
// map write.  Arms that need reification or contain an incompatible field stay
// on the full validator path (D3.2.4v3, D8.3.2-D8.3.3).
static bool runtime_union_map_has_exact_rep(TypeMap* candidate, Type* expected,
        int depth = 0) {
    expected = runtime_boundary_unwrap_type(expected);
    if (!candidate || !expected || depth > 64) return false;
    if (lambda_type_is_union(expected)) {
        TypeBinary* binary = (TypeBinary*)expected;
        return runtime_union_map_has_exact_rep(candidate, binary->left, depth + 1) ||
            runtime_union_map_has_exact_rep(candidate, binary->right, depth + 1);
    }
    return expected->type_id == LMD_TYPE_MAP && expected != &TYPE_MAP &&
        candidate == (TypeMap*)expected && ((TypeMap*)expected)->is_trusted_contract;
}

static bool runtime_union_map_rep_proves(TypeMap* candidate, Type* expected,
        int depth = 0) {
    expected = runtime_boundary_unwrap_type(expected);
    if (!candidate || !expected || depth > 64) return false;
    if (lambda_type_is_union(expected)) {
        TypeBinary* binary = (TypeBinary*)expected;
        return runtime_union_map_rep_proves(candidate, binary->left, depth + 1) ||
            runtime_union_map_rep_proves(candidate, binary->right, depth + 1);
    }
    if (expected->type_id != LMD_TYPE_MAP || expected == &TYPE_MAP ||
            !((TypeMap*)expected)->is_trusted_contract) {
        return false;
    }
    MapContractRelation relation = runtime_map_contract_relation_cached(candidate,
        (TypeMap*)expected);
    return relation == MAP_CONTRACT_EXACT_TRUSTED ||
        relation == MAP_CONTRACT_STORAGE_COMPATIBLE;
}

static bool runtime_union_map_rep_proves_cached(TypeMap* candidate,
        Type* expected) {
    Heap* heap = context ? context->heap : NULL;
    if (!heap) {
        return runtime_union_map_has_exact_rep(candidate, expected) ||
            runtime_union_map_rep_proves(candidate, expected);
    }
    uint32_t base = runtime_map_contract_cache_base(candidate, expected);
    LambdaMapContractCacheEntry* available = NULL;
    for (uint32_t probe = 0; probe < 8; probe++) {
        LambdaMapContractCacheEntry* entry = &heap->map_contract_cache[
            (base + probe) & (LAMBDA_MAP_CONTRACT_CACHE_CAPACITY - 1)];
        if (entry->candidate == candidate && entry->expected == expected) {
            if (cow_profile_enabled()) g_cow_profile.union_map_rep_cache_hits++;
            return entry->relation == MAP_CONTRACT_UNION_MEMBER_PROVEN;
        }
        if (!entry->candidate) {
            available = entry;
            break;
        }
    }

    if (cow_profile_enabled()) g_cow_profile.union_map_rep_cache_misses++;
    bool proven = runtime_union_map_has_exact_rep(candidate, expected) ||
        runtime_union_map_rep_proves(candidate, expected);
    if (!proven) return false;
    if (!available) {
        uint32_t slot = heap->map_contract_cache_next++ %
            LAMBDA_MAP_CONTRACT_CACHE_CAPACITY;
        available = &heap->map_contract_cache[slot];
    }
    available->candidate = candidate;
    available->expected = expected;
    available->relation = MAP_CONTRACT_UNION_MEMBER_PROVEN;
    return true;
}


bool lambda_type_try_admit(Item value, Type* expected, Type** env, Item* converted) {
    RootFrame roots(1);
    Rooted<Item> source(roots, value);
    return runtime_type_admit_value_env(source.get(), expected, env, converted);
}

static bool runtime_type_admit_value_env(Item value, Type* expected, Type** env,
        Item* converted) {
    if (!converted) return false;
    if (expected && expected->type_id == LMD_TYPE_TYPE &&
            expected->kind == TYPE_KIND_BINDER) {
        return runtime_type_admit_binder(value, (TypeBinder*)expected, env, converted);
    }
    if (expected && expected->type_id == LMD_TYPE_TYPE &&
            expected->kind == TYPE_KIND_BOUND_REF) {
        TypeBoundRef* ref = (TypeBoundRef*)expected;
        Type* resolved = env && env[ref->slot] ? env[ref->slot] : ref->bound;
        return resolved && runtime_type_admit_value_env(value, resolved, env, converted);
    }
    expected = runtime_boundary_unwrap_type(expected);
    if (!expected) return false;
    // The bare string singleton cannot convert or refine a string value.
    if (expected == &TYPE_STRING && get_type_id(value) == LMD_TYPE_STRING) {
        *converted = value;
        return true;
    }
    // T27-4: `any` admits every non-error value unchanged (lambda_type_matches
    // answers true at once); the numeric, array and map probes below only
    // rediscovered that on every open leaf store, e.g. richards'
    // `w.tasks[tid].pp = ...` below an untyped `array` field. Errors keep the
    // full path, whose answer depends on the contract accepting error.
    if (expected->type_id == LMD_TYPE_ANY && get_type_id(value) != LMD_TYPE_ERROR) {
        *converted = value;
        return true;
    }
    bool binder_dependent = runtime_contract_uses_binder(expected);
    TypeId value_type = get_type_id(value);
    if (!binder_dependent && (value_type == LMD_TYPE_MAP ||
            value_type == LMD_TYPE_ARRAY || value_type == LMD_TYPE_ARRAY_NUM) &&
            lambda_value_rep_proves_contract(value, expected)) {
        if (get_type_id(value) == LMD_TYPE_MAP && cow_profile_enabled()) {
            g_cow_profile.map_admit_calls++;
            Type* arm = runtime_boundary_nonnull_map_arm(expected);
            if (arm && value.map->type == arm && ((TypeMap*)arm)->is_trusted_contract)
                g_cow_profile.map_admit_exact_shape_hits++;
            else {
                g_cow_profile.map_admit_storage_compatible_hits++;
                g_cow_profile.map_admit_readonly_validations++;
            }
        }
        // Maintained shapes/certificates include contract and carrier facts;
        // raw writes invalidate them before publishing (D3.3.4).
        *converted = value;
        return true;
    }
    if (lambda_type_is_union(expected) && cow_profile_enabled())
        g_cow_profile.union_admit_calls++;

    if (!binder_dependent && get_type_id(value) == LMD_TYPE_MAP && value.map &&
            lambda_type_is_union(expected)) {
        TypeMap* candidate = (TypeMap*)value.map->type;
        if (candidate && typemap_ptr_is_plausible(candidate) &&
                runtime_union_map_rep_proves_cached(candidate, expected)) {
            *converted = value;
            return true;
        }
    }

    LambdaNumericKind source_kind = lambda_numeric_kind_from_item(value);
    // S11.1.6v2: `T?` is `T | null`, so a nullable numeric contract admits a
    // non-null number exactly as its base does -- the base's boundary picks the
    // representation, as the JIT's nullable F64 lane does (S11.4.5, D3.2.6).
    // Membership alone kept `5` an int in a `float?` binding on T0 while the
    // JIT stored 5.0. This covers the two native nullable lanes, `int?` and
    // `float?`, whose MIR carriers re-represent; the sized and wide optionals
    // keep membership, as their MIR carriers do. A value already of the base's
    // kind needs no re-representation either.
    Type* numeric_contract = expected;
    if (source_kind != LAMBDA_NUM_INVALID) {
        bool nullable = false;
        Type* base = lambda_type_nullable_lane_base(expected, &nullable);
        LambdaNumericKind base_kind = nullable && base
            ? lambda_numeric_kind_from_type(base) : LAMBDA_NUM_INVALID;
        if ((base_kind == LAMBDA_NUM_INT || base_kind == LAMBDA_NUM_FLOAT) &&
                base_kind != source_kind) {
            numeric_contract = base;
        }
    }
    LambdaNumericKind target_kind = lambda_numeric_kind_from_type(numeric_contract);
    if (source_kind != LAMBDA_NUM_INVALID && target_kind != LAMBDA_NUM_INVALID &&
            target_kind != LAMBDA_NUM_INTEGER) {
        // A declared concrete numeric boundary establishes the destination
        // representation, even when membership would accept the source tag.
        // Checking lambda_type_matches first left an int-tagged value at a
        // float boundary, after which a native float body could unbox it as
        // the wrong physical lane.
        if (!lambda_numeric_boundary_admit(value, numeric_contract, converted)) return false;
        // S11.2.1: a literal contract then admits its one value only; the
        // carrier admission alone let `x: 1` take any int (LR03-11)
        Item literal;
        if (lambda_literal_contract_value(numeric_contract, &literal)) {
            return fn_eq(*converted, literal) == BOOL_TRUE;
        }
        return true;
    }

    // An array annotation is a complete rank-and-element contract, not a
    // TypeId comparison. Route it before generic membership can erase a named
    // record layout or accept a matching leaf lane at the wrong rank.
    LambdaArrayContractInfo array_info = {};
    if (lambda_array_contract_info(expected, &array_info)) {
        return runtime_type_admit_array_env(value, expected, env, converted);
    }

    // A trusted compiler-built map contract is an admission certificate only
    // when the candidate carries that exact TypeMap. Dynamic and JS-created
    // shapes still take the validator/conversion path even if their bytes line up.
    //
    // The named contract is reached through its non-null arm: `N?` is a
    // TypeUnary whose OWN type_id is LMD_TYPE_TYPE, so testing the wrapper hid
    // the map arm and the value fell through to the lambda_type_matches
    // shortcut below -- structurally admitted, never reified. A self-referential
    // record is necessarily optional (its recursion terminates on null), so the
    // whole graph kept the literal's packed layout while direct field reads
    // addressed it with the contract's byte offsets (D3.2.4).
    Type* expected_map_contract = runtime_boundary_nonnull_map_arm(expected);
    if (get_type_id(value) == LMD_TYPE_MAP && expected_map_contract) {
        if (cow_profile_enabled()) g_cow_profile.map_admit_calls++;
        TypeMap* expected_map = (TypeMap*)expected_map_contract;
        if (binder_dependent) {
            return runtime_type_admit_map_env(value, expected_map_contract, env,
                converted);
        }
        TypeMap* candidate_map = value.map ? (TypeMap*)value.map->type : NULL;
        if (candidate_map && typemap_ptr_is_plausible(candidate_map)) {
            MapContractRelation relation = runtime_map_contract_relation_cached(
                candidate_map, expected_map);
            if (relation == MAP_CONTRACT_STORAGE_COMPATIBLE) {
                if (cow_profile_enabled()) {
                    g_cow_profile.map_admit_storage_compatible_hits++;
                    g_cow_profile.map_admit_readonly_validations++;
                }
                // The candidate shape is maintained by every map write: a
                // type-changing store retags or rebuilds its ShapeEntry before
                // publishing the value. Once every field has the same semantic
                // contract and physical lane as the expected shape, rescanning
                // the packed value through the schema validator only repeats
                // the proof already made by the shape relation.
                *converted = value;
                return true;
            }
            if (relation == MAP_CONTRACT_NEEDS_REIFICATION ||
                    relation == MAP_CONTRACT_INCOMPATIBLE) {
                if (cow_profile_enabled()) g_cow_profile.map_admit_reifications++;
                // The static relation deliberately rejects erased `any` fields,
                // but the runtime value may still satisfy the named contract.
                // Route that conservative result through field admission rather
                // than letting the generic validator accept a physically
                // incompatible shape that direct MIR reads would misaddress.
                return runtime_type_admit_map_env(value, expected_map_contract, env,
                    converted, relation == MAP_CONTRACT_NEEDS_REIFICATION);
            }
        }
    }

    // Preserve an already conforming union member rather than arbitrarily
    // re-representing it through an earlier union arm.
    if (!binder_dependent && lambda_type_matches(value, expected)) {
        *converted = value;
        return true;
    }

    if (expected->type_id == LMD_TYPE_TYPE && expected->kind == TYPE_KIND_BINARY &&
            ((TypeBinary*)expected)->op == OPERATOR_UNION) {
        TypeBinary* union_type = (TypeBinary*)expected;
        return runtime_type_admit_value_env(value, union_type->left, env, converted) ||
            runtime_type_admit_value_env(value, union_type->right, env, converted);
    }

    if (source_kind != LAMBDA_NUM_INVALID && target_kind != LAMBDA_NUM_INVALID) {
        // A numeric pair reached this DEFERRED boundary but cannot be represented
        // exactly in the target contract. Do not let type-directional membership
        // turn that failed conversion into a truncating native unbox.
        return lambda_numeric_boundary_admit(value, expected, converted);
    }

    if (expected->type_id == LMD_TYPE_MAP) {
        return runtime_type_admit_map_env(value, expected, env, converted);
    }
    return false;
}

// Resolve a field in a freshly installed shape. A ShapeEntry created from an
// unpooled key carries NAME_ID_NONE, so probing by NameId alone can miss even
// though the field is right there — and the callers below then fall back to the
// entry from the *previous* shape, which map_rebuild_for_type_change cannot find
// in the chain it is rebuilding and therefore silently skips, losing the write.
// Same two-probe rule as js_named_fast_lookup: identity first, byte seam second.
static ShapeEntry* map_resolve_entry_in_shape(TypeMap* shape, NameRef key_ref,
        const char* key_cstr, size_t key_len) {
    if (!shape) return NULL;
    if (key_ref && property_key_id(key_ref) != NAME_ID_NONE) {
        ShapeEntry* hit = typemap_hash_lookup_by_name_id(shape,
            property_key_id(key_ref), property_key_hash(key_ref));
        if (hit) return hit;
    }
    return map_find_shape_entry(shape, key_cstr, key_len);
}

static ShapeEntry* map_detach_shared_ctor_shape_for_type(Item map_item,
        TypeMap** map_type_slot, void** type_slot, const char* key_cstr,
        size_t key_len, NameRef key_ref, ShapeEntry* entry, TypeId value_type) {
    // constructor pre-shapes and their JS transitions belong to Map storage.
    if (get_type_id(map_item) != LMD_TYPE_MAP) return entry;
    if (!map_type_slot || !*map_type_slot || !entry || !entry->type) return entry;
    TypeId field_type = entry->type->type_id;
    if (!map_shared_ctor_shape_should_detach_for_type(*map_type_slot, field_type, value_type)) {
        return entry;
    }
    NameId operation_name_id = key_ref ? property_key_id(key_ref) : NAME_ID_NONE;
    bool js_active = js_realm_runtime_has_input();
    // a Lambda context may have a JS capsule before its Input exists; use
    // the Lambda pool until that realm can own transitions (D5.4.1).
    TypeMap* transition = js_active ? js_typemap_transition_for_type(map_item, entry,
        operation_name_id, value_type) : NULL;
    if (transition) {
        *map_type_slot = transition;
        if (type_slot) *type_slot = transition;
        ShapeEntry* refreshed = map_resolve_entry_in_shape(transition, key_ref,
            key_cstr, key_len);
        if (refreshed) return refreshed;
    }
    TypeMap* clone = js_active ? js_typemap_clone_for_mutation_pub(map_item)
        : map_clone_typemap_for_mutation(map_item.map, context->pool);
    if (!clone) return NULL;
    *map_type_slot = clone;
    if (type_slot) *type_slot = clone;
    // Ordinary Input and runtime strings use the id-less byte seam; identity
    // keys recover the cloned slot by NameId.
    ShapeEntry* refreshed = map_resolve_entry_in_shape(clone, key_ref,
        key_cstr, key_len);
    if (refreshed) return refreshed;
    // The clone installed itself on the map, so the pre-detach entry is no
    // longer in the live chain. Returning it anyway is what silently dropped a
    // width-changing store: map_rebuild_for_type_change matches the changed
    // field by pointer and simply skips one it cannot find. Fail loudly instead
    // — the caller turns NULL into an error rather than a wrong answer.
    log_error("map_detach: '%.*s' not found in detached shape %p",
        (int)key_len, key_cstr ? key_cstr : "", (void*)clone);
    return NULL;
}

Item fn_map_set(Item map_item, Item key, Item value) {
    if (item_is_list(value)) {
        // a field or attribute stores the list's array image (S2.5.6); the
        // copy is a safepoint, so the owner and key stay rooted across it
        RootFrame roots(2);
        Rooted<Item> rooted_map(roots, map_item);
        Rooted<Item> rooted_key(roots, key);
        Item image = slot_image(value);
        return fn_map_set(rooted_map.get(), rooted_key.get(), image);
    }
    if (get_type_id(key) == LMD_TYPE_STRING) {
        String* name = key.get_string();
        if (!utf8_key_is_canonical(name->chars, name->len)) {
            name = heap_create_name(name->chars, name->len);
            if (!name) return ItemError;
            key.item = s2it(name);
        }
    }
    TypeId map_type_id = get_type_id(map_item);

    // VMap: in-place mutation via vtable
    if (map_type_id == LMD_TYPE_VMAP) {
        // VMap backing storage is lazy for host wrappers; route all writes
        // through the public setter so ordinary maps allocate on first write.
        return vmap_set(map_item, key, value);
    }

    // support both Map and Element (Element has map-like attributes)
    TypeMap* map_type = NULL;
    void** type_slot = NULL;
    void** data_slot = NULL;
    int* cap_slot = NULL;

    if (map_type_id == LMD_TYPE_MAP) {
        Map* mp = map_item.map;
        if (!mp) { log_error("fn_map_set: null map"); return ItemError; }
        if (mp->is_static) { log_error("fn_map_set: cannot mutate static map"); return ItemError; }
        type_slot = &mp->type;
        data_slot = &mp->data;
        cap_slot = &mp->data_cap;
    } else if (false) {
        Object* obj = map_item.object;
        if (!obj) { log_error("fn_map_set: null object"); return ItemError; }
        if (obj->is_static) { log_error("fn_map_set: cannot mutate static object"); return ItemError; }
        type_slot = &obj->type;
        data_slot = &obj->data;
        cap_slot = &obj->data_cap;
    } else if (map_type_id == LMD_TYPE_ELEMENT) {
        Element* el = (Element*)map_item.container;
        if (!el) { log_error("fn_map_set: null element"); return ItemError; }
        if (el->is_static) { log_error("fn_map_set: cannot mutate static element"); return ItemError; }
        type_slot = &el->type;
        data_slot = &el->data;
        cap_slot = &el->data_cap;
    } else {
        log_error("fn_map_set: not a map or element (type=%d)", map_type_id);
        return ItemError;
    }

    map_type = (TypeMap*)*type_slot;
    if (!map_type) {
        log_error("fn_map_set: no shape");
        return ItemError;
    }

    // get key text; Lambda strings/symbols are length-bearing even when their
    // chars are NUL-terminated, and JS property names may contain any byte.
    const char* key_cstr = NULL;
    size_t key_len = 0;
    String* key_string = NULL;
    TypeId key_type = get_type_id(key);
    if (key_type == LMD_TYPE_STRING) {
        key_string = key.get_safe_string();
        key_cstr = key_string ? key_string->chars : NULL;
        key_len = key_string ? key_string->len : 0;
    } else if (key_type == LMD_TYPE_SYMBOL) {
        Symbol* sym = key.get_safe_symbol();
        key_cstr = sym ? sym->chars : NULL;
        key_len = sym ? sym->len : 0;
    } else {
        log_error("fn_map_set: key must be string or symbol");
        return ItemError;
    }
    if (!key_cstr) {
        log_error("fn_map_set: null key string");
        return ItemError;
    }
    if (!map_type->shape) {
        if (map_extend_open_shape(map_item, key, value)) return ItemNull;
        log_error("fn_map_set: unable to create field '%s'", key_cstr);
        return ItemError;
    }
    NameRef key_ref = key_type == LMD_TYPE_STRING &&
        string_is_pooled(key_string) ? key_string : NULL;
    NameId key_id = key_ref ? property_key_id(key_ref) : NAME_ID_NONE;
    bool identity_key = key_ref && property_key_requires_identity(key_ref);

    // find field in shape
    TypeId value_type = get_type_id(value);
    ShapeEntry* entry = map_type->shape;
    // A1: the hash table answers a plain Lambda string key, so a member write
    // no longer walks every field; building an n-key map was O(n²) on these
    // lookups alone (LR03-38). A hit is the field. A miss is final only on a
    // tree node, whose table holds every field by construction (D3.4.3v4); a
    // private type can gain entries its table never saw (elmt_put), so it
    // keeps the walk, as JS shapes and identity keys do.
    bool table_answers = false;
    if (!identity_key && !map_type->js_meta && key_len <= INT_MAX &&
            typemap_hash_is_usable(map_type)) {
        ShapeEntry* hit = typemap_hash_lookup(map_type, key_cstr, (int)key_len);
        if (hit ? hit->key_kind == NAME_KEY_STRING : map_type->is_transition_shared_shape) {
            table_answers = true;
            entry = hit;
        }
    }
    while (entry) {
        bool name_matches = false;
        if (identity_key) {
            // Symbol/private diagnostic bytes are not property identity.
            name_matches = entry->name_id != NAME_ID_NONE && entry->name_id == key_id;
        } else if (entry->key_kind == NAME_KEY_STRING) {
            // Ordinary Input fields have no NameId, so this is the explicit
            // byte-confirmation seam; pointer equality is never identity.
            name_matches = shape_field_name_equals(entry, key_cstr, key_len);
        }
        if (name_matches) {
            if (entry->byte_offset < 0) {
                log_error("fn_map_set: attempted store to virtual shape field");
                return ItemError;
            }
            // arena-owned elements cannot trace replacement GC values;
            // attribute overrides need the same roots as initial stores.
            if (map_type_id == LMD_TYPE_ELEMENT && context &&
                    context->ui_mode && context->arena &&
                    !ui_prepare_element_field(&value)) return ItemError;
            if (map_type_id == LMD_TYPE_MAP &&
                    map_ctor_offset_is_reserved(map_item.map, entry->byte_offset)) {
                // An RHS, parameter initializer or inherited setter can publish
                // another key first. Reserve storage without preordering creation.
                bool published_after = false;
                for (ShapeEntry* next = typemap_next_field(map_type, entry); next;
                        next = typemap_next_field(map_type, next)) {
                    if (!map_ctor_offset_is_reserved(map_item.map, next->byte_offset)) {
                        published_after = true;
                        break;
                    }
                }
                if (published_after) {
                    map_type = js_typemap_clone_for_mutation_pub(map_item);
                    if (!map_type) return ItemError;
                    *type_slot = map_type;
                    entry = map_resolve_entry_in_shape(map_type, key_ref, key_cstr, key_len);
                    if (!entry) return ItemError;
                    typemap_move_field_to_end(map_type, entry);
                }
            }
            // A typed field's contract is richer than the value's TypeId.
            // Reinstalling a certified T[] must not retag it as open array.
            if (map_type->is_trusted_contract &&
                    lambda_value_rep_proves_contract(value, entry->type)) {
                if (map_type_id == LMD_TYPE_MAP) {
                    map_ctor_initialize_offset(map_item.map, entry->byte_offset);
                }
                void* field_ptr = (char*)*data_slot + entry->byte_offset;
                if (!map_shape_field_store_native_lane(field_ptr, entry, value)) {
                    map_field_store(field_ptr, value, shape_entry_storage_type_id(entry));
                }
                return ItemNull;
            }
            TypeId field_type = entry->type->type_id;
            bool plain_shape = !map_type->js_meta && map_type->type_id == map_type_id &&
                !map_type->is_shared_constructor_shape && !map_type->slot_entries &&
                map_type->slot_count == 0 && !map_item.container->has_ctor_reserved &&
                (map_type_id != LMD_TYPE_MAP || map_item.map->map_kind == MAP_KIND_PLAIN);
            // D3.4.3v5/D3.4.5: Lambda shared shapes use the context's tree,
            // never the JS constructor path, which requires an active JS realm.
            if (plain_shape && field_type != LMD_TYPE_ANY &&
                    map_shared_ctor_shape_should_detach_for_type(map_type, field_type, value_type)) {
                return container_retype_field(map_item.container, map_type_id, type_slot,
                    data_slot, cap_slot, entry, value) ? ItemNull : ItemError;
            }
            if (!plain_shape) entry = map_detach_shared_ctor_shape_for_type(map_item, &map_type,
                type_slot, key_cstr, key_len, key_ref, entry, value_type);
            if (!entry || !entry->type) return ItemError;
            // A reserved constructor slot becomes observable only at the
            // source assignment that reaches this storage write.
            if (map_type_id == LMD_TYPE_MAP) {
                map_ctor_initialize_offset(map_item.map, entry->byte_offset);
            }
            field_type = entry->type->type_id;
            void* field_ptr = (char*)*data_slot + entry->byte_offset;

            // D3.2.4v4: an `any` field is a TypedItem lane that every value
            // fits, so a write of another kind stores in place and the field
            // keeps its declared contract. Comparing the wrapper's TypeId with
            // the value's rebuilt the shape around the value's kind on every
            // kind change, minting a pool shape each time (LR03-37).
            const LaneStorageDesc* storage = shape_entry_storage(entry);
            if (storage->kind == LANE_STORAGE_TYPED_ITEM &&
                    storage->value_domain == LMD_TYPE_ANY && value_type != LMD_TYPE_ERROR) {
                map_field_store(field_ptr, value, LMD_TYPE_ANY);
                return ItemNull;
            }

            if (field_type == LMD_TYPE_NULL && typemap_is_shared_shape(map_type)) {
                // A shared constructor placeholder is a raw Item lane. Source
                // order can move it out of the leading fixed prefix, but it
                // must still retain the null descriptor for mixed instances.
                map_field_store_dynamic_item(field_ptr, value);
                return ItemNull;
            }

            LaneStorageDesc lane = {};
            if (shape_entry_uses_native_lane(entry, &lane) &&
                    map_shape_field_store_native_lane(field_ptr, entry, value)) {
                return ItemNull;
            }

            if (field_type == value_type) {
                // same type — fast path: in-place update
                map_field_store(field_ptr, value, value_type);
                return ItemNull;
            }

            // FLOAT field + INT value → widen int to double (lossless, no reshape)
            if (field_type == LMD_TYPE_FLOAT && value_type == LMD_TYPE_INT) {
                map_field_store_int_as_float(field_ptr, value);
                return ItemNull;
            }

            // `int` and `int64` both occupy eight bytes, but their slot
            // carriers differ (double versus int64_t).  Rebuild the field so
            // subsequent reads use the carrier that was actually written.

            // NULL → INT/FLOAT/STRING/FUNC fast path — same byte size (all 8 bytes)
            // Avoids map_rebuild_for_type_change which allocates from data zone and
            // can trigger GC compaction that corrupts field data at scale.
            // Safe for JS constructor objects (non-pooled shapes).
            // An error is never a field contract: retagging a SHARED literal
            // shape to `error` here made every later literal at that site
            // fail its own construction ("unknown map storage type error").
            if (field_type == LMD_TYPE_NULL && value_type != LMD_TYPE_ERROR) {
                int old_bsz = shape_entry_storage_size(entry);
                int new_bsz = lambda_lane_storage_size(type_info[value_type].type);
                if (old_bsz == new_bsz) {
                    map_field_store(field_ptr, value, value_type);
                    shape_entry_set_type(entry, type_info[value_type].type);
                    return ItemNull;
                }
            }

            // Container/null type change — fast path (same byte size = sizeof(void*))
            // NULL↔MAP, NULL↔ARRAY, MAP↔ELEMENT, etc. all store pointers,
            // and _map_read_field handles null pointers for all container types.
            // No shape rebuild needed — just update the value in-place.
            // UNDEFINED and BOOL are included because:
            //   - For UNDEFINED: _map_read_field ignores the stored value entirely
            //     (returns a constant), so an 8-byte slot with zeros is fine.
            //   - For BOOL: stored as 1 byte but in shaped (JS constructor) objects
            //     the slot is always 8 bytes. Avoiding rebuild preserves slot alignment.
            //   - Key invariant: shaped objects have all 8-byte slots. Rebuild would
            //     break JIT-compiled code that uses hardcoded byte_offset = slot*8.
            {
                bool old_is_ptr = (field_type == LMD_TYPE_NULL || field_type == LMD_TYPE_MAP ||
                    field_type == LMD_TYPE_VMAP || field_type == LMD_TYPE_VARRAY ||
                    field_type == LMD_TYPE_ELEMENT || field_type == LMD_TYPE_VELMT ||
                    field_type == LMD_TYPE_ARRAY || field_type == LMD_TYPE_ARRAY_NUM ||
                    field_type == LMD_TYPE_RANGE ||
                    field_type == LMD_TYPE_UNDEFINED || field_type == LMD_TYPE_BOOL);
                bool new_is_ptr = (value_type == LMD_TYPE_NULL || value_type == LMD_TYPE_MAP ||
                    value_type == LMD_TYPE_VMAP || value_type == LMD_TYPE_VARRAY ||
                    value_type == LMD_TYPE_ELEMENT || value_type == LMD_TYPE_VELMT ||
                    value_type == LMD_TYPE_ARRAY || value_type == LMD_TYPE_ARRAY_NUM ||
                    value_type == LMD_TYPE_RANGE ||
                    value_type == LMD_TYPE_UNDEFINED || value_type == LMD_TYPE_BOOL);
                if (old_is_ptr && new_is_ptr) {
                    // safety: only do in-place update when byte sizes match.
                    // shaped (constructor) objects always use 8-byte slots, but
                    // regular map_put objects use type_info byte sizes which
                    // differ for UNDEFINED(1)/BOOL(1) vs pointer types(8).
                    int old_bsz = shape_entry_storage_size(entry);
                    int new_bsz = lambda_lane_storage_size(type_info[value_type].type);
                    if (old_bsz != new_bsz) {
                        // fall through to map_rebuild_for_type_change
                    } else {
                        map_field_store(field_ptr, value, value_type);
                        // Update the ShapeEntry type so GC can properly trace
                        // container pointers stored in formerly-NULL fields, and
                        // so a stored null is not read back as a zero-valued T.
                        // The T→NULL downgrade is gated on this instance owning
                        // the shape — see shape_entry_retag_is_safe.
                        if (shape_entry_retag_is_safe(map_type, value_type)) {
                            shape_entry_set_type(entry, type_info[value_type].type);
                        }
                        return ItemNull;
                    }
                }
            }

            // Shaped JS objects preallocate fixed 8-byte slots and publish
            // slot_entries for slot-indexed access.  Do not run the generic
            // Lambda map rebuild here: it packs fields by type byte size and
            // breaks the slot*8 layout used by compiled JS accessors.
            if (typemap_entry_uses_fixed_slot(map_type, entry)) {
                map_field_store(field_ptr, value, value_type);
                if (shape_entry_retag_is_safe(map_type, value_type)) {
                    shape_entry_set_type(entry, type_info[value_type].type);
                }
                return ItemNull;
            }

            // type change — rebuild shape with new field type
            log_debug("fn_map_set: type change for '%s' (%d → %d), rebuilding shape",
                      key_cstr, field_type, value_type);
            Container* cont = map_item.container;
            // D3.4.5 through the runtime tree (Impl_Map_Transition_Coverage
            // P2): a plain Lambda map or element retyped the same way as
            // another takes one shared target instead of minting a private
            // chain per write, and its later adds grow from that target in the
            // tree. JS shapes keep their own transitions and the rebuild.
            if (plain_shape) {
                return container_retype_field(cont, map_type_id, type_slot,
                    data_slot, cap_slot, entry, value) ? ItemNull : ItemError;
            }
            map_rebuild_for_type_change(type_slot, data_slot, cap_slot,
                                        map_type_id, cont, entry,
                                        type_info[value_type].type, value);
            return ItemNull;
        }
        entry = table_answers ? NULL : typemap_next_field(map_type, entry);
    }
    // S2.1.4 part 3 / S9.1.6: a name is in a map's key domain, so an unknown
    // member write GROWS the shape rather than failing. Growth was previously
    // only reachable from the cow-path caller, which is why an ordinary
    // `p.z = 9` on a declared type silently did nothing on T0 and errored on
    // MIR. The hard error remains for anything that cannot grow — a non-name
    // key, or a value with no attribute face.
    if (map_extend_open_shape(map_item, key, value)) return ItemNull;
    log_error("fn_map_set: field '%s' not found", key_cstr);
    return ItemError;
}

Item map_literal_begin(void) {
    Map* map = (Map*)heap_calloc(sizeof(Map), LMD_TYPE_MAP);
    if (!map) {
        set_runtime_error(ERR_OUT_OF_MEMORY, "computed map literal allocation failed");
        return ItemError;
    }
    map->type_id = LMD_TYPE_MAP;
    map->type = &EmptyMap;
    return (Item){.map = map};
}

Element* elmt_literal_begin(TypeElmt* type) {
    if (!type) return NULL;
    // Reuse the ordinary element allocator so UI-mode literals retain their
    // DomElement representation while their attribute shape grows at runtime.
    // The literal's TypeElmt is passed directly: its type_index belongs to the
    // DEFINING module's type list, and the active context->type_list is the
    // running script's, so an index lookup here handed every module-defined
    // computed-key/spread element literal a foreign type (graph/* crashes).
    return elmt_with_type(type);
}

Item map_literal_put(Item owner, Item key, Item value) {
    if (!is_text_type_id(get_type_id(key))) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "computed map key must evaluate to string or symbol");
        return ItemError;
    }
    RootFrame roots(3);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_key(roots, key);
    Rooted<Item> rooted_value(roots, value);
    Item result = fn_map_set(rooted_owner.get(), rooted_key.get(), rooted_value.get());
    if (get_type_id(result) == LMD_TYPE_ERROR) {
        set_runtime_error(ERR_INVALID_OPERATION, "computed map key could not be stored");
        return ItemError;
    }
    return rooted_owner.get();
}

Item map_literal_spread(Item owner, Item source) {
    TypeId source_type = get_type_id(source);
    if (source_type != LMD_TYPE_MAP && source_type != LMD_TYPE_VMAP &&
            source_type != LMD_TYPE_ELEMENT) {
        set_runtime_error(ERR_TYPE_MISMATCH,
            "map literal spread requires a map-like value or element");
        return ItemError;
    }

    RootFrame roots(4);
    Rooted<Item> rooted_owner(roots, owner);
    Rooted<Item> rooted_source(roots, source);
    Rooted<Item> rooted_key(roots, ItemNull);
    Rooted<Item> rooted_value(roots, ItemNull);
    SymbolKeyList* keys = item_keys(rooted_source.get());
    int64_t key_count = symbol_key_list_len(keys);
    for (int64_t index = 0; index < key_count; index++) {
        Symbol* symbol = symbol_key_list_at(keys, index);
        rooted_key.set((Item){.item = y2it(symbol)});
        if (source_type == LMD_TYPE_VMAP) {
            // item_keys reifies VMap text keys as Symbols, while HashMap VMaps
            // retain String keys. Re-enter through the VMap name seam so a
            // spread does not turn every reified field into null.
            rooted_value.set(vmap_get_by_str(rooted_source.get().vmap, symbol->chars));
        } else {
            rooted_value.set(fn_index(rooted_source.get(), rooted_key.get()));
        }
        // A spread contributes each selected field to the fresh literal.
        cow_capture_value(rooted_value.get());
        if (get_type_id(rooted_value.get()) == LMD_TYPE_ERROR ||
                get_type_id(map_literal_put(rooted_owner.get(), rooted_key.get(),
                    rooted_value.get())) == LMD_TYPE_ERROR) {
            symbol_key_list_free(keys);
            return ItemError;
        }
    }
    symbol_key_list_free(keys);
    return rooted_owner.get();
}

